    INSERT INTO flashcards (id, codigo_fase, frente, verso, dica, opcoes, correta) VALUES
        (1, N'fase1', N'O que é uma Variável?', N'Um espaço reservado na memória para armazenar um dado.', N'Disciplina: Lógica com Python.', NULL, NULL),
        (2, N'fase1', N'Para que serve a estrutura ''for'' em Python?', N'Para criar um laço de repetição iterável (loop).', N'Percorre listas e sequências.', NULL, NULL),
        (3, N'fase1', N'O que é um Dicionário?', N'Uma estrutura de dados baseada em pares de ''chave: valor''.', N'Usa chaves {}. Ex: {''curso'': ''ADS''}', NULL, NULL),
        (4, N'fase1', N'Qual a diferença entre = e == em programação?', N'= é para Atribuição. == é para Comparação (Verificar se é igual).', N'Erro muito comum em lógica básica.', NULL, NULL),
        (5, N'fase1', N'O que faz a palavra ''def'' em Python?', N'Serve para definir/criar uma nova função.', N'Ex: def calcular_media():', NULL, NULL),
        (6, N'fase1', N'Para que serve a função len()?', N'Para retornar o tamanho (quantidade de itens) de uma lista ou string.', N'Vem da palavra ''length'' (comprimento).', NULL, NULL),
        (7, N'fase1', N'O que é uma Lista (List) em Python?', N'Uma coleção ordenada e mutável de itens.', N'Usa colchetes []. Ex: notas = [10, 8, 9]', NULL, NULL),
        (8, N'fase1', N'O que faz o método .append()?', N'Adiciona um novo item ao final de uma lista existente.', N'Muito usado dentro de laços de repetição.', NULL, NULL),
        (9, N'fase1', N'Para que serve o if/elif/else?', N'Para criar estruturas de decisão (condicionais) na lógica do código.', N'Se (if) chover, levo guarda-chuva. Senão (else)...', NULL, NULL),
        (10, N'fase1', N'O que é o laço ''while''?', N'Um loop que continua executando enquanto uma condição for Verdadeira (True).', N'Cuidado com o loop infinito!', NULL, NULL),
        (11, N'fase1', N'Qual a diferença entre int e float?', N'Int é número inteiro (ex: 5). Float é número decimal/quebrado (ex: 5.5).', N'Tipos de dados primitivos.', NULL, NULL),
        (12, N'fase1', N'O que é um dado Booleano (bool)?', N'Um tipo de dado que só possui dois valores: True (Verdadeiro) ou False (Falso).', N'Base da álgebra booleana.', NULL, NULL),
        (13, N'fase1', N'Como se faz um comentário em Python?', N'Usando o símbolo de hashtag (#) antes do texto.', N'O computador ignora essa linha na execução.', NULL, NULL),
        (14, N'fase1', N'Para que serve a função input()?', N'Para capturar um dado ou texto digitado pelo usuário no teclado.', N'Sempre retorna o dado como String (texto).', NULL, NULL),
        (15, N'fase1', N'Para que serve a função print()?', N'Para exibir mensagens ou valores na tela (console).', N'O ''Olá, Mundo!'' usa essa função.', NULL, NULL),
        (16, N'fase1', N'O que é uma função Lambda?', N'Uma função anônima e rápida, escrita em uma única linha.', N'Usada para lógicas curtas e matemáticas.', NULL, NULL),
        (17, N'fase1', N'Para que serve o bloco try/except?', N'Para tratar erros (exceções) e evitar que o programa ''crache'' e feche sozinho.', N'Tente (try) fazer isso, se der erro (except) avise.', NULL, NULL),
        (18, N'fase1', N'O que faz o comando ''import''?', N'Traz bibliotecas, módulos ou arquivos externos para dentro do seu código atual.', N'Ex: import math, import random', NULL, NULL),
        (19, N'fase1', N'Qual a diferença entre ''=='' e ''is''?', N'''=='' compara se o valor é igual. ''is'' compara se são o mesmo objeto na memória.', N'Conceito avançado de gerenciamento de memória.', NULL, NULL),
        (20, N'fase1', N'O que é Slicing (Fatiamento) em Python?', N'Uma técnica para extrair pedaços de uma string ou lista usando [início:fim].', N'Ex: texto[0:4] pega as primeiras 4 letras.', NULL, NULL),
        (21, N'fase1', N'Por que escrever um algoritmo antes do código Python pode ajudar?', N'Permite organizar os passos da solução e examinar a lógica antes de lidar com os detalhes da linguagem.', N'ED · 1º semestre · Planejamento separa o problema da sintaxe.', NULL, NULL),
        (22, N'fase1', N'Como um fluxograma auxilia a discussão de uma solução?', N'Ele representa visualmente o fluxo de ações e decisões, facilitando acompanhar caminhos possíveis do algoritmo.', N'ED · 1º semestre · Observe a sequência e os desvios do fluxo.', NULL, NULL),
        (23, N'fase1', N'Qual é a utilidade do pseudocódigo no planejamento de programas?', N'Descrever a solução de forma estruturada e próxima da linguagem humana, sem depender de uma sintaxe executável específica.', N'ED · 1º semestre · Pseudocódigo ajuda a comunicar a lógica.', NULL, NULL),
        (24, N'fase1', N'Por que alterar a indentação pode mudar um programa Python?', N'A indentação delimita blocos, indicando quais instruções pertencem a uma condição, repetição ou função.', N'ED · 1º semestre · Espaços também expressam estrutura.', NULL, NULL),
        (25, N'fase1', N'Quando o tipo inteiro é mais adequado que um número de ponto flutuante?', N'Quando o dado representa uma quantidade sem parte fracionária, como uma contagem de elementos.', N'ED · 1º semestre · Relacione o tipo ao significado do dado.', NULL, NULL),
        (26, N'fase1', N'Por que números de ponto flutuante podem apresentar pequenas diferenças de precisão?', N'Sua representação binária tem limitações; certos valores decimais não são representados exatamente.', N'ED · 1º semestre · Representação aproximada exige cuidado nas comparações.', NULL, NULL),
        (27, N'fase1', N'Como funções ajudam a evitar repetição em programas Python?', N'Elas agrupam uma tarefa em um bloco reutilizável, que pode ser chamado em diferentes pontos com dados apropriados.', N'ED · 1º semestre · Uma responsabilidade bem definida favorece reutilização.', NULL, NULL),
        (28, N'fase1', N'Por que o nome de uma função deve indicar a tarefa que ela realiza?', N'Porque ajuda a compreender sua finalidade ao ler uma chamada, tornando o código mais claro e fácil de manter.', N'ED · 1º semestre · Um nome útil explica a intenção.', NULL, NULL),
        (29, N'fase1', N'Como escolher entre lista e dicionário para organizar dados em Python?', N'Use lista para uma sequência acessada por posições e dicionário para associações consultadas por chaves.', N'ED · 1º semestre · O modo de acesso ajuda a escolher a estrutura.', NULL, NULL),
        (30, N'fase1', N'Por que uma chave de dicionário funciona como identificador de um valor?', N'Cada chave identifica uma associação no dicionário, permitindo localizar seu valor sem depender de uma posição numérica.', N'ED · 1º semestre · Pense em uma palavra associada à sua tradução.', NULL, NULL),
        (31, N'fase1', N'Que possibilidade de entrada a leitura de arquivos acrescenta a um programa?', N'Permite processar dados já armazenados em documentos, sem exigir que todos sejam digitados novamente.', N'ED · 1º semestre · Arquivos ampliam as origens dos dados.', NULL, NULL),
        (32, N'fase1', N'Como arquivos de texto e binários diferem na representação dos dados?', N'Arquivos de texto usam uma codificação textual; arquivos binários armazenam sequências de bytes interpretadas segundo um formato próprio.', N'ED · 1º semestre · A extensão sozinha não explica toda a estrutura.', NULL, NULL),
        (33, N'fase1', N'Como depuração e testes se complementam no desenvolvimento Python?', N'Testes evidenciam comportamentos diferentes do esperado; a depuração ajuda a investigar suas causas e acompanhar o estado da execução.', N'ED · 1º semestre · Detectar uma falha e explicar sua causa são etapas relacionadas.', NULL, NULL),
        (34, N'fase1', N'Para que serve executar um programa passo a passo no depurador?', N'Observar a sequência de instruções e os valores das variáveis para localizar onde o comportamento se desvia do esperado.', N'ED · 1º semestre · Acompanhe o estado antes e depois de cada passo.', NULL, NULL),
        (35, N'fase1', N'Qual é a função de uma asserção em um teste automatizado?', N'Comparar um resultado ou condição observada com o comportamento esperado, sinalizando quando a verificação falha.', N'ED · 1º semestre · Um teste precisa de um critério de sucesso.', NULL, NULL),
        (36, N'fase1', N'Como objetos organizam dados e comportamentos em Python?', N'Objetos reúnem estado e operações relacionadas, e são instâncias de classes que definem essa estrutura.', N'ED · 1º semestre · Classe descreve; objeto concretiza uma instância.', NULL, NULL),
        (37, N'fase2', N'O que é a Média Aritmética?', N'A soma de todos os valores dividida pela quantidade deles.', N'Disciplina: Matemática e Estatística.', NULL, NULL),
        (38, N'fase2', N'O que é a Mediana em um conjunto de dados?', N'É o valor que fica exatamente no meio quando os dados estão em ordem crescente.', N'Não é afetada por valores extremos (outliers).', NULL, NULL),
        (39, N'fase2', N'O que é a Moda estatística?', N'É o valor que aparece com maior frequência num conjunto de dados.', N'Pode haver mais de uma moda (bimodal).', NULL, NULL),
        (40, N'fase2', N'Para que serve o Desvio Padrão?', N'Para medir a dispersão dos dados, ou seja, o quão distantes eles estão da média.', N'Desvio baixo = dados muito próximos da média.', NULL, NULL),
        (41, N'fase2', N'O que é a Variância?', N'É o quadrado do desvio padrão, indicando o quão longe os valores se encontram do valor esperado.', N'Base para análises estatísticas profundas.', NULL, NULL),
        (42, N'fase2', N'O que estuda a Lógica Proposicional?', N'Proposições que podem ser classificadas como Verdadeiras ou Falsas.', N'Base para a programação de computadores.', NULL, NULL),
        (43, N'fase2', N'Na Tabela Verdade, o que faz o operador AND (E)?', N'Retorna Verdadeiro apenas se TODAS as condições forem verdadeiras.', N'Multiplicação lógica.', NULL, NULL),
        (44, N'fase2', N'Na Tabela Verdade, o que faz o operador OR (OU)?', N'Retorna Verdadeiro se PELO MENOS UMA das condições for verdadeira.', N'Soma lógica.', NULL, NULL),
        (45, N'fase2', N'Na Tabela Verdade, o que faz o operador NOT (NÃO)?', N'Inverte o valor lógico da proposição (Verdadeiro vira Falso e vice-versa).', N'Negação.', NULL, NULL),
        (46, N'fase2', N'O que é um Grafo?', N'Conjunto de Vértices (nós) conectados por Arestas (linhas).', N'Usado em GPS, mapas e redes.', NULL, NULL),
        (47, N'fase2', N'Num Grafo, o que é um Vértice?', N'É a entidade, ponto ou nó que armazena a informação.', N'Pense nas cidades num mapa.', NULL, NULL),
        (48, N'fase2', N'Num Grafo, o que é uma Aresta?', N'É a linha ou caminho que conecta dois vértices.', N'Pense nas estradas que ligam as cidades.', NULL, NULL),
        (49, N'fase2', N'O que é uma Árvore na Teoria dos Grafos?', N'Um grafo conectado e sem ciclos (sem caminhos fechados que voltem à origem).', N'Usada na organização de pastas no PC.', NULL, NULL),
        (50, N'fase2', N'O que é o Teorema de Bayes?', N'Fórmula matemática usada para calcular a probabilidade condicional de um evento baseado em conhecimentos anteriores.', N'Base matemática para filtros de Spam.', NULL, NULL),
        (51, N'fase2', N'Na Teoria dos Conjuntos, o que é a União (A ∪ B)?', N'A junção de todos os elementos do conjunto A com todos os do conjunto B.', N'Soma de conjuntos sem repetir os iguais.', NULL, NULL),
        (52, N'fase2', N'O que é a Interseção de Conjuntos (A ∩ B)?', N'Apenas os elementos que existem SIMULTANEAMENTE no conjunto A e no conjunto B.', N'O que eles têm em comum.', NULL, NULL),
        (53, N'fase2', N'O que é uma Matriz (Álgebra Linear)?', N'Um arranjo bidimensional de números organizados em linhas e colunas.', N'Essencial para a computação gráfica.', NULL, NULL),
        (54, N'fase2', N'O que é um Vetor?', N'Uma matriz de uma única linha ou única coluna. Na física, possui magnitude e direção.', N'Usado como array na programação.', NULL, NULL),
        (55, N'fase2', N'O que é uma Função Linear?', N'Uma função cujo gráfico forma uma linha reta (f(x) = ax + b).', N'Crescimento constante.', NULL, NULL),
        (56, N'fase2', N'O que é uma Função Exponencial?', N'Uma função onde a variável está no expoente, gerando um crescimento ou decaimento curvo e muito rápido.', N'A forma como os vírus se espalham.', NULL, NULL),
        (57, N'fase2', N'Qual é o papel da incógnita em uma equação que modela um problema?', N'Representar um valor desconhecido que deve satisfazer a relação expressa pela equação.', N'ED · 1º semestre · A igualdade impõe uma condição ao valor procurado.', NULL, NULL),
        (58, N'fase2', N'Como reconhecer duas grandezas diretamente proporcionais?', N'Quando variam mantendo uma razão constante: multiplicar uma delas por um fator multiplica a outra pelo mesmo fator.', N'ED · 1º semestre · Verifique a razão, não apenas se ambas aumentam.', NULL, NULL),
        (59, N'fase2', N'Que elementos pertencem à união de dois conjuntos?', N'Todos os elementos que pertencem a pelo menos um dos conjuntos, sem contar repetidos como novos elementos.', N'ED · 1º semestre · União reúne as possibilidades.', NULL, NULL),
        (60, N'fase2', N'Que elementos pertencem à interseção de dois conjuntos?', N'Somente os elementos que pertencem simultaneamente aos dois conjuntos.', N'ED · 1º semestre · Procure o que é comum.', NULL, NULL),
        (61, N'fase2', N'O que o domínio de uma função indica?', N'O conjunto de valores de entrada para os quais a função está definida.', N'ED · 1º semestre · O domínio delimita quais entradas são admitidas.', NULL, NULL),
        (62, N'fase2', N'Como o coeficiente angular influencia o gráfico de uma função afim?', N'Ele determina a inclinação da reta e indica como a saída varia quando a entrada aumenta.', N'ED · 1º semestre · Observe a taxa de variação.', NULL, NULL),
        (63, N'fase2', N'Como encontrar a raiz de uma função afim?', N'Iguale a expressão da função a zero e resolva a equação para descobrir a entrada que produz saída nula.', N'ED · 1º semestre · No gráfico, procure o encontro com o eixo horizontal.', NULL, NULL),
        (64, N'fase2', N'Que característica distingue uma função quadrática de uma função afim?', N'A função quadrática tem termo de grau dois com coeficiente não nulo e seu gráfico é uma parábola.', N'ED · 1º semestre · O maior grau determina uma mudança no formato do gráfico.', NULL, NULL),
        (65, N'fase2', N'Como a forma logarítmica se relaciona com a exponencial?', N'O logaritmo indica o expoente ao qual a base deve ser elevada para produzir um valor positivo, respeitadas as condições da base.', N'ED · 1º semestre · Logaritmo responde a uma pergunta sobre o expoente.', NULL, NULL),
        (66, N'fase2', N'Como o logaritmo de um produto pode ser reescrito?', N'Como a soma dos logaritmos dos fatores na mesma base, quando os fatores são positivos e a base é válida.', N'ED · 1º semestre · A propriedade transforma multiplicação em soma.', NULL, NULL),
        (67, N'fase2', N'O que significam os dois índices de um elemento de matriz?', N'O primeiro indica a linha e o segundo a coluna em que o elemento se encontra.', N'ED · 1º semestre · A posição organiza a leitura da tabela.', NULL, NULL),
        (68, N'fase2', N'Qual condição permite multiplicar uma matriz por outra?', N'O número de colunas da primeira deve ser igual ao número de linhas da segunda.', N'ED · 1º semestre · Compare as dimensões internas.', NULL, NULL),
        (69, N'fase2', N'Por que uma amostra grande não é automaticamente representativa?', N'Porque sua seleção pode deixar características importantes da população de fora, mesmo com muitos participantes.', N'ED · 1º semestre · Quantidade e qualidade da seleção são diferentes.', NULL, NULL),
        (70, N'fase2', N'Como se obtém a média aritmética de valores com o mesmo peso?', N'Somando todos os valores e dividindo pela quantidade de observações.', N'ED · 1º semestre · A soma é distribuída igualmente entre as observações.', NULL, NULL),
        (71, N'fase2', N'Como localizar a mediana quando há uma quantidade ímpar de observações?', N'Ordene os valores e identifique o elemento que ocupa a posição central.', N'ED · 1º semestre · Ordenar os dados é indispensável.', NULL, NULL),
        (72, N'fase2', N'Por que comparar dispersão além da média pode ser necessário?', N'Conjuntos com a mesma média podem ter valores muito próximos ou muito afastados, revelando variabilidades diferentes.', N'ED · 1º semestre · O desvio-padrão ajuda a descrever essa diferença.', NULL, NULL),
        (73, N'fase3', N'O que é a Placa-Mãe (Motherboard)?', N'A placa de circuito principal que conecta todos os componentes do computador.', N'Disciplinas: Infraestrutura e Hardware.', NULL, NULL),
        (74, N'fase3', N'Para que serve a CPU (Processador)?', N'É o cérebro do computador, responsável por processar e executar as instruções e cálculos.', N'Central Processing Unit.', NULL, NULL),
        (75, N'fase3', N'Qual a diferença entre RAM e HD/SSD?', N'RAM é a memória de curto prazo (volátil). HD/SSD é o armazenamento permanente.', N'Desligou o PC, a RAM apaga tudo.', NULL, NULL),
        (76, N'fase3', N'O que é a BIOS / UEFI?', N'O primeiro software que é executado ao ligar o PC, responsável por acordar e testar o hardware (POST).', N'Basic Input/Output System.', NULL, NULL),
        (77, N'fase3', N'O que é uma Placa de Vídeo (GPU)?', N'O componente especializado na renderização e processamento pesado de gráficos e imagens.', N'Graphic Processing Unit.', NULL, NULL),
        (78, N'fase3', N'Para que serve a Fonte de Alimentação?', N'Converter a energia elétrica da tomada (Corrente Alternada) para a energia usada pelo PC (Corrente Contínua).', N'O coração elétrico da máquina.', NULL, NULL),
        (79, N'fase3', N'O que é um Sistema Operacional (SO)?', N'O software base que gerencia o hardware e permite executar outros programas e interfaces.', N'Ex: Windows, Linux, macOS.', NULL, NULL),
        (80, N'fase3', N'O que é o Kernel de um Sistema Operacional?', N'O núcleo do SO, que faz a ponte direta entre o software (aplicativos) e o hardware (CPU, memória).', N'O motor invisível do SO.', NULL, NULL),
        (81, N'fase3', N'O que é a Virtualização?', N'A tecnologia que permite criar versões virtuais de recursos físicos, como correr um Windows dentro do Linux.', N'A base da Computação em Nuvem.', NULL, NULL),
        (82, N'fase3', N'O que é uma Máquina Virtual (VM)?', N'Um arquivo que atua como um computador físico independente, com o seu próprio SO, correndo isolado.', N'Um PC dentro do PC.', NULL, NULL),
        (83, N'fase3', N'O que é um Hypervisor?', N'O software, firmware ou hardware que cria e executa as máquinas virtuais.', N'O gestor das VMs (Ex: VirtualBox).', NULL, NULL),
        (84, N'fase3', N'O que é Computação em Nuvem?', N'O fornecimento de serviços de computação (servidores, armazenamento, bancos) através da Internet.', N'AWS, Azure, Google Cloud.', NULL, NULL),
        (85, N'fase3', N'O que é um Servidor?', N'Um computador muito potente e ligado 24/7 projetado para fornecer serviços e recursos a outros computadores (clientes).', N'A espinha dorsal da web.', NULL, NULL),
        (86, N'fase3', N'O que é um Data Center?', N'Um local físico (prédio ou sala) focado em abrigar centenas de servidores e infraestruturas de TI.', N'Onde a nuvem mora fisicamente.', NULL, NULL),
        (87, N'fase3', N'O que é o Endereço MAC?', N'O identificador físico e único de fábrica da placa de rede de um dispositivo.', N'Media Access Control.', NULL, NULL),
        (88, N'fase3', N'Qual a diferença entre Software e Firmware?', N'Software são os programas normais. Firmware é o software gravado diretamente na memória do hardware para o controlar.', N'O sistema do controle remoto da TV é um firmware.', NULL, NULL),
        (89, N'fase3', N'O que são periféricos de Entrada e Saída (I/O)?', N'Entrada envia dados ao PC (Teclado/Mouse). Saída mostra dados do PC ao usuário (Monitor/Impressora).', N'I/O (Input / Output).', NULL, NULL),
        (90, N'fase3', N'O que é o Sistema de Arquivos?', N'O método que o Sistema Operacional usa para controlar como os dados são guardados e recuperados no disco.', N'Ex: NTFS no Windows, ext4 no Linux.', NULL, NULL),
        (91, N'fase3', N'O que é o RAID em armazenamento?', N'A combinação de vários discos rígidos físicos numa única unidade lógica para melhorar o desempenho ou a segurança (cópia espelho).', N'Redundant Array of Independent Disks.', NULL, NULL),
        (92, N'fase3', N'O que significa formatação de baixo nível?', N'A criação de trilhas e setores no disco magnético na fábrica. A formatação que fazemos em casa é a de alto nível.', N'O reset físico absoluto do disco.', NULL, NULL),
        (93, N'fase3', N'O que a organização de computadores descreve sobre um sistema?', N'As unidades operacionais e suas interconexões que implementam a arquitetura, como sinais de controle e interfaces com periféricos.', N'ED · 1º semestre · Observe como os componentes trabalham em conjunto.', NULL, NULL),
        (94, N'fase3', N'O que a arquitetura de computadores apresenta ao programador?', N'Características que afetam a execução lógica, como conjunto de instruções, representação de dados e endereçamento de memória.', N'ED · 1º semestre · Considere os recursos visíveis à programação.', NULL, NULL),
        (95, N'fase3', N'Como entrada, processamento, memória e saída se relacionam?', N'As entradas fornecem dados, o processador executa instruções armazenadas na memória e as saídas apresentam os resultados.', N'ED · 1º semestre · Siga o caminho dos dados pelo sistema.', NULL, NULL),
        (96, N'fase3', N'Por que a memória principal é necessária durante a execução de programas?', N'Ela disponibiliza programas e dados para o processamento, apoiando a execução das instruções pela CPU.', N'ED · 1º semestre · Processar exige acesso às instruções e aos dados.', NULL, NULL),
        (97, N'fase3', N'Qual desperdício pode ocorrer com partições fixas de memória?', N'Um programa menor que sua partição pode deixar espaço reservado sem uso, e um maior pode não caber nela.', N'ED · 1º semestre · Compare o tamanho do processo com o espaço reservado.', NULL, NULL),
        (98, N'fase3', N'Como as partições dinâmicas diferem das partições fixas?', N'As áreas são alocadas conforme o tamanho dos processos, exigindo gerenciamento das regiões livres e ocupadas.', N'ED · 1º semestre · O tamanho da área acompanha a necessidade do processo.', NULL, NULL),
        (99, N'fase3', N'Como a fragmentação pode impedir uma alocação mesmo havendo memória livre?', N'O espaço livre pode estar dividido em regiões pequenas que, isoladamente, não comportam o processo solicitado.', N'ED · 1º semestre · Quantidade total livre não significa área contínua suficiente.', NULL, NULL),
        (100, N'fase3', N'Por que mover um processo na memória exige cuidado com os endereços?', N'O programa precisa continuar acessando corretamente suas instruções e dados na nova localização, o que exige suporte à relocação.', N'ED · 1º semestre · Mudança de posição não pode invalidar referências.', NULL, NULL);
    INSERT INTO flashcards (id, codigo_fase, frente, verso, dica, opcoes, correta) VALUES
        (101, N'fase3', N'O que torna o sistema decimal uma numeração posicional?', N'O valor de cada algarismo depende da posição que ocupa e da potência de dez associada a ela.', N'ED · 1º semestre · A mesma cifra pode representar unidades ou centenas.', NULL, NULL),
        (102, N'fase3', N'Como calcular o valor de um número em uma base posicional?', N'Multiplique cada algarismo pela potência da base correspondente à sua posição e some os resultados.', N'ED · 1º semestre · A posição mais à direita começa na potência zero.', NULL, NULL),
        (103, N'fase3', N'Quais símbolos aparecem nos sistemas binário, octal e hexadecimal?', N'Binário usa 0 e 1; octal usa 0 a 7; hexadecimal usa 0 a 9 e A a F.', N'ED · 1º semestre · A quantidade de símbolos acompanha a base.', NULL, NULL),
        (104, N'fase3', N'Por que cada posição binária corresponde a uma potência de dois?', N'Porque o sistema usa base dois; os pesos das posições são 1, 2, 4, 8 e assim por diante.', N'ED · 1º semestre · O valor total resulta da soma dos pesos com bit igual a um.', NULL, NULL),
        (105, N'fase3', N'Como uma cor pode ser indicada em uma folha de estilos usando hexadecimal?', N'Por um código numérico precedido de #, como #ff0000 para vermelho na representação RGB de seis dígitos.', N'ED · 1º semestre · Hexadecimal também representa componentes de cor.', NULL, NULL),
        (106, N'fase3', N'Por que caracteres precisam de códigos numéricos no computador?', N'A memória guarda representações digitais; uma codificação associa símbolos textuais a valores que podem ser armazenados em bits.', N'ED · 1º semestre · O caractere visível e sua codificação são coisas diferentes.', NULL, NULL),
        (107, N'fase3', N'Quantos estados um pixel de uma imagem binária pode representar?', N'Dois estados, pois cada pixel é representado por um bit, frequentemente interpretado como preto ou branco.', N'ED · 1º semestre · Um bit permite duas possibilidades.', NULL, NULL),
        (108, N'fase3', N'Por que compilar com sucesso não prova que o programa está correto?', N'A compilação verifica condições necessárias para gerar o programa, mas erros de lógica ou falhas podem aparecer durante a execução.', N'ED · 1º semestre · Compilação e teste avaliam aspectos diferentes.', NULL, NULL),
        (109, N'fase4', N'O que significa a sigla LGPD?', N'Lei Geral de Proteção de Dados (Lei 13.709/2018).', N'Disciplinas: Cibersegurança e Legislação.', NULL, NULL),
        (110, N'fase4', N'Na LGPD, quem é o Titular dos Dados?', N'A pessoa singular (física) a quem se referem os dados pessoais recolhidos.', N'O cidadão, o dono da informação.', NULL, NULL),
        (111, N'fase4', N'O que é um Dado Pessoal Sensível?', N'Dado que revela origem racial, religião, filiação política, saúde ou biometria.', N'Dados que podem causar discriminação.', NULL, NULL),
        (112, N'fase4', N'Quem é o Encarregado de Dados (DPO)?', N'O profissional indicado pela empresa para ser o canal de comunicação sobre a proteção de dados.', N'Data Protection Officer.', NULL, NULL),
        (113, N'fase4', N'O que é Phishing?', N'Ataque de engenharia social que usa e-mails ou sites falsos para roubar informações da vítima.', N'Pense em ''pescar'' a senha do usuário.', NULL, NULL),
        (114, N'fase4', N'O que é um Ransomware?', N'Um malware que criptografa os dados do computador e exige o pagamento de um resgate (geralmente em Bitcoin).', N'Ransom = Resgate.', NULL, NULL),
        (115, N'fase4', N'O que é um ataque DDoS?', N'Enviar milhares de requisições simultâneas para derrubar um servidor por sobrecarga.', N'Distributed Denial of Service.', NULL, NULL),
        (116, N'fase4', N'O que é um Cavalo de Troia (Trojan)?', N'Malware disfarçado de programa legítimo para abrir as ''portas'' do PC ao atacante.', N'Presente de grego.', NULL, NULL),
        (117, N'fase4', N'Qual a diferença entre Vírus e Worm?', N'O vírus precisa que o usuário execute o arquivo para o infetar. O Worm (verme) espalha-se sozinho pela rede.', N'Worms são autônomos.', NULL, NULL),
        (118, N'fase4', N'O que é a Engenharia Social no hacking?', N'Técnica de manipulação psicológica para enganar pessoas e fazê-las entregar senhas ou dados confidenciais.', N'Hackear a mente humana.', NULL, NULL),
        (119, N'fase4', N'Para que serve um Firewall?', N'Barreira de segurança que monitoriza e bloqueia o tráfego de rede de entrada e saída baseado em regras.', N'Parede de fogo da rede.', NULL, NULL),
        (120, N'fase4', N'O que é uma VPN?', N'Uma rede privada virtual que cria um túnel criptografado, ocultando o endereço IP e o tráfego do usuário.', N'Virtual Private Network.', NULL, NULL),
        (121, N'fase4', N'O que é Criptografia Simétrica?', N'Usa a MESMA chave secreta tanto para encriptar quanto para desencriptar a mensagem.', N'Rápida, mas difícil de compartilhar a chave em segurança.', NULL, NULL),
        (122, N'fase4', N'O que é Criptografia Assimétrica?', N'Usa um par de chaves: uma Chave Pública (para encriptar) e uma Chave Privada (para desencriptar).', N'A base da segurança na Internet moderna.', NULL, NULL),
        (123, N'fase4', N'O que é uma função de Hash?', N'Algoritmo de mão única que transforma qualquer dado numa string de tamanho fixo, impossível de reverter.', N'Usada para guardar senhas no banco de dados.', NULL, NULL),
        (124, N'fase4', N'O que é a Autenticação de 2 Fatores (2FA)?', N'Adicionar uma camada extra de segurança (ex: SMS, Token, Biometria) além da senha padrão.', N'Algo que você sabe + Algo que você tem.', NULL, NULL),
        (125, N'fase4', N'O que é um Teste de Invasão (PenTest)?', N'Um ataque cibernético simulado e autorizado num sistema para encontrar e corrigir vulnerabilidades.', N'Realizado por White Hats (Hackers Éticos).', NULL, NULL),
        (126, N'fase4', N'O que é uma vulnerabilidade Zero-Day?', N'Uma falha de software recém-descoberta que os criadores do sistema ainda não tiveram tempo de corrigir (zero dias).', N'Ataques indetectáveis no momento.', NULL, NULL),
        (127, N'fase4', N'O que é a Regra de Backup 3-2-1?', N'Ter 3 cópias dos dados, em 2 tipos de média diferentes, sendo 1 cópia fora da empresa (offsite/nuvem).', N'Garante a recuperação total em caso de desastre.', NULL, NULL),
        (128, N'fase4', N'Qual a função do protocolo HTTPS?', N'Permitir a navegação segura na web, criptografando a comunicação entre o navegador e o servidor com certificados SSL/TLS.', N'O cadeado verde na barra de endereço.', NULL, NULL),
        (129, N'fase4', N'Qual princípio é afetado quando alguém lê um arquivo sem autorização?', N'A confidencialidade, pois ela exige restringir o acesso à informação às pessoas e aos sistemas autorizados.', N'AVA · 1º semestre · Associe leitura indevida à exposição de informação.', NULL, NULL),
        (130, N'fase4', N'Qual princípio é afetado por uma alteração não autorizada nas notas de alunos?', N'A integridade, que busca preservar a correção dos dados e impedir modificações indevidas.', N'AVA · 1º semestre · Pense na confiabilidade do conteúdo.', NULL, NULL),
        (131, N'fase4', N'Qual princípio é afetado quando um serviço fica inacessível aos usuários legítimos?', N'A disponibilidade, pois os recursos precisam estar acessíveis para uso autorizado quando necessário.', N'AVA · 1º semestre · Relacione a falha à continuidade de acesso.', NULL, NULL),
        (132, N'fase4', N'Por que a engenharia social também exige treinamento de pessoas?', N'Porque explora confiança, medo ou distração para induzir alguém a revelar informações ou realizar ações inseguras.', N'AVA · 1º semestre · A vulnerabilidade explorada pode estar na interação humana.', NULL, NULL),
        (133, N'fase4', N'Por que instalar um firewall sem revisar suas regras é insuficiente?', N'O firewall decide com base nas regras configuradas; regras incorretas podem permitir tráfego indevido ou bloquear serviços necessários.', N'AVA · 1º semestre · Ferramentas dependem de configuração e acompanhamento.', NULL, NULL),
        (134, N'fase4', N'Qual cuidado central acompanha o uso de uma chave criptográfica simétrica?', N'A mesma chave permite cifrar e decifrar, por isso seu compartilhamento e armazenamento precisam ser protegidos.', N'AVA · 1º semestre · A proteção da chave faz parte da proteção dos dados.', NULL, NULL),
        (135, N'fase4', N'Como a criptografia assimétrica organiza suas chaves?', N'Ela utiliza um par relacionado de chaves, uma pública e outra privada, com papéis complementares nas operações criptográficas.', N'AVA · 1º semestre · A chave privada deve permanecer protegida.', NULL, NULL),
        (136, N'fase4', N'Como IDS e IPS diferem na reação a atividades suspeitas?', N'O IDS se concentra em detectar e alertar; o IPS também pode interromper ou bloquear atividades identificadas como maliciosas.', N'AVA · 1º semestre · Detecção e prevenção são funções relacionadas, mas distintas.', NULL, NULL),
        (137, N'fase4', N'Por que correlacionar eventos em um SIEM ajuda a investigar incidentes?', N'Eventos de fontes diferentes podem revelar um padrão de ataque que passaria despercebido quando cada registro é examinado isoladamente.', N'AVA · 1º semestre · Procure relações entre registros e horários.', NULL, NULL),
        (138, N'fase4', N'Por que isolar uma máquina comprometida pode fazer parte da resposta a incidentes?', N'O isolamento busca conter a propagação do ataque e reduzir novos danos enquanto a equipe investiga e recupera o ambiente.', N'AVA · 1º semestre · Contenção limita o alcance do incidente.', NULL, NULL),
        (139, N'fase4', N'Qual é o papel de um plano de recuperação de desastres?', N'Definir como restaurar serviços e dados após uma interrupção, com ações e responsabilidades previamente organizadas.', N'AVA · 1º semestre · Planejar antes reduz improvisação durante a crise.', NULL, NULL),
        (140, N'fase4', N'Por que segurança por design começa antes de o programa ficar pronto?', N'Decisões de arquitetura e validação tomadas desde o início reduzem vulnerabilidades e evitam tratar segurança apenas como correção final.', N'AVA · 1º semestre · Segurança acompanha o ciclo de desenvolvimento.', NULL, NULL),
        (141, N'fase4', N'O que uma política de segurança comunica aos colaboradores?', N'Diretrizes formais para proteger informações e ativos, incluindo responsabilidades e regras de uso e acesso.', N'AVA · 1º semestre · A política orienta comportamentos e decisões.', NULL, NULL),
        (142, N'fase4', N'Como normas de segurança ajudam a organizar a proteção de informações?', N'Elas oferecem referências e requisitos para estruturar práticas, avaliar riscos e verificar controles de forma consistente.', N'AVA · 1º semestre · Normas apoiam a gestão, além das ferramentas.', NULL, NULL),
        (143, N'fase4', N'Para que serve uma auditoria de segurança da informação?', N'Avaliar a eficácia das medidas de proteção e identificar falhas, riscos ou desvios que precisam de correção.', N'AVA · 1º semestre · Auditoria compara práticas e evidências.', NULL, NULL),
        (144, N'fase4', N'Por que conscientização deve acompanhar as políticas de segurança?', N'As pessoas precisam compreender as regras e sua finalidade para aplicá-las no trabalho e reconhecer situações de risco.', N'AVA · 1º semestre · Uma política sem compreensão dificilmente orienta a prática.', NULL, NULL),
        (145, N'fase5', N'O que é a Inclusão Digital?', N'A democratização do acesso às tecnologias de informação para todas as camadas da sociedade.', N'Disciplinas: Ética e Sociedade.', NULL, NULL),
        (146, N'fase5', N'O que é o conceito de Green IT (TI Verde)?', N'O conjunto de práticas para reduzir o impacto ambiental da tecnologia (consumo de energia, lixo eletrônico).', N'Sustentabilidade na tecnologia.', NULL, NULL),
        (147, N'fase5', N'O que garante a Propriedade Intelectual em Software?', N'Protege o código-fonte de um sistema como direitos de autor, impedindo a cópia ou pirataria comercial.', N'Software é tratado como uma obra literária por lei.', NULL, NULL),
        (148, N'fase5', N'O que é o Viés Algorítmico (Bias)?', N'Quando uma IA reproduz discriminações e preconceitos humanos porque foi treinada com dados históricos falhos.', N'O algoritmo herda os defeitos da sociedade.', NULL, NULL),
        (149, N'fase5', N'Qual a diferença entre Open Source e Software Proprietário?', N'Open Source tem o código-fonte aberto e colaborativo. Proprietário é fechado, patenteado e pertence a uma empresa.', N'Linux vs Windows.', NULL, NULL),
        (150, N'fase5', N'O que é o Copyleft?', N'Licença que permite o livre uso, modificação e compartilhamento de uma obra, desde que as versões alteradas mantenham as mesmas liberdades.', N'O oposto do Copyright restritivo.', NULL, NULL),
        (151, N'fase5', N'O que é o Cyberbullying?', N'A intimidação, assédio ou violência psicológica realizada através da internet e redes sociais.', N'Bullying digital.', NULL, NULL),
        (152, N'fase5', N'O que é um Deepfake?', N'Vídeos ou áudios gerados por IA que substituem o rosto ou a voz de uma pessoa para criar situações falsas e realistas.', N'Ameaça gigante à política e privacidade.', NULL, NULL),
        (153, N'fase5', N'O que é a Obsolescência Programada?', N'A tática da indústria de fabricar aparelhos desenhados para quebrarem ou ficarem inúteis rapidamente, forçando uma nova compra.', N'Celular que fica lento após 2 anos.', NULL, NULL),
        (154, N'fase5', N'O que é o Lixo Eletrônico (E-waste)?', N'Equipamentos tecnológicos descartados incorretamente que libertam metais pesados tóxicos no solo.', N'O lado negro do consumo tecnológico.', NULL, NULL),
        (155, N'fase5', N'O que são Fake News?', N'Notícias falsas ou distorcidas disseminadas rapidamente em massa pelas redes sociais para manipular opiniões.', N'A desinformação digital.', NULL, NULL),
        (156, N'fase5', N'O que é Privacidade Digital?', N'O direito do usuário de controlar como as suas informações pessoais são recolhidas e usadas na internet.', N'O seu histórico de pesquisa é seu.', NULL, NULL),
        (157, N'fase5', N'O que são as normas WCAG (Acessibilidade Web)?', N'Diretrizes internacionais que garantem que sites e aplicações possam ser usados por pessoas com deficiências (visuais, motoras, etc).', N'Web Content Accessibility Guidelines.', NULL, NULL),
        (158, N'fase5', N'Qual o foco da Ergonomia na TI?', N'A conceção de estações de trabalho (cadeira, monitor, teclado) para evitar lesões por esforço repetitivo em profissionais de tecnologia.', N'Cuidar da saúde do desenvolvedor.', NULL, NULL),
        (159, N'fase5', N'Qual o impacto social da Automação e da IA?', N'A eliminação de empregos operacionais antigos, mas simultaneamente a criação de novas especializações tecnológicas.', N'A Quarta Revolução Industrial.', NULL, NULL),
        (160, N'fase5', N'O que é Netiqueta?', N'O conjunto de regras de etiqueta e boa educação que governam o comportamento social na internet.', N'Não escrever tudo em CAIXA ALTA (Gritar).', NULL, NULL),
        (161, N'fase5', N'O que é a Sociedade da Informação?', N'Uma sociedade onde a criação, distribuição e uso da informação tornaram-se a atividade econômica e cultural mais importante.', N'A Era da Informação.', NULL, NULL),
        (162, N'fase5', N'O que é o Tecnocentrismo?', N'A crença ilusória de que a tecnologia, por si só, resolverá todos os problemas da humanidade.', N'A tecnologia é ferramenta, não milagre.', NULL, NULL),
        (163, N'fase5', N'O que é a Exclusão Digital?', N'A desigualdade entre aqueles que têm fácil acesso à tecnologia e aqueles que não têm, agravando a pobreza e o desemprego.', N'A consequência da falta de Inclusão Digital.', NULL, NULL),
        (164, N'fase5', N'Como a Tecnologia afeta os Direitos Humanos?', N'Pode promovê-los (liberdade de expressão) ou ameaçá-los (vigilância estatal em massa e invasão de privacidade).', N'A tecnologia como uma faca de dois gumes.', NULL, NULL),
        (165, N'fase5', N'Por que progresso tecnológico deve ser analisado junto com seus impactos sociais?', N'Avanços técnicos podem coexistir com desigualdade e degradação; avaliar seus efeitos ajuda a orientar decisões voltadas ao bem coletivo.', N'AVA · 1º semestre · Tecnologia e qualidade de vida não avançam automaticamente juntas.', NULL, NULL),
        (166, N'fase5', N'Como refletir sobre valores ajuda a tomar decisões éticas?', N'Permite examinar quais interesses orientam a escolha e se seus efeitos respeitam direitos, deveres e princípios de convivência.', N'AVA · 1º semestre · Considere razões e consequências da decisão.', NULL, NULL),
        (167, N'fase5', N'Por que a ética empresarial envolve diferentes públicos?', N'As ações da organização afetam funcionários, clientes, fornecedores, concorrentes e comunidade, exigindo coerência nessas relações.', N'AVA · 1º semestre · A responsabilidade ultrapassa uma relação comercial isolada.', NULL, NULL),
        (168, N'fase5', N'Como uma visão ética de interesse coletivo amplia a análise do lucro?', N'Ela considera o benefício comum e as relações de solidariedade, reconhecendo que resultados econômicos devem coexistir com responsabilidade.', N'AVA · 1º semestre · O resultado da empresa afeta outras pessoas.', NULL, NULL),
        (169, N'fase5', N'Como direitos e deveres se relacionam no exercício da cidadania?', N'O cidadão deve ter direitos reconhecidos e respeitar os direitos das demais pessoas, participando da vida comunitária.', N'AVA · 1º semestre · Cidadania combina proteção e responsabilidade.', NULL, NULL),
        (170, N'fase5', N'Como a educação contribui para o exercício da cidadania?', N'Favorece o desenvolvimento da pessoa, a compreensão de direitos e deveres e a participação crítica na sociedade.', N'AVA · 1º semestre · Aprender também prepara para a convivência.', NULL, NULL),
        (171, N'fase5', N'Por que acompanhar decisões públicas é uma prática de cidadania?', N'Permite participar, fiscalizar e propor melhorias em assuntos que afetam a comunidade.', N'AVA · 1º semestre · Cidadania não se limita ao voto.', NULL, NULL),
        (172, N'fase5', N'Como o respeito às diferenças aparece nos deveres do cidadão?', N'Na preservação da vida, da liberdade e da intimidade das pessoas e na recusa de práticas discriminatórias.', N'AVA · 1º semestre · Convivência exige reconhecer o outro como sujeito de direitos.', NULL, NULL),
        (173, N'fase5', N'Quais dimensões devem ser consideradas no tripé da sustentabilidade?', N'As dimensões social, ambiental e econômica, avaliadas de forma conjunta nas decisões e nos resultados da organização.', N'AVA · 1º semestre · Lucro é apenas uma parte da análise.', NULL, NULL),
        (174, N'fase5', N'O que caracteriza a dimensão social da sustentabilidade?', N'A preocupação com equidade, dignidade, direitos e fortalecimento das relações sociais e da comunidade.', N'AVA · 1º semestre · Pense em pessoas e condições de vida.', NULL, NULL),
        (175, N'fase5', N'Por que indicadores são úteis na gestão da sustentabilidade?', N'Eles permitem acompanhar processos, comparar resultados e fornecer informações para decisões e ações de melhoria.', N'AVA · 1º semestre · Medir deve ajudar a agir.', NULL, NULL),
        (176, N'fase5', N'Como a melhoria contínua se relaciona com a gestão ambiental?', N'Ela exige revisar atividades e buscar formas de reduzir impactos, consumo de recursos e geração de resíduos ao longo do tempo.', N'AVA · 1º semestre · Gestão ambiental é um processo permanente.', NULL, NULL),
        (177, N'fase5', N'Para que servem os Objetivos de Desenvolvimento Sustentável?', N'Oferecem objetivos comuns para enfrentar desafios sociais, ambientais e econômicos, orientando ações e cooperação.', N'AVA · 1º semestre · Os objetivos conectam problemas que se influenciam.', NULL, NULL),
        (178, N'fase5', N'Qual compromisso entre presente e futuro orienta o desenvolvimento sustentável?', N'Atender às necessidades atuais sem comprometer a possibilidade de as próximas gerações atenderem às próprias necessidades.', N'AVA · 1º semestre · Considere os efeitos duradouros das escolhas.', NULL, NULL),
        (179, N'fase5', N'Por que digitalização não garante, sozinha, redução das desigualdades?', N'Se acesso, infraestrutura e capacitação forem desiguais, os benefícios podem se concentrar em poucos grupos.', N'AVA · 1º semestre · Distribuir oportunidades também exige políticas e formação.', NULL, NULL),
        (180, N'fase5', N'Como consumo e produção responsáveis se relacionam com a sustentabilidade?', N'Buscam reduzir desperdícios e impactos nos padrões de produção e uso de recursos, considerando seus efeitos sociais e ambientais.', N'AVA · 1º semestre · Observe o ciclo completo de produtos e serviços.', NULL, NULL),
        (181, N'fase26', N'Por que a dignidade humana não depende da profissão ou da renda de alguém?', N'Ela decorre do valor da pessoa como ser humano, e não de sua posição econômica, social ou profissional.', N'AVA · 1º semestre · A dignidade é inerente à pessoa.', NULL, NULL),
        (182, N'fase26', N'O que a universalidade dos direitos humanos exige?', N'Que a proteção alcance todas as pessoas, sem reservar direitos apenas a um grupo considerado mais importante.', N'AVA · 1º semestre · Considere quem pode usufruir dos direitos.', NULL, NULL),
        (183, N'fase26', N'Por que os direitos humanos são chamados de indivisíveis?', N'Porque formam um conjunto: não é adequado escolher alguns para proteger e abandonar os demais.', N'AVA · 1º semestre · Liberdade e condições dignas de vida se complementam.', NULL, NULL),
        (184, N'fase26', N'O que significa interdependência entre direitos humanos?', N'A realização de um direito se relaciona com outros; educação, saúde e participação social, por exemplo, influenciam-se mutuamente.', N'AVA · 1º semestre · Direitos não funcionam como compartimentos isolados.', NULL, NULL),
        (185, N'fase26', N'Por que se usa a expressão dimensões de direitos humanos?', N'Ela destaca que os direitos se acumulam e se complementam, em vez de uma geração substituir e encerrar a anterior.', N'AVA · 1º semestre · Pense em construção histórica cumulativa.', NULL, NULL),
        (186, N'fase26', N'Que tipo de proteção caracteriza os direitos civis e políticos?', N'A proteção de liberdades e da participação política, limitando arbitrariedades do poder e reconhecendo direitos dos indivíduos.', N'AVA · 1º semestre · Relacione liberdade com limites ao poder.', NULL, NULL),
        (187, N'fase26', N'Como os direitos sociais se relacionam com uma vida digna?', N'Eles abrangem condições como trabalho, saúde, moradia, educação e proteção social, necessárias ao exercício concreto da dignidade.', N'AVA · 1º semestre · Não basta reconhecer direitos apenas no papel.', NULL, NULL),
        (188, N'fase26', N'Por que a proteção do meio ambiente envolve direitos coletivos?', N'Porque a qualidade ambiental afeta a vida de muitas pessoas e depende de responsabilidades que ultrapassam interesses individuais.', N'AVA · 1º semestre · Considere a dimensão compartilhada dos impactos.', NULL, NULL),
        (189, N'fase26', N'Como a Constituição contribui para a proteção dos direitos fundamentais?', N'Ela reconhece garantias de dignidade, igualdade e liberdade e orienta a atuação do Estado e a aplicação das demais normas.', N'AVA · 1º semestre · A Constituição organiza limites e garantias.', NULL, NULL),
        (190, N'fase26', N'O que a igualdade perante a lei busca impedir?', N'Tratamentos arbitrariamente discriminatórios baseados em características pessoais ou sociais, preservando a proteção jurídica de todos.', N'AVA · 1º semestre · Diferenças pessoais não retiram dignidade.', NULL, NULL),
        (191, N'fase26', N'Por que a proibição da tortura protege também pessoas acusadas de crimes?', N'A dignidade e a proteção contra tratamento desumano não desaparecem diante de uma acusação ou condenação.', N'AVA · 1º semestre · Direitos fundamentais não dependem de aprovação social.', NULL, NULL),
        (192, N'fase26', N'Por que liberdade de expressão envolve responsabilidade?', N'A liberdade de manifestar ideias não elimina a responsabilidade por danos ou violações de direitos decorrentes dessa manifestação.', N'AVA · 1º semestre · Expressar-se também exige respeito aos outros.', NULL, NULL),
        (193, N'fase26', N'Como o respeito às convicções contribui para a convivência democrática?', N'Permite que pessoas com crenças e posições diferentes convivam sem perder direitos por essas diferenças.', N'AVA · 1º semestre · Pluralidade exige respeito recíproco.', NULL, NULL),
        (194, N'fase26', N'Por que proteger a intimidade é relevante em serviços digitais?', N'Informações sobre a vida privada podem expor a pessoa; proteger a intimidade limita intromissões e usos que desrespeitem sua dignidade.', N'AVA · 1º semestre · Relacione vida privada e tratamento de informações.', NULL, NULL),
        (195, N'fase26', N'Por que a proteção das pessoas com deficiência integra os direitos humanos?', N'Porque a dignidade e a igualdade precisam alcançar essas pessoas, incluindo condições para exercer seus direitos e participar da sociedade.', N'AVA · 1º semestre · Inclusão torna direitos efetivamente acessíveis.', NULL, NULL),
        (196, N'fase26', N'Qual é a importância da participação social na construção de políticas de direitos humanos?', N'Ela permite incorporar necessidades e propostas de diferentes grupos, fortalecendo políticas voltadas à dignidade e à inclusão.', N'AVA · 1º semestre · Diálogo aproxima políticas das experiências vividas.', NULL, NULL),
        (197, N'fase27', N'Como o princípio da finalidade orienta a coleta de dados em um cadastro?', N'A coleta deve ter um propósito específico, explícito e legítimo, que oriente os usos posteriores dos dados.', N'AVA · 1º semestre · Pergunte para que cada dado será utilizado.', NULL, NULL),
        (198, N'fase27', N'Como aplicar o princípio da necessidade em um formulário?', N'Solicitar apenas os dados pertinentes e proporcionais ao objetivo, evitando campos sem utilidade para a finalidade informada.', N'AVA · 1º semestre · Menos coleta desnecessária reduz exposição.', NULL, NULL),
        (199, N'fase27', N'O que a adequação exige do uso dos dados pessoais?', N'Que o tratamento seja compatível com a finalidade informada e com o contexto em que os dados foram coletados.', N'AVA · 1º semestre · Compare o uso realizado com o propósito declarado.', NULL, NULL),
        (200, N'fase27', N'Por que transparência importa no tratamento de dados pessoais?', N'Ela permite que os titulares compreendam como seus dados são utilizados e quais práticas estão envolvidas no tratamento.', N'AVA · 1º semestre · Informação clara favorece o exercício de direitos.', NULL, NULL);
    INSERT INTO flashcards (id, codigo_fase, frente, verso, dica, opcoes, correta) VALUES
        (201, N'fase27', N'Qual decisão caracteriza o papel do controlador de dados?', N'Decidir sobre o tratamento de dados pessoais, incluindo suas finalidades e os meios relevantes para realizá-lo.', N'AVA · 1º semestre · Identifique quem define o tratamento.', NULL, NULL),
        (202, N'fase27', N'Como o operador se relaciona com o controlador no tratamento de dados?', N'O operador realiza o tratamento em nome do controlador, seguindo as instruções pertinentes e as responsabilidades de proteção.', N'AVA · 1º semestre · Execução e decisão podem caber a agentes diferentes.', NULL, NULL),
        (203, N'fase27', N'Que função de comunicação é associada ao encarregado de dados?', N'Atuar como canal entre a organização, os titulares e a autoridade de proteção de dados, apoiando a cultura de privacidade.', N'AVA · 1º semestre · O encarregado aproxima os envolvidos no tratamento.', NULL, NULL),
        (204, N'fase27', N'Por que não se deve tratar consentimento como a única base legal possível?', N'A legislação prevê diferentes hipóteses de tratamento, como execução de contrato e obrigação legal, cuja aplicação depende do contexto.', N'AVA · 1º semestre · A escolha da base exige analisar a atividade.', NULL, NULL),
        (205, N'fase27', N'Por que proteger dados em trânsito e em repouso?', N'Eles podem ser expostos tanto durante a transmissão quanto quando armazenados; os controles precisam considerar os dois momentos.', N'AVA · 1º semestre · O ciclo dos dados vai além do banco de dados.', NULL, NULL),
        (206, N'fase27', N'Como a privacidade por design influencia o desenvolvimento de sistemas?', N'Ela incorpora proteção de dados desde a concepção e ao longo do desenvolvimento, em vez de acrescentá-la somente ao final.', N'AVA · 1º semestre · Pense nas primeiras decisões de requisitos e arquitetura.', NULL, NULL),
        (207, N'fase27', N'O que significa adotar privacidade como configuração padrão?', N'O sistema começa com configurações voltadas à proteção dos dados, sem depender de o usuário descobrir e ativar essas proteções.', N'AVA · 1º semestre · A configuração inicial também comunica uma escolha de projeto.', NULL, NULL),
        (208, N'fase27', N'Por que o descarte de dados também precisa ser previsto no projeto?', N'A proteção deve acompanhar todo o ciclo de vida, incluindo quando e como informações deixam de ser necessárias e são descartadas.', N'AVA · 1º semestre · Guardar indefinidamente também é uma decisão de tratamento.', NULL, NULL),
        (209, N'fase27', N'Por que usar um serviço de nuvem estrangeiro exige avaliar a transferência de dados?', N'Porque o tratamento pode envolver outro país, exigindo atenção às condições e garantias de proteção dos titulares.', N'AVA · 1º semestre · Localização e fluxo dos dados fazem parte da análise.', NULL, NULL),
        (210, N'fase27', N'Qual é a finalidade das salvaguardas em transferências internacionais?', N'Preservar a proteção dos dados e os direitos dos titulares quando as informações são tratadas fora do país de origem.', N'AVA · 1º semestre · A proteção deve acompanhar os dados.', NULL, NULL),
        (211, N'fase27', N'Como registros e documentos podem ajudar em uma fiscalização de dados?', N'Eles permitem esclarecer práticas de tratamento e apresentar evidências sobre as medidas adotadas e os problemas identificados.', N'AVA · 1º semestre · Responsabilização exige informações verificáveis.', NULL, NULL),
        (212, N'fase27', N'Por que a fiscalização pode envolver correção de irregularidades?', N'Porque identificar falhas e exigir sua correção contribui para adequar o tratamento e proteger os direitos dos titulares.', N'AVA · 1º semestre · A avaliação deve resultar em providências concretas.', NULL, NULL),
        (213, N'fase28', N'Que perguntas ajudam a separar entrada, processamento e saída de um algoritmo?', N'Quais dados são necessários, quais operações levam ao resultado e qual resultado deve ser apresentado.', N'ED · 1º semestre · Planeje antes de escrever os comandos.', NULL, NULL),
        (214, N'fase28', N'Quais três estruturas básicas organizam um algoritmo estruturado?', N'Sequência, decisão e repetição, usadas para ordenar ações, escolher caminhos e repetir tarefas.', N'ED · 1º semestre · Uma solução combina essas estruturas.', NULL, NULL),
        (215, N'fase28', N'O que caracteriza um trecho sequencial de programa em C?', N'As instruções são executadas na ordem definida, sem uma escolha de caminho ou repetição naquele trecho.', N'ED · 1º semestre · A posição dos comandos influencia o resultado.', NULL, NULL),
        (216, N'fase28', N'Quando uma estrutura de decisão é necessária em um algoritmo?', N'Quando a execução deve escolher uma ação conforme uma condição, como tratar situações diferentes de uma entrada.', N'ED · 1º semestre · Decidir significa selecionar um caminho.', NULL, NULL),
        (217, N'fase28', N'Em C, que tipo de operandos o operador de resto % aceita?', N'Operandos inteiros; ele produz o resto da divisão inteira.', N'ED · 1º semestre · Resto e divisão de ponto flutuante são operações diferentes.', NULL, NULL),
        (218, N'fase28', N'Como a precedência influencia uma expressão com soma e multiplicação em C?', N'A multiplicação é avaliada antes da soma, salvo quando parênteses determinam outro agrupamento.', N'ED · 1º semestre · Parênteses tornam a intenção explícita.', NULL, NULL),
        (219, N'fase28', N'Por que usar = no lugar de == pode mudar o sentido de uma condição em C?', N'Porque = atribui um valor, enquanto == compara igualdade; trocar os operadores altera a operação realizada.', N'ED · 1º semestre · Atribuir não é perguntar se dois valores são iguais.', NULL, NULL),
        (220, N'fase28', N'Como pré-incremento e pós-incremento diferem dentro de uma expressão simples?', N'No pré-incremento, o novo valor é usado na expressão; no pós-incremento, usa-se o valor anterior e depois ocorre o incremento.', N'ED · 1º semestre · Considere quando o valor participa da expressão.', NULL, NULL),
        (221, N'fase28', N'O que distingue fprintf de printf no destino da saída?', N'fprintf escreve em um fluxo indicado, como um arquivo; printf escreve na saída padrão, normalmente exibida no terminal.', N'ED · 1º semestre · A operação também precisa indicar seu destino.', NULL, NULL),
        (222, N'fase28', N'O que distingue fscanf de scanf na origem da leitura?', N'fscanf lê dados de um fluxo de arquivo indicado; scanf lê da entrada padrão, normalmente associada ao teclado.', N'ED · 1º semestre · Identifique de onde vêm os dados.', NULL, NULL),
        (223, N'fase28', N'Por que dividir um programa C em funções facilita sua manutenção?', N'Cada função pode concentrar uma tarefa, permitindo compreender, testar e alterar partes menores do programa.', N'ED · 1º semestre · Modularizar reduz a quantidade de responsabilidades por trecho.', NULL, NULL),
        (224, N'fase28', N'Que informações aparecem no cabeçalho de uma função em C?', N'O tipo de retorno, o nome e a lista de parâmetros, que descrevem como a função recebe e devolve valores.', N'ED · 1º semestre · O cabeçalho apresenta a interface da função.', NULL, NULL),
        (225, N'fase28', N'O que acontece com um argumento escalar passado por valor em C?', N'Seu valor é copiado para o parâmetro; alterar esse parâmetro não altera diretamente a variável original do chamador.', N'ED · 1º semestre · A função trabalha com uma cópia do valor recebido.', NULL, NULL),
        (226, N'fase28', N'Como o escopo limita o uso de uma variável local em C?', N'Ela só pode ser referenciada dentro do escopo em que foi declarada, respeitando os blocos envolvidos.', N'ED · 1º semestre · O nome não fica disponível em todo o programa.', NULL, NULL),
        (227, N'fase28', N'Quais são os índices válidos de um vetor C com tamanho n?', N'De 0 até n menos 1; acessar fora desse intervalo ultrapassa os elementos reservados para o vetor.', N'ED · 1º semestre · O primeiro elemento usa índice zero.', NULL, NULL),
        (228, N'fase28', N'Por que uma string C precisa reservar espaço além dos caracteres visíveis?', N'Porque o caractere nulo de término, ''\0'', também ocupa uma posição no vetor de caracteres.', N'ED · 1º semestre · O terminador informa onde o texto termina.', NULL, NULL),
        (229, N'fase29', N'Quais recursos compõem o campo da TIC nas organizações?', N'Hardware, software, redes, bancos de dados e serviços associados, usados para apoiar processamento e comunicação de informações.', N'ED · 1º semestre · A TIC vai além dos computadores isolados.', NULL, NULL),
        (230, N'fase29', N'Por que acesso à internet e dispositivos é uma questão de inclusão digital?', N'Sem esses recursos, parte da população encontra barreiras para participar de serviços e atividades digitais.', N'ED · 1º semestre · Acesso desigual limita oportunidades.', NULL, NULL),
        (231, N'fase29', N'Para que serve analisar o impacto presente e futuro da TI em uma organização?', N'Para compreender se a tecnologia atua como suporte, sustenta operações críticas ou pode transformar sua posição estratégica.', N'ED · 1º semestre · Considere necessidades atuais e possibilidades futuras.', NULL, NULL),
        (232, N'fase29', N'Que responsabilidades da CPU sustentam o funcionamento de um computador?', N'Executar instruções, processar dados e coordenar operações dos demais componentes.', N'ED · 1º semestre · A CPU participa do processamento e do controle.', NULL, NULL),
        (233, N'fase29', N'O que faz um conjunto de elementos constituir um sistema?', N'A interação organizada entre suas partes em busca de um ou mais objetivos.', N'ED · 1º semestre · Partes sem relação não bastam para explicar um sistema.', NULL, NULL),
        (234, N'fase29', N'Como sistemas de informação apoiam as organizações?', N'Integram processos, organizam operações e oferecem informações úteis para decisões.', N'ED · 1º semestre · Relacione dados, processos e objetivos.', NULL, NULL),
        (235, N'fase29', N'Que tipo de contribuição um sistema de informações gerenciais oferece aos gestores?', N'Relatórios e informações sobre operações para apoiar planejamento, organização e controle.', N'ED · 1º semestre · O SIG transforma registros em acompanhamento gerencial.', NULL, NULL),
        (236, N'fase29', N'Por que um sistema de apoio à decisão é útil diante de incerteza?', N'Ele permite examinar dados e alternativas em situações complexas que não se resolvem apenas com rotinas padronizadas.', N'ED · 1º semestre · Nem toda decisão tem uma regra fixa pronta.', NULL, NULL),
        (237, N'fase29', N'Como um sistema especialista representa conhecimento de um domínio?', N'Usa uma base de conhecimento e regras para apoiar análises e conclusões em uma área específica.', N'ED · 1º semestre · Pense em conhecimento especializado organizado em regras.', NULL, NULL),
        (238, N'fase29', N'Como realidade aumentada e realidade virtual diferem na relação com o ambiente?', N'A realidade virtual substitui a percepção por um ambiente virtual; a aumentada sobrepõe informações digitais ao ambiente físico.', N'ED · 1º semestre · Observe se o mundo físico permanece como base.', NULL, NULL),
        (239, N'fase29', N'Por que experiência do usuário envolve mais que aparência visual?', N'Porque inclui como a pessoa entende, utiliza e percebe o produto, envolvendo usabilidade, acessibilidade e funcionalidade.', N'ED · 1º semestre · Uma tela bonita também precisa funcionar bem para quem a usa.', NULL, NULL),
        (240, N'fase29', N'Como conhecimento tácito e explícito se distinguem?', N'O tácito se liga à experiência e à prática; o explícito está estruturado e pode ser registrado e compartilhado mais diretamente.', N'ED · 1º semestre · Experiência pessoal e documentação são formas diferentes de conhecimento.', NULL, NULL),
        (241, N'fase29', N'Como linhas e colunas organizam uma planilha eletrônica?', N'Elas formam células identificáveis, nas quais dados e fórmulas podem ser registrados e relacionados.', N'ED · 1º semestre · A posição permite referenciar informações.', NULL, NULL),
        (242, N'fase29', N'Qual a diferença prática entre classificar e filtrar dados em uma planilha?', N'Classificar reorganiza a ordem dos registros; filtrar seleciona quais registros são exibidos segundo critérios.', N'ED · 1º semestre · Ordenar e selecionar são operações distintas.', NULL, NULL),
        (243, N'fase29', N'Por que referências de células são úteis em fórmulas?', N'Permitem calcular usando os valores de posições indicadas, relacionando informações sem reescrever cada valor na fórmula.', N'ED · 1º semestre · A fórmula acompanha os dados referenciados.', NULL, NULL),
        (244, N'fase29', N'Como ferramentas de produtividade apoiam tarefas de escritório?', N'Ajudam a organizar dados, calcular resultados, preparar documentos e apresentar informações de forma estruturada.', N'ED · 1º semestre · Escolha a ferramenta conforme a tarefa.', NULL, NULL),
        (245, N'bonus1', N'Bônus 01: O que é a ''Deep Web''?', N'A parte da internet que não é indexada por motores de busca como o Google.', N'Não é necessariamente ilegal, apenas oculta.', NULL, NULL),
        (246, N'bonus1', N'Bônus 01: O que foi o vírus ''ILOVEYOU'' (2000)?', N'Um dos maiores worms de e-mail da história que causou bilhões em prejuízos.', N'Engenharia social pura.', NULL, NULL),
        (247, N'bonus1', N'Bônus 01: O que é o Teste de Invasão (PenTest)?', N'Simular um ataque cibernético autorizado para encontrar falhas de segurança.', N'Feito por Hackers Éticos.', NULL, NULL),
        (248, N'bonus1', N'Bônus 01: Quem é o grupo ''Anonymous''?', N'Um coletivo descentralizado internacional de ativistas hackers (hacktivistas).', N'Usam a máscara de Guy Fawkes.', NULL, NULL),
        (249, N'bonus1', N'Bônus 01: Quem é Kevin Mitnick?', N'Um dos hackers mais famosos da história, especialista em Engenharia Social.', N'Chegou a ser o homem mais procurado do FBI.', NULL, NULL),
        (250, N'bonus1', N'Bônus 01: O que é uma vulnerabilidade ''Zero-Day''?', N'Uma falha de segurança recém-descoberta que os criadores do software ainda não conhecem e não corrigiram.', N'Dia-zero (nenhum tempo para consertar).', NULL, NULL),
        (251, N'bonus1', N'Bônus 01: Qual a diferença entre Malware e Vírus?', N'Malware é qualquer código malicioso. Vírus é um tipo de malware que se replica inserindo seu código em outros programas.', N'Todo vírus é um malware, mas nem todo malware é vírus.', NULL, NULL),
        (252, N'bonus1', N'Bônus 01: O que é um Cavalo de Troia (Trojan)?', N'Um malware disfarçado de software legítimo e inofensivo para enganar o usuário.', N'Inspirado na lenda grega.', NULL, NULL),
        (253, N'bonus1', N'Bônus 01: O que é Engenharia Social no hacking?', N'A arte de manipular psicologicamente as pessoas para que entreguem informações confidenciais.', N'O ''hackeamento'' do cérebro humano.', NULL, NULL),
        (254, N'bonus1', N'Bônus 01: Qual a diferença entre Black Hat e White Hat?', N'Black Hats invadem para roubar e destruir. White Hats (éticos) invadem para testar e proteger o sistema.', N'Chapéu preto (vilão) vs Chapéu branco (herói).', NULL, NULL),
        (255, N'bonus1', N'Bônus 01: O que é um programa de ''Bug Bounty''?', N'Empresas que pagam recompensas em dinheiro para hackers que encontrarem e reportarem falhas em seus sistemas.', N'Caçadores de recompensas digitais.', NULL, NULL),
        (256, N'bonus1', N'Bônus 01: O que significa CAPTCHA?', N'Completely Automated Public Turing test to tell Computers and Humans Apart (Teste para diferenciar humanos e robôs).', N'Aquelas imagens irritantes de semáforos.', NULL, NULL),
        (257, N'bonus1', N'Bônus 01: Como funciona uma VPN?', N'Cria um túnel criptografado entre você e a internet, ocultando seu IP e sua localização.', N'Virtual Private Network.', NULL, NULL),
        (258, N'bonus1', N'Bônus 01: O que é o navegador Tor?', N'Um navegador projetado para comunicação anônima, roteando o tráfego por vários servidores voluntários (nós).', N'Símbolo da cebola (The Onion Router).', NULL, NULL),
        (259, N'bonus1', N'Bônus 01: Quem criou o Bitcoin?', N'Uma pessoa ou grupo sob o pseudônimo de ''Satoshi Nakamoto''. A identidade real nunca foi descoberta.', N'Criado logo após a crise de 2008.', NULL, NULL),
        (260, N'bonus1', N'Bônus 01: O que foi o Stuxnet?', N'Um vírus de computador militar extremamente sofisticado, criado para sabotar usinas nucleares.', N'A primeira arma cibernética do mundo.', NULL, NULL),
        (261, N'bonus1', N'Bônus 01: O que foi o Morris Worm (1988)?', N'Um dos primeiros malwares distribuídos pela internet, que acidentalmente derrubou milhares de computadores.', N'Criado por um estudante para ''medir'' o tamanho da internet.', NULL, NULL),
        (262, N'bonus1', N'Bônus 01: O que foi o WannaCry (2017)?', N'Um ataque de ransomware global que infectou centenas de milhares de PCs exigindo resgate em Bitcoin.', N'Paralisou até os hospitais do Reino Unido.', NULL, NULL),
        (263, N'bonus1', N'Bônus 01: O que foi a Máquina Enigma?', N'Uma máquina de criptografia usada pelos nazistas na 2ª Guerra Mundial, quebrada pela equipe de Alan Turing.', N'Filme: O Jogo da Imitação.', NULL, NULL),
        (264, N'bonus1', N'Bônus 01: O que foi a ARPANET?', N'A rede de computadores financiada pelo departamento de defesa dos EUA que deu origem à Internet atual.', N'Avó da internet.', NULL, NULL),
        (265, N'bonus1', N'Bônus 01: Qual foi o primeiro ''Bug'' de computador real?', N'Uma mariposa (inseto/bug) real que ficou presa nos relés do computador Mark II em 1947.', N'Encontrada pela pioneira Grace Hopper.', NULL, NULL),
        (266, N'bonus1', N'Bônus 01: Quem foi Alan Turing?', N'Matemático britânico considerado o pai da ciência da computação e da Inteligência Artificial.', N'Criou o ''Teste de Turing''.', NULL, NULL),
        (267, N'bonus1', N'Bônus 01: Quem foi Ada Lovelace?', N'Matemática inglesa reconhecida como a primeira pessoa programadora da história (anos 1840).', N'Escreveu o primeiro algoritmo para a Máquina Analítica.', NULL, NULL),
        (268, N'bonus1', N'Bônus 01: Qual a arquitetura de Von Neumann?', N'O design base de quase todos os PCs modernos, separando CPU, memória e dispositivos de Entrada/Saída.', N'Conceito criado em 1945.', NULL, NULL),
        (269, N'bonus1', N'Bônus 01: Quem é Linus Torvalds?', N'O engenheiro de software finlandês que criou o núcleo (kernel) do sistema operacional Linux.', N'Também criou o sistema de versionamento Git.', NULL, NULL),
        (270, N'bonus1', N'Bônus 01: O que é o Konami Code?', N'Um código de trapaça famoso nos videogames: Cima, Cima, Baixo, Baixo, Esquerda, Direita, Esquerda, Direita, B, A.', N'O maior easter egg da cultura pop.', NULL, NULL),
        (271, N'bonus1', N'Bônus 01: O que é um ataque de Força Bruta?', N'Tentar adivinhar uma senha testando milhões de combinações possíveis até acertar.', N'Motivo pelo qual pedem senhas complexas.', NULL, NULL),
        (272, N'bonus1', N'Bônus 01: O que é Phreaking?', N'A exploração e hackeamento do sistema de telecomunicações e linhas telefônicas antigas.', N'Steve Jobs e Wozniak vendiam as ''Blue Boxes'' de phreaking.', NULL, NULL),
        (273, N'bonus1', N'Bônus 01: O que significa a mensagem de erro HTTP 404?', N'Indica que o cliente conseguiu se comunicar com o servidor, mas o servidor não encontrou o arquivo ou página solicitada.', N'Page Not Found.', NULL, NULL),
        (274, N'bonus1', N'Bônus 01: O que significa a mensagem de erro HTTP 418?', N'I''m a teapot (Eu sou um bule de chá). É uma piada oficial de primeiro de abril criada no protocolo HTTP em 1998.', N'O easter egg oficial da web.', NULL, NULL),
        (275, N'fase6', N'O que é a estrutura de dados Pilha (Stack)?', N'O último elemento a entrar é o primeiro a sair (LIFO - Last In, First Out).', N'Disciplina: Algoritmos e Dados. Ex: Botão ''Desfazer''.', NULL, NULL),
        (276, N'fase6', N'O que é a Fila (Queue)?', N'O primeiro elemento a entrar é o primeiro a sair (FIFO - First In, First Out).', N'Ex: Fila de impressão numa impressora.', NULL, NULL),
        (277, N'fase6', N'O que é um Algoritmo de Ordenação?', N'Um método para organizar dados numa sequência lógica (ex: crescente ou decrescente).', N'Ex: Bubble Sort, Quick Sort.', NULL, NULL),
        (278, N'fase6', N'O que é a Complexidade ''Big O''?', N'Uma notação matemática para medir a eficiência de um algoritmo (tempo e memória) à medida que os dados crescem.', N'O(1) é excelente, O(n²) é muito lento.', NULL, NULL),
        (279, N'fase6', N'O que é uma Árvore Binária?', N'Estrutura de dados onde cada nó tem no máximo dois filhos (ramo esquerdo e direito).', N'Excelente para pesquisas rápidas.', NULL, NULL),
        (280, N'fase6', N'O que é uma Lista Ligada (Linked List)?', N'Uma sequência de elementos onde cada nó contém um valor e um ''ponteiro'' para o próximo nó da lista.', N'Não usa blocos de memória contíguos como os Arrays.', NULL, NULL),
        (281, N'fase6', N'O que é uma Tabela de Dispersão (Hash Table)?', N'Estrutura que mapeia chaves para valores usando uma função matemática (Hash), permitindo pesquisas ultra-rápidas.', N'A base dos Dicionários em Python.', NULL, NULL),
        (282, N'fase6', N'Como funciona a Pesquisa Binária (Binary Search)?', N'Procura um item dividindo repetidamente uma lista ORDENADA pela metade até encontrar o valor.', N'Muito mais rápido que olhar um por um.', NULL, NULL),
        (283, N'fase6', N'Como funciona a Pesquisa Linear?', N'Percorre a lista elemento por elemento, do início ao fim, até encontrar o que procura.', N'Simples, mas lento em listas gigantes (O(n)).', NULL, NULL),
        (284, N'fase6', N'O que é a Recursividade?', N'É quando uma função se invoca a si mesma repetidamente até atingir uma condição de paragem.', N'Muito usada para calcular fatoriais e percorrer árvores.', NULL, NULL),
        (285, N'fase6', N'Como funciona o algoritmo Bubble Sort?', N'Compara pares vizinhos e troca-os se estiverem na ordem errada, fazendo o maior valor ''flutuar'' para o final.', N'O algoritmo de ordenação mais simples e menos eficiente.', NULL, NULL),
        (286, N'fase6', N'O que é o algoritmo Merge Sort?', N'Usa a técnica ''Dividir para Conquistar'', cortando a lista em metades e depois unindo-as já ordenadas.', N'Muito eficiente e estável (O(n log n)).', NULL, NULL),
        (287, N'fase6', N'O que é o Quick Sort?', N'Escolhe um elemento como ''Pivô'' e particiona a lista, colocando os menores à esquerda e os maiores à direita.', N'O algoritmo de ordenação mais famoso do mundo.', NULL, NULL),
        (288, N'fase6', N'O que significa um algoritmo ter complexidade O(1)?', N'Significa ''Tempo Constante''. O algoritmo demora exatamente o mesmo tempo, quer a lista tenha 10 ou 1 milhão de itens.', N'O Santo Graal da eficiência.', NULL, NULL),
        (289, N'fase6', N'O que é a Programação Dinâmica (Memoization)?', N'Técnica de otimização que guarda os resultados de funções pesadas numa cache para não ter de os calcular de novo.', N'Memória salva processamento.', NULL, NULL),
        (290, N'fase6', N'O que é um Algoritmo Guloso (Greedy)?', N'Toma a melhor decisão local disponível no momento imediato, na esperança de que leve à melhor solução global.', N'Nem sempre entrega o cenário perfeito, mas é rápido.', NULL, NULL),
        (291, N'fase6', N'Em Python, o que é uma Tupla (Tuple)?', N'Uma coleção de itens ordenados, mas que é IMUTÁVEL (não pode ser alterada depois de criada).', N'Usa parênteses (). Ex: coordenadas = (x, y)', NULL, NULL),
        (292, N'fase6', N'Em Python, o que é um Conjunto (Set)?', N'Uma coleção não ordenada de itens ÚNICOS (não permite valores duplicados).', N'Usa chaves {}. Excelente para remover repetições.', NULL, NULL),
        (293, N'fase6', N'Qual é a estrutura LIFO?', N'Last In, First Out (Último a entrar, primeiro a sair).', N'É a regra da estrutura de Pilha (Stack).', NULL, NULL),
        (294, N'fase6', N'Qual é a estrutura FIFO?', N'First In, First Out (Primeiro a entrar, primeiro a sair).', N'É a regra da estrutura de Fila (Queue).', NULL, NULL),
        (295, N'fase7', N'O que são Ponteiros (Pointers) em C?', N'Variáveis especiais que, em vez de guardar um valor, guardam o ENDEREÇO DE MEMÓRIA de outra variável.', N'Disciplina: Programação em C.', NULL, NULL),
        (296, N'fase7', N'Para que serve a biblioteca <stdio.h>?', N'Standard Input/Output. É obrigatória para usar as funções básicas de entrada e saída, como printf e scanf.', N'O cabeçalho (header) mais famoso do C.', NULL, NULL),
        (297, N'fase7', N'Para que serve a função malloc()?', N'Memory Allocation. Serve para alocar blocos de memória dinamicamente enquanto o programa está correndo.', N'Pede memória emprestada ao sistema.', NULL, NULL),
        (298, N'fase7', N'O que a função free() faz?', N'Liberta a memória que foi alocada dinamicamente com o malloc(), devolvendo-a ao sistema operacional.', N'Evita o Memory Leak (Fuga de Memória).', NULL, NULL),
        (299, N'fase7', N'O que é um Struct em C?', N'Uma estrutura que agrupa diferentes tipos de variáveis sob um único nome.', N'É o ''avô'' das Classes da Orientação a Objetos.', NULL, NULL),
        (300, N'fase7', N'Como declaramos o tipo ''String'' em C?', N'O C não tem um tipo ''String'' nativo. Usamos um Array (vetor) de caracteres (char).', N'Ex: char nome[50];', NULL, NULL);
    INSERT INTO flashcards (id, codigo_fase, frente, verso, dica, opcoes, correta) VALUES
        (301, N'fase7', N'O que faz o operador ''&'' numa variável em C?', N'Retorna o endereço de memória físico onde essa variável está guardada.', N'Muito usado dentro do scanf().', NULL, NULL),
        (302, N'fase7', N'O que faz o operador ''*'' associado a um ponteiro?', N'Faz a ''desreferenciação'', acedendo ao valor que está guardado naquele endereço de memória.', N'Lê o conteúdo apontado.', NULL, NULL),
        (303, N'fase7', N'O que faz a função printf()?', N'Imprime texto formatado e valores de variáveis na tela (console).', N'Print Formatted.', NULL, NULL),
        (304, N'fase7', N'O que faz a função scanf()?', N'Lê os dados formatados introduzidos pelo usuário através do teclado.', N'Scan Formatted.', NULL, NULL),
        (305, N'fase7', N'O que é um Array (Vetor) em C?', N'Uma estrutura que armazena uma coleção sequencial de elementos do MESMO TIPO de dados.', N'A primeira posição é sempre o índice [0].', NULL, NULL),
        (306, N'fase7', N'O que é uma Matriz em C?', N'Um Array bidimensional (ou com mais dimensões), organizado em linhas e colunas.', N'Ex: int matriz[3][3];', NULL, NULL),
        (307, N'fase7', N'O que é o GCC?', N'GNU Compiler Collection. É o compilador mais utilizado no mundo para transformar código C em linguagem máquina.', N'Traduz o texto para binário.', NULL, NULL),
        (308, N'fase7', N'Para que serve a diretiva #define?', N'Usada para criar macros ou definir constantes globais que não mudam durante o programa.', N'Ex: #define PI 3.1415', NULL, NULL),
        (309, N'fase7', N'O que marca o fim de uma string (char array) em C?', N'O caractere nulo (Null Terminator), representado por ''\0''.', N'Diz ao programa onde a frase termina.', NULL, NULL),
        (310, N'fase7', N'Como funciona o loop ''do-while''?', N'Executa o bloco de código PELO MENOS UMA VEZ antes de verificar se a condição é verdadeira.', N'A verificação fica no final.', NULL, NULL),
        (311, N'fase7', N'Para que serve o comando ''switch-case''?', N'Substitui uma longa cadeia de ''if-else'', permitindo testar o valor de uma variável contra vários casos específicos.', N'Ideal para menus de opções.', NULL, NULL),
        (312, N'fase7', N'Para que serve a palavra-chave ''break'' num switch?', N'Para interromper a execução e sair do bloco switch; caso contrário, executará os casos seguintes em cascata.', N'Trava a cascata.', NULL, NULL),
        (313, N'fase7', N'O que é Passagem por Valor numa função?', N'A função recebe apenas uma CÓPIA da variável. Alterar o valor dentro da função não afeta a variável original.', N'Seguro, mas gasta memória duplicada.', NULL, NULL),
        (314, N'fase7', N'O que é Passagem por Referência numa função?', N'A função recebe o PONTEIRO (endereço) da variável original. Qualquer alteração afeta os dados reais do programa.', N'Rápido e afeta a raiz do dado.', NULL, NULL),
        (315, N'fase8', N'O que são Requisitos Funcionais?', N'Descrevem o que o sistema DEVE FAZER (as suas funções). Ex: ''O sistema deve emitir faturas''.', N'Disciplina: Análise e Eng. de Sistemas.', NULL, NULL),
        (316, N'fase8', N'O que são Requisitos Não Funcionais?', N'Descrevem COMO o sistema deve ser, as suas qualidades e restrições. Ex: ''A tela deve carregar em 1 segundo''.', N'Focam em performance, segurança, design.', NULL, NULL),
        (317, N'fase8', N'O que é um Diagrama de Casos de Uso (UML)?', N'Um desenho que mostra as interações entre os Usuários (Atores) e o Sistema.', N'Foca nas ações principais do ponto de vista do usuário.', NULL, NULL),
        (318, N'fase8', N'Qual a diferença entre a Metodologia Ágil e o modelo Cascata (Waterfall)?', N'O Ágil é flexível e iterativo (entregas parciais). O Cascata é linear, rígido e só testa no final.', N'Ágil adapta-se; Cascata planeia tudo antes.', NULL, NULL),
        (319, N'fase8', N'O que é um Diagrama de Classes?', N'Diagrama estrutural da UML que mapeia a estrutura estática do sistema (classes, atributos, métodos e heranças).', N'A planta-baixa dos programadores Orientados a Objetos.', NULL, NULL),
        (320, N'fase8', N'Quais são as fases clássicas do Ciclo de Vida do Software?', N'1. Levantamento de Requisitos; 2. Análise/Design; 3. Implementação (Código); 4. Testes; 5. Implantação; 6. Manutenção.', N'O passo a passo para criar qualquer sistema.', NULL, NULL),
        (321, N'fase8', N'O que faz a Engenharia de Requisitos?', N'É a disciplina que foca em descobrir, documentar e manter as regras de negócio e necessidades do cliente.', N'A ponte entre o cliente e os programadores.', NULL, NULL),
        (322, N'fase8', N'O que é o Diagrama de Sequência (UML)?', N'Mostra como os objetos interagem num determinado cenário ao longo de uma linha de tempo temporal.', N'Foco na troca de mensagens cronológicas.', NULL, NULL),
        (323, N'fase8', N'O que é o Diagrama de Atividades (UML)?', N'Semelhante a um fluxograma, modela o fluxo de controle de uma atividade para outra dentro do sistema.', N'Mostra o caminho da lógica, passo a passo.', NULL, NULL),
        (324, N'fase8', N'O que é o Framework Scrum?', N'Uma estrutura de trabalho ágil focada em equipes pequenas que realizam entregas de software em ciclos curtos (Sprints).', N'A metodologia ágil mais famosa.', NULL, NULL),
        (325, N'fase8', N'O que é a metodologia Kanban?', N'Método de gestão visual do fluxo de trabalho contínuo, usando um quadro com colunas (A Fazer, Fazendo, Feito).', N'Criado originalmente pela Toyota.', NULL, NULL),
        (326, N'fase8', N'O que é o XP (Extreme Programming)?', N'Metodologia ágil extremamente focada na excelência técnica, exigindo testes contínuos e Programação em Par (Pair Programming).', N'Foco pesado na qualidade do código.', NULL, NULL),
        (327, N'fase8', N'O que é o padrão MVC?', N'Model (Dados/Regras), View (Interface Visual) e Controller (Mediador). Um padrão de arquitetura que separa responsabilidades.', N'Não mistura HTML com acessos ao banco de dados.', NULL, NULL),
        (328, N'fase8', N'O que são Testes Unitários?', N'Testes de baixo nível que verificam se a menor parte testável de um código (uma função ou método) funciona corretamente de forma isolada.', N'Testa o tijolo antes de construir o muro.', NULL, NULL),
        (329, N'fase8', N'O que são Testes de Integração?', N'Testes que verificam se os diferentes módulos, classes ou bancos de dados funcionam bem quando ligados entre si.', N'Testa a junção dos tijolos.', NULL, NULL),
        (330, N'fase8', N'O que é o Teste de Aceitação do Usuário (UAT)?', N'A fase final onde o cliente ou o usuário real testa o sistema para validar se atende aos requisitos de negócio.', N'A validação final antes de ir para produção.', NULL, NULL),
        (331, N'fase8', N'O que é Refatoração (Refactoring)?', N'O processo de reescrever e limpar o código-fonte para melhorar a sua estrutura interna, sem alterar o seu comportamento externo.', N'Arrumar a casa por dentro.', NULL, NULL),
        (332, N'fase8', N'O que é a Dívida Técnica (Technical Debt)?', N'O custo futuro acumulado ao escolhermos soluções de código fáceis e rápidas agora, em vez da abordagem correta e otimizada.', N'Fazer rápido hoje significa ter de refazer amanhã.', NULL, NULL),
        (333, N'fase8', N'O que são os Padrões de Projeto (Design Patterns)?', N'Soluções típicas, testadas e reutilizáveis para resolver problemas comuns no design de software.', N'Ex: Singleton, Factory, Observer.', NULL, NULL),
        (334, N'fase8', N'O que significa a sigla UML?', N'Unified Modeling Language (Linguagem de Modelação Unificada). É a linguagem visual padrão para documentar sistemas de software.', N'O ''idioma'' internacional dos diagramas de sistemas.', NULL, NULL),
        (335, N'fase8', N'Por que a UML pode apoiar projetos implementados em linguagens diferentes?', N'Porque expressa modelos e decisões do sistema de modo independente da linguagem usada para programá-lo.', N'ED · 2º semestre · Modelar uma solução e codificá-la são atividades relacionadas, mas distintas.', NULL, NULL),
        (336, N'fase8', N'Como os requisitos ajudam a validar um sistema depois de construído?', N'Eles registram expectativas aceitas e oferecem uma referência para verificar se as funcionalidades entregues atendem ao que foi solicitado.', N'ED · 2º semestre · A avaliação precisa de um critério conhecido.', NULL, NULL),
        (337, N'fase8', N'Como um protótipo contribui para esclarecer uma funcionalidade?', N'Ele apresenta um esboço que facilita a visualização e a discussão com o usuário, mesmo sem ter toda a lógica ou persistência implementada.', N'ED · 2º semestre · Experimentar a ideia pode revelar mal-entendidos.', NULL, NULL),
        (338, N'fase8', N'O que muda quando a análise do sistema avança para o projeto?', N'O entendimento do problema é refinado em decisões de solução, incluindo estrutura, algoritmos, interfaces e escolhas de implementação.', N'ED · 2º semestre · Passe do entendimento para a organização da solução.', NULL, NULL),
        (339, N'fase8', N'Como casos de uso ajudam a comunicar a visão geral de um sistema?', N'Eles mostram as funcionalidades oferecidas e os perfis externos que interagem com elas, apoiando a discussão do escopo.', N'ED · 2º semestre · Observe quem usa qual serviço.', NULL, NULL),
        (340, N'fase8', N'Quando a inclusão entre casos de uso é útil na modelagem?', N'Quando um caso de uso incorpora comportamento obrigatório representado por outro caso de uso, permitindo explicitar esse reaproveitamento.', N'ED · 2º semestre · Pense em comportamento incluído, não apenas em ordem temporal.', NULL, NULL),
        (341, N'fase8', N'Que aspecto do sistema um diagrama de classes destaca?', N'A estrutura das entidades e seus relacionamentos, mostrando como as responsabilidades e informações estão organizadas.', N'ED · 2º semestre · Ele descreve a estrutura, não a sequência completa de execução.', NULL, NULL),
        (342, N'fase8', N'Como atributos e operações se distinguem na representação de uma classe?', N'Atributos representam características ou dados; operações representam comportamentos e podem indicar parâmetros e retorno.', N'ED · 2º semestre · Estado e comportamento são dimensões complementares.', NULL, NULL),
        (343, N'fase8', N'Por que uma classe abstrata não representa um objeto criado diretamente?', N'Ela serve como uma definição geral a ser especializada; a instanciação direta é reservada a classes concretas.', N'ED · 2º semestre · Uma abstração pode orientar outras classes.', NULL, NULL),
        (344, N'fase8', N'O que uma dependência indica entre elementos de um modelo?', N'Que um elemento utiliza informações ou serviços de outro e pode ser afetado por mudanças nesse fornecedor.', N'ED · 2º semestre · A relação tem uma direção.', NULL, NULL),
        (345, N'fase8', N'Qual pergunta um diagrama de sequência ajuda a responder?', N'Como participantes trocam mensagens ao longo de uma interação, esclarecendo a ordem e a colaboração necessárias ao comportamento.', N'ED · 2º semestre · Acompanhe quem chama quem.', NULL, NULL),
        (346, N'fase8', N'O que o foco de controle mostra em uma linha de vida?', N'O intervalo em que o participante está executando uma ação ou operação na interação representada.', N'ED · 2º semestre · Observe a atividade dentro da linha de vida.', NULL, NULL),
        (347, N'fase8', N'Como decisão e bifurcação se diferenciam em um diagrama de atividades?', N'A decisão seleciona caminhos por condições; a bifurcação separa fluxos que podem ocorrer em paralelo.', N'ED · 2º semestre · Escolher um caminho é diferente de iniciar trabalhos paralelos.', NULL, NULL),
        (348, N'fase8', N'Quando um diagrama de máquina de estados é especialmente útil?', N'Quando importa compreender como um objeto muda de situação ao longo de sua vida em resposta a eventos.', N'ED · 2º semestre · Pense em estados e transições de um mesmo objeto.', NULL, NULL),
        (349, N'fase8', N'Como uma iteração contribui para o desenvolvimento de software?', N'Ela permite planejar, construir, testar e avaliar uma parte ou versão da solução, usando o aprendizado para orientar refinamentos.', N'ED · 2º semestre · Cada ciclo pode gerar aprendizado e uma versão avaliável.', NULL, NULL),
        (350, N'fase8', N'Por que a manutenção continua após a implantação?', N'Porque é necessário corrigir problemas, acompanhar desempenho e segurança e ajustar o sistema conforme surgem necessidades dos usuários.', N'ED · 2º semestre · A entrega inicia também uma fase de acompanhamento.', NULL, NULL),
        (351, N'fase9', N'O que é um endereço IP?', N'Identificador numérico exclusivo atribuído a cada dispositivo conectado numa rede de computadores.', N'Disciplina: Redes e Sistemas Distribuídos.', NULL, NULL),
        (352, N'fase9', N'Para que serve o DNS?', N'Domain Name System. Traduz nomes de domínios fáceis (google.com) para endereços IP numéricos.', N'A lista telefônica da Web.', NULL, NULL),
        (353, N'fase9', N'Qual a diferença entre os protocolos TCP e UDP?', N'TCP garante a entrega e ordem dos dados. O UDP é muito mais rápido, mas não verifica se o dado chegou (não é confiável).', N'TCP para arquivos. UDP para jogos/streaming.', NULL, NULL),
        (354, N'fase9', N'O que é um Sistema Distribuído?', N'Vários computadores independentes na rede a trabalharem juntos para parecerem um único sistema coeso para o usuário.', N'A base arquitetural da Nuvem (Cloud).', NULL, NULL),
        (355, N'fase9', N'O que faz um Load Balancer (Balanceador de Carga)?', N'Distribui o tráfego de rede e as requisições igualmente entre vários servidores para evitar sobrecargas e quedas.', N'Evita que um único servidor suporte todo o peso.', NULL, NULL),
        (356, N'fase9', N'O que é um endereço MAC?', N'O endereço físico gravado permanentemente na placa de rede pelo fabricante. Não muda com a internet.', N'Media Access Control.', NULL, NULL),
        (357, N'fase9', N'O que é o Modelo OSI?', N'Um modelo de referência conceitual dividido em 7 camadas (Física, Ligação, Rede, Transporte, Sessão, Apresentação, Aplicação).', N'Cria um padrão de comunicação universal.', NULL, NULL),
        (358, N'fase9', N'O que é o Modelo TCP/IP?', N'O modelo prático que realmente move a internet, condensando o modelo OSI em apenas 4 camadas.', N'Aplicação, Transporte, Internet e Acesso à Rede.', NULL, NULL),
        (359, N'fase9', N'Qual a diferença entre HTTP e HTTPS?', N'O HTTPS utiliza a camada de segurança SSL/TLS, encriptando todo o tráfego para que não possa ser intercetado.', N'Hyper Text Transfer Protocol (Secure).', NULL, NULL),
        (360, N'fase9', N'O que é o protocolo FTP?', N'File Transfer Protocol. Usado historicamente para transferir arquivos de um computador para um servidor na rede.', N'Transferência pura de arquivos.', NULL, NULL),
        (361, N'fase9', N'Para que serve o SSH?', N'Secure Shell. Protocolo de rede que permite ligar-se de forma encriptada e segura a servidores remotos através de um terminal em linha de comando.', N'Acesso remoto seguro a servidores Linux.', NULL, NULL),
        (362, N'fase9', N'Quais são as portas padrão para os protocolos HTTP e HTTPS?', N'HTTP corre na porta 80. HTTPS corre na porta segura 443.', N'Portas essenciais do Firewall.', NULL, NULL),
        (363, N'fase9', N'O que faz um Router (Roteador)?', N'É o equipamento de rede que envia os pacotes de dados entre diferentes redes (ex: da sua rede local para a Internet global).', N'O ''carteiro'' da internet.', NULL, NULL),
        (364, N'fase9', N'O que faz um Switch?', N'Equipamento que liga vários dispositivos dentro de uma mesma rede local (LAN), enviando os dados apenas para o dispositivo correto (usando o MAC).', N'Diferente do Hub, que enviava para todos.', NULL, NULL),
        (365, N'fase9', N'Para que serve um Firewall numa rede?', N'Filtra o tráfego de entrada e de saída com base num conjunto de regras de segurança, bloqueando ligações não autorizadas.', N'A barreira de segurança da rede.', NULL, NULL),
        (366, N'fase9', N'O que é uma VPN?', N'Virtual Private Network. Cria um túnel encriptado na internet pública, simulando uma ligação privada e segura à rede da empresa.', N'Segurança e privacidade remotas.', NULL, NULL),
        (367, N'fase9', N'Para que serve a Máscara de Sub-rede (Subnet Mask)?', N'Divide um grande bloco de endereços IP em redes menores, indicando que parte do IP é a rede e que parte é a máquina.', N'Ex: 255.255.255.0', NULL, NULL),
        (368, N'fase9', N'O que faz o protocolo DHCP?', N'Dynamic Host Configuration Protocol. Atribui automaticamente endereços IP, gateways e DNS aos computadores quando estes se ligam à rede.', N'Imagine configurar o IP de cada celular manualmente!', NULL, NULL),
        (369, N'fase9', N'O que testa o comando Ping?', N'Envia pacotes ICMP para um IP de destino e aguarda a resposta, medindo o tempo de ida e volta para verificar se a máquina está online.', N'Teste básico de conectividade.', NULL, NULL),
        (370, N'fase9', N'Na rede, o que é a Latência (vulgo ''Lag'')?', N'O tempo que um pacote de dados demora a viajar do ponto A (o seu PC) até ao ponto B (Servidor) e voltar.', N'Baixa latência = resposta rápida.', NULL, NULL),
        (371, N'fase9', N'Quais elementos precisam atuar juntos para que equipamentos compartilhem dados em rede?', N'Dispositivos capazes de comunicar, meios de transmissão que os conectem e protocolos que estabeleçam como a troca ocorre.', N'AVA · 2º semestre · Equipamento, caminho e regras.', NULL, NULL),
        (372, N'fase9', N'Por que uma videoconferência pode sofrer mesmo com boa capacidade de transmissão?', N'Porque aplicações em tempo real também são sensíveis a atraso e jitter, a variação desse atraso, que afetam a continuidade da comunicação.', N'AVA · 2º semestre · Volume de dados não é a única medida de qualidade.', NULL, NULL),
        (373, N'fase9', N'O que o throughput mostra sobre uma conexão?', N'A taxa de transferência efetivamente alcançada, considerando fatores como congestionamento, perdas e limitações dos equipamentos.', N'AVA · 2º semestre · Compare a capacidade anunciada com o resultado real.', NULL, NULL),
        (374, N'fase9', N'Por que disponibilidade de rede exige pensar em contingência?', N'Porque componentes podem falhar e uma alternativa de operação ajuda a manter o serviço quando o caminho principal deixa de funcionar.', N'AVA · 2º semestre · Planeje a continuidade antes da falha.', NULL, NULL),
        (375, N'fase9', N'Como a divisão em camadas facilita a investigação de uma falha de comunicação?', N'Ela organiza responsabilidades, permitindo localizar se o problema envolve sinal, enlace, endereçamento ou outra função da comunicação.', N'AVA · 2º semestre · Investigue a função afetada.', NULL, NULL),
        (376, N'fase9', N'Quais aspectos da comunicação pertencem à camada física?', N'Sinais, meios, conectores e características elétricas ou mecânicas necessárias à transmissão de bits.', N'AVA · 2º semestre · Pense no transporte do sinal.', NULL, NULL),
        (377, N'fase9', N'Qual diferença entre store-and-forward e cut-through no encaminhamento de quadros?', N'Store-and-forward recebe o quadro completo antes de encaminhá-lo e pode verificar erros; cut-through começa a encaminhar após ler o destino, reduzindo a espera.', N'AVA · 2º semestre · O momento de encaminhar cria um compromisso entre espera e verificação.', NULL, NULL),
        (378, N'fase9', N'Como a escolha entre TCP e UDP se relaciona com as necessidades da aplicação?', N'TCP fornece mecanismos de entrega confiável e ordenada; UDP envia datagramas sem essas garantias, deixando à aplicação lidar com perdas e ordem quando necessário.', N'AVA · 2º semestre · Considere confiabilidade e os mecanismos que cada aplicação necessita.', NULL, NULL),
        (379, N'fase9', N'Por que IP, MAC e porta não substituem uns aos outros?', N'Eles identificam aspectos distintos: IP atua no endereçamento entre redes, MAC no enlace e porta na identificação do serviço ou processo de comunicação.', N'AVA · 2º semestre · Cada identificador tem seu contexto.', NULL, NULL),
        (380, N'fase9', N'Como a notação decimal de um endereço IPv4 representa seus bits?', N'Ela separa os 32 bits em quatro grupos de oito, exibidos como números de 0 a 255 separados por pontos.', N'AVA · 2º semestre · Cada número representa um octeto.', NULL, NULL),
        (381, N'fase9', N'Como a máscara de sub-rede ajuda a interpretar um IPv4?', N'Ela indica quais bits pertencem ao prefixo de rede e sub-rede e quais identificam hosts dentro desse grupo.', N'AVA · 2º semestre · Bits 1 marcam o prefixo; bits 0 marcam a parte de host.', NULL, NULL),
        (382, N'fase9', N'Como uma VLAN permite separar equipamentos ligados ao mesmo switch?', N'Ela organiza redes lógicas distintas no mesmo equipamento físico, separando os grupos; a comunicação entre VLANs exige roteamento apropriado.', N'AVA · 2º semestre · A divisão lógica não depende apenas do cabo.', NULL, NULL),
        (383, N'fase9', N'O que faz um conjunto de computadores ser percebido como um sistema distribuído?', N'Os computadores cooperam por uma rede e oferecem um serviço coerente ao usuário, embora existam componentes independentes por trás dele.', N'AVA · 2º semestre · Várias partes podem apresentar um serviço integrado.', NULL, NULL),
        (384, N'fase9', N'Como os nós de um sistema distribuído coordenam suas tarefas?', N'Eles trocam mensagens pela rede para compartilhar informações e organizar a execução, podendo representar máquinas ou processos.', N'AVA · 2º semestre · A comunicação faz a cooperação acontecer.', NULL, NULL),
        (385, N'fase9', N'Por que falhas independentes são um desafio em sistemas distribuídos?', N'Uma parte pode falhar enquanto outras continuam operando, exigindo que o sistema detecte e trate essa situação sem presumir uma falha total.', N'AVA · 2º semestre · Nem todos os componentes têm o mesmo estado ao mesmo tempo.', NULL, NULL),
        (386, N'fase9', N'Por que réplicas podem apresentar dados diferentes por um breve período?', N'A atualização precisa se propagar pela rede; durante esse intervalo, uma réplica pode ainda não ter recebido a alteração processada pelo líder.', N'AVA · 2º semestre · Replicação envolve tempo de comunicação.', NULL, NULL),
        (387, N'fase10', N'O que é o Teste de Turing?', N'Um teste proposto por Alan Turing para verificar se uma máquina consegue exibir um comportamento inteligente indistinguível de um humano.', N'Disciplina: Inteligência Artificial.', NULL, NULL),
        (388, N'fase10', N'O que são Agentes Inteligentes em IA?', N'Sistemas (software ou hardware) que percebem o ambiente através de sensores e agem para maximizar a hipótese de sucesso dos seus objetivos.', N'Ex: Um robô aspirador de pó.', NULL, NULL),
        (389, N'fase10', N'O que é uma Heurística na IA?', N'Uma ''regra de ouro'' ou atalho mental usado pela IA para encontrar soluções boas o suficiente num tempo muito rápido, sem garantir a perfeição absoluta.', N'Troca perfeição por velocidade.', NULL, NULL),
        (390, N'fase10', N'O que é o PLN (Processamento de Linguagem Natural)?', N'Área da IA focada em ensinar as máquinas a compreender, interpretar e gerar a linguagem humana (texto e fala).', N'Como o ChatGPT ou a Alexa funcionam.', NULL, NULL),
        (391, N'fase10', N'Qual a diferença entre Inovação Incremental e Disruptiva?', N'Incremental melhora algo que já existe (iPhone 14 para 15). Disruptiva cria um novo mercado, matando o anterior (Netflix vs Blockbuster).', N'Evolução vs Revolução.', NULL, NULL),
        (392, N'fase10', N'O que é o Machine Learning (Aprendizado de Máquina)?', N'Subárea da IA onde os sistemas aprendem a identificar padrões em grandes volumes de dados, sem serem explicitamente programados passo a passo.', N'A máquina cria a sua própria lógica.', NULL, NULL),
        (393, N'fase10', N'O que é o Deep Learning (Aprendizado Profundo)?', N'Uma evolução do Machine Learning baseada em Redes Neurais Artificiais profundas (com várias camadas ocultas) para lidar com dados muito complexos.', N'A base do reconhecimento facial moderno.', NULL, NULL),
        (394, N'fase10', N'O que são Redes Neurais Artificiais?', N'Algoritmos matemáticos divididos em nós (neurônios) e camadas (Input, Ocultas, Output), biologicamente inspirados no cérebro humano.', N'Mimetizam as sinapses cerebrais.', NULL, NULL),
        (395, N'fase10', N'Como funciona o Aprendizado Supervisionado?', N'O modelo de IA é treinado recebendo os dados de exemplo E o ''gabarito'' com a resposta correta (dados rotulados).', N'Existe um supervisor a dizer à IA o que é certo.', NULL, NULL),
        (396, N'fase10', N'O que é o Aprendizado Não Supervisionado?', N'O modelo recebe dados brutos sem rótulos ou categorias, e tem de descobrir padrões ou agrupar informações sozinho (Clustering).', N'A IA tenta encontrar lógica no caos sozinha.', NULL, NULL),
        (397, N'fase10', N'Como funciona o Aprendizado por Reforço (Reinforcement Learning)?', N'A IA aprende por tentativa e erro dentro de um ambiente, recebendo ''recompensas'' ao acertar e ''punições'' ao errar.', N'Como treinar um cão de estimação.', NULL, NULL),
        (398, N'fase10', N'Na IA, o que é o erro de Overfitting?', N'Quando o modelo de IA ''decora'' viciosamente os dados de treino, acertando tudo no laboratório, mas errando gravemente quando lida com dados novos reais.', N'Falta de capacidade de generalização.', NULL, NULL),
        (399, N'fase10', N'O que é um Algoritmo de Classificação?', N'Um algoritmo que prevê uma etiqueta ou categoria (Variável Discreta). Ex: Dizer se um e-mail é ''Spam'' ou ''Não Spam''.', N'Divide os dados em caixas.', NULL, NULL),
        (400, N'fase10', N'O que é um Algoritmo de Regressão?', N'Um algoritmo que prevê um número ou valor contínuo baseado em tendências históricas. Ex: Prever o preço de uma casa no futuro.', N'Desenha uma linha de tendência.', NULL, NULL);
    INSERT INTO flashcards (id, codigo_fase, frente, verso, dica, opcoes, correta) VALUES
        (401, N'fase10', N'O que estuda a Visão Computacional?', N'O campo da IA focado em permitir que computadores extraiam informações e entendam imagens digitais e vídeos do mundo real.', N'Como os carros da Tesla conduzem sozinhos.', NULL, NULL),
        (402, N'fase10', N'O que é um Chatbot?', N'Um programa de computador projetado para simular conversas com usuários humanos, geralmente suportado por árvores de decisão ou PNL.', N'Atendimento automatizado.', NULL, NULL),
        (403, N'fase10', N'O que é o Viés Algorítmico (Bias)?', N'Quando a IA herda e reproduz preconceitos e discriminações raciais ou sociais devido à má qualidade dos dados usados para a treinar.', N'A máquina apenas reflete os defeitos da sociedade.', NULL, NULL),
        (404, N'fase10', N'O que significa o conceito de Big Data?', N'O processamento e armazenamento de volumes de dados tão gigantescos, rápidos e complexos (Os 3 Vs) que os bancos de dados tradicionais não suportam.', N'Volume, Velocidade e Variedade.', NULL, NULL),
        (405, N'fase10', N'O que é a Mineração de Dados (Data Mining)?', N'A exploração e análise de bancos de dados colossais para descobrir padrões ocultos, correlações ou anomalias valiosas para o negócio.', N'Extrair ouro comercial dos dados.', NULL, NULL),
        (406, N'fase10', N'O que significa a sigla LLM na IA moderna?', N'Large Language Model (Grande Modelo de Linguagem). IAs de processamento de linguagem treinadas com terabytes de texto da internet.', N'A tecnologia base do ChatGPT.', NULL, NULL),
        (407, N'fase30', N'Como a industrialização se relaciona com a crise ambiental estudada na disciplina?', N'Ela transformou a produção e a vida urbana, ampliando também fontes de poluição do ar, da água e do solo.', N'AVA · 2º semestre · Observe os efeitos ambientais das mudanças econômicas.', NULL, NULL),
        (408, N'fase30', N'Por que o uso intensivo de energia deve fazer parte da análise ambiental?', N'Porque os recursos e os processos usados para gerar energia podem comprometer o ambiente, especialmente quando a demanda cresce sem cuidado com seus impactos.', N'AVA · 2º semestre · Relacione fonte energética, consumo e consequências.', NULL, NULL),
        (409, N'fase30', N'O que um caso de contaminação do solo ensina sobre resíduos industriais?', N'Que abandonar materiais perigosos pode espalhar a contaminação para o solo, a água e a população; o problema não termina quando a atividade industrial encerra.', N'AVA · 2º semestre · O resíduo permanece no ambiente.', NULL, NULL),
        (410, N'fase30', N'Por que a educação faz parte da resposta aos problemas ambientais?', N'Porque mudanças duradouras dependem de compreensão e comportamento, além de medidas de controle da poluição.', N'AVA · 2º semestre · Conhecer o problema ajuda a mudar as práticas.', NULL, NULL),
        (411, N'fase30', N'Por que recursos naturais não devem ser analisados isoladamente?', N'Eles são limitados e interligados: a redução ou degradação de um recurso pode afetar outros e comprometer condições de vida.', N'AVA · 2º semestre · Pense em relações entre água, solo e seres vivos.', NULL, NULL),
        (412, N'fase30', N'Como a educação ambiental crítica apoia a tomada de decisão?', N'Ela desenvolve a capacidade de analisar problemas e escolher ações ambientalmente responsáveis, em espaços formais e não formais.', N'AVA · 2º semestre · Aprender também é avaliar escolhas.', NULL, NULL),
        (413, N'fase30', N'Por que limitar a educação ambiental à proteção de animais e plantas é insuficiente?', N'Porque problemas ambientais também envolvem pobreza, desigualdade, condições de vida e decisões sociais que precisam entrar na análise.', N'AVA · 2º semestre · A sociedade faz parte do ambiente.', NULL, NULL),
        (414, N'fase30', N'Qual contribuição histórica de Tbilisi aparece no estudo da educação ambiental?', N'A conferência consolidou definições, objetivos, princípios e estratégias que orientam práticas educativas sobre o ambiente.', N'AVA · 2º semestre · Lembre dos fundamentos compartilhados da área.', NULL, NULL),
        (415, N'fase30', N'Por que educação ambiental é um processo contínuo de aprendizagem?', N'Porque envolve aprender sobre questões ambientais e reunir conhecimentos para tomar decisões e agir individual e coletivamente.', N'AVA · 2º semestre · Não se resume a uma campanha isolada.', NULL, NULL),
        (416, N'fase30', N'Qual a vantagem de investigar as causas dos problemas ambientais?', N'Atuar sobre suas causas permite prevenir e transformar práticas que geram danos, em vez de apenas aliviar seus efeitos visíveis.', N'AVA · 2º semestre · Pergunte de onde o problema vem.', NULL, NULL),
        (417, N'fase30', N'Como a ecocidadania amplia a ideia de cidadania?', N'Ela acrescenta responsabilidade ecológica à participação social, relacionando a comunidade local à vida no planeta.', N'AVA · 2º semestre · A ação começa perto e pode ter efeitos distantes.', NULL, NULL),
        (418, N'fase30', N'Por que um projeto de educação ambiental deve respeitar a diversidade do grupo?', N'Porque participantes têm conhecimentos, valores e experiências diferentes, que influenciam a compreensão e a participação nas atividades.', N'AVA · 2º semestre · Conheça as pessoas antes de planejar.', NULL, NULL),
        (419, N'fase30', N'Como a interdisciplinaridade ajuda a compreender uma questão ambiental?', N'Ela articula conhecimentos e métodos de diferentes áreas, permitindo compreender relações que uma disciplina isolada pode deixar de lado.', N'AVA · 2º semestre · Problemas reais atravessam fronteiras das matérias.', NULL, NULL),
        (420, N'fase30', N'Uma atitude ecológica garante um comportamento sustentável em todas as situações?', N'Não. Atitudes expressam disposições e valores, mas hábitos e circunstâncias podem levar a comportamentos contraditórios.', N'AVA · 2º semestre · Compare o que a pessoa valoriza com o que faz.', NULL, NULL),
        (421, N'fase30', N'Como experiências de educação ambiental já realizadas ajudam um novo projeto?', N'Elas oferecem referências que podem ser analisadas e adaptadas ao contexto e aos participantes, sem virar uma receita única.', N'AVA · 2º semestre · Adapte a experiência, não apenas a repita.', NULL, NULL),
        (422, N'fase30', N'O que caracteriza uma aprendizagem ambiental capaz de orientar ações?', N'A capacidade de avaliar impactos, reunir informações, comparar alternativas e assumir responsabilidade por decisões que preservem ou melhorem a qualidade ambiental.', N'AVA · 2º semestre · Conhecimento precisa apoiar escolhas concretas.', NULL, NULL),
        (423, N'fase31', N'Por que o conhecimento científico pode ser revisado?', N'Porque suas afirmações são verificáveis e falíveis: novas evidências ou análises podem exigir a revisão das explicações.', N'AVA · 2º semestre · Uma conclusão científica não é um dogma.', NULL, NULL),
        (424, N'fase31', N'Como indução e dedução contribuem de modos diferentes para uma pesquisa?', N'A indução parte de observações particulares para formular generalizações; a dedução parte de premissas gerais para examinar consequências específicas.', N'AVA · 2º semestre · Observe o sentido do raciocínio.', NULL, NULL),
        (425, N'fase31', N'Qual papel uma hipótese desempenha na investigação de um problema?', N'Ela propõe uma possível resposta ou explicação que deverá ser confrontada com evidências, em vez de ser tomada como conclusão pronta.', N'AVA · 2º semestre · A hipótese abre uma investigação.', NULL, NULL),
        (426, N'fase31', N'Por que lei científica e teoria não são sinônimos?', N'Uma lei descreve um padrão observado; uma teoria oferece uma explicação fundamentada para um conjunto de fenômenos.', N'AVA · 2º semestre · Descrição de regularidade e explicação têm funções distintas.', NULL, NULL),
        (427, N'fase31', N'Por que é recomendável escrever o resumo depois do corpo do trabalho?', N'Porque o resumo precisa representar o estudo efetivamente realizado, incluindo seu objetivo, percurso e resultados, já definidos no texto.', N'AVA · 2º semestre · Resuma o que foi feito de fato.', NULL, NULL),
        (428, N'fase31', N'Qual função o desenvolvimento cumpre em um trabalho acadêmico?', N'Ele detalha o estudo, articulando fundamentação, métodos e análise dos dados ou argumentos que sustentam a pesquisa.', N'AVA · 2º semestre · É o lugar de mostrar como a investigação foi construída.', NULL, NULL),
        (429, N'fase31', N'O que uma conclusão deve recuperar de uma pesquisa?', N'Os principais resultados e suas interpretações, relacionando-os ao objetivo do trabalho e, quando pertinente, a possibilidades de continuidade.', N'AVA · 2º semestre · Feche o problema apresentado na introdução.', NULL, NULL),
        (430, N'fase31', N'Como apêndice e anexo se distinguem pela autoria do material?', N'O apêndice reúne material complementar elaborado pelo próprio autor; o anexo incorpora material produzido por terceiros com a devida indicação de origem.', N'AVA · 2º semestre · Pergunte quem produziu o documento complementar.', NULL, NULL),
        (431, N'fase31', N'Como a citação se relaciona com a referência em um texto acadêmico?', N'A citação usa uma ideia, dado ou trecho no texto; a referência fornece as informações que identificam a obra de origem.', N'AVA · 2º semestre · Uma aparece no argumento; a outra identifica a fonte.', NULL, NULL),
        (432, N'fase31', N'Quando uma citação é considerada direta?', N'Quando reproduz literalmente um trecho da fonte, preservando as palavras originais e identificando sua autoria e localização.', N'AVA · 2º semestre · A transcrição deve ser reconhecível como transcrição.', NULL, NULL),
        (433, N'fase31', N'Por que escrever uma ideia de outro autor com suas palavras ainda exige citar a fonte?', N'Porque a redação mudou, mas a contribuição intelectual continua vindo da obra consultada; essa é a lógica da citação indireta.', N'AVA · 2º semestre · Parafrasear não transfere a autoria da ideia.', NULL, NULL),
        (434, N'fase31', N'Como o plágio prejudica a comunicação científica?', N'Ele apresenta conteúdo ou ideias alheias como próprios, ocultando sua origem e comprometendo a confiança e o reconhecimento da autoria.', N'AVA · 2º semestre · A integridade depende de atribuição clara.', NULL, NULL),
        (435, N'fase31', N'Toda pesquisa precisa resultar imediatamente em um produto novo?', N'Não. A pesquisa básica também amplia o conhecimento sem exigir uma aplicação imediata; possíveis usos podem surgir depois.', N'AVA · 2º semestre · Produzir conhecimento já é um objetivo válido.', NULL, NULL),
        (436, N'fase31', N'Como a inovação se relaciona com a aplicação do conhecimento?', N'Ela transforma conhecimentos em produtos, processos ou serviços novos ou aprimorados que atendem necessidades e geram valor.', N'AVA · 2º semestre · A ideia precisa chegar a uma aplicação útil.', NULL, NULL),
        (437, N'fase31', N'Qual a diferença entre criar uma inovação e ela se tornar prática de mercado?', N'Criar a inovação introduz uma solução; tornar-se prática de mercado envolve sua adoção mais ampla por empresas, organizações ou usuários.', N'AVA · 2º semestre · Pense na diferença entre desenvolver e difundir.', NULL, NULL),
        (438, N'fase31', N'Por que o transistor é apresentado como exemplo de pesquisa aplicada à computação?', N'Seu desenvolvimento permitiu usar dispositivos eletrônicos como interruptores em grande quantidade, contribuindo para circuitos computacionais mais confiáveis.', N'AVA · 2º semestre · Uma descoberta física pode transformar o hardware.', NULL, NULL),
        (439, N'fase32', N'Por que compreender o propósito do sistema vem antes de detalhar sua implementação?', N'Porque o desenvolvimento precisa partir do problema e das necessidades do cliente, evitando construir corretamente uma solução que não atende ao objetivo.', N'ED · 2º semestre · Primeiro entenda o que precisa ser resolvido.', NULL, NULL),
        (440, N'fase32', N'Como diferenciar uma função esperada de um atributo de qualidade do sistema?', N'A função descreve um comportamento oferecido; o atributo de qualidade ou restrição descreve condições como desempenho, usabilidade ou confiabilidade.', N'ED · 2º semestre · Pergunte o que faz e sob quais condições.', NULL, NULL),
        (441, N'fase32', N'Qual diferença entre validar requisitos e gerenciar suas mudanças?', N'Validar examina se os requisitos têm qualidade e representam necessidades; gerenciar acompanha e controla suas alterações durante a vida do projeto.', N'ED · 2º semestre · Uma atividade avalia; a outra acompanha a evolução.', NULL, NULL),
        (442, N'fase32', N'Por que elicitação exige ouvir diferentes partes interessadas?', N'Porque usuários, clientes, equipe técnica e outros envolvidos conhecem necessidades e restrições diferentes que precisam ser conciliadas.', N'ED · 2º semestre · Uma única visão pode deixar lacunas.', NULL, NULL),
        (443, N'fase32', N'Como uma história de usuário relaciona uma função ao seu valor?', N'Ela apresenta quem precisa da função, o que deseja realizar e por que isso é útil, mantendo o foco no benefício esperado.', N'ED · 2º semestre · Papel, necessidade e benefício.', NULL, NULL),
        (444, N'fase32', N'Por que rastrear a origem e o destino de um requisito ajuda a manter o projeto?', N'Porque permite relacionar a necessidade aos elementos construídos e avaliar o que deve mudar quando essa necessidade é alterada.', N'ED · 2º semestre · Siga os vínculos em ambas as direções.', NULL, NULL),
        (445, N'fase32', N'Como a rastreabilidade entre requisitos e testes apoia a verificação?', N'Ela mostra quais testes avaliam cada requisito e ajuda a encontrar necessidades sem cobertura de verificação.', N'ED · 2º semestre · Um requisito deve ter uma forma de avaliação.', NULL, NULL),
        (446, N'fase32', N'Por que um épico costuma ser dividido antes de entrar em uma iteração?', N'Porque sua abrangência pode ser grande demais para uma entrega curta; a divisão cria histórias menores e mais compreensíveis.', N'ED · 2º semestre · Reduza o tamanho preservando o valor de cada parte.', NULL, NULL),
        (447, N'fase32', N'Por que uma tarefa técnica não equivale necessariamente a uma história de usuário?', N'A tarefa pode ser apenas uma parte da implementação; a história representa uma funcionalidade ou benefício percebido pelo usuário.', N'ED · 2º semestre · Criar uma tela pode ser só uma parte da experiência completa.', NULL, NULL),
        (448, N'fase32', N'Como a ambiguidade na documentação afeta a construção do software?', N'Ela permite interpretações diferentes sobre o comportamento esperado, dificultando desenvolvimento, testes e acordo com as partes interessadas.', N'ED · 2º semestre · Escreva de modo que duas pessoas entendam a mesma coisa.', NULL, NULL),
        (449, N'fase32', N'Quais grupos de atividades aparecem na organização de um processo de software?', N'Especificação, projeto e implementação, verificação e validação, além da evolução da solução ao longo do tempo.', N'ED · 2º semestre · O processo cobre mais que escrever código.', NULL, NULL),
        (450, N'fase32', N'Como o modelo cascata organiza suas principais atividades?', N'Ele dispõe etapas como requisitos, projeto, implementação, testes e manutenção em uma sequência, na qual resultados anteriores orientam os seguintes.', N'ED · 2º semestre · Visualize o encadeamento entre etapas.', NULL, NULL),
        (451, N'fase32', N'Qual benefício o feedback frequente traz ao desenvolvimento incremental?', N'Permite avaliar partes funcionais antes da entrega completa e usar o retorno do cliente para orientar os próximos incrementos.', N'ED · 2º semestre · Aprenda com uma entrega utilizável.', NULL, NULL),
        (452, N'fase32', N'Por que requisitos de usuário precisam de uma linguagem compreensível aos envolvidos?', N'Porque devem comunicar expectativas e permitir sua validação por quem conhece o problema, mesmo sem domínio dos detalhes técnicos.', N'ED · 2º semestre · A especificação também é um instrumento de diálogo.', NULL, NULL),
        (453, N'fase32', N'Como completude e consistência se diferenciam na validação de requisitos?', N'Completude busca necessidades e detalhes que ficaram ausentes; consistência busca requisitos que se contradizem.', N'ED · 2º semestre · Procure lacunas e conflitos separadamente.', NULL, NULL),
        (454, N'fase32', N'Qual papel a análise de riscos exerce no modelo espiral?', N'Ela orienta a avaliação de alternativas e o planejamento dos ciclos, ajudando a enfrentar incertezas antes de avançar na solução.', N'ED · 2º semestre · Cada volta deve reduzir dúvidas importantes.', NULL, NULL),
        (455, N'bonus2', N'Bônus 02: O que foi o ENIAC (1946)?', N'O primeiro computador digital eletrônico de grande escala, construído com válvulas para calcular tabelas de artilharia militar.', N'Ocupava uma sala inteira e pesava 30 toneladas.', NULL, NULL),
        (456, N'bonus2', N'Bônus 02: Quem foi Ada Lovelace?', N'A primeira programadora da história (século XIX), que criou o primeiro algoritmo focado numa máquina mecânica de computação.', N'Matemática visionária.', NULL, NULL),
        (457, N'bonus2', N'Bônus 02: Quem foi Alan Turing?', N'Matemático britânico considerado o ''Pai da Ciência da Computação''. Decifrou os códigos nazis da Máquina Enigma.', N'Criou o ''Teste de Turing'' para inteligência artificial.', NULL, NULL),
        (458, N'bonus2', N'Bônus 02: O que foi a Máquina Analítica?', N'Um projeto de computador mecânico desenhado por Charles Babbage em 1837, ancestral dos computadores modernos.', N'Nunca foi totalmente construída no seu tempo.', NULL, NULL),
        (459, N'bonus2', N'Bônus 02: Qual foi o impacto da invenção do Transístor?', N'Substituiu as válvulas, permitindo que os computadores se tornassem muito mais pequenos, baratos e não superaquecessem.', N'A base de toda a eletrônica moderna.', NULL, NULL),
        (460, N'bonus2', N'Bônus 02: O que ditava a Lei de Moore (1965)?', N'Que a quantidade de transístores (o poder de processamento) num microchip dobraria a cada dois anos, sem aumento de custos.', N'A profecia que guiou a evolução do Hardware.', NULL, NULL),
        (461, N'bonus2', N'Bônus 02: O que foi a ARPANET?', N'Uma rede de computadores financiada pelo departamento militar dos EUA que é a base histórica da Internet.', N'Para proteger os dados em caso de ataque nuclear.', NULL, NULL),
        (462, N'bonus2', N'Bônus 02: Quem inventou a World Wide Web (WWW)?', N'Tim Berners-Lee em 1989, trabalhando no CERN, com o objetivo de compartilhar arquivos HTML entre cientistas.', N'Criou também o protocolo HTTP.', NULL, NULL),
        (463, N'bonus2', N'Bônus 02: Qual o papel de Margaret Hamilton na Missão Apollo 11?', N'Ela foi a Diretora de Engenharia de Software da NASA; o código da sua equipe impediu que o módulo lunar caísse na lua.', N'A mãe do termo ''Engenharia de Software''.', NULL, NULL),
        (464, N'bonus2', N'Bônus 02: Qual foi o primeiro ''Bug'' de computador real?', N'Uma traça real que ficou presa num relé do computador Mark II em 1947, encontrada por Grace Hopper.', N'A origem literal do termo ''Inseto''.', NULL, NULL),
        (465, N'bonus2', N'Bônus 02: Quem criou o sistema operacional Linux?', N'Linus Torvalds, em 1991, lançando o kernel de forma aberta (open source) para a comunidade.', N'Hoje o Linux domina os servidores do mundo.', NULL, NULL),
        (466, N'bonus2', N'Bônus 02: O que foi o Computador Altair 8800 (1975)?', N'O primeiro computador pessoal de sucesso comercial. Inspirou Bill Gates a fundar a Microsoft para vender software.', N'Era uma caixa com interruptores e luzes.', NULL, NULL),
        (467, N'bonus2', N'Bônus 02: O que a Xerox PARC inventou que a Apple e a Microsoft copiaram?', N'A Interface Gráfica do Usuário (GUI) com janelas e o Mouse de computador.', N'A Xerox não sabia comercializar a invenção.', NULL, NULL),
        (468, N'bonus2', N'Bônus 02: O que foi o ''Bug do Milênio'' (Y2K)?', N'O medo de que os computadores parassem no ano 2000, pois as datas eram guardadas apenas com os dois últimos dígitos (99 para 1999).', N'Bilhões foram gastos em refatoração de código.', NULL, NULL),
        (469, N'bonus2', N'Bônus 02: O que foi a ''Bolha da Internet'' (Dot-com Bubble) no ano 2000?', N'Uma crise financeira causada pela especulação cega em qualquer empresa que tivesse um site ''.com'', quebrando milhares de startups.', N'Muitas promessas, pouco lucro real.', NULL, NULL),
        (470, N'bonus2', N'Bônus 02: Qual a origem da linguagem Python?', N'Criada por Guido van Rossum em 1991, com foco na legibilidade do código. O nome é uma homenagem ao grupo ''Monty Python''.', N'Não tem a ver com a cobra.', NULL, NULL),
        (471, N'bonus2', N'Bônus 02: O que foi a ''Guerra dos Navegadores'' nos anos 90?', N'A competição feroz pela fatia de mercado de browsers entre o Netscape Navigator e o Internet Explorer da Microsoft.', N'O IE venceu por vir pré-instalado no Windows.', NULL, NULL),
        (472, N'bonus2', N'Bônus 02: O que é o Easter Egg ''Konami Code''?', N'Um código de trapaça famoso em videojogos: Cima, Cima, Baixo, Baixo, Esquerda, Direita, Esquerda, Direita, B, A.', N'O mais famoso ovo de páscoa digital.', NULL, NULL),
        (473, N'bonus2', N'Bônus 02: Como começou a Amazon.com em 1994?', N'Fundada por Jeff Bezos na garagem de sua casa operando exclusivamente como uma livraria online.', N'Hoje vende desde pens a infraestrutura cloud (AWS).', NULL, NULL),
        (474, N'bonus2', N'Bônus 02: Como o Google revolucionou a busca na Web (1998)?', N'Com o algoritmo PageRank, que ordenava os sites com base na quantidade e qualidade de links (relevância) apontados para eles.', N'Mataram os diretórios organizados manualmente.', NULL, NULL),
        (475, N'bonus2', N'Bônus 02: O que representou o lançamento do iPhone (2007)?', N'Revolucionou a computação móvel ao eliminar os teclados físicos em favor do ''Multitouch'' capacitivo e a entrada de lojas de apps.', N'Transformou os celulares em computadores de bolso.', NULL, NULL),
        (476, N'bonus2', N'Bônus 02: Quem é o criador da linguagem C?', N'Dennis Ritchie, na década de 1970. A linguagem foi usada para reescrever o sistema operacional UNIX.', N'A base da maioria dos sistemas modernos.', NULL, NULL),
        (477, N'bonus2', N'Bônus 02: O que significa ''RTFM'' na cultura Hacker?', N'Read The F***ing Manual (Leia o maldito manual).', N'A resposta rude mas clássica para perguntas óbvias.', NULL, NULL),
        (478, N'bonus2', N'Bônus 02: O que foi o sistema MS-DOS?', N'O sistema operacional em linha de comando da Microsoft que dominou os PCs na década de 1980.', N'Antecessor do Windows.', NULL, NULL),
        (479, N'bonus2', N'Bônus 02: O que era o Cartão Perfurado?', N'Pedaços de papel rígido com furos estrategicamente posicionados usados para inserir dados e código nos primeiros computadores.', N'Código físico.', NULL, NULL),
        (480, N'bonus2', N'Bônus 02: Qual o papel de Steve Wozniak na fundação da Apple?', N'Ele era o gênio técnico que projetou e construiu manualmente as placas de circuito dos computadores Apple I e Apple II.', N'Jobs vendia, Wozniak construía.', NULL, NULL),
        (481, N'bonus2', N'Bônus 02: O que foi o ''Projeto Manhattan'' do Google?', N'A criação de um sistema de IA focado em vencer o melhor jogador humano do mundo de Go (um complexo jogo de tabuleiro asiático).', N'AlphaGo.', NULL, NULL),
        (482, N'bonus2', N'Bônus 02: O que significa o acrônimo ''CAPTCHA''?', N'Completely Automated Public Turing test to tell Computers and Humans Apart.', N'Testes de semáforos e passadeiras de peões.', NULL, NULL),
        (483, N'bonus2', N'Bônus 02: O que foi o erro 418 do protocolo HTTP?', N'I''m a teapot (Eu sou um bule de chá). Foi criado em 1998 como uma piada de primeiro de abril sobre protocolos de cafeteiras conectadas.', N'O Easter Egg oficial da Web.', NULL, NULL),
        (484, N'bonus2', N'Bônus 02: O que são as ''Blue Boxes'' (Caixas Azuis) dos anos 70?', N'Dispositivos criados por hackers (Phreakers) que emitiam os mesmos tons acústicos da operadora de telefonia para fazer chamadas gratuitas.', N'Jobs e Wozniak vendiam essas caixas antes da Apple.', NULL, NULL),
        (485, N'fase11', N'O que é uma Chave Primária (Primary Key)?', N'Um campo (ou conjunto de campos) que identifica de forma exclusiva uma linha numa tabela.', N'Disciplina: Bancos de Dados. Ex: NIF ou CPF.', NULL, NULL),
        (486, N'fase11', N'O que é uma Chave Estrangeira (Foreign Key)?', N'Um campo numa tabela que faz referência à Chave Primária de outra tabela, criando um vínculo entre ambas.', N'Garante a integridade referencial.', NULL, NULL),
        (487, N'fase11', N'Qual a diferença entre SQL e NoSQL?', N'SQL é relacional (tabelas e esquemas rígidos). NoSQL é não-relacional (documentos flexíveis, chave-valor, grafos).', N'MySQL vs MongoDB.', NULL, NULL),
        (488, N'fase11', N'O que significa a sigla CRUD?', N'Create (Criar), Read (Ler), Update (Atualizar), Delete (Apagar).', N'As 4 operações básicas de qualquer sistema.', NULL, NULL),
        (489, N'fase11', N'Para que serve a cláusula JOIN no SQL?', N'Para combinar e recuperar dados de duas ou mais tabelas baseando-se numa coluna em comum entre elas.', N'Une os ''Clientes'' aos seus ''Pedidos''.', NULL, NULL),
        (490, N'fase11', N'O que é a Normalização de Dados?', N'O processo de organizar as tabelas para minimizar a redundância (dados repetidos) e evitar anomalias de atualização.', N'Dividir para organizar.', NULL, NULL),
        (491, N'fase11', N'O que dita a Primeira Forma Normal (1FN)?', N'Que uma tabela não deve conter atributos multivalorados ou compostos. Cada célula deve ter um valor atômico (único).', N'Não colocar dois telefones na mesma célula.', NULL, NULL),
        (492, N'fase11', N'O que significa o acrônimo ACID em transações de Bancos de Dados?', N'Atomicidade, Consistência, Isolamento e Durabilidade.', N'Garante que a transação bancária não para no meio do caminho.', NULL, NULL),
        (493, N'fase11', N'Qual a diferença entre DDL e DML no SQL?', N'DDL define a estrutura (CREATE, ALTER, DROP). DML manipula os dados (INSERT, UPDATE, DELETE).', N'DDL mexe na tabela, DML mexe na linha.', NULL, NULL),
        (494, N'fase11', N'Para que serve o comando SELECT?', N'Para consultar e extrair dados específicos de uma ou mais tabelas.', N'A operação mais usada (Read do CRUD).', NULL, NULL),
        (495, N'fase11', N'Como funciona o comando GROUP BY?', N'Agrupa linhas com os mesmos valores em colunas de resumo, frequentemente usado com funções matemáticas (SUM, COUNT).', N'Agrupa para somar ou contar.', NULL, NULL),
        (496, N'fase11', N'O que é um Índice (Index) numa Banco de Dados?', N'Uma estrutura de dados especial criada para acelerar incrivelmente a velocidade das pesquisas nas tabelas.', N'Como o índice remissivo no fim de um livro.', NULL, NULL),
        (497, N'fase11', N'O que é uma Trigger (Gatilho)?', N'Um código SQL que é executado automaticamente APÓS ou ANTES de um evento (Insert, Update ou Delete) numa tabela.', N'Excelente para criar logs de auditoria automáticos.', NULL, NULL),
        (498, N'fase11', N'O que é uma Stored Procedure (Procedimento Armazenado)?', N'Um bloco de código SQL guardado no servidor que pode ser invocado pela aplicação várias vezes.', N'Poupa tráfego de rede e centraliza regras de negócio.', NULL, NULL),
        (499, N'fase11', N'O que é uma View (Vista)?', N'Uma ''tabela virtual'' baseada no resultado de uma consulta SELECT (Query). Não guarda os dados fisicamente.', N'Facilita a leitura de JOINs muito complexos.', NULL, NULL),
        (500, N'fase11', N'O que é um SGBD?', N'Sistema Gerenciador de Banco de Dados. O software responsável por administrar os bancos de dados.', N'Ex: SQL Server, PostgreSQL, Oracle.', NULL, NULL);
    INSERT INTO flashcards (id, codigo_fase, frente, verso, dica, opcoes, correta) VALUES
        (501, N'fase11', N'Como o MongoDB guarda os seus dados?', N'Em coleções de Documentos no formato BSON (semelhante ao JSON), sem necessidade de colunas rígidas.', N'Ideal para dados desestruturados.', NULL, NULL),
        (502, N'fase11', N'O que é um Diagrama Entidade-Relacionamento (DER)?', N'Um modelo visual que descreve a estrutura lógica do banco de dados, as suas entidades e como se conectam.', N'A planta-baixa do banco.', NULL, NULL),
        (503, N'fase11', N'Para que servem os comandos COMMIT e ROLLBACK?', N'COMMIT guarda as alterações da transação permanentemente. ROLLBACK desfaz e reverte tudo em caso de erro.', N'Salvar vs Desfazer.', NULL, NULL),
        (504, N'fase11', N'Qual a diferença entre DELETE e TRUNCATE?', N'DELETE apaga linhas específicas e registra isso no log (mais lento). TRUNCATE limpa a tabela inteira de imediato (rápido).', N'TRUNCATE é um ''reset'' à tabela.', NULL, NULL),
        (505, N'fase11', N'Por que um modelo conceitual deve começar pelo domínio do problema?', N'Para representar conceitos, características e relações relevantes antes de decidir detalhes tecnológicos da solução.', N'ED · 3º semestre · Entenda os dados antes da implementação.', NULL, NULL),
        (506, N'fase11', N'Qual a relação entre MER e DER no projeto de dados?', N'O MER organiza conceitos de entidades, atributos e relacionamentos; o DER representa graficamente essa organização.', N'ED · 3º semestre · Modelo e representação gráfica se complementam.', NULL, NULL),
        (507, N'fase11', N'Que decisões aparecem no modelo físico de um banco?', N'Detalhes de implementação, como tabelas, campos, tipos, índices e recursos do sistema de banco escolhido.', N'ED · 3º semestre · É a etapa ligada à implementação.', NULL, NULL),
        (508, N'fase11', N'Como o domínio de um atributo ajuda a manter dados coerentes?', N'Define quais valores são permitidos para aquele atributo, restringindo entradas incompatíveis.', N'ED · 3º semestre · Tipo e conjunto de valores precisam fazer sentido.', NULL, NULL),
        (509, N'fase11', N'O que uma tupla representa em uma relação?', N'Um registro formado por pares de atributos e valores, correspondente a uma linha da tabela.', N'ED · 3º semestre · Uma ocorrência, não a tabela inteira.', NULL, NULL),
        (510, N'fase11', N'Por que a chave primária precisa distinguir as tuplas?', N'Para permitir identificar unicamente cada registro, inclusive quando outros atributos se repetem.', N'ED · 3º semestre · Nome de pessoa nem sempre identifica alguém.', NULL, NULL),
        (511, N'fase11', N'Quando uma chave primária pode ser composta?', N'Quando a identificação única exige a combinação de mais de um atributo.', N'ED · 3º semestre · A combinação, e não cada campo isolado, identifica.', NULL, NULL),
        (512, N'fase11', N'Por que os domínios de uma chave estrangeira e da chave referenciada devem ser compatíveis?', N'Porque a relação é estabelecida comparando valores entre esses atributos.', N'ED · 3º semestre · Os campos relacionados precisam representar o mesmo tipo de referência.', NULL, NULL),
        (513, N'fase11', N'Para que pode ser usada uma chave artificial em uma tabela?', N'Para oferecer uma identificação técnica, como um número sequencial, em lugar de uma chave natural mais complexa.', N'ED · 3º semestre · É uma decisão de identificação do registro.', NULL, NULL),
        (514, N'fase11', N'Qual diferença de participação a cardinalidade mínima zero ou um expressa?', N'Zero permite ausência de associação; um exige que exista ao menos uma ocorrência relacionada.', N'ED · 3º semestre · Observe a obrigatoriedade da relação.', NULL, NULL),
        (515, N'fase11', N'Como modelar uma mesa que pode existir sem empregado alocado?', N'Com participação mínima zero da mesa na associação com empregado.', N'ED · 3º semestre · Existência da entidade não obriga associação.', NULL, NULL),
        (516, N'fase11', N'O que precisa mudar quando um atributo guarda uma lista de valores na primeira forma normal?', N'Os valores devem ser representados de modo atômico, evitando grupos repetidos no mesmo atributo.', N'ED · 3º semestre · Um atributo não deve esconder vários itens repetidos.', NULL, NULL),
        (517, N'fase11', N'Qual dependência a segunda forma normal procura eliminar?', N'A dependência de atributo não chave de apenas parte de uma chave composta.', N'ED · 3º semestre · Verifique a chave inteira.', NULL, NULL),
        (518, N'fase11', N'Qual problema de dependência é tratado pela terceira forma normal?', N'A dependência transitiva inadequada entre atributos não chave, após atender à segunda forma normal.', N'ED · 3º semestre · Um atributo não chave não deve determinar outro indevidamente.', NULL, NULL),
        (519, N'fase11', N'O que CREATE TABLE define antes de inserir registros?', N'A estrutura da tabela, com nomes das colunas e seus tipos, podendo incluir restrições.', N'ED · 3º semestre · Criar estrutura não equivale a inserir dados.', NULL, NULL),
        (520, N'fase11', N'Como varchar e nvarchar diferem no armazenamento textual apresentado?', N'Ambos permitem comprimento variável; nvarchar representa texto Unicode no SQL Server.', N'ED · 3º semestre · Considere os caracteres que precisam ser armazenados.', NULL, NULL),
        (521, N'fase12', N'O que é uma Classe na POO?', N'Um molde, planta ou especificação que define os atributos e comportamentos de um objeto.', N'Disciplina: POO com C#.', NULL, NULL),
        (522, N'fase12', N'O que é um Objeto?', N'Uma instância concreta (materialização) de uma Classe, residente na memória durante a execução do programa.', N'A classe é a forma do bolo; o objeto é o bolo.', NULL, NULL),
        (523, N'fase12', N'O que é a Herança em POO?', N'O mecanismo onde uma classe filha adquire automaticamente as características e comportamentos de uma classe pai.', N'Promove o reaproveitamento de código.', NULL, NULL),
        (524, N'fase12', N'O que é o Polimorfismo?', N'A capacidade de um método ter diferentes comportamentos dependendo do objeto que o invoca.', N'Ex: ''EmitirSom()'' -> Cão ladra, Gato mia.', NULL, NULL),
        (525, N'fase12', N'O que é o Encapsulamento?', N'A técnica de ocultar o estado interno de um objeto (usando variáveis private) e expor apenas os métodos seguros (public).', N'Protege os dados de alterações indevidas.', NULL, NULL),
        (526, N'fase12', N'O que é uma Classe Abstrata?', N'Uma classe genérica que não pode ser instanciada (não se pode fazer ''new''), servindo apenas de base para outras classes herdarem.', N'Modelo base obrigatório.', NULL, NULL),
        (527, N'fase12', N'O que é uma Interface?', N'Um contrato 100% vazio. Define APENAS a assinatura dos métodos que as classes que a implementam são obrigadas a criar.', N'Resolve o problema da herança múltipla no C#.', NULL, NULL),
        (528, N'fase12', N'O que é um Construtor?', N'Um método especial, executado automaticamente quando o objeto é instanciado, usado para inicializar os seus atributos.', N'Tem sempre o mesmo nome da Classe.', NULL, NULL),
        (529, N'fase12', N'Qual a diferença entre os modificadores ''public'' e ''private''?', N'Public: Qualquer parte do código acessa. Private: Apenas a própria classe tem acesso.', N'Níveis de visibilidade.', NULL, NULL),
        (530, N'fase12', N'O que é a Sobrecarga (Overloading)?', N'Criar vários métodos com o MESMO NOME na mesma classe, mas com parâmetros diferentes (quantidade ou tipo).', N'Comportamentos variados conforme os argumentos.', NULL, NULL),
        (531, N'fase12', N'O que é a Sobrescrita (Overriding)?', N'Quando a classe filha reescreve e muda a lógica de um método herdado da classe pai.', N'Usa as palavras ''virtual'' e ''override'' no C#.', NULL, NULL),
        (532, N'fase12', N'O que faz a palavra-chave ''static'' num método ou atributo?', N'O membro pertence à Classe em si e não aos objetos gerados. Pode ser usado sem instanciar a classe.', N'Ex: Math.Round();', NULL, NULL),
        (533, N'fase12', N'Para que servem as Propriedades (Getters / Setters) em C#?', N'Para acessar e modificar os atributos privados de forma controlada e segura.', N'O filtro de entrada de dados.', NULL, NULL),
        (534, N'fase12', N'Para que serve o operador ''new''?', N'Para alocar memória e instanciar um novo objeto a partir de uma classe.', N'Ex: Carro c = new Carro();', NULL, NULL),
        (535, N'fase12', N'O que é o Garbage Collector (Coletor de Lixo)?', N'Um processo automático do .NET que limpa a memória, destruindo objetos que já não estão sendo usados pelo programa.', N'Evita o Memory Leak automaticamente.', NULL, NULL),
        (536, N'fase12', N'Para que servem os ''Namespaces'' em C#?', N'Para organizar o código e evitar conflitos de nomes entre classes (ex: duas classes chamadas ''Usuario'' em pastas diferentes).', N'Como se fossem ''sobrenomes'' das classes.', NULL, NULL),
        (537, N'fase12', N'Para que serve o bloco ''try / catch''?', N'Para capturar e tratar exceções (erros) em tempo de execução, impedindo que o programa feche abruptamente.', N'Gestão elegante de erros.', NULL, NULL),
        (538, N'fase12', N'No C#, qual a diferença entre Value Types e Reference Types?', N'Value (structs, int) guarda o dado direto na memória Stack. Reference (classes, arrays) guarda um ponteiro na memória Heap.', N'Gestão interna do .NET.', NULL, NULL),
        (539, N'fase12', N'Qual a grande diferença entre o Paradigma POO e o Procedural?', N'O Procedural foca numa sequência de funções e dados globais soltos. O POO agrupa dados e funções no mesmo elemento (Objeto).', N'POO modela o mundo real.', NULL, NULL),
        (540, N'fase12', N'Para que serve a palavra-chave ''this''?', N'Faz referência à instância ATUAL do objeto. Usado para diferenciar atributos da classe de variáveis locais com o mesmo nome.', N'Eu próprio.', NULL, NULL),
        (541, N'fase12', N'Quais membros podem compor a declaração de uma classe em C#?', N'Campos, propriedades, construtores e métodos, organizados conforme estado e comportamento necessários.', N'ED · 3º semestre · Uma classe reúne dados e operações.', NULL, NULL),
        (542, N'fase12', N'Como um construtor participa da criação de um objeto?', N'Recebe parâmetros e inicializa o estado necessário para a nova instância.', N'ED · 3º semestre · Criar um objeto também envolve prepará-lo.', NULL, NULL),
        (543, N'fase12', N'Para que servem modificadores como private e public nos membros?', N'Para controlar sua visibilidade e acessibilidade, apoiando o encapsulamento.', N'ED · 3º semestre · Nem todo detalhe precisa ser público.', NULL, NULL),
        (544, N'fase12', N'Como um método público pode oferecer acesso controlado a um campo privado?', N'Executando uma operação definida sobre esse campo sem torná-lo diretamente acessível externamente.', N'ED · 3º semestre · Exponha comportamentos, preserve detalhes internos.', NULL, NULL),
        (545, N'fase12', N'Quando BigInteger pode ser útil em C#?', N'Quando é preciso representar inteiros maiores que os limites dos tipos inteiros usuais.', N'ED · 3º semestre · Ele oferece precisão inteira arbitrária.', NULL, NULL),
        (546, N'fase12', N'Que responsabilidade a família System.IO atende no .NET?', N'Operações de entrada e saída, especialmente envolvendo arquivos e fluxos de dados.', N'ED · 3º semestre · Bibliotecas agrupam recursos por responsabilidade.', NULL, NULL),
        (547, N'fase12', N'Como C# e .NET se relacionam sem serem a mesma coisa?', N'C# é a linguagem; .NET fornece ambiente, ferramentas e bibliotecas para construir e executar aplicações.', N'ED · 3º semestre · Linguagem e plataforma são conceitos diferentes.', NULL, NULL),
        (548, N'fase12', N'Por que conhecer a biblioteca padrão reduz trabalho repetido?', N'Ela disponibiliza código reutilizável para tarefas comuns, já utilizado e testado em muitos projetos.', N'ED · 3º semestre · Procure recursos existentes antes de recriar tudo.', NULL, NULL),
        (549, N'fase12', N'Como o tratamento de exceções melhora a organização do código?', N'Separa o tratamento de falhas do fluxo principal, permitindo registrar problemas e liberar recursos de forma organizada.', N'ED · 3º semestre · Falhas também precisam de um caminho previsto.', NULL, NULL),
        (550, N'fase12', N'Além de informar um erro, que ações podem ser necessárias ao tratar uma exceção?', N'Liberar recursos, registrar informações para diagnóstico e responder adequadamente ao usuário.', N'ED · 3º semestre · Tratar não é simplesmente esconder o erro.', NULL, NULL),
        (551, N'fase12', N'Como PascalCase e camelCase ajudam a leitura de código C#?', N'Criam convenções consistentes: classes e propriedades usam PascalCase; variáveis locais e parâmetros geralmente usam camelCase.', N'ED · 3º semestre · Consistência facilita localizar o papel de um nome.', NULL, NULL),
        (552, N'fase12', N'Por que dominar fundamentos continua importante ao usar recursos avançados de C#?', N'Porque esses recursos se apoiam em classes, herança, tipos e outros conceitos básicos da linguagem.', N'ED · 3º semestre · Sintaxe avançada não substitui entendimento.', NULL, NULL),
        (553, N'fase12', N'Que partes o operador => separa em uma expressão lambda?', N'Os parâmetros da operação e o corpo que define seu resultado ou comportamento.', N'ED · 3º semestre · É uma forma compacta de função anônima.', NULL, NULL),
        (554, N'fase12', N'Como Any e All diferem em consultas LINQ?', N'Any verifica se algum elemento atende à condição; All verifica se todos atendem.', N'ED · 3º semestre · Existência e universalidade são perguntas diferentes.', NULL, NULL),
        (555, N'fase12', N'Que problema Distinct resolve em uma sequência consultada com LINQ?', N'Produz uma sequência com elementos distintos conforme a comparação usada.', N'ED · 3º semestre · Serve para eliminar repetições no resultado.', NULL, NULL),
        (556, N'fase12', N'Como um callback participa de uma operação que termina depois?', N'Uma função é fornecida para ser chamada em um momento posterior, como após concluir uma tarefa assíncrona.', N'ED · 3º semestre · O retorno de chamada conecta etapas.', NULL, NULL),
        (557, N'fase13', N'Qual a diferença entre UX e UI?', N'UX = User Experience (Jornada, sentimento e usabilidade). UI = User Interface (Cores, botões e estética visual).', N'Disciplina: Web Responsivo e UX/UI.', NULL, NULL),
        (558, N'fase13', N'O que é o Design Responsivo?', N'Técnica que permite que um site adapte o seu layout automaticamente ao tamanho da tela (PC, Tablet, Smartphone).', N'Feito usando Media Queries no CSS.', NULL, NULL),
        (559, N'fase13', N'O que é a abordagem ''Mobile First''?', N'Estratégia de desenhar e programar o site primeiro para o celular, e só depois expandi-lo para monitores maiores.', N'Altamente recomendado pelo Google.', NULL, NULL),
        (560, N'fase13', N'Para que serve o CSS Flexbox?', N'Para organizar, alinhar e distribuir o espaço entre os itens numa linha ou coluna (1 dimensão).', N'Ideal para alinhar menus e botões.', NULL, NULL),
        (561, N'fase13', N'Para que serve o CSS Grid Layout?', N'Para criar estruturas de layout complexas trabalhando com linhas E colunas simultaneamente (2 dimensões).', N'A grelha de construção do site.', NULL, NULL),
        (562, N'fase13', N'O que é um Wireframe?', N'O ''esqueleto'' ou rascunho estrutural de uma tela, sem cores, fontes ou imagens finais.', N'A planta-baixa do site.', NULL, NULL),
        (563, N'fase13', N'O que é um Protótipo de Alta Fidelidade?', N'Uma simulação interativa que se parece exatamente com o produto final, contendo cores, animações e cliques funcionais.', N'Geralmente criado no Figma.', NULL, NULL),
        (564, N'fase13', N'O que são as normas WCAG?', N'Web Content Accessibility Guidelines. Diretrizes mundiais para tornar a web acessível a pessoas com deficiência.', N'Acessibilidade para todos.', NULL, NULL),
        (565, N'fase13', N'O que é a Hierarquia Visual?', N'A organização dos elementos na interface para guiar o olhar do usuário por ordem de importância (usando tamanho, cor, contraste).', N'O que devo ler primeiro?', NULL, NULL),
        (566, N'fase13', N'O que estuda a Psicologia das Cores?', N'Como as cores afetam a perceção e o comportamento do usuário (ex: Vermelho para alertas, Verde para sucesso).', N'Cores transmitem emoções.', NULL, NULL),
        (567, N'fase13', N'Qual a diferença entre fontes Serifadas e Sem Serifa?', N'Serifadas (Serif) têm ''perninhas'' ou prolongamentos nos cantos (ex: Times New Roman). Sem Serifa (Sans-Serif) têm traços retos (ex: Arial).', N'Sans-Serif é o padrão para Web.', NULL, NULL),
        (568, N'fase13', N'O que é uma Call to Action (CTA)?', N'Um elemento (geralmente um botão de destaque) que incita o usuário a realizar uma ação desejada (ex: ''Comprar Agora'').', N'Chamar para a ação.', NULL, NULL),
        (569, N'fase13', N'No CSS, para que servem as Media Queries?', N'Para aplicar estilos condicionados ao tamanho da tela do dispositivo (ex: @media (max-width: 600px)).', N'O motor da responsividade.', NULL, NULL),
        (570, N'fase13', N'O que é o DOM (Document Object Model)?', N'A representação estrutural em árvore do documento HTML, permitindo que o JavaScript altere os elementos em tempo real.', N'A ponte entre HTML e JavaScript.', NULL, NULL),
        (571, N'fase13', N'O que é o HTML Semântico?', N'O uso de tags apropriadas para o significado do conteúdo (ex: <header>, <article>, <nav>) em vez de apenas <div> genéricas.', N'Melhora a acessibilidade e o SEO.', NULL, NULL),
        (572, N'fase13', N'O que é o ''White Space'' (Espaço em Branco) no UI Design?', N'A área vazia entre os elementos de uma interface. É crucial para deixar o design respirar e evitar poluição visual.', N'O vazio também é design.', NULL, NULL),
        (573, N'fase13', N'O que é um Teste A/B?', N'Testar duas versões diferentes de uma mesma página simultaneamente para ver qual delas tem melhor taxa de conversão.', N'O botão verde vende mais que o azul?', NULL, NULL),
        (574, N'fase13', N'O que é o conceito de ''Affordance'' em UX?', N'A característica visual de um objeto que sugere intuitivamente como ele deve ser usado (ex: um botão com sombra parece clicável).', N'Sugestão visual de uso.', NULL, NULL),
        (575, N'fase13', N'O que é uma ''Persona'' em UX Design?', N'Uma representação semi-fictícia do cliente ideal da aplicação, baseada em dados reais, para guiar as decisões de design.', N'Dar rosto e nome ao público-alvo.', NULL, NULL),
        (576, N'fase13', N'O que é o Mapa da Jornada do Usuário (User Journey)?', N'A documentação visual de todos os passos, frustrações e sucessos que um usuário tem ao interagir com o produto.', N'O passo a passo da experiência.', NULL, NULL),
        (577, N'fase13', N'Quando usar main em vez de uma divisão genérica da página?', N'Quando a região contém o conteúdo principal do documento, distinguindo-a de elementos complementares.', N'ED · 3º semestre · Marque a função do conteúdo.', NULL, NULL),
        (578, N'fase13', N'Como article e section diferem na estrutura semântica?', N'Article representa conteúdo independente; section agrupa conteúdos relacionados dentro de uma organização temática.', N'ED · 3º semestre · Independência e agrupamento são ideias diferentes.', NULL, NULL),
        (579, N'fase13', N'Como dividir responsabilidades entre HTML e CSS em uma página?', N'HTML organiza a estrutura e o significado; CSS define a apresentação visual.', N'ED · 3º semestre · Estrutura e aparência trabalham juntas.', NULL, NULL),
        (580, N'fase13', N'Como texto alternativo e estrutura semântica ajudam acessibilidade e busca?', N'Tornam imagens e regiões mais compreensíveis para tecnologias assistivas e mecanismos de busca.', N'ED · 3º semestre · A descrição deve representar o conteúdo.', NULL, NULL),
        (581, N'fase13', N'Por que um site responsivo não precisa de uma página separada para cada tela?', N'Layouts, imagens e regras condicionais adaptam a mesma base de conteúdo ao espaço disponível.', N'ED · 3º semestre · Uma base pode atender diferentes dispositivos.', NULL, NULL),
        (582, N'fase13', N'Como evitar que uma imagem ultrapasse um contêiner estreito?', N'Usar largura máxima de 100% e altura automática para preservar a proporção.', N'ED · 3º semestre · Redimensione sem distorcer.', NULL, NULL),
        (583, N'fase13', N'O que uma media query decide antes de aplicar um estilo?', N'Se as condições de mídia, como largura ou orientação, correspondem ao ambiente de exibição.', N'ED · 3º semestre · Estilos podem depender do contexto.', NULL, NULL),
        (584, N'fase13', N'Por que considerar hover e pointer além da largura da tela?', N'Porque suporte ao mouse e precisão do ponteiro variam, afetando a interação com controles.', N'ED · 3º semestre · Uma tela grande também pode usar toque.', NULL, NULL),
        (585, N'fase13', N'Qual diferença de organização orienta a escolha entre Flexbox e Grid?', N'Flexbox trabalha principalmente em uma dimensão; Grid coordena linhas e colunas em duas dimensões.', N'ED · 3º semestre · Escolha conforme a estrutura do layout.', NULL, NULL),
        (586, N'fase13', N'Por que Flexbox é útil em barras de navegação e controles?', N'Facilita alinhar e distribuir itens em componentes que precisam se adaptar ao espaço.', N'ED · 3º semestre · Alinhamento não precisa de margens improvisadas.', NULL, NULL),
        (587, N'fase13', N'Como flex-direction altera a disposição dos itens?', N'Define se seguem uma linha ou coluna, inclusive em ordem inversa, e determina o eixo principal.', N'ED · 3º semestre · A direção muda a referência de alinhamento.', NULL, NULL),
        (588, N'fase13', N'Qual vantagem de medidas proporcionais em um layout fluido?', N'Os elementos acompanham o espaço disponível em vez de depender exclusivamente de dimensões fixas.', N'ED · 3º semestre · Proporção ajuda a adaptação.', NULL, NULL),
        (589, N'fase13', N'Como o grid do Bootstrap distribui a largura de uma linha?', N'Por um sistema de doze colunas que podem ser combinadas conforme a necessidade do layout.', N'ED · 3º semestre · Container, row e colunas trabalham juntos.', NULL, NULL),
        (590, N'fase13', N'Qual benefício de reutilizar componentes de um framework de interface?', N'Reduz repetição e ajuda a manter padrões de aparência e comportamento entre telas.', N'ED · 3º semestre · Reutilização não dispensa testes.', NULL, NULL),
        (591, N'fase13', N'Como eventos conectam ações do usuário ao JavaScript?', N'Cliques, teclas e outras ações disparam tratamentos que podem alterar a página.', N'ED · 3º semestre · Interatividade responde a acontecimentos.', NULL, NULL),
        (592, N'fase13', N'Quando a delegação de eventos é especialmente útil?', N'Quando elementos são criados dinamicamente e um ancestral pode tratar os eventos propagados por eles.', N'ED · 3º semestre · Um tratamento pode atender vários descendentes.', NULL, NULL),
        (593, N'fase14', N'O que é Machine Learning (ML)?', N'Sistemas que aprendem a identificar padrões em grandes volumes de dados sem precisarem de ser explicitamente programados passo a passo.', N'Disciplina: Machine Learning.', NULL, NULL),
        (594, N'fase14', N'O que é a Inteligência Artificial (IA)?', N'O campo amplo da ciência da computação que procura criar máquinas capazes de realizar tarefas que normalmente exigem inteligência humana.', N'ML é um subcampo da IA.', NULL, NULL),
        (595, N'fase14', N'O que é o Aprendizado Supervisionado?', N'O modelo é treinado usando um conjunto de dados onde a RESPOSTA CORRETA (rótulo) já é fornecida.', N'Treinado com ''gabarito''.', NULL, NULL),
        (596, N'fase14', N'O que é o Aprendizado Não Supervisionado?', N'O modelo recebe dados brutos sem rótulos e tenta descobrir padrões ou agrupar os dados sozinho.', N'Organiza o caos de forma autônoma.', NULL, NULL),
        (597, N'fase14', N'O que é o Aprendizado por Reforço?', N'A IA aprende por tentativa e erro dentro de um ambiente, recebendo ''recompensas'' (pontos) ao acertar e ''punições'' ao errar.', N'Como ensinar um cão com biscoitos.', NULL, NULL),
        (598, N'fase14', N'O que é o Overfitting?', N'Quando o modelo memoriza ou decora os dados de treino tão bem que falha miseravelmente quando tenta analisar dados novos e reais.', N'Falta de generalização.', NULL, NULL),
        (599, N'fase14', N'O que é o Underfitting?', N'Quando o modelo é demasiado simples ou treinado por pouco tempo e não consegue sequer capturar os padrões dos dados de treino.', N'Erro na teoria e na prática.', NULL, NULL),
        (600, N'fase14', N'O que é um Algoritmo de Regressão?', N'Prevê um número ou valor contínuo baseado em tendências históricas. Ex: Prever o preço de uma casa ou o valor das ações.', N'Desenha uma linha de tendência (gráfico).', NULL, NULL);
    INSERT INTO flashcards (id, codigo_fase, frente, verso, dica, opcoes, correta) VALUES
        (601, N'fase14', N'O que é um Algoritmo de Classificação?', N'Prevê a que categoria pertence um dado. Ex: Classificar se um tumor é maligno ou benigno, ou se um e-mail é spam.', N'Separa em caixas/etiquetas.', NULL, NULL),
        (602, N'fase14', N'O que são as Redes Neurais Artificiais?', N'Modelos matemáticos inspirados no cérebro humano, organizados em camadas de nós (neurônios) interligados.', N'A base da inteligência artificial moderna.', NULL, NULL),
        (603, N'fase14', N'O que é o Deep Learning (Aprendizado Profundo)?', N'Uma área do ML que utiliza Redes Neurais com múltiplas camadas ocultas (''Deep'') para resolver problemas altamentes complexos.', N'O poder por trás do reconhecimento facial e ChatGPT.', NULL, NULL),
        (604, N'fase14', N'O que é o Processamento de Linguagem Natural (PLN)?', N'A capacidade de a máquina compreender, interpretar e gerar texto ou fala na linguagem humana (inglês, português, etc).', N'A ponte entre o homem e o texto do robô.', NULL, NULL),
        (605, N'fase14', N'O que é a Visão Computacional?', N'O ensino dos computadores para extraírem informações, identificarem e interpretarem imagens e vídeos do mundo real.', N'Carros autônomos dependem disto.', NULL, NULL),
        (606, N'fase14', N'Qual a diferença entre Dados de Treino e Dados de Teste?', N'Treino: 80% dos dados, usados para ensinar o modelo. Teste: 20% guardados em segredo para avaliar se o modelo aprendeu de verdade.', N'O teste é a ''prova final'' do modelo.', NULL, NULL),
        (607, N'fase14', N'O que é o Viés Algorítmico (Bias)?', N'Quando a IA herda preconceitos (sociais ou raciais) devido ao uso de um banco de dados histórico defeituoso.', N'A IA pode ser racista se ensinada assim.', NULL, NULL),
        (608, N'fase14', N'O que é Clustering (Agrupamento)?', N'Uma técnica de Aprendizado Não Supervisionado que divide os dados em grupos semelhantes baseados nas suas características intrínsecas.', N'Usado para segmentar perfis de clientes de marketing.', NULL, NULL),
        (609, N'fase14', N'Como funciona uma Árvore de Decisão?', N'Um modelo em forma de fluxograma onde cada ''nó'' é uma pergunta e os ''ramos'' são as respostas possíveis até chegar à decisão final.', N'Mapeia uma série de regras ''se-então''.', NULL, NULL),
        (610, N'fase14', N'O que é o algoritmo KNN (K-Nearest Neighbors)?', N'Classifica um dado observando a categoria da maioria dos seus ''K'' vizinhos mais próximos no gráfico.', N'Diz-me com quem andas e eu dir-te-ei quem és.', NULL, NULL),
        (611, N'fase14', N'O que é a Matriz de Confusão?', N'Uma tabela usada para avaliar o desempenho de um modelo de classificação, mostrando Verdadeiros Positivos, Falsos Positivos, etc.', N'Onde o algoritmo acertou e onde se confundiu.', NULL, NULL),
        (612, N'fase14', N'O que é a Extração de Características (Feature Engineering)?', N'O processo de selecionar, manipular e limpar as variáveis de entrada mais importantes para ajudar a IA a aprender melhor.', N'Entra lixo, sai lixo (GIGO).', NULL, NULL),
        (613, N'fase14', N'Que cuidado com os rótulos é necessário no aprendizado supervisionado?', N'Verificar se são adequados e representativos, pois critérios e vieses humanos da rotulagem podem ser aprendidos pelo modelo.', N'AVA · 3º semestre · O rótulo também resulta de decisões humanas.', NULL, NULL),
        (614, N'fase14', N'Como avaliar padrões de um modelo não supervisionado sem respostas conhecidas?', N'Examinar coerência, interpretabilidade e utilidade dos grupos ou padrões para o objetivo da análise.', N'AVA · 3º semestre · Sem rótulos, a avaliação exige outros critérios.', NULL, NULL),
        (615, N'fase14', N'Por que preparar os dados faz parte do desenvolvimento de um modelo?', N'Porque coleta, limpeza e transformação influenciam a qualidade da informação usada no aprendizado.', N'AVA · 3º semestre · O algoritmo depende dos dados recebidos.', NULL, NULL),
        (616, N'fase14', N'Por que não existe uma única regra para preencher valores ausentes?', N'A decisão depende do contexto, da origem da ausência e do efeito da alteração sobre a análise.', N'AVA · 3º semestre · Avalie antes de remover ou preencher.', NULL, NULL),
        (617, N'fase14', N'O que a inclinação representa na regressão linear simples?', N'A variação prevista na saída quando a variável de entrada aumenta uma unidade.', N'AVA · 3º semestre · Relacione entrada e saída da reta.', NULL, NULL),
        (618, N'fase14', N'O que representa o intercepto de uma regressão linear simples?', N'O valor previsto para a saída quando a variável de entrada é zero.', N'AVA · 3º semestre · É o termo constante do modelo.', NULL, NULL),
        (619, N'fase14', N'Por que dividir exemplos em treino e teste antes de avaliar uma árvore?', N'Para avaliar previsões em exemplos que não foram usados no ajuste do modelo.', N'AVA · 3º semestre · Treinar e avaliar no mesmo conjunto distorce a medida.', NULL, NULL),
        (620, N'fase14', N'Qual objetivo orienta a atualização dos centróides no K-Means?', N'Reduzir a soma das distâncias quadráticas dos pontos aos centróides dos respectivos grupos.', N'AVA · 3º semestre · O algoritmo procura grupos internamente próximos.', NULL, NULL),
        (621, N'fase14', N'Como uma rede neural aprende sem regras explícitas para cada exemplo?', N'Ajustando parâmetros internos a partir dos exemplos apresentados durante o treinamento.', N'AVA · 3º semestre · Aprender altera os parâmetros do modelo.', NULL, NULL),
        (622, N'fase14', N'Por que funções de ativação não lineares são importantes nas redes?', N'Permitem representar relações não lineares entre entradas e saídas.', N'AVA · 3º semestre · Sem não linearidade, a capacidade de representação fica limitada.', NULL, NULL),
        (623, N'fase14', N'Por que uma avaliação de classificação pode usar várias métricas?', N'Porque precisão, recall, F1 e outras medidas descrevem aspectos diferentes dos acertos e erros.', N'AVA · 3º semestre · Uma única medida pode esconder falhas relevantes.', NULL, NULL),
        (624, N'fase14', N'Por que escolher métricas também envolve consequências sociais?', N'Erros de classificação podem prejudicar pessoas; avaliar deve considerar os custos e efeitos desses erros.', N'AVA · 3º semestre · O impacto importa além do número final.', NULL, NULL),
        (625, N'fase14', N'Qual a diferença entre parâmetros aprendidos e hiperparâmetros?', N'Parâmetros são ajustados a partir dos dados; hiperparâmetros são escolhas que controlam o treinamento e a complexidade.', N'AVA · 3º semestre · Pense em pesos aprendidos e profundidade escolhida.', NULL, NULL),
        (626, N'fase14', N'Como o grid search procura uma configuração de hiperparâmetros?', N'Avalia sistematicamente combinações dentro de um conjunto de valores definido previamente.', N'AVA · 3º semestre · É uma busca em uma grade de possibilidades.', NULL, NULL),
        (627, N'fase14', N'Por que combinar ajuste de hiperparâmetros com validação cruzada?', N'Para comparar desempenho em diferentes partições e reduzir decisões baseadas em uma divisão favorável dos dados.', N'AVA · 3º semestre · Observe média e variação do desempenho.', NULL, NULL),
        (628, N'fase14', N'Por que o modelo mais complexo nem sempre é a melhor escolha?', N'Simplicidade, custo computacional e generalização também importam, além do desempenho medido.', N'AVA · 3º semestre · Complexidade precisa se justificar.', NULL, NULL),
        (629, N'fase15', N'O que é o Manifesto Ágil (2001)?', N'O documento fundador das metodologias ágeis, que prioriza Indivíduos, Software a funcionar, Colaboração com o cliente e Resposta a mudanças.', N'Disciplina: Engenharia de Software Ágil.', NULL, NULL),
        (630, N'fase15', N'O que é o Scrum?', N'Um framework ágil iterativo (por ciclos) e incremental, focado no trabalho de equipe para entregar valor rápido ao cliente.', N'A metodologia mais adotada no mundo.', NULL, NULL),
        (631, N'fase15', N'Quem é o Product Owner (PO)?', N'A voz do cliente na equipe. É o ÚNICO responsável por definir as prioridades do produto e gerenciar o Backlog.', N'O dono da visão do produto.', NULL, NULL),
        (632, N'fase15', N'Quem é o Scrum Master?', N'O líder servidor da equipe. A sua função é garantir o uso correto do Scrum e remover impedimentos ou barreiras técnicas e burocráticas.', N'O facilitador e protetor da equipe.', NULL, NULL),
        (633, N'fase15', N'O que é uma Sprint no Scrum?', N'Um ciclo de trabalho fixo (timebox de 1 a 4 semanas) onde um conjunto de tarefas é planeado e executado até estar pronto.', N'O ''coração'' pulsante do Scrum.', NULL, NULL),
        (634, N'fase15', N'Qual o objetivo da reunião Daily Scrum?', N'Sincronização tática da equipe de Desenvolvimento. Duração máxima de 15 minutos. O que fiz ontem, farei hoje e há algum impedimento?', N'Reunião rápida, feita em pé.', NULL, NULL),
        (635, N'fase15', N'O que ocorre na Sprint Planning?', N'A reunião onde a equipe define o Objetivo da Sprint e seleciona as histórias do Backlog que consegue construir nesse ciclo.', N'O planejamento inicial.', NULL, NULL),
        (636, N'fase15', N'Qual o propósito da Sprint Review?', N'Ocorre no FIM da Sprint para demonstrar o incremento (o software pronto) ao cliente e aos stakeholders para colher feedback.', N'Hora da demonstração prática.', NULL, NULL),
        (637, N'fase15', N'O que é a Sprint Retrospective (Retrospectiva)?', N'A última cerimônia, onde a equipe debate O PROCESSO (o que correu bem, o que falhou) para encontrar melhorias contínuas para a próxima Sprint.', N'Melhorar a forma como se trabalha.', NULL, NULL),
        (638, N'fase15', N'O que é o Product Backlog?', N'A lista viva, ordenada e priorizada pelo PO de TUDO o que é necessário construir e melhorar no produto.', N'A lista de desejos do software.', NULL, NULL),
        (639, N'fase15', N'O que é o Sprint Backlog?', N'O subconjunto de tarefas selecionadas do Product Backlog pela equipe para serem desenvolvidas apenas durante a Sprint atual.', N'O trabalho fechado para o mês.', NULL, NULL),
        (640, N'fase15', N'O que é o Incremento no Scrum?', N'A soma de todas as tarefas concluídas numa Sprint. Deve ser um software testado, a funcionar e pronto para uso pelo cliente.', N'Valor real entregue no fim.', NULL, NULL),
        (641, N'fase15', N'O que é uma História de Usuário (User Story)?', N'A descrição simples de um requisito do ponto de vista de quem usa o sistema. ''Como [perfil], eu quero [ação], para [benefício]''.', N'Foca no valor gerado para o cliente.', NULL, NULL),
        (642, N'fase15', N'O que é um Épico (Epic)?', N'Uma História de Usuário muito grande ou complexa que não cabe numa única Sprint e tem de ser fatiada em histórias menores.', N'Um requisito gigante.', NULL, NULL),
        (643, N'fase15', N'O que são Story Points (Planning Poker)?', N'Uma técnica da equipe para estimar o ESFORÇO e a complexidade de uma tarefa usando valores relativos (como a sequência de Fibonacci).', N'Não mede horas, mede esforço.', NULL, NULL),
        (644, N'fase15', N'O que é um Burndown Chart?', N'Um gráfico que mostra diariamente a quantidade de trabalho restante na Sprint em relação ao tempo. A linha ''queima'' para baixo até zero.', N'Mede a velocidade da equipe.', NULL, NULL),
        (645, N'fase15', N'Como funciona o método Kanban?', N'Uma metodologia baseada na gestão visual do fluxo de trabalho contínuo através de um quadro (A Fazer, Fazendo, Feito).', N'Não tem Sprints com tempos fixos como o Scrum.', NULL, NULL),
        (646, N'fase15', N'O que é o limite de WIP no Kanban?', N'Work In Progress. Consiste em limitar a quantidade máxima de tarefas que a equipe pode realizar em simultâneo na coluna ''Fazendo''.', N'Pare de começar, comece a terminar.', NULL, NULL),
        (647, N'fase15', N'O que é o DoD (Definition of Done)?', N'O Acordo da Definição de Pronto. Um checklist que determina se uma tarefa foi codificada, testada e atende aos níveis de qualidade.', N'Pronto significa realmente pronto a usar.', NULL, NULL),
        (648, N'fase15', N'O que significa ''Timebox'' nos métodos Ágeis?', N'A duração de tempo MÁXIMA permitida para realizar uma cerimônia ou ciclo (Ex: a Daily tem um Timebox cravado de 15 minutos).', N'Bateu no tempo, a reunião acaba.', NULL, NULL),
        (649, N'fase15', N'Por que qualidade de software depende das necessidades dos usuários?', N'Porque um produto precisa apresentar as características esperadas e atender ao que foi acordado durante seu desenvolvimento.', N'ED · 3º semestre · Qualidade envolve adequação ao uso.', NULL, NULL),
        (650, N'fase15', N'Por que qualidade não deve ficar apenas com a equipe de testes?', N'Todos os envolvidos influenciam decisões e artefatos; prevenir problemas exige participação ao longo do processo.', N'ED · 3º semestre · Qualidade é responsabilidade compartilhada.', NULL, NULL),
        (651, N'fase15', N'Como a melhoria contínua se aplica à produção de software?', N'A equipe aprende com os resultados e ajusta suas práticas para executar o trabalho melhor nas próximas entregas.', N'ED · 3º semestre · Use evidências para aperfeiçoar processos.', NULL, NULL),
        (652, N'fase15', N'No modelo de McCall estudado, o que a visão de transição avalia?', N'A capacidade de adaptação a outros ambientes, incluindo portabilidade, reúso e interoperabilidade.', N'ED · 3º semestre · É uma perspectiva histórica de qualidade de produto.', NULL, NULL),
        (653, N'fase15', N'Como qualidade de processo se diferencia de qualidade de produto?', N'Produto trata do resultado entregue; processo trata da organização e das práticas usadas para produzi-lo.', N'ED · 3º semestre · Boas práticas apoiam resultados repetíveis.', NULL, NULL),
        (654, N'fase15', N'Por que padronizar processos pode melhorar estimativas de projeto?', N'Processos conhecidos facilitam comparar trabalhos e aprender sobre prazos e custos de execução.', N'ED · 3º semestre · Estimativas precisam de experiência organizada.', NULL, NULL),
        (655, N'fase15', N'O que uma representação de maturidade por estágios propõe?', N'Um caminho de evolução em que níveis alcançados sustentam as melhorias seguintes.', N'ED · 3º semestre · O material apresenta modelos históricos de maturidade.', NULL, NULL),
        (656, N'fase15', N'Qual é a diferença entre apenas executar um processo e controlá-lo por medidas?', N'Controlá-lo envolve acompanhar indicadores para compreender resultados e orientar decisões de melhoria.', N'ED · 3º semestre · Execução não é o mesmo que controle.', NULL, NULL),
        (657, N'fase15', N'Qual é a condição que distingue uma técnica dinâmica de avaliação?', N'Ela exige executar o software, como ocorre em testes e simulações.', N'ED · 3º semestre · Técnicas estáticas não dependem de execução.', NULL, NULL),
        (658, N'fase15', N'Por que validar requisitos não deve ser deixado apenas para o fim?', N'Avaliar ao longo do desenvolvimento ajuda a detectar divergências entre o produto e o que o cliente necessita.', N'ED · 3º semestre · Descobrir cedo reduz retrabalho.', NULL, NULL),
        (659, N'fase15', N'O que um teste compara para produzir evidência de falha?', N'O resultado observado com o resultado esperado sob condições previamente definidas.', N'ED · 3º semestre · Sem expectativa clara, o resultado é difícil de avaliar.', NULL, NULL),
        (660, N'fase15', N'Como teste e depuração se complementam?', N'O teste revela falhas; a depuração investiga suas causas para que possam ser corrigidas.', N'ED · 3º semestre · Detectar e explicar são atividades diferentes.', NULL, NULL),
        (661, N'fase15', N'Por que manutenção de software inclui mais que corrigir defeitos?', N'Também pode melhorar atributos, adaptar o sistema a mudanças e incorporar novas necessidades após a entrega.', N'ED · 3º semestre · Software continua evoluindo em produção.', NULL, NULL),
        (662, N'fase15', N'O que caracteriza uma manutenção perfectiva no material estudado?', N'Alterações destinadas a melhorar o produto ou atender novas necessidades e funcionalidades dos usuários.', N'ED · 3º semestre · Melhorar não significa apenas corrigir.', NULL, NULL),
        (663, N'fase15', N'Quais objetivos centrais orientam a gestão de configuração?', N'Identificar artefatos controlados, gerenciar alterações e preservar integridade e rastreabilidade.', N'ED · 3º semestre · Saiba o que mudou e em qual versão.', NULL, NULL),
        (664, N'fase15', N'Por que uma linha de base deve abranger também requisitos e testes?', N'Porque a versão de referência precisa manter coerência entre os artefatos relacionados, não somente o código.', N'ED · 3º semestre · Uma entrega é um conjunto consistente.', NULL, NULL),
        (665, N'fase33', N'Quais elementos ajudam a analisar uma falha de comunicação na equipe?', N'Emissor, mensagem, canal, receptor e ruídos. Examinar cada elemento ajuda a identificar onde o entendimento foi alterado.', N'AVA · 3º semestre · Pense no caminho percorrido pela mensagem.', NULL, NULL),
        (666, N'fase33', N'Por que um gesto pode gerar mal-entendido em uma equipe multicultural?', N'Gestos e expressões podem ter sentidos diferentes entre culturas; confirmar verbalmente a interpretação evita tratar cortesia como concordância.', N'AVA · 3º semestre · Contexto cultural também comunica.', NULL, NULL),
        (667, N'fase33', N'Qual o risco de sugerir uma solução antes de ouvir todo o relato do usuário?', N'O profissional pode diagnosticar o problema errado, gerar retrabalho e frustrar o usuário por ignorar detalhes importantes.', N'AVA · 3º semestre · Primeiro compreenda o problema.', NULL, NULL),
        (668, N'fase33', N'Como demonstrar escuta ativa sem apenas permanecer em silêncio?', N'Prestar atenção, fazer intervenções oportunas e devolver o entendimento ao interlocutor para confirmar se a mensagem foi compreendida.', N'AVA · 3º semestre · Ouvir inclui verificar o entendimento.', NULL, NULL),
        (669, N'fase33', N'O que a abordagem comportamental de liderança permite desenvolver?', N'Comportamentos observáveis e treináveis, como definir metas, acompanhar resultados, dar feedback e apoiar a equipe.', N'AVA · 3º semestre · Liderança também se aprende pela prática.', NULL, NULL),
        (670, N'fase33', N'Quando uma liderança participativa favorece profissionais experientes?', N'Quando sua experiência e autonomia permitem contribuir com decisões, como discutir arquitetura e alternativas técnicas.', N'AVA · 3º semestre · Participar fortalece o pertencimento.', NULL, NULL),
        (671, N'fase33', N'Como a inteligência emocional ajuda um líder técnico?', N'Ajuda a reconhecer e regular emoções próprias e compreender as de outras pessoas, favorecendo decisões e relações sob pressão.', N'AVA · 3º semestre · Competência técnica não substitui empatia.', NULL, NULL),
        (672, N'fase33', N'Como o exemplo cotidiano sustenta a liderança ética?', N'O líder demonstra integridade nas próprias ações e incentiva decisões e comportamentos coerentes com os valores comunicados.', N'AVA · 3º semestre · Discurso e prática precisam combinar.', NULL, NULL),
        (673, N'fase33', N'Como as teorias X e Y diferem na visão sobre os trabalhadores?', N'A teoria X pressupõe necessidade de controle; a Y admite responsabilidade, realização e satisfação no trabalho em condições favoráveis.', N'AVA · 3º semestre · A visão do gestor influencia sua gestão.', NULL, NULL),
        (674, N'fase33', N'Na teoria de Herzberg, salário e reconhecimento têm o mesmo papel?', N'Não. Condições externas, como salário, evitam insatisfação; reconhecimento, responsabilidade e crescimento estão ligados à motivação pelo trabalho.', N'AVA · 3º semestre · Diferencie condições e conteúdo do trabalho.', NULL, NULL),
        (675, N'fase33', N'Por que reunir profissionais competentes não basta para formar uma equipe?', N'São necessários objetivos claros, papéis complementares, normas e confiança para transformar competências individuais em trabalho conjunto.', N'AVA · 3º semestre · Equipe exige coordenação.', NULL, NULL),
        (676, N'fase33', N'Por que conflitos podem surgir mesmo em equipes comprometidas?', N'Pessoas interdependentes podem ter prioridades e valores distintos, além de restrições de tempo, orçamento e informação.', N'AVA · 3º semestre · Divergência não implica falta de compromisso.', NULL, NULL),
        (677, N'fase33', N'O que caracteriza uma negociação distributiva?', N'As partes disputam a divisão de um recurso limitado; melhorar a parcela de uma reduz a parcela disponível à outra.', N'AVA · 3º semestre · É a divisão de um valor considerado fixo.', NULL, NULL),
        (678, N'fase33', N'Como a negociação integrativa pode beneficiar ambas as partes?', N'Explorando interesses e alternativas para criar combinações de benefícios, em vez de discutir apenas uma única concessão.', N'AVA · 3º semestre · Procure criar valor em conjunto.', NULL, NULL),
        (679, N'fase33', N'Para que serve avaliar a BATNA antes de negociar?', N'Para conhecer a alternativa disponível caso não haja acordo e comparar a proposta da mesa com essa possibilidade.', N'AVA · 3º semestre · Alternativa fora do acordo.', NULL, NULL),
        (680, N'fase33', N'Por que preparar propostas equivalentes ajuda na negociação?', N'Combinações de valor semelhante para quem propõe permitem descobrir prioridades da outra parte e facilitar concessões entre temas.', N'AVA · 3º semestre · Compare pacotes, não só um preço.', NULL, NULL),
        (681, N'fase34', N'Como a visão socioantropológica amplia a compreensão da surdez?', N'Considera a pessoa surda em sua identidade, cultura e experiência linguística, sem reduzi-la apenas à comparação biológica com quem ouve.', N'AVA · 3º semestre · A pessoa não se resume à condição auditiva.', NULL, NULL),
        (682, N'fase34', N'Por que o uso de língua de sinais favorece o desenvolvimento da linguagem?', N'Oferece um meio visual de comunicação e expressão do pensamento acessível às pessoas surdas, sem depender da audição.', N'AVA · 3º semestre · Linguagem não é sinônimo de fala oral.', NULL, NULL),
        (683, N'fase34', N'Qual responsabilidade do professor permanece quando há intérprete em sala?', N'O professor continua responsável pelo ensino; o intérprete medeia a comunicação entre as línguas.', N'AVA · 3º semestre · Interpretar não substitui ensinar.', NULL, NULL),
        (684, N'fase34', N'Qual limitação histórica marcou as práticas oralistas descritas no material?', N'A imposição exclusiva da língua oral negligenciava a língua de sinais, a cultura e necessidades das pessoas surdas.', N'AVA · 3º semestre · O material compara abordagens educacionais.', NULL, NULL),
        (685, N'fase34', N'Qual proposta caracteriza a comunicação total na educação de surdos?', N'O uso de diferentes recursos comunicativos para favorecer a comunicação, em contraste com a exclusividade oralista.', N'AVA · 3º semestre · Não confunda com a proposta bilíngue.', NULL, NULL),
        (686, N'fase34', N'Como o bilinguismo organiza a aprendizagem linguística do aluno surdo?', N'Valoriza a língua de sinais como primeira língua e a aprendizagem da língua portuguesa como outra língua.', N'AVA · 3º semestre · As duas línguas têm estruturas próprias.', NULL, NULL),
        (687, N'fase34', N'Por que o contato entre pares surdos é relevante para a educação bilíngue?', N'Favorece identificação, cultura compartilhada e construção de uma autoimagem positiva.', N'AVA · 3º semestre · A dimensão cultural faz parte da inclusão.', NULL, NULL),
        (688, N'fase34', N'Qual é a função do intérprete de Libras e português na escola?', N'Mediar a comunicação com competência nas duas línguas e conhecimento da cultura surda, sem assumir o papel docente.', N'AVA · 3º semestre · Mediação linguística e ensino são funções diferentes.', NULL, NULL),
        (689, N'fase34', N'Por que as línguas de sinais são reconhecidas como línguas completas?', N'Possuem organização gramatical e componentes linguísticos, como morfologia, sintaxe e semântica.', N'AVA · 3º semestre · Não são simples mímicas.', NULL, NULL),
        (690, N'fase34', N'Por que não se pode presumir que todo surdo no mundo use Libras?', N'Línguas de sinais variam entre países e comunidades; Libras é uma das línguas usadas no Brasil.', N'AVA · 3º semestre · Não existe uma língua de sinais universal.', NULL, NULL),
        (691, N'fase34', N'O que se estuda na fonologia das línguas de sinais?', N'As unidades envolvidas na produção dos sinais, como configurações e movimentos, e suas combinações.', N'AVA · 3º semestre · Unidades mínimas também existem em línguas visuais.', NULL, NULL),
        (692, N'fase34', N'O que a configuração de mão descreve em um sinal?', N'O formato assumido pela mão durante a articulação, que pode permanecer ou mudar ao longo do sinal.', N'AVA · 3º semestre · Observe a forma da mão, não só sua posição.', NULL, NULL),
        (693, N'fase34', N'O que o ponto de articulação informa na Libras?', N'O lugar do corpo ou do espaço de sinalização em que o sinal é realizado.', N'AVA · 3º semestre · Localização integra a formação do sinal.', NULL, NULL),
        (694, N'fase34', N'Como dois sinais podem se distinguir mesmo com movimento igual?', N'Uma diferença na configuração da mão pode produzir sinais diferentes, mantendo outros parâmetros iguais.', N'AVA · 3º semestre · Compare todos os parâmetros.', NULL, NULL),
        (695, N'fase34', N'Como o espaço participa da sintaxe da Libras?', N'Locais no espaço podem estabelecer referentes e relações gramaticais durante o discurso.', N'AVA · 3º semestre · O espaço tem função linguística.', NULL, NULL),
        (696, N'fase34', N'Por que a expressão facial não é apenas um detalhe na sinalização?', N'Ela participa da construção de sentidos e de formas como perguntas, afirmações e exclamações.', N'AVA · 3º semestre · Expressões também fazem parte da gramática.', NULL, NULL),
        (697, N'fase35', N'Por que incluir stdio.h ao usar printf e scanf?', N'O cabeçalho declara recursos de entrada e saída usados por essas funções.', N'ED · 3º semestre · Cabeçalhos descrevem recursos da biblioteca.', NULL, NULL),
        (698, N'fase35', N'Que tipo de informação torna um comentário realmente útil em C?', N'A explicação do motivo de uma decisão ou de uma restrição que não fica evidente no código.', N'ED · 3º semestre · Comente a intenção, não repita cada comando.', NULL, NULL),
        (699, N'fase35', N'Por que o especificador de scanf deve corresponder ao tipo de destino?', N'Porque a função precisa interpretar a entrada e armazená-la conforme o tipo esperado.', N'ED · 3º semestre · Formato e variável precisam combinar.', NULL, NULL),
        (700, N'fase35', N'Por que distinguir operadores aritméticos, relacionais e lógicos?', N'Eles realizam cálculos, comparações e combinações de condições com finalidades diferentes.', N'ED · 3º semestre · Entenda a operação antes de montar a expressão.', NULL, NULL);
    INSERT INTO flashcards (id, codigo_fase, frente, verso, dica, opcoes, correta) VALUES
        (701, N'fase35', N'Como uma condição controla o caminho executado por um if?', N'Uma expressão verdadeira seleciona o bloco associado; uma falsa permite seguir outro caminho definido pelo programa.', N'ED · 3º semestre · Decisão altera o fluxo.', NULL, NULL),
        (702, N'fase35', N'O que o operador de negação lógica faz com uma condição em C?', N'Inverte seu valor lógico: uma condição verdadeira torna-se falsa e vice-versa.', N'ED · 3º semestre · Negar não é comparar por igualdade.', NULL, NULL),
        (703, N'fase35', N'Quando uma repetição controlada por contador é adequada?', N'Quando a quantidade de iterações é conhecida ou pode ser delimitada por uma contagem.', N'ED · 3º semestre · Inicialize, teste e atualize o contador.', NULL, NULL),
        (704, N'fase35', N'Qual cuidado evita que um while permaneça executando indefinidamente?', N'Garantir que o estado usado na condição possa mudar e levar ao encerramento do laço.', N'ED · 3º semestre · A condição precisa poder deixar de ser verdadeira.', NULL, NULL),
        (705, N'fase35', N'Quais índices são válidos em um vetor de tamanho n em C?', N'Os índices vão de zero até n menos um.', N'ED · 3º semestre · O primeiro elemento usa índice zero.', NULL, NULL),
        (706, N'fase35', N'O que pode acontecer ao acessar um vetor fora dos limites em C?', N'Comportamento indefinido, corrupção de dados ou falhas, pois não há verificação automática de limites.', N'ED · 3º semestre · Não dependa do compilador para proteger o acesso.', NULL, NULL),
        (707, N'fase35', N'Por que iniciar soma e contador antes de percorrer um vetor?', N'Para que a acumulação comece de um estado conhecido e não use valores indeterminados.', N'ED · 3º semestre · Cada acumulador precisa de um ponto de partida.', NULL, NULL),
        (708, N'fase35', N'Por que uma soma por linha de matriz deve ser reiniciada a cada linha?', N'Para não misturar valores acumulados das linhas anteriores no resultado da linha atual.', N'ED · 3º semestre · Observe o escopo de cada repetição.', NULL, NULL),
        (709, N'fase35', N'Como dividir um programa em funções melhora sua manutenção?', N'Cada função concentra uma tarefa, permitindo reutilizar, compreender e alterar partes menores do programa.', N'ED · 3º semestre · Responsabilidades menores facilitam revisão.', NULL, NULL),
        (710, N'fase35', N'Por que alterar um parâmetro comum em uma função C não muda a variável original?', N'Porque a função recebe uma cópia do valor; modificar a cópia não altera o objeto original.', N'ED · 3º semestre · C usa passagem por valor.', NULL, NULL),
        (711, N'fase35', N'Que informação é armazenada em uma variável ponteiro?', N'Um endereço de memória, que pode permitir acessar o objeto localizado naquele endereço.', N'ED · 3º semestre · Endereço e conteúdo são coisas distintas.', NULL, NULL),
        (712, N'fase35', N'O que o modo r indica ao abrir um arquivo com fopen?', N'Que o arquivo será aberto para leitura.', N'ED · 3º semestre · Escolha o modo conforme a operação desejada.', NULL, NULL),
        (713, N'fase36', N'Por que avaliar apenas a aparência não basta para avaliar a experiência de uso?', N'Uma interface pode ser agradável e ainda apresentar fluxos confusos ou impedir a conclusão de tarefas.', N'ED · 3º semestre · Experiência envolve o que a pessoa consegue fazer.', NULL, NULL),
        (714, N'fase36', N'Por que um fluxo de login precisa representar erro e carregamento, além do sucesso?', N'Porque esses estados fazem parte da experiência real e precisam orientar o usuário sobre o que está acontecendo.', N'ED · 3º semestre · Projete também os caminhos alternativos.', NULL, NULL),
        (715, N'fase36', N'Por que o design centrado no usuário é cíclico?', N'Resultados de pesquisa e avaliação alimentam revisões nas decisões de design ao longo do desenvolvimento.', N'ED · 3º semestre · Aprender com usuários altera a solução.', NULL, NULL),
        (716, N'fase36', N'Qual risco existe em projetar uma interface só com suposições da equipe?', N'A solução pode refletir preferências internas em vez de necessidades, limites e comportamentos reais dos usuários.', N'ED · 3º semestre · Valide pressupostos com evidências.', NULL, NULL),
        (717, N'fase36', N'O que a pesquisa de UX procura além de observar quais botões são usados?', N'Objetivos, motivos, contexto, dificuldades e sentimentos que explicam o comportamento.', N'ED · 3º semestre · Observe a pessoa e sua tarefa.', NULL, NULL),
        (718, N'fase36', N'Por que uma entrevista de pesquisa não deve virar apresentação do produto?', N'Explicar e justificar o design pode orientar as respostas e esconder dúvidas que a pesquisa precisa revelar.', N'ED · 3º semestre · Ouça antes de defender a solução.', NULL, NULL),
        (719, N'fase36', N'Como uma persona ajuda a equipe durante decisões de interface?', N'Representa padrões e necessidades dos usuários para orientar prioridades, linguagem, navegação e fluxos.', N'ED · 3º semestre · Persona é instrumento de decisão.', NULL, NULL),
        (720, N'fase36', N'Por que registrar dores e habilidades tecnológicas em uma persona?', N'Esses fatores mostram obstáculos e ajudam a ajustar a interface ao contexto e à experiência da pessoa.', N'ED · 3º semestre · Evite exigir habilidades que o público não tem.', NULL, NULL),
        (721, N'fase36', N'Por que discutir wireframes antes de cores e imagens finais?', N'Para avaliar estrutura e caminhos sem distrações visuais e corrigir problemas mais cedo.', N'ED · 3º semestre · Primeiro examine a lógica da experiência.', NULL, NULL),
        (722, N'fase36', N'Que pergunta a arquitetura da informação procura responder?', N'Como organizar, nomear e conectar conteúdos para que as pessoas encontrem o que precisam.', N'ED · 3º semestre · Organização também é parte da interface.', NULL, NULL),
        (723, N'fase36', N'Como a hierarquia visual reduz esforço de compreensão?', N'Destaca prioridades e orienta a leitura, ajudando a pessoa a reconhecer informações e ações importantes.', N'ED · 3º semestre · Nem tudo deve competir pela atenção.', NULL, NULL),
        (724, N'fase36', N'Por que um sistema de componentes ajuda a consistência visual?', N'Define padrões compartilhados de tipografia, cores, espaçamento e comportamento entre partes do produto.', N'ED · 3º semestre · Repetição coerente facilita reconhecimento.', NULL, NULL),
        (725, N'fase36', N'Que perguntas ajudam a avaliar a usabilidade de uma tela?', N'Se o usuário entende informações e rótulos, identifica o próximo passo e percebe o resultado de suas ações.', N'ED · 3º semestre · Avalie a conclusão da tarefa.', NULL, NULL),
        (726, N'fase36', N'Por que vários elementos chamativos ao mesmo tempo podem prejudicar a interface?', N'Eles competem pela atenção e dificultam identificar o que é prioritário.', N'ED · 3º semestre · Destaque precisa ter propósito.', NULL, NULL),
        (727, N'fase36', N'Como combinar dados quantitativos e qualitativos na melhoria da interface?', N'Usar métricas para localizar padrões e observações ou entrevistas para compreender os motivos desses padrões.', N'ED · 3º semestre · Números e relatos se complementam.', NULL, NULL),
        (728, N'fase36', N'Qual função útil uma microinteração deve cumprir?', N'Dar feedback, indicar estados ou orientar uma ação, ajudando o usuário a entender a interação.', N'ED · 3º semestre · Movimento deve comunicar alguma coisa.', NULL, NULL),
        (729, N'bonus3', N'Bônus 03: O que é a Síndrome do Impostor?', N'O sentimento constante de que não é bom o suficiente, de que é uma fraude e que o seu sucesso se deve apenas à sorte.', N'Afeta cerca de 80% dos desenvolvedores iniciantes.', NULL, NULL),
        (730, N'bonus3', N'Bônus 03: Qual a linguagem de programação que foi para a Lua (Apollo 11)?', N'Assembly, escrito por Margaret Hamilton e a sua equipe.', N'O código era literalmente costurado em fios de cobre.', NULL, NULL),
        (731, N'bonus3', N'Bônus 03: O que dita a Lei de Moore?', N'A observação de que o número de transístores num microchip dobra aproximadamente a cada dois anos.', N'Dita o ritmo da evolução do hardware mundial.', NULL, NULL),
        (732, N'bonus3', N'Bônus 03: Qual a principal diferença entre um Júnior, um Pleno e um Sênior?', N'Júnior precisa de orientação. Pleno resolve problemas de forma independente. Sênior previne os problemas antes que eles aconteçam e orienta a equipe.', N'Evolução natural de carreira.', NULL, NULL),
        (733, N'bonus3', N'Bônus 03: O que são Hard Skills?', N'Habilidades técnicas e mensuráveis que podem ser aprendidas, como programar em C#, configurar redes ou gerenciar bancos de dados.', N'O que coloca no currículo.', NULL, NULL),
        (734, N'bonus3', N'Bônus 03: O que são Soft Skills?', N'Habilidades comportamentais e interpessoais, como comunicação, empatia, inteligência emocional e resolução de conflitos.', N'Muitas empresas contratam pelo Hard e demitem pelo Soft.', NULL, NULL),
        (735, N'bonus3', N'Bônus 03: O que é a Síndrome de Burnout?', N'Um estado de esgotamento físico e mental extremo causado por stress crônico e prolongado no ambiente de trabalho.', N'Muito comum em TI; a saúde mental vem primeiro.', NULL, NULL),
        (736, N'bonus3', N'Bônus 03: O que significa ter um perfil profissional ''T-Shaped''?', N'Ter conhecimentos gerais amplos em várias áreas da TI (a barra horizontal do T), mas ser profundamente especialista numa única área (a barra vertical).', N'O perfil mais procurado pelas empresas.', NULL, NULL),
        (737, N'bonus3', N'Bônus 03: O que é o ''Tutorial Hell'' (Inferno dos Tutoriais)?', N'O ciclo vicioso em que o aluno consome dezenas de cursos e vídeos, mas sente-se incapaz de construir um projeto real sozinho a partir do zero.', N'Para sair: pare de assistir e comece a programar.', NULL, NULL),
        (738, N'bonus3', N'Bônus 03: O que é a Síndrome do Objeto Brilhante (Shiny Object Syndrome)?', N'A tendência de abandonar uma tecnologia ou linguagem que ainda está aprendendo, só porque surgiu um novo framework ''da moda''.', N'Foco vence o ''hype''.', NULL, NULL),
        (739, N'bonus3', N'Bônus 03: O que é um Hackathon?', N'Uma maratona de programação (geralmente de 24h a 48h) onde equipes competem para criar um protótipo de software que resolva um problema específico.', N'Excelente para networking e portfólio.', NULL, NULL),
        (740, N'bonus3', N'Bônus 03: Por que o GitHub é considerado o ''Currículo do Programador''?', N'Porque mostra o código real que escreveu, os seus commits e a sua capacidade de colaborar, o que vale mais do que diplomas em muitas vagas.', N'Mantenha o seu portfólio ativo.', NULL, NULL),
        (741, N'bonus3', N'Bônus 03: O que é o trabalho Assíncrono?', N'Modelo de trabalho onde a comunicação não exige uma resposta imediata. Permite que cada pessoa trabalhe no seu fuso horário e ritmo, usando ferramentas como o Slack ou Jira.', N'A base do trabalho remoto global.', NULL, NULL),
        (742, N'bonus3', N'Bônus 03: Qual a importância do idioma Inglês na TI?', N'As linguagens, frameworks, a melhor documentação oficial, os fóruns (Stack Overflow) e os melhores salários remotos estão todos em inglês.', N'É a verdadeira linguagem de programação universal.', NULL, NULL),
        (743, N'bonus3', N'Bônus 03: O que é o ''Fit Cultural'' numa entrevista de emprego?', N'A avaliação feita pelos RH para saber se os valores, crenças e o comportamento do candidato estão alinhados com a cultura da empresa.', N'Não basta codar bem, tem de se dar bem com a equipe.', NULL, NULL),
        (744, N'bonus3', N'Bônus 03: O que é o ''Mito do Programador 10x''?', N'A ideia de que existe um programador ''lobo solitário'' tão genial que produz dez vezes mais que uma pessoa normal.', N'O trabalho em equipe consistente supera sempre o talento isolado.', NULL, NULL),
        (745, N'bonus3', N'Bônus 03: O que é o Code Review (Revisão de Código)?', N'Prática onde outros programadores da equipe leem e analisam o seu código antes de ele ser fundido (merge) ao projeto principal.', N'A melhor forma de aprender a programar melhor.', NULL, NULL),
        (746, N'bonus3', N'Bônus 03: O que é Pair Programming (Programação em Par)?', N'Técnica Ágil onde dois programadores compartilham o mesmo tela: um digita o código (Piloto) e o outro revê e pensa na estratégia (Navegador).', N'Duas cabeças pensam melhor que uma.', NULL, NULL),
        (747, N'bonus3', N'Bônus 03: O que significa ''Networking'' profissional?', N'A construção e manutenção de uma rede de contatos profissionais que trocam conhecimentos, indicações de vagas e experiências mútuas.', N'Quem não é visto não é lembrado.', NULL, NULL),
        (748, N'bonus3', N'Bônus 03: O que é um NDA (Non-Disclosure Agreement)?', N'Um Acordo de Confidencialidade. Um contrato legal em que promete não revelar os segredos de negócio e o código da empresa a terceiros.', N'Nunca coloque código da empresa no seu GitHub público.', NULL, NULL),
        (749, N'bonus3', N'Bônus 03: O que é a técnica Pomodoro?', N'Um método de gestão de tempo que alterna blocos de 25 minutos de foco absoluto com 5 minutos de descanso para manter o cérebro fresco.', N'Aumenta a produtividade e evita a fadiga.', NULL, NULL),
        (750, N'bonus3', N'Bônus 03: O que é atuar como Freelancer?', N'Trabalhar de forma independente, prestando serviços de desenvolvimento ou design para vários clientes sem vínculo de emprego exclusivo.', N'Seja o seu próprio patrão.', NULL, NULL),
        (751, N'bonus3', N'Bônus 03: O que é um teste de ''Live Coding'' em processos seletivos?', N'Uma etapa da entrevista onde o candidato tem de compartilhar a tela e resolver um problema de lógica em tempo real, enquanto o avaliador observa.', N'Testa como lida com a pressão.', NULL, NULL),
        (752, N'bonus3', N'Bônus 03: Qual a importância de participar em Comunidades de Devs?', N'Acelera a aprendizagem através do apoio de pessoas mais experientes, ajuda a resolver bloqueios técnicos e abre portas no mercado de trabalho.', N'Discord, Reddit, Fóruns locais.', NULL, NULL),
        (753, N'bonus3', N'Bônus 03: O que significa trabalhar ''Alocado'' vs ''Outsourcing'' (Terceirização)?', N'Alocado é ser contratado para a equipe interna. Outsourcing é trabalhar para uma empresa que o ''aluga'' como consultor a outro cliente corporativo.', N'Modelo muito comum em consultorias de TI.', NULL, NULL),
        (754, N'bonus3', N'Bônus 03: O que é uma Mentoria de Carreira?', N'Um relacionamento profissional onde uma pessoa experiente (mentor) orienta, compartilha atalhos e aconselha um profissional menos experiente (mentorado).', N'Encurta a curva de aprendizagem.', NULL, NULL),
        (755, N'bonus3', N'Bônus 03: O que significa ter Inteligência Emocional no trabalho?', N'A capacidade de reconhecer e gerenciar as suas próprias emoções (não entrar em pânico perante bugs) e ter empatia com os colegas.', N'Fundamental para liderar.', NULL, NULL),
        (756, N'bonus3', N'Bônus 03: O que é a síndrome do ''Not Invented Here'' (Não Inventado Aqui)?', N'O preconceito nocivo de empresas ou equipes que recusam usar bibliotecas de terceiros excelentes, querendo criar tudo do zero internamente.', N'Não reinvente a roda.', NULL, NULL),
        (757, N'bonus3', N'Bônus 03: O que é ''Gamificação'' (O que estamos a fazer agora)?', N'O uso de mecânicas e dinâmicas de jogos (pontos, níveis, recompensas) em contextos que não são de jogo (estudo, trabalho) para aumentar o engajamento.', N'A magia do Nex_TI!', NULL, NULL),
        (758, N'bonus3', N'Bônus 03: O que é o Princípio de Pareto (Regra 80/20)?', N'A regra que diz que 80% dos resultados vêm de 20% dos esforços. Na TI, 80% dos bugs estão em 20% do código.', N'Foco no que realmente dá resultado.', NULL, NULL),
        (759, N'fase16', N'O que é o .NET Core (ou apenas .NET)?', N'Um framework open-source e multiplataforma (Windows, Linux, macOS) criado pela Microsoft para construir vários tipos de aplicações.', N'Disciplina: Web e Aplicações com .NET.', NULL, NULL),
        (760, N'fase16', N'O que é o Entity Framework Core (EF Core)?', N'Um ORM (Object-Relational Mapper) que permite manipular bancos de dados usando objetos C# em vez de escrever código SQL manual.', N'Mapeamento Objeto-Relacional.', NULL, NULL),
        (761, N'fase16', N'Para que serve uma API REST?', N'Para comunicar sistemas (Front-end e Back-end) trocando dados, geralmente no formato JSON, através do protocolo HTTP.', N'Usa os métodos GET, POST, PUT e DELETE.', NULL, NULL),
        (762, N'fase16', N'O que é a Injeção de Dependência (DI)?', N'Técnica onde uma classe recebe os objetos (dependências) de que precisa a partir de uma fonte externa, em vez de os instanciar (usar ''new'') internamente.', N'Desacopla o código e facilita os testes.', NULL, NULL),
        (763, N'fase16', N'O que é o padrão MVC no ASP.NET?', N'Um padrão de arquitetura que divide a aplicação em Model (Dados), View (Interface) e Controller (Lógica de interligação).', N'Separação de responsabilidades.', NULL, NULL),
        (764, N'fase16', N'O que é o Kestrel?', N'O servidor web embutido, multiplataforma e extremamente rápido, incluído por padrão nas aplicações ASP.NET Core.', N'Servidor web do .NET.', NULL, NULL),
        (765, N'fase16', N'O que é o NuGet?', N'O gestor de pacotes oficial da plataforma .NET. Permite instalar, remover e atualizar bibliotecas de terceiros no projeto.', N'O equivalente ao ''npm'' do Node.js.', NULL, NULL),
        (766, N'fase16', N'Qual a diferença entre IEnumerable e IQueryable no C#?', N'IEnumerable executa a consulta na memória (após trazer os dados da base). IQueryable traduz os filtros para SQL e executa diretamente no banco de dados.', N'IQueryable é muito mais otimizado para bancos de dados.', NULL, NULL),
        (767, N'fase16', N'O que é o Swagger (OpenAPI)?', N'Uma ferramenta que gera automaticamente uma interface visual e interativa para documentar e testar os endpoints de uma API REST.', N'A documentação viva da API.', NULL, NULL),
        (768, N'fase16', N'No ciclo de vida de Injeção de Dependência, o que significa ''Singleton''?', N'Cria uma única instância do serviço a primeira vez que é solicitado, e compartilha essa mesma instância com todas as requisições futuras.', N'Único para todos.', NULL, NULL),
        (769, N'fase16', N'No ciclo de vida de Injeção de Dependência, o que significa ''Scoped''?', N'Cria uma nova instância do serviço por cada requisição HTTP (request).', N'O mais comum em APIs web.', NULL, NULL),
        (770, N'fase16', N'O que é o LINQ (Language Integrated Query)?', N'Um conjunto de funcionalidades do C# que permite escrever consultas complexas (filtros, ordenações) em coleções de dados ou bancos de dados de forma nativa.', N'O SQL dentro do C#.', NULL, NULL),
        (771, N'fase16', N'O que é uma Minimal API no .NET?', N'Uma forma simplificada de criar APIs HTTP no C# com poucas linhas de código, sem a complexidade dos Controllers tradicionais.', N'Rápido e direto ao ponto.', NULL, NULL),
        (772, N'fase16', N'O que faz a palavra-chave ''await'' em C#?', N'Pausa a execução do método atual até que a tarefa assíncrona (Task) seja concluída, libertando a thread principal.', N'Programação Assíncrona (async/await).', NULL, NULL),
        (773, N'fase16', N'O que é o arquivo appsettings.json?', N'O arquivo principal de configuração das aplicações .NET, usado para guardar chaves, strings de conexão e parâmetros globais.', N'Onde fica a ''Connection String''.', NULL, NULL),
        (774, N'fase16', N'O que é o CORS (Cross-Origin Resource Sharing)?', N'Um mecanismo de segurança dos navegadores que bloqueia requisições HTTP de domínios diferentes, a menos que a API as autorize explicitamente.', N'Erro clássico ao ligar Front-end ao Back-end.', NULL, NULL),
        (775, N'fase16', N'O que é um token JWT (JSON Web Token)?', N'Um padrão de mercado para autenticação. É uma string encriptada gerada após o login que o cliente usa para acessar rotas protegidas da API.', N'O ''passaporte'' de acesso do usuário.', NULL, NULL),
        (776, N'fase16', N'O que é o Middleware no ASP.NET Core?', N'Um pedaço de código (componente) inserido no pipeline de requisições da aplicação, que pode intercetar, processar ou alterar o request/response.', N'Ex: Autenticação, tratamento de erros globais.', NULL, NULL),
        (777, N'fase16', N'O que são Data Annotations?', N'Atributos colocados por cima das propriedades de uma classe (ex: [Required], [MaxLength(50)]) para validar os dados automaticamente.', N'Validação de modelos.', NULL, NULL),
        (778, N'fase16', N'O que são as Migrations no Entity Framework Core?', N'Um sistema que permite gerar e aplicar alterações na estrutura do banco de dados (criar tabelas, colunas) a partir das mudanças feitas nas classes C#.', N'Versionamento do esquema do banco de dados.', NULL, NULL),
        (779, N'fase16', N'Qual é o papel do binding no processamento HTTP do ASP.NET Core?', N'Ele transforma dados de rota, consulta, cabeçalhos ou corpo da requisição em valores utilizáveis pelo código. Essa conversão aproxima as entradas HTTP dos parâmetros e objetos esperados pela aplicação.', N'ED · 4º semestre · Do texto recebido para os valores usados pelo programa.', NULL, NULL),
        (780, N'fase16', N'Por que a ordem dos middlewares altera o comportamento de uma aplicação ASP.NET Core?', N'A requisição atravessa uma sequência configurada de componentes. Cada etapa pode preparar informações, encaminhar ou encerrar o processamento; por isso, etapas que dependem de outras devem respeitar essa ordem.', N'ED · 4º semestre · O pipeline é uma sequência com dependências.', NULL, NULL),
        (781, N'fase16', N'O que se ganha ao agrupar endpoints relacionados com um prefixo comum?', N'A configuração fica mais modular e legível, reduzindo repetição sem exigir mudança nos endereços públicos. A organização interna pode evoluir preservando o contrato que os clientes já utilizam.', N'ED · 4º semestre · Melhor organização não precisa alterar a URL consumida.', NULL, NULL),
        (782, N'fase16', N'Por que um formulário MVC pode usar ViewModel diferente da entidade de domínio?', N'O ViewModel descreve os campos e regras de entrada daquela tela; a entidade representa os dados do domínio. Separá-los permite limitar o que o usuário envia e adaptar a interface sem expor toda a estrutura interna.', N'ED · 4º semestre · O formulário tem uma finalidade mais específica que a entidade.', NULL, NULL),
        (783, N'fase16', N'O que muda quando uma aplicação troca uma lista em memória por persistência com EF Core?', N'Os registros passam a ser gravados e consultados em uma base durável, podendo sobreviver ao reinício do processo. A interface deve passar a usar essa fonte persistente para manter consistência entre operações.', N'ED · 4º semestre · O dado precisa existir além da execução atual.', NULL, NULL),
        (784, N'fase16', N'Por que uma rotina de seed deve verificar o estado do banco antes de inserir dados iniciais?', N'Para não recriar indiscriminadamente registros a cada inicialização. A preparação da base precisa considerar que dados persistidos e cadastros feitos durante o uso já podem existir.', N'ED · 4º semestre · Inicialização não deve tratar toda execução como primeira instalação.', NULL, NULL),
        (785, N'fase16', N'Como a concorrência otimista ajuda a evitar a perda silenciosa de uma edição?', N'Ela compara uma versão conhecida pelo editor com a versão armazenada no momento de salvar. Quando outra alteração ocorreu, o conflito pode ser tratado em vez de sobrescrever dados sem perceber.', N'ED · 4º semestre · Compare a versão lida com a versão atual.', NULL, NULL),
        (786, N'fase16', N'Quais informações compõem o contrato de um endpoint HTTP?', N'Endereço, método, parâmetros, formato de entrada, validações, respostas e estrutura dos dados retornados. Esse conjunto permite ao consumidor saber como solicitar uma operação e interpretar seu resultado.', N'ED · 4º semestre · O contrato é maior que uma URL.', NULL, NULL),
        (787, N'fase16', N'Qual é a função de um proxy de desenvolvimento na integração React e ASP.NET Core?', N'Encaminhar determinadas chamadas feitas ao servidor de desenvolvimento da interface para a API. Isso simplifica o uso de caminhos locais durante o desenvolvimento, mantendo claras as responsabilidades dos dois projetos.', N'ED · 4º semestre · A chamada chega por uma porta e é encaminhada ao serviço responsável.', NULL, NULL),
        (788, N'fase16', N'Por que uma tela que consulta uma API precisa distinguir carregamento, vazio e erro?', N'Cada estado tem uma causa e uma orientação diferentes. Aguardar dados, receber uma coleção sem itens e falhar na consulta não devem produzir a mesma mensagem ou uma tela aparentemente travada.', N'ED · 4º semestre · Ausência de itens não significa falha de comunicação.', NULL, NULL),
        (789, N'fase16', N'Como roles e claims podem apoiar regras de autorização no ASP.NET Core?', N'Roles expressam papéis amplos, como administrador; claims registram afirmações ou atributos usados em decisões mais específicas. Políticas podem considerar essas informações para permitir ou negar operações.', N'ED · 4º semestre · Papel geral e informação específica atendem níveis diferentes.', NULL, NULL),
        (790, N'fase16', N'Por que proteger uma rota no React não substitui autorizar o endpoint no servidor?', N'A proteção da interface organiza a navegação, mas chamadas à API podem ocorrer sem passar por essa tela. O servidor precisa verificar a identidade e as permissões de cada operação protegida.', N'ED · 4º semestre · Ocultar a página não impede uma chamada direta.', NULL, NULL),
        (791, N'fase16', N'Como logs, métricas e rastreamento se complementam na observabilidade de uma aplicação web?', N'Logs descrevem eventos; métricas quantificam tendências; rastreamento acompanha o percurso de requisições. Juntos ajudam a relacionar sintomas, frequência e pontos onde o tempo ou a falha se concentram.', N'ED · 4º semestre · Evento, tendência e percurso são visões complementares.', NULL, NULL),
        (792, N'fase16', N'Qual é a diferença entre verificar vida e prontidão de um serviço web?', N'A verificação de vida indica se a aplicação está em execução; a de prontidão considera condições necessárias para atender, como acesso à base. Um processo vivo pode ainda não estar pronto para receber trabalho.', N'ED · 4º semestre · Estar rodando não garante conseguir atender.', NULL, NULL),
        (793, N'fase16', N'Como circuit breaker evita agravar a falha de uma dependência?', N'Após falhas repetidas, suspende temporariamente chamadas que provavelmente falhariam, permitindo resposta alternativa e posterior tentativa controlada. Ele reduz desperdício de recursos enquanto a dependência se recupera.', N'ED · 4º semestre · Pare de insistir por um período e depois reavalie.', NULL, NULL),
        (794, N'fase16', N'Por que segredos de uma aplicação .NET devem ficar fora dos arquivos versionados?', N'Senhas, tokens e chaves permitem acesso a recursos e podem comprometer o sistema quando expostos. Fontes externas de configuração permitem fornecê-los por ambiente sem incorporá-los ao código ou à imagem publicada.', N'ED · 4º semestre · Configuração pública e credencial exigem tratamentos diferentes.', NULL, NULL),
        (795, N'fase17', N'Qual a principal diferença entre uma Aplicação Nativa e Híbrida?', N'A Nativa usa o código original (Kotlin/Swift) para uma performance máxima. A Híbrida usa tecnologias web (HTML/JS) dentro de uma ''casca'' mobile.', N'Disciplina: Desenvolvimento Mobile.', NULL, NULL),
        (796, N'fase17', N'O que é o desenvolvimento Cross-Platform?', N'A capacidade de escrever um código numa única linguagem (ex: C#, Dart, JS) e compilá-lo para gerar aplicações tanto para Android como iOS.', N'Escreve uma vez, corre em todo o lado.', NULL, NULL),
        (797, N'fase17', N'O que é o .NET MAUI?', N'Framework da Microsoft (evolução do Xamarin) para criar aplicações nativas para Android, iOS, macOS e Windows utilizando C# e XAML.', N'Multi-platform App UI.', NULL, NULL),
        (798, N'fase17', N'O que é o Ciclo de Vida (Lifecycle) de uma tela mobile?', N'A série de estados pelos quais uma app passa: Criada (OnCreate), Visível (OnStart), Em Pausa (OnPause) e Destruída (OnDestroy).', N'Evita consumo excessivo de bateria em 2º plano.', NULL, NULL),
        (799, N'fase17', N'Para que serve a API de Geolocalização?', N'Permite à aplicação acessar o GPS e às redes móveis do celular para determinar a latitude e longitude do usuário.', N'Usada no Uber, iFood, Waze.', NULL, NULL),
        (800, N'fase17', N'Para que serve o SQLite em projetos Mobile?', N'É um banco de dados relacional extremamente leve, que fica embutida dentro do próprio celular para guardar informações offline.', N'Funciona sem internet.', NULL, NULL);
    INSERT INTO flashcards (id, codigo_fase, frente, verso, dica, opcoes, correta) VALUES
        (801, N'fase17', N'Qual é a linguagem oficial recomendada atualmente pela Google para o Android?', N'Kotlin (substituindo o antigo Java).', N'Moderna, concisa e segura.', NULL, NULL),
        (802, N'fase17', N'Qual é a linguagem oficial recomendada atualmente pela Apple para o iOS?', N'Swift (substituindo o antigo Objective-C).', N'Rápida e interativa.', NULL, NULL),
        (803, N'fase17', N'O que é o React Native?', N'Um framework Cross-Platform criado pelo Facebook que permite desenvolver apps nativas utilizando JavaScript e React.', N'Usado pelo Instagram e Discord.', NULL, NULL),
        (804, N'fase17', N'O que é o Flutter?', N'Um UI Toolkit Cross-Platform criado pela Google, que utiliza a linguagem Dart para desenhar interfaces bonitas e fluidas rapidamente.', N'O principal concorrente do React Native.', NULL, NULL),
        (805, N'fase17', N'O que é o arquivo APK ou AAB no Android?', N'O pacote final compilado e compactado que contém a aplicação pronta para ser instalada ou enviada para a Google Play Store.', N'Android Package / Android App Bundle.', NULL, NULL),
        (806, N'fase17', N'O que é o Xcode?', N'O Ambiente de Desenvolvimento Integrado (IDE) oficial da Apple, obrigatório para compilar e publicar aplicações para o iOS.', N'Só funciona no macOS.', NULL, NULL),
        (807, N'fase17', N'O que são Push Notifications?', N'Mensagens ou alertas curtos enviados pelo servidor diretamente para a tela do celular do usuário, mesmo quando a app está fechada.', N'Mensagens de aviso do WhatsApp ou Banco.', NULL, NULL),
        (808, N'fase17', N'O que significa ''Background Process'' no mobile?', N'Um processo em segundo plano, ou seja, código que continua a ser executado mesmo quando o usuário está noutra app.', N'Ex: O Spotify a tocar música enquanto lê e-mails.', NULL, NULL),
        (809, N'fase17', N'Qual a diferença entre ''px'' (pixels) e ''dp'' (density-independent pixels)?', N'O pixel varia de tamanho conforme a tela. O ''dp'' ajusta-se automaticamente à densidade da tela para que os botões tenham sempre o mesmo tamanho físico.', N'Responsividade móvel.', NULL, NULL),
        (810, N'fase17', N'O que é o Firebase?', N'Uma plataforma da Google (BaaS) que fornece banco de dados em tempo real, autenticação, analytics e hospedagem, simplificando o Back-end de apps.', N'Back-end as a Service.', NULL, NULL),
        (811, N'fase17', N'O que é a funcionalidade ''Hot Reload''?', N'A capacidade de injetar código alterado diretamente na app em execução, atualizando a interface em segundos sem perder o estado ou reiniciar a app.', N'Acelera a criação de UIs.', NULL, NULL),
        (812, N'fase17', N'O que é o Material Design?', N'Um sistema de design global criado pela Google focado em UI limpa, com sombras físicas, cores vibrantes e animações de transição intuitivas.', N'O padrão visual do Android.', NULL, NULL),
        (813, N'fase17', N'O que é uma WebView?', N'Um componente invisível que embute um navegador web dentro de uma app nativa, permitindo renderizar páginas HTML diretamente na tela.', N'Um browser disfarçado de app.', NULL, NULL),
        (814, N'fase17', N'O que é o sistema de Permissões Mobile?', N'O mecanismo de segurança (exigido por Android e iOS) que obriga a app a perguntar ao usuário se pode acessar a câmera, microfone ou arquivos.', N'''Permitir acesso à câmera?''', NULL, NULL),
        (815, N'fase17', N'Por que o projeto de um aplicativo móvel deve considerar bateria e conectividade desde o início?', N'Dispositivos têm recursos limitados e podem alternar entre redes ou ficar desconectados. Essas condições influenciam consumo, armazenamento, sincronização e a continuidade das tarefas do usuário.', N'ED · 4º semestre · O ambiente de uso faz parte dos requisitos.', NULL, NULL),
        (816, N'fase17', N'Qual é a utilidade do hot reload durante o desenvolvimento com Flutter?', N'Ele permite visualizar muitas alterações no aplicativo em execução com rapidez, facilitando ajustes e experimentação da interface. Isso reduz o intervalo entre editar e avaliar o resultado durante o desenvolvimento.', N'ED · 4º semestre · Pense no ciclo editar, observar e ajustar.', NULL, NULL),
        (817, N'fase17', N'Para que serve o diagnóstico realizado pelo flutter doctor?', N'Para verificar o ambiente de desenvolvimento e apontar dependências ou configurações ausentes. Seu resultado ajuda a localizar problemas de instalação antes de investigar o código do aplicativo.', N'ED · 4º semestre · Verifique a ferramenta antes de culpar a aplicação.', NULL, NULL),
        (818, N'fase17', N'Por que testes em emulador devem ser complementados por testes em aparelho físico?', N'O aparelho revela características reais de toque, sensores, visibilidade e comportamento do hardware que a simulação não reproduz integralmente. As duas formas de teste atendem a necessidades complementares.', N'ED · 4º semestre · Simular cenários e observar o hardware são tarefas diferentes.', NULL, NULL),
        (819, N'fase17', N'Por que interfaces Android usam dp para dimensões e sp para texto?', N'dp reduz diferenças provocadas pela densidade de pixels; sp também considera a preferência de tamanho de texto do usuário. Essas unidades favorecem consistência visual e acessibilidade em diferentes aparelhos.', N'ED · 4º semestre · Densidade e escala de texto não são a mesma coisa.', NULL, NULL),
        (820, N'fase17', N'Como a composição de widgets ajuda a construir uma tela Flutter?', N'A interface é organizada pela combinação de componentes com responsabilidades menores. Essa composição permite reutilizar partes da tela e compreender sua estrutura sem concentrar tudo em um único componente.', N'ED · 4º semestre · Uma tela pode ser uma árvore de pequenas partes.', NULL, NULL),
        (821, N'fase17', N'Qual é a diferença central entre StatelessWidget e StatefulWidget?', N'StatelessWidget não mantém um objeto de estado mutável próprio; StatefulWidget associa-se a um State que pode mudar ao longo do uso. Ambos podem ser reconstruídos pelo framework quando necessário.', N'ED · 4º semestre · A diferença está no estado próprio, não em impedir reconstruções.', NULL, NULL),
        (822, N'fase17', N'Por que convém limitar a região afetada por uma atualização de estado no Flutter?', N'Atualizações em níveis muito altos podem reconstruir componentes que não dependem da mudança. Organizar o estado perto de seus consumidores reduz trabalho desnecessário e facilita a manutenção.', N'ED · 4º semestre · Atualize a parte que depende do dado alterado.', NULL, NULL),
        (823, N'fase17', N'Que benefício um tempo limite traz a uma requisição de aplicativo móvel?', N'Ele evita espera indefinida quando o servidor ou a conexão não responde. Depois do limite, o aplicativo pode tratar a falha e orientar o usuário sobre uma tentativa posterior.', N'ED · 4º semestre · Esperar para sempre não é um tratamento de erro.', NULL, NULL),
        (824, N'fase17', N'O que validar antes de transformar a resposta de uma API em itens da tela mobile?', N'O status HTTP e a estrutura dos dados recebidos, incluindo tipos e valores ausentes. Uma resposta de erro pode ter formato diferente da coleção esperada, mesmo quando existe um corpo JSON.', N'ED · 4º semestre · Receber JSON não garante receber a coleção correta.', NULL, NULL),
        (825, N'fase17', N'Como escolher entre preferências, SQLite e armazenamento protegido no aplicativo?', N'Preferências atendem pequenos valores de configuração; SQLite atende dados estruturados e consultas; armazenamento protegido atende segredos de sessão. A escolha depende da estrutura, do volume e da sensibilidade dos dados.', N'ED · 4º semestre · Classifique o dado antes de escolher onde gravá-lo.', NULL, NULL),
        (826, N'fase17', N'Por que sincronizar dados após recuperar a conexão pode exigir reconciliação?', N'O mesmo registro pode ter sido alterado em outros dispositivos enquanto o aplicativo estava offline. A sincronização precisa identificar e resolver essas diferenças conforme as regras do sistema.', N'ED · 4º semestre · Enviar uma fila não resolve sozinho versões concorrentes.', NULL, NULL),
        (827, N'fase17', N'Como separar apresentação, domínio e dados melhora uma aplicação mobile?', N'A apresentação trata interação e visualização; o domínio reúne regras; a camada de dados cuida de persistência e integrações. Essa divisão reduz dependências e facilita testar e modificar cada responsabilidade.', N'ED · 4º semestre · Tela, regra e acesso a dados têm motivos diferentes para mudar.', NULL, NULL),
        (828, N'fase17', N'Qual é o papel de Form e dos validadores em um formulário Flutter?', N'Eles organizam a validação dos campos e a exibição de mensagens antes de continuar uma operação. Um validador sinaliza o problema encontrado ou indica que o campo passou pela regra definida.', N'ED · 4º semestre · A validação precisa produzir orientação útil ao usuário.', NULL, NULL),
        (829, N'fase17', N'Por que autenticação e autorização são verificações diferentes em um app móvel?', N'Autenticação verifica a identidade; autorização determina quais recursos essa identidade pode acessar. Estar autenticado não concede automaticamente todas as permissões da aplicação.', N'ED · 4º semestre · Identificar a pessoa não é liberar toda ação.', NULL, NULL),
        (830, N'fase17', N'O que uma matriz de compatibilidade ajuda a planejar nos testes mobile?', N'A cobertura de combinações relevantes de telas, versões do sistema, desempenho, sensores e condições de rede. Ela torna explícitos os cenários necessários para o público do aplicativo.', N'ED · 4º semestre · Teste variações importantes, não apenas um aparelho ideal.', NULL, NULL),
        (831, N'fase18', N'O que é uma Stored Procedure (Procedimento Armazenado)?', N'Um bloco de código SQL guardado no banco de dados para ser reutilizado várias vezes pelas aplicações que se conectam a ela.', N'Disciplina: Programação de Bancos de Dados.', NULL, NULL),
        (832, N'fase18', N'O que é uma Trigger (Gatilho)?', N'Um código SQL que é disparado e executado automaticamente no exato momento em que ocorre um evento (Insert, Update, Delete) numa tabela.', N'Ótimo para manter históricos/logs automáticos.', NULL, NULL),
        (833, N'fase18', N'Qual a principal diferença entre uma View e uma Tabela?', N'A tabela armazena dados físicos no disco. A View é uma ''tabela virtual'' temporária que apresenta o resultado de uma consulta pré-definida (SELECT).', N'A View não ocupa espaço com os dados.', NULL, NULL),
        (834, N'fase18', N'O que é o conceito ACID em transações?', N'Um conjunto de propriedades (Atomicidade, Consistência, Isolamento, Durabilidade) que garante que as transações no banco de dados processam com segurança.', N'Garante a fiabilidade do sistema bancário.', NULL, NULL),
        (835, N'fase18', N'Para que serve o comando COMMIT?', N'Para confirmar o sucesso de uma transação, guardando e gravando permanentemente as alterações efetuadas no banco de dados.', N'Confirmar a gravação.', NULL, NULL),
        (836, N'fase18', N'Para que serve o comando ROLLBACK?', N'Para reverter e cancelar todas as alterações feitas numa transação caso ocorra um erro antes do comando COMMIT.', N'O ''Desfazer'' (Ctrl+Z) do banco de dados.', NULL, NULL),
        (837, N'fase18', N'O que é um Cursor em SQL?', N'Uma estrutura de controle que permite percorrer e processar os registros (linhas) resultantes de um SELECT, um por um.', N'Como um laço ''for'', mas muito lento em SQL.', NULL, NULL),
        (838, N'fase18', N'O que é uma User-Defined Function (UDF)?', N'Uma função criada pelo usuário para efetuar cálculos ou formatar dados e retornar um único valor (escalar) ou uma tabela.', N'Pode ser usada dentro de um comando SELECT.', NULL, NULL),
        (839, N'fase18', N'Qual a principal diferença entre Procedure e Function em SQL?', N'Uma Function tem SEMPRE de devolver um valor e pode ser usada num SELECT. A Procedure pode apenas alterar dados e não pode ser usada num SELECT.', N'A função calcula, a procedure executa tarefas.', NULL, NULL),
        (840, N'fase18', N'O que é um Índice Agrupado (Clustered Index)?', N'Ordena fisicamente os dados no disco da mesma forma que o índice. Uma tabela só pode ter UM índice agrupado (geralmente a Chave Primária).', N'Muda a ordem real das folhas no arquivo.', NULL, NULL),
        (841, N'fase18', N'O que é um Índice Não Agrupado (Non-Clustered Index)?', N'Cria uma estrutura de procura separada (como um índice de livro) que aponta para os dados. Uma tabela pode ter vários.', N'Índice remissivo no fim de um livro.', NULL, NULL),
        (842, N'fase18', N'O que é um Deadlock (Impasse)?', N'Quando duas ou mais transações ficam bloqueadas eternamente, com cada uma à espera que a outra liberte um recurso (tabela) que a outra bloqueou.', N'Abraço da morte.', NULL, NULL),
        (843, N'fase18', N'O que é o nível de isolamento ''Read Uncommitted''?', N'O nível mais baixo de isolamento; permite a uma transação ler dados não confirmados (sujos) que ainda estão sendo alterados por outra transação.', N'Leitura fantasma/suja (Dirty Read).', NULL, NULL),
        (844, N'fase18', N'O que é o T-SQL (Transact-SQL)?', N'Uma extensão proprietária da linguagem SQL criada pela Microsoft para uso no SQL Server, que adiciona lógica de programação (IF, WHILE, Variáveis).', N'A linguagem de programação do SQL Server.', NULL, NULL),
        (845, N'fase18', N'O que faz o comando EXEC ou EXECUTE?', N'É utilizado para invocar e correr uma Stored Procedure ou executar uma string de código SQL dinâmico.', N'Dá o ''play'' na Procedure.', NULL, NULL),
        (846, N'fase18', N'O que é uma Tabela Temporária (ex: #Tabela)?', N'Uma tabela que existe apenas temporariamente na memória (ou no tempdb) durante a ligação do usuário e é eliminada ao encerrar a sessão.', N'Usa o símbolo ''#'' na frente do nome.', NULL, NULL),
        (847, N'fase18', N'Para que serve a função SCOPE_IDENTITY() em T-SQL?', N'Devolve o último valor de Identidade (ID autoincremental) que acabou de ser gerado pelo INSERT na sessão e escopo atuais.', N'Qual foi o ID que acabei de inserir?', NULL, NULL),
        (848, N'fase18', N'Qual a diferença entre a cláusula WHERE e a HAVING?', N'O WHERE filtra os dados ANTES do agrupamento. O HAVING filtra os dados JÁ AGRUPADOS por uma função agregadora (SUM, COUNT).', N'HAVING é o WHERE do GROUP BY.', NULL, NULL),
        (849, N'fase18', N'O que é o Particionamento de Tabelas?', N'A divisão de uma tabela gigantesca em pedaços (partições) menores distribuídos por vários discos, para melhorar drasticamente a performance.', N'Ex: Particionar dados por ano (2025, 2026).', NULL, NULL),
        (850, N'fase18', N'O que é um Plano de Execução (Execution Plan)?', N'A rota ou estratégia interna escolhida pelo motor do banco de dados para recuperar os dados da forma mais otimizada possível.', N'Mostra se o SQL está usando os índices corretamente.', NULL, NULL),
        (851, N'fase18', N'Que operações INSERT, UPDATE e DELETE representam na manipulação de registros?', N'INSERT acrescenta registros, UPDATE altera registros existentes e DELETE remove registros. Esses comandos atuam sobre os dados e devem ser usados considerando os critérios e as regras da operação.', N'ED · 4º semestre · Pense em inserir, modificar e retirar linhas.', NULL, NULL),
        (852, N'fase18', N'Como CREATE, ALTER e DROP se diferenciam dos comandos que alteram registros?', N'Eles definem, modificam ou removem estruturas e objetos do banco, como tabelas. Seu foco é a organização da base, enquanto os comandos de manipulação atuam nos dados armazenados.', N'ED · 4º semestre · Estrutura da tabela e conteúdo da tabela são níveis diferentes.', NULL, NULL),
        (853, N'fase18', N'Qual é a diferença entre COMMIT e ROLLBACK dentro de uma transação?', N'COMMIT confirma as alterações da transação; ROLLBACK desfaz as alterações ainda abrangidas por ela. Esse controle permite tratar um conjunto de operações como uma unidade de trabalho.', N'ED · 4º semestre · Confirmar ou desfazer a unidade de trabalho.', NULL, NULL),
        (854, N'fase18', N'Como uma restrição CHECK ajuda a proteger os dados de uma tabela?', N'Ela aplica uma condição aos valores gravados, como exigir um preço positivo junto de NOT NULL. A validação no banco preserva a regra mesmo quando a gravação vem de aplicações diferentes.', N'ED · 4º semestre · A regra acompanha a tabela, não apenas uma tela.', NULL, NULL),
        (855, N'fase18', N'Que cuidado o exemplo de backup do SQL Server destaca sobre o destino do arquivo?', N'O caminho de destino precisa existir para que a cópia seja gravada com sucesso. Depois da operação, é necessário observar o resultado informado pelo servidor para confirmar sua execução.', N'ED · 4º semestre · Informar um caminho não garante que ele esteja disponível.', NULL, NULL),
        (856, N'fase18', N'Quando um INNER JOIN inclui uma combinação de registros no resultado?', N'Quando os registros satisfazem a condição de correspondência entre as tabelas. Linhas sem correspondência não são preservadas por esse tipo de junção.', N'ED · 4º semestre · A presença no resultado depende do encontro definido na condição.', NULL, NULL),
        (857, N'fase18', N'O que um LEFT JOIN preserva quando não encontra correspondência na outra tabela?', N'Preserva as linhas da tabela à esquerda e apresenta valores nulos para as colunas da tabela à direita sem correspondência. Isso permite consultar também itens que ainda não possuem relacionamento correspondente.', N'ED · 4º semestre · A tabela à esquerda define as linhas preservadas.', NULL, NULL),
        (858, N'fase18', N'Como UNION organiza o resultado de duas consultas compatíveis?', N'Reúne as linhas produzidas pelos SELECTs em um único resultado. No exemplo das aulas, nomes de autores e editoras aparecem na mesma estrutura de colunas, acompanhados de uma indicação de tipo.', N'ED · 4º semestre · Empilhe resultados compatíveis em uma mesma estrutura.', NULL, NULL),
        (859, N'fase18', N'Por que um CROSS JOIN pode produzir um resultado muito grande?', N'Ele combina cada linha de uma tabela com cada linha da outra. Assim, tabelas com m e n linhas produzem m vezes n combinações antes de qualquer filtro adicional.', N'ED · 4º semestre · É o produto cartesiano das linhas.', NULL, NULL),
        (860, N'fase18', N'O que funções de agregação permitem obter em uma consulta SQL?', N'Sínteses de um conjunto de registros, como quantidade com COUNT, soma com SUM, média com AVG e extremos com MIN e MAX. Elas permitem responder perguntas sobre o conjunto, não apenas listar suas linhas.', N'ED · 4º semestre · Transforme vários registros em uma medida resumida.', NULL, NULL),
        (861, N'fase18', N'Como uma view pode facilitar a manutenção de consultas recorrentes?', N'Ela dá uma representação reutilizável a uma consulta, podendo esconder parte de sua complexidade e apresentar dados organizados. Assim, consumidores não precisam repetir a mesma composição em cada acesso.', N'ED · 4º semestre · Reutilize uma consulta por meio de uma visão nomeada.', NULL, NULL),
        (862, N'fase18', N'Por que excluir um registro pai exige considerar suas chaves estrangeiras dependentes?', N'A exclusão pode deixar referências sem destino. O banco aplica a regra configurada, que pode impedir a remoção ou tratar dependentes por uma ação apropriada, como cascata quando prevista.', N'ED · 4º semestre · A relação precisa continuar coerente depois da exclusão.', NULL, NULL),
        (863, N'fase18', N'Que benefício um procedimento armazenado traz para operações repetidas no banco?', N'Ele reúne instruções SQL como uma subrotina reutilizável, centralizando lógica de acesso e permitindo controlar quem pode executá-la. Isso facilita manutenção de operações usadas por diferentes chamadas.', N'ED · 4º semestre · Uma operação pode ter um ponto comum de implementação.', NULL, NULL),
        (864, N'fase18', N'Por que os tipos dos parâmetros de um procedimento devem ser compatíveis com os dados consultados?', N'A compatibilidade evita comparações inadequadas e erros ao utilizar os valores recebidos em filtros e operações. O contrato do procedimento deve refletir o significado e o tipo esperado de cada entrada.', N'ED · 4º semestre · Um parâmetro precisa representar corretamente o campo que será comparado.', NULL, NULL),
        (865, N'fase18', N'O que diferencia a execução de um trigger DML da chamada comum de um procedimento?', N'O trigger é acionado automaticamente por um evento de alteração configurado na tabela ou view, como INSERT, UPDATE ou DELETE. Um procedimento comum é chamado explicitamente pelo consumidor.', N'ED · 4º semestre · Um reage a um evento; o outro é invocado diretamente.', NULL, NULL),
        (866, N'fase18', N'Qual é a diferença entre triggers AFTER e INSTEAD OF no SQL Server?', N'AFTER executa em resposta à operação após sua realização conforme as verificações aplicáveis; INSTEAD OF executa no lugar da operação que o acionou. A escolha altera quando e como a lógica participa da mudança.', N'ED · 4º semestre · Depois da operação ou em substituição a ela.', NULL, NULL),
        (867, N'fase19', N'O que é a Cloud Computing (Computação em Nuvem)?', N'A entrega de serviços informáticos (servidores, bancos de dados, software) via Internet, gerenciados por terceiros com base no ''pague o que utilizar''.', N'Disciplina: Cloud e DevOps.', NULL, NULL),
        (868, N'fase19', N'O que é o Docker?', N'Uma plataforma de código aberto que automatiza a instalação e execução de aplicações em unidades padronizadas e isoladas chamadas Contentores.', N'Acaba com o ''no meu PC funciona''.', NULL, NULL),
        (869, N'fase19', N'Para que serve o Kubernetes?', N'É um sistema (orquestrador) desenvolvido pela Google para automatizar o deployment, o escalonamento e a gestão de milhares de contentores Docker.', N'O capitão/orquestrador dos contentores.', NULL, NULL),
        (870, N'fase19', N'O que significa CI/CD?', N'Continuous Integration (Integração Contínua) e Continuous Deployment (Entrega Contínua). O processo de automatizar testes e lançamentos de código em produção.', N'Automatização desde o ''git push'' até ao servidor.', NULL, NULL),
        (871, N'fase19', N'Defina IaaS, PaaS e SaaS.', N'IaaS (Máquina/Infraestrutura alugada); PaaS (Ambiente para desenvolvimento); SaaS (Software final pronto para o usuário, ex: Gmail).', N'Os 3 níveis do serviço Cloud.', NULL, NULL),
        (872, N'fase19', N'O que é Escalabilidade Horizontal?', N'Aumentar a capacidade adicionando MAIS máquinas (servidores) ao sistema, dividindo a carga entre eles.', N'Scale-out.', NULL, NULL),
        (873, N'fase19', N'O que é Escalabilidade Vertical?', N'Aumentar a capacidade colocando mais recursos físicos (mais RAM ou CPU mais potente) na MESMA máquina existente.', N'Scale-up.', NULL, NULL),
        (874, N'fase19', N'O que é Serverless (Computação sem Servidor)?', N'Modelo onde o provedor Cloud aloca recursos dinamicamente. O programador apenas escreve o código (funções) e só paga pelo tempo exato de execução.', N'Ex: AWS Lambda.', NULL, NULL),
        (875, N'fase19', N'O que é IaC (Infraestrutura como Código)?', N'A gestão e provisionamento de centros de dados Cloud através de arquivos com código e scripts, em vez de configurar as coisas manualmente em painéis web.', N'O servidor configurado em linhas de código.', NULL, NULL),
        (876, N'fase19', N'O que é o Terraform?', N'Uma ferramenta open-source popular de IaC (Infraestrutura como Código) que permite criar, alterar e gerenciar redes seguras e eficientes em múltiplos provedores Cloud.', N'Automatiza a criação do servidor.', NULL, NULL),
        (877, N'fase19', N'O que é o AWS EC2?', N'Amazon Elastic Compute Cloud. O serviço de IaaS da Amazon que permite alugar e correr servidores virtuais (instâncias) na nuvem.', N'A máquina virtual da Amazon.', NULL, NULL),
        (878, N'fase19', N'O que é o Amazon S3?', N'Amazon Simple Storage Service. Um serviço de armazenamento de arquivos em nuvem seguro e infinitamente escalável focado em objetos (imagens, backups).', N'O ''disco rígido'' infinito da AWS.', NULL, NULL),
        (879, N'fase19', N'O que é um Pipeline de DevOps?', N'Um conjunto de etapas automatizadas (Build, Test, Deploy) que o código percorre desde o repositório até ser publicado no servidor final.', N'A esteira de montagem do software.', NULL, NULL),
        (880, N'fase19', N'O que é uma Arquitetura de Microsserviços?', N'Onde uma aplicação grande é construída como um conjunto de pequenos serviços modulares e independentes, cada um correndo o seu próprio processo.', N'Opõe-se à arquitetura Monolítica.', NULL, NULL),
        (881, N'fase19', N'O que é o GitHub Actions?', N'Uma plataforma nativa no GitHub que permite criar, testar e fazer o deployment automático do seu código (pipeline de CI/CD).', N'Ação automatizada sempre que se faz um ''push''.', NULL, NULL),
        (882, N'fase19', N'O que significa ''Alta Disponibilidade'' (High Availability)?', N'Sistemas configurados (usando balanceadores e redundância) para garantirem que estão online e acessíveis 99,99% do tempo, sem paralisações.', N'O sistema não pode cair.', NULL, NULL),
        (883, N'fase19', N'No Docker, o que é uma Imagem?', N'Um modelo/arquivo imutável de apenas leitura contendo as instruções necessárias (SO, bibliotecas, código) para instanciar um Contentor.', N'A ''forma de bolo'' do contentor.', NULL, NULL),
        (884, N'fase19', N'O que faz o comando ''docker-compose up''?', N'Lê o arquivo ''docker-compose.yml'' e inicia simultaneamente múltiplos contentores interligados (ex: Aplicação + Banco de Dados).', N'Sobe todo o ambiente de uma vez.', NULL, NULL),
        (885, N'fase19', N'O que é o Blue-Green Deployment?', N'Técnica de lançamento de software em que dois ambientes idênticos coexistem (Azul ativo, Verde atualizado). O tráfego é movido do Azul para o Verde sem o usuário notar.', N'Atualização com Zero Downtime (sem paralisação).', NULL, NULL),
        (886, N'fase19', N'O que é Monitorização e Observabilidade em DevOps?', N'Uso de ferramentas (métricas, logs, traces) para compreender rapidamente o estado interno de um sistema e detetar gargalos ou quedas antes do cliente.', N'Medição contínua da saúde do software.', NULL, NULL),
        (887, N'fase19', N'O que diferencia IaaS, PaaS e SaaS quanto à responsabilidade do cliente?', N'Cada modelo abstrai partes diferentes da solução, mudando o que o cliente gerencia e o que fica a cargo do provedor.', N'AVA · 4º semestre · Observe o nível de controle necessário.', NULL, NULL),
        (888, N'fase19', N'Que recursos básicos uma oferta IaaS disponibiliza?', N'Capacidade computacional, armazenamento e rede, normalmente com servidores virtuais.', N'AVA · 4º semestre · Infraestrutura é a base da aplicação.', NULL, NULL),
        (889, N'fase19', N'Como PaaS permite concentrar trabalho no desenvolvimento da aplicação?', N'O provedor administra componentes da plataforma e oferece ambiente para criar e executar aplicações.', N'AVA · 4º semestre · Parte da operação fica abstraída.', NULL, NULL),
        (890, N'fase19', N'Qual a diferença prática de SaaS para uma infraestrutura contratada isoladamente?', N'No SaaS o usuário utiliza uma aplicação pronta; em infraestrutura isolada ainda precisa construir e administrar outras camadas.', N'AVA · 4º semestre · É software entregue como serviço.', NULL, NULL),
        (891, N'fase19', N'Como a alocação dinâmica de recursos ajuda diante de demandas variáveis?', N'Permite ajustar capacidade às necessidades de uso, em vez de manter sempre a mesma estrutura fixa.', N'AVA · 4º semestre · Capacidade acompanha a demanda.', NULL, NULL),
        (892, N'fase19', N'Por que acompanhar consumo é importante mesmo quando a nuvem escala automaticamente?', N'Porque medir permite relacionar uso a aplicações ou usuários e controlar gastos e desperdícios.', N'AVA · 4º semestre · Escalar não elimina a gestão de custos.', NULL, NULL),
        (893, N'fase19', N'Como serviços em nuvem podem apoiar equipes distribuídas?', N'Disponibilizam sistemas e dados por acesso remoto, permitindo colaboração sem depender do mesmo local físico.', N'AVA · 4º semestre · Colaboração exige acesso adequado e seguro.', NULL, NULL),
        (894, N'fase19', N'Por que múltiplos usuários e aplicações exigem atenção à segurança na nuvem?', N'Ampliam a superfície de ataque e tornam necessário controlar acesso, isolamento e proteção das informações.', N'AVA · 4º semestre · Disponibilidade em rede exige controles.', NULL, NULL),
        (895, N'fase19', N'Quais dimensões precisam ser consideradas numa evolução para a nuvem?', N'Infraestrutura, arquitetura e práticas de desenvolvimento, pois mudar apenas servidores não resolve todas as necessidades.', N'AVA · 4º semestre · A transformação vai além da hospedagem.', NULL, NULL),
        (896, N'fase19', N'Que função uma SAN desempenha na infraestrutura de armazenamento?', N'Fornece uma rede especializada para acesso ao armazenamento em bloco pelos servidores.', N'AVA · 4º semestre · Armazenamento pode estar separado do servidor.', NULL, NULL),
        (897, N'fase19', N'Por que arquitetura e operação precisam ser pensadas juntas em aplicações de nuvem?', N'Alocação dinâmica e distribuição exigem decisões coerentes de desempenho, disponibilidade, segurança e manutenção.', N'AVA · 4º semestre · A arquitetura influencia o funcionamento em produção.', NULL, NULL),
        (898, N'fase19', N'O que distingue uma aplicação cloud-native de uma apenas transferida para a nuvem?', N'Ela já é projetada considerando automação, elasticidade, resiliência e distribuição.', N'AVA · 4º semestre · O ambiente participa das decisões de projeto.', NULL, NULL),
        (899, N'fase19', N'Por que DevOps não se resume à adoção de uma ferramenta de publicação?', N'Envolve colaboração entre desenvolvimento e operação e automação ao longo do ciclo do software.', N'AVA · 4º semestre · A cultura sustenta as ferramentas.', NULL, NULL),
        (900, N'fase19', N'Como a integração contínua ajuda a encontrar erros mais cedo?', N'Integra pequenas mudanças com frequência e executa build e testes automatizados sobre elas.', N'AVA · 4º semestre · Integrações menores são mais fáceis de verificar.', NULL, NULL);
    INSERT INTO flashcards (id, codigo_fase, frente, verso, dica, opcoes, correta) VALUES
        (901, N'fase19', N'Entrega contínua exige publicar automaticamente cada alteração em produção?', N'Não. Mantém o software pronto para liberação, mas pode conservar uma etapa de aprovação antes de publicar.', N'AVA · 4º semestre · Entrega contínua e implantação contínua não são idênticas.', NULL, NULL),
        (902, N'fase19', N'Qual vantagem de descrever infraestrutura como código?', N'Permite provisionar e gerenciar ambientes de maneira repetível, reduzindo configurações manuais inconsistentes.', N'AVA · 4º semestre · O ambiente também pode ser versionado.', NULL, NULL),
        (903, N'fase20', N'O que é um MVP (Minimum Viable Product)?', N'A versão mais simples de um novo produto que permite à equipe recolher o máximo de validação sobre o cliente com o mínimo esforço.', N'Disciplina: Empreendedorismo em TI.', NULL, NULL),
        (904, N'fase20', N'Qual o principal objetivo do Empreendedorismo em TI?', N'Identificar problemas ou necessidades reais da sociedade e criar soluções de base tecnológica escaláveis e inovadoras.', N'Não é só programar, é resolver uma dor.', NULL, NULL),
        (905, N'fase20', N'O que caracteriza uma Startup?', N'Um grupo de pessoas à procura de um modelo de negócio inovador, repetível e escalável, a trabalhar em condições de extrema incerteza.', N'Não é apenas uma ''pequena empresa''.', NULL, NULL),
        (906, N'fase20', N'O que é um Modelo B2B (Business to Business)?', N'Um modelo onde a empresa comercializa os seus produtos (como softwares ERP) ou serviços diretamente a outras Empresas, não a pessoas físicas.', N'Ex: A Microsoft a vender o Office à IBM.', NULL, NULL),
        (907, N'fase20', N'O que é um Modelo B2C (Business to Consumer)?', N'Um modelo comercial em que os produtos ou serviços são vendidos diretamente da empresa para o consumidor ou usuário final.', N'Ex: Spotify, Netflix, iFood.', NULL, NULL),
        (908, N'fase20', N'O que é um ''Pitch'' (ou Pitch Deck)?', N'Uma apresentação verbal rápida (entre 3 a 5 minutos) utilizada para vender a ideia da sua startup a potenciais investidores ou parceiros.', N'Venda de elevador (Elevator Pitch).', NULL, NULL),
        (909, N'fase20', N'O que é um Investidor Anjo (Angel Investor)?', N'Uma pessoa física (geralmente empresários de sucesso) que investe o seu próprio capital numa startup ainda na sua fase inicial de risco.', N'Aporta dinheiro e mentoria inteligente (Smart Money).', NULL, NULL),
        (910, N'fase20', N'O que é Venture Capital (Capital de Risco)?', N'Fundos de investimento de grandes grupos aplicados em startups maduras com alto potencial de crescimento escalável e retorno agressivo.', N'Injetam os milhões na empresa.', NULL, NULL),
        (911, N'fase20', N'O que significa o indicador CAC (Custo de Aquisição de Clientes)?', N'O montante médio que a empresa tem de gastar em marketing, anúncios e vendas para conseguir atrair um único cliente novo para o produto.', N'Quanto custa comprar um cliente.', NULL, NULL),
        (912, N'fase20', N'O que é a métrica LTV (Lifetime Value)?', N'O lucro financeiro líquido que um cliente gera para a empresa durante todo o tempo em que mantém relacionamento e assinatura ativa.', N'A regra de ouro: O LTV tem de ser superior ao CAC.', NULL, NULL),
        (913, N'fase20', N'O que significa o Churn Rate?', N'A taxa de cancelamento. A percentagem de clientes que param de pagar ou de usar o serviço da sua empresa num determinado período.', N'A métrica do ''balde furado''.', NULL, NULL),
        (914, N'fase20', N'O que significa o termo ''Pivotar'' (Pivot) no mundo das startups?', N'Alterar fundamentalmente a estratégia do modelo de negócio ou as funcionalidades do produto ao perceber que a ideia original não está dando lucro.', N'Mudar a rota do barco antes dele afundar.', NULL, NULL),
        (915, N'fase20', N'O que é o Break-even Point (Ponto de Equilíbrio)?', N'O ponto financeiro de viragem em que os custos da empresa são iguais às suas receitas. Daí para a frente, a empresa passa finalmente a gerar lucro líquido.', N'O famoso ''ficar a zero e sair do vermelho''.', NULL, NULL),
        (916, N'fase20', N'O que é a prática do ''Bootstrapping''?', N'Iniciar e desenvolver uma startup usando apenas os próprios recursos do fundador e o dinheiro dos primeiros clientes, sem aceitar investimento externo.', N'Crescer pelos seus próprios meios.', NULL, NULL),
        (917, N'fase20', N'O que é o Business Model Canvas?', N'Uma ferramenta de gestão estratégica em formato visual (1 quadro com 9 blocos) focada em desenvolver ou documentar um modelo de negócio completo.', N'A evolução ágil do Plano de Negócios clássico.', NULL, NULL),
        (918, N'fase20', N'O que é a Proposta de Valor (Value Proposition)?', N'A afirmação simples que explica o benefício do seu produto, como ele resolve a dor do cliente e por que ele deve comprar de si e não da concorrência.', N'O pilar central do seu negócio.', NULL, NULL),
        (919, N'fase20', N'O que é o conceito de ''Growth Hacking''?', N'Uma abordagem focada no marketing impulsionado por experiências rápidas, ciência de dados e desenvolvimento de software para garantir o crescimento (Growth) explosivo.', N'Usar tecnologia no marketing em prol do crescimento.', NULL, NULL),
        (920, N'fase20', N'O que é o indicador ROI (Return on Investment)?', N'Retorno Sobre o Investimento. Uma métrica utilizada para medir o lucro (rentabilidade) gerado num projeto em relação ao montante que foi inicialmente investido nele.', N'O projeto deu dinheiro ou prejuízo?', NULL, NULL),
        (921, N'fase20', N'O que é considerado uma Startup ''Unicórnio''?', N'Uma empresa privada de tecnologia ou startup que consegue alcançar uma avaliação de mercado financeira igual ou superior a 1 Milhão de Dólares antes de ir para a bolsa de valores.', N'Uma avaliação astronômica e rara.', NULL, NULL),
        (922, N'fase20', N'O que preconiza o método ''Lean Startup'' (Startup Enxuta) criado por Eric Ries?', N'Aplicar o ciclo ''Construir-Medir-Aprender'' num processo científico focado em lançar o MVP o mais rápido possível para validar fatos sem desperdiçar dinheiro e tempo.', N'Falhar rapidamente, aprender depressa, gastar pouco.', NULL, NULL),
        (923, N'fase20', N'Como a administração contribui para transformar uma ideia em operação?', N'Coordena esforços e recursos para alcançar objetivos de forma organizada.', N'AVA · 4º semestre · Uma solução precisa funcionar como atividade contínua.', NULL, NULL),
        (924, N'fase20', N'Por que um empreendedor precisa de habilidades humanas além das técnicas?', N'Porque também precisa trabalhar com pessoas, comunicar decisões e coordenar relações na organização.', N'AVA · 4º semestre · Conhecimento técnico é apenas uma parte da gestão.', NULL, NULL),
        (925, N'fase20', N'Que papel as habilidades conceituais têm na administração?', N'Permitem compreender a organização como conjunto e relacionar decisões a um contexto mais amplo.', N'AVA · 4º semestre · Enxergue além de uma tarefa isolada.', NULL, NULL),
        (926, N'fase20', N'Como controles preliminar, concorrente e posterior se diferenciam?', N'Atuam antes da atividade, durante sua execução e sobre os resultados obtidos, respectivamente.', N'AVA · 4º semestre · O momento do controle muda sua finalidade.', NULL, NULL),
        (927, N'fase20', N'O que distingue uma iniciativa empreendedora de apenas imaginar uma solução?', N'Identificar oportunidade, organizar recursos e implementar algo que gere valor.', N'AVA · 4º semestre · Empreender envolve execução e aprendizagem.', NULL, NULL),
        (928, N'fase20', N'Inovar exige sempre inventar algo totalmente novo?', N'Não. Melhorias relevantes em processos, produtos ou formas de atender necessidades também podem gerar inovação.', N'AVA · 4º semestre · O critério central é a criação de valor.', NULL, NULL),
        (929, N'fase20', N'Por que sustentabilidade faz parte da análise de um empreendimento?', N'Porque o negócio se relaciona com efeitos econômicos, sociais e ambientais de suas decisões.', N'AVA · 4º semestre · Resultados precisam ser pensados no tempo e no contexto.', NULL, NULL),
        (930, N'fase20', N'Como microeconomia e macroeconomia oferecem perspectivas distintas ao empreendedor?', N'A primeira analisa agentes e decisões individuais; a segunda examina fenômenos amplos, como inflação e crescimento.', N'AVA · 4º semestre · As duas escalas afetam o negócio.', NULL, NULL),
        (931, N'fase20', N'Que informações um plano de negócios procura organizar?', N'Objetivos, caminhos para alcançá-los e recursos necessários, apoiando análise e decisão.', N'AVA · 4º semestre · Planejar transforma hipóteses em questões verificáveis.', NULL, NULL),
        (932, N'fase20', N'Por que o plano de negócios deve continuar sendo revisto após a abertura?', N'Porque expansão, novos produtos e mudanças de mercado exigem reavaliar caminhos e recursos.', N'AVA · 4º semestre · Planejamento acompanha o ciclo da empresa.', NULL, NULL),
        (933, N'fase20', N'Qual pergunta ajuda a separar uma boa ideia de uma oportunidade real?', N'Se existe uma necessidade de mercado e se a solução proposta pode gerar valor para clientes.', N'AVA · 4º semestre · Interesse pessoal não prova demanda.', NULL, NULL),
        (934, N'fase20', N'Por que priorizar oportunidades em vez de executar todas ao mesmo tempo?', N'Tempo, recursos e capacidade são limitados; é preciso escolher opções alinhadas aos objetivos do negócio.', N'AVA · 4º semestre · Priorizar também significa decidir o que adiar.', NULL, NULL),
        (935, N'fase20', N'Como a capacidade operacional influencia uma empresa de serviços de TI?', N'Limita o volume de atendimento ou entrega e afeta custos, qualidade e experiência dos clientes.', N'AVA · 4º semestre · Promessas precisam caber na capacidade de execução.', NULL, NULL),
        (936, N'fase20', N'Para que acompanhar o fluxo de caixa no planejamento financeiro?', N'Para compreender entradas e saídas de recursos e antecipar dificuldades que afetem a continuidade da operação.', N'AVA · 4º semestre · Resultado e disponibilidade de dinheiro não são a mesma coisa.', NULL, NULL),
        (937, N'fase20', N'O que representa o ponto de equilíbrio de um empreendimento?', N'A situação em que a receita total iguala os custos totais, sem lucro nem prejuízo naquele nível de operação.', N'AVA · 4º semestre · Relaciona volume de vendas e estrutura de custos.', NULL, NULL),
        (938, N'fase20', N'Qual papel do marketing de conteúdo na comunicação de um negócio?', N'Oferecer conteúdo relevante ao público e apoiar o relacionamento e o posicionamento da proposta comercial.', N'AVA · 4º semestre · Conteúdo deve atender a uma necessidade do público.', NULL, NULL),
        (939, N'fase37', N'Por que compartilhar código entre plataformas não elimina testes em cada sistema móvel?', N'Diferenças de comportamento, aparência e acesso a recursos continuam existindo entre plataformas.', N'AVA · 4º semestre · Reúso de código não garante experiência idêntica.', NULL, NULL),
        (940, N'fase37', N'Por que câmera e localização precisam ser consideradas nos testes em aparelhos reais?', N'Porque dependem de permissões e do funcionamento dos recursos do dispositivo.', N'AVA · 4º semestre · Preveja autorização e recusa do usuário.', NULL, NULL),
        (941, N'fase37', N'Qual proposta do React Native favorece aplicativos para Android e iOS?', N'Construir aplicações com JavaScript ou TypeScript e componentes nativos a partir de uma base compartilhada.', N'AVA · 4º semestre · Uma base pode atender plataformas diferentes.', NULL, NULL),
        (942, N'fase37', N'Como View e Text dividem responsabilidades no React Native?', N'View organiza contêineres e layout; Text representa conteúdo textual na interface.', N'AVA · 4º semestre · Texto não deve ser tratado como um contêiner genérico.', NULL, NULL),
        (943, N'fase37', N'O que um componente personalizado encapsula?', N'Estrutura, estilo e comportamento que podem ser reutilizados em diferentes partes do aplicativo.', N'AVA · 4º semestre · Reúso ajuda a manter consistência.', NULL, NULL),
        (944, N'fase37', N'Para que props são usadas entre componentes React?', N'Para fornecer dados e configurações que orientam o comportamento ou a apresentação do componente.', N'AVA · 4º semestre · Props são entradas do componente.', NULL, NULL),
        (945, N'fase37', N'Que problema useState resolve em um componente funcional?', N'Permite manter e atualizar informações que variam com o tempo, como entradas e estados da interface.', N'AVA · 4º semestre · Mudança de estado pode atualizar a tela.', NULL, NULL),
        (946, N'fase37', N'Qual característica central do AsyncStorage atende à persistência simples?', N'Armazenamento assíncrono de pares chave-valor que podem permanecer entre sessões.', N'AVA · 4º semestre · Persistência não é o mesmo que estado em memória.', NULL, NULL),
        (947, N'fase37', N'Como endpoints organizam o acesso aos dados de uma API?', N'URLs identificam recursos sobre os quais o cliente solicita operações.', N'AVA · 4º semestre · Pense em recursos como usuários ou produtos.', NULL, NULL),
        (948, N'fase37', N'Como GET e PATCH diferem em uma API HTTP?', N'GET solicita uma representação do recurso; PATCH é usado para alterações parciais.', N'AVA · 4º semestre · A intenção da operação deve ser explícita.', NULL, NULL),
        (949, N'fase37', N'Por que FlatList é mais adequada que renderizar uma longa lista inteira de uma vez?', N'Utiliza virtualização para limitar os itens renderizados conforme a área visível e reduzir uso de recursos.', N'AVA · 4º semestre · Listas longas exigem cuidado com memória e renderização.', NULL, NULL),
        (950, N'fase37', N'Quando SectionList é mais apropriada que uma lista simples?', N'Quando os dados precisam ser apresentados em grupos ou seções com cabeçalhos.', N'AVA · 4º semestre · A estrutura da lista deve refletir os dados.', NULL, NULL),
        (951, N'fase37', N'Que organização a navegação por abas oferece ao aplicativo?', N'Acesso rápido a seções principais, que podem preservar seus próprios estados e históricos.', N'AVA · 4º semestre · Abas favorecem áreas de importância semelhante.', NULL, NULL),
        (952, N'fase37', N'Por que indicar carregamento e erro durante uma consulta remota?', N'Para que o usuário compreenda a espera e saiba quando a operação não foi concluída.', N'AVA · 4º semestre · Feedback evita uma interface aparentemente travada.', NULL, NULL),
        (953, N'fase37', N'Como o armazenamento local pode melhorar uso sem conexão?', N'Mantém informações no dispositivo para consulta e operação sem depender de toda leitura vir do servidor.', N'AVA · 4º semestre · Dados locais precisam de estratégia de atualização.', NULL, NULL),
        (954, N'fase37', N'Qual função de uma fila de operações pendentes em um aplicativo offline?', N'Registrar ações e seus estados para que possam ser processadas ou tentadas novamente na sincronização.', N'AVA · 4º semestre · Não confunda pendente com confirmado.', NULL, NULL),
        (955, N'fase38', N'Em relações étnico-raciais, por que raça é tratada como construção social?', N'Porque características físicas recebem significados e consequências sociais em contextos históricos. Isso permite estudar o racismo sem aceitar a ideia de hierarquias biológicas entre grupos humanos.', N'AVA · 4º semestre · Separe a aparência física do valor social que lhe é atribuído.', NULL, NULL),
        (956, N'fase38', N'O que caracteriza o pertencimento a um grupo étnico?', N'Experiências, referências culturais e reconhecimento de origens ou interesses compartilhados. Esse pertencimento envolve tanto a identificação da própria pessoa quanto suas relações com outros grupos.', N'AVA · 4º semestre · Pense em pertencimento e história compartilhada.', NULL, NULL),
        (957, N'fase38', N'Como identificações endógena e exógena participam da identidade étnica?', N'A endógena parte do reconhecimento do próprio sujeito ou grupo; a exógena envolve classificações atribuídas por outros. A interação entre elas torna a identidade um processo social dinâmico.', N'AVA · 4º semestre · Quem atribui a identificação: o próprio grupo ou outros?', NULL, NULL),
        (958, N'fase38', N'Que problema existe em explicar desigualdades sociais pelo chamado racismo científico?', N'Essa doutrina tentou transformar relações históricas de poder em diferenças naturais entre pessoas. Assim, justificava exclusão e hierarquias por argumentos biológicos sem fundamento para essa finalidade.', N'AVA · 4º semestre · Desigualdade histórica não é destino biológico.', NULL, NULL),
        (959, N'fase38', N'Como distinguir preconceito de discriminação racial?', N'Preconceito envolve crenças e julgamentos antecipados sobre um grupo; discriminação corresponde a práticas e ações que produzem tratamento desigual. As duas dimensões se relacionam, mas não são idênticas.', N'AVA · 4º semestre · Diferencie julgamento e ação.', NULL, NULL),
        (960, N'fase38', N'Por que indicadores de acesso à educação e ao emprego ajudam a estudar o racismo?', N'Eles permitem observar desigualdades de oportunidades entre grupos, inclusive quando não há uma declaração explícita de preconceito. A análise deve considerar os processos históricos e sociais que produzem esses resultados.', N'AVA · 4º semestre · Observe oportunidades e resultados, além de intenções.', NULL, NULL),
        (961, N'fase38', N'Qual é o risco de usar a ideia de convivência racial harmoniosa para explicar toda a história brasileira?', N'Ela pode ocultar escravização, conflitos, exclusão e desigualdades. Reconhecer trocas culturais não elimina a necessidade de examinar relações de poder e discriminação.', N'AVA · 4º semestre · Convivência não prova igualdade.', NULL, NULL),
        (962, N'fase38', N'Por que os quilombos são importantes para compreender a resistência negra?', N'Eles evidenciam organização e resistência à escravização, contrariando a ideia de aceitação passiva. Também expressam tentativas de construir outras formas de vida e organização social.', N'AVA · 4º semestre · Resistência também envolve criar alternativas de sociedade.', NULL, NULL),
        (963, N'fase38', N'Por que a abolição legal não assegurou automaticamente igualdade de oportunidades?', N'A mudança jurídica não eliminou as barreiras sociais e econômicas acumuladas. O acesso efetivo a direitos e espaços sociais continuou dependendo de mobilização e transformação das condições de vida.', N'AVA · 4º semestre · Liberdade formal e igualdade concreta têm dimensões diferentes.', NULL, NULL),
        (964, N'fase38', N'O que o estudo das africanidades brasileiras procura reconhecer?', N'As raízes africanas presentes na cultura e na vida brasileira, incluindo modos de viver, trabalhar, organizar lutas e produzir conhecimentos. A perspectiva valoriza a participação ativa dos afrodescendentes na formação do país.', N'AVA · 4º semestre · Observe contribuições culturais e protagonismo histórico.', NULL, NULL),
        (965, N'fase38', N'Por que estudar a África anterior à colonização ajuda a enfrentar estereótipos?', N'Porque permite conhecer histórias, conhecimentos e realizações que são apagados quando o continente aparece apenas associado à colonização ou à escravização. Essa ampliação combate imagens homogêneas e depreciativas.', N'AVA · 4º semestre · A história africana não começa com a chegada europeia.', NULL, NULL),
        (966, N'fase38', N'Por que reconhecer direitos em uma lei não basta para eliminar a discriminação?', N'O reconhecimento precisa se traduzir em práticas, acesso e condições de participação. A distância entre direitos declarados e experiências cotidianas deve ser analisada e enfrentada.', N'AVA · 4º semestre · Compare o direito reconhecido com sua realização cotidiana.', NULL, NULL),
        (967, N'fase38', N'Como a socialização participa da construção da identidade?', N'Ao conviver, a pessoa aprende linguagens, valores, hábitos e regras de seus grupos. Ela incorpora e interpreta essas referências na formação de sua identidade, em um processo que envolve educação formal e informal.', N'AVA · 4º semestre · A identidade se forma nas relações sociais.', NULL, NULL),
        (968, N'fase38', N'Como representações estereotipadas podem contribuir para a exclusão racial?', N'Quando associam repetidamente um grupo a posições inferiores, tornam desigualdades aparentemente normais e limitam seu reconhecimento social. Analisar essas imagens ajuda a desfazer hierarquias aprendidas.', N'AVA · 4º semestre · Pergunte quais papéis e valores são atribuídos a cada grupo.', NULL, NULL),
        (969, N'fase38', N'Qual é a relação entre valorização da identidade e participação cidadã?', N'Reconhecer positivamente origens e referências culturais pode fortalecer a autoestima e a reivindicação de direitos. Imagens sistematicamente negativas podem dificultar esse reconhecimento e a participação.', N'AVA · 4º semestre · Reconhecimento também influencia a capacidade de se posicionar.', NULL, NULL),
        (970, N'fase38', N'Como uma prática educativa pode contribuir para a convivência antirracista?', N'Valorizando diferenças, revendo padrões que tratam apenas um grupo como ideal e enfrentando atitudes discriminatórias no cotidiano. A diversidade deve participar das relações e das atividades, e não aparecer apenas como exceção.', N'AVA · 4º semestre · Transforme reconhecimento em práticas diárias.', NULL, NULL),
        (971, N'fase39', N'O que diferencia um projeto de uma atividade operacional contínua?', N'Um projeto é um esforço temporário voltado a criar um produto, serviço ou resultado único. Essa característica exige organizar objetivos e trabalho para alcançar um resultado definido.', N'ED · 4º semestre · Observe duração delimitada e resultado específico.', NULL, NULL),
        (972, N'fase39', N'Por que o planejamento ágil é progressivo e revisável?', N'O uso do produto e a execução revelam necessidades, limitações e riscos antes desconhecidos. O plano deve incorporar esse aprendizado para continuar orientando a equipe na direção de resultados úteis.', N'ED · 4º semestre · Aprender durante a execução deve influenciar o plano.', NULL, NULL),
        (973, N'fase39', N'Priorizar software funcionando significa abandonar documentação?', N'Não. Os valores ágeis reconhecem utilidade na documentação, mas dão maior prioridade à entrega de software funcionando. A documentação deve apoiar o produto e a colaboração conforme as necessidades reais.', N'ED · 4º semestre · Prioridade relativa não significa eliminar o outro elemento.', NULL, NULL),
        (974, N'fase39', N'Como a incerteza influencia a escolha entre abordagem preditiva, ágil ou híbrida?', N'Necessidades mais estáveis favorecem maior detalhamento antecipado; mudanças e aprendizado frequentes pedem adaptação. Uma abordagem híbrida combina práticas conforme o contexto, em vez de tratar os modelos como uma disputa.', N'ED · 4º semestre · Escolha a abordagem pelo problema, não pelo rótulo.', NULL, NULL),
        (975, N'fase39', N'Por que iniciar muitas tarefas ao mesmo tempo não comprova produtividade de uma equipe?', N'Porque o trabalho iniciado ainda pode não gerar resultado utilizável. O acompanhamento deve valorizar a conclusão de entregas e o fluxo, em vez de apenas a quantidade de atividades abertas.', N'ED · 4º semestre · Trabalho em andamento não equivale a valor entregue.', NULL, NULL),
        (976, N'fase39', N'Como o empirismo orienta decisões em um projeto Scrum?', N'A equipe aprende com o que executa e observa, usando evidências para adaptar o trabalho. Isso permite lidar com incerteza sem pressupor que todas as respostas já são conhecidas no início.', N'ED · 4º semestre · Fazer, observar, aprender e adaptar.', NULL, NULL),
        (977, N'fase39', N'Como transparência, inspeção e adaptação dependem umas das outras?', N'A transparência torna trabalho e problemas visíveis; a inspeção examina essa realidade; a adaptação ajusta o rumo. Se a informação é escondida, a avaliação e os ajustes perdem confiabilidade.', N'ED · 4º semestre · Não é possível ajustar bem aquilo que não se enxerga.', NULL, NULL),
        (978, N'fase39', N'Qual é o foco da responsabilidade do Product Owner no Scrum?', N'Maximizar o valor do produto e organizar o Product Backlog de modo coerente com o objetivo. Isso não significa determinar sozinho como a equipe deve executar cada solução técnica.', N'ED · 4º semestre · Direção e valor do produto orientam prioridades.', NULL, NULL),
        (979, N'fase39', N'Como o Scrum Master contribui quando a equipe encontra impedimentos?', N'Facilitando o uso efetivo do Scrum, apoiando o aprendizado e promovendo a remoção de impedimentos. Sua atuação não corresponde a fiscalizar horas ou distribuir ordens técnicas como um chefe tradicional.', N'ED · 4º semestre · Apoiar a efetividade da equipe é diferente de controlá-la.', NULL, NULL),
        (980, N'fase39', N'Por que Developers, no Scrum, não significa apenas quem escreve código?', N'A responsabilidade é construir um incremento utilizável e inclui as competências necessárias para isso, como testes, experiência do usuário e dados. O foco é realizar o trabalho do produto de forma colaborativa.', N'ED · 4º semestre · O resultado exige mais que programação.', NULL, NULL),
        (981, N'fase39', N'Por que o Product Backlog é chamado de emergente?', N'Ele muda à medida que surgem informações, feedback e novas prioridades. Seu papel é apoiar entendimento e decisões sobre o produto, não congelar todas as tarefas no começo do projeto.', N'ED · 4º semestre · O aprendizado altera o que faz sentido construir.', NULL, NULL),
        (982, N'fase39', N'Qual é a vantagem de trabalhar em ciclos curtos com feedback frequente?', N'As hipóteses podem ser verificadas mais cedo, reduzindo o tempo gasto seguindo uma direção inadequada. A equipe ganha oportunidades regulares de ajustar o produto e o trabalho.', N'ED · 4º semestre · Descobrir cedo reduz o custo de corrigir.', NULL, NULL),
        (983, N'fase39', N'O que torna um Sprint Goal mais útil que uma lista de telas a construir?', N'Ele expressa o resultado que a Sprint pretende alcançar para o usuário. Esse objetivo une tarefas e decisões técnicas em um propósito comum, permitindo avaliar o valor do conjunto.', N'ED · 4º semestre · Descreva o que o usuário conseguirá fazer.', NULL, NULL),
        (984, N'fase39', N'Qual é a finalidade da Daily Scrum para os Developers?', N'Inspecionar o avanço em direção ao Sprint Goal e adaptar o plano de trabalho. O encontro ajuda a coordenar ações e identificar impedimentos, em vez de funcionar como prestação individual de contas ao chefe.', N'ED · 4º semestre · O foco é ajustar o trabalho em direção ao objetivo.', NULL, NULL),
        (985, N'fase39', N'Por que terminar a programação não basta para considerar uma entrega pronta?', N'A entrega precisa cumprir os critérios de qualidade da Definition of Done, que podem incluir testes e integração. Código incompleto nesses critérios não representa automaticamente um incremento utilizável.', N'ED · 4º semestre · Pronto exige evidências de qualidade acordadas.', NULL, NULL),
        (986, N'fase39', N'Como Sprint Review e Sprint Retrospective se diferenciam?', N'A Review inspeciona o resultado do produto com interessados para orientar próximos passos; a Retrospective examina o modo de trabalhar da equipe para melhorá-lo. Ambas geram aprendizado, com focos diferentes.', N'ED · 4º semestre · Uma examina o produto; a outra melhora o trabalho da equipe.', NULL, NULL),
        (987, N'bonus4', N'Bônus 04: O que é um ''Unicórnio'' no mercado de TI?', N'Uma startup de capital fechado que conseguiu atingir uma avaliação de mercado superior a 1 Bilhão de Dólares.', N'Ex: Nubank, Uber, iFood (no seu início).', NULL, NULL),
        (988, N'bonus4', N'Bônus 04: O que é um Pitch Deck?', N'Uma apresentação visual curta (10 a 15 slides) usada por empreendedores para apresentar o seu modelo de negócio a investidores para levantar capital.', N'A apresentação que pode valer milhões.', NULL, NULL),
        (989, N'bonus4', N'Bônus 04: O que é Bootstrapping?', N'Iniciar e escalar uma empresa usando exclusivamente o próprio dinheiro dos fundadores e o fluxo de caixa gerado pelas vendas iniciais.', N'Crescer sem dinheiro de fora.', NULL, NULL),
        (990, N'bonus4', N'Bônus 04: O que é o Burn Rate (Taxa de Queima)?', N'A velocidade (geralmente mensal) com que uma startup gasta o seu capital de investimento para se manter a operar antes de ser rentável.', N'A que velocidade queima o dinheiro do investidor.', NULL, NULL),
        (991, N'bonus4', N'Bônus 04: O que é Runway (Pista de Descolagem)?', N'A quantidade de tempo (em meses) que a startup tem para sobreviver operando com o seu saldo atual, com base no seu Burn Rate.', N'Se acabar a pista, a empresa fecha.', NULL, NULL),
        (992, N'bonus4', N'Bônus 04: Qual a diferença entre Incubadora e Aceleradora?', N'A incubadora ajuda ideias embrionárias a estruturarem-se fisicamente. A aceleradora pega numa startup que já fatura e injeta capital intensivo para escalar rapidamente.', N'Apoio inicial vs Crescimento explosivo.', NULL, NULL),
        (993, N'bonus4', N'Bônus 04: O que significa B2B2C?', N'Business to Business to Consumer. Uma empresa que vende um serviço a outra empresa, mas o foco final é chegar ao consumidor daquela empresa.', N'Ex: iFood vendendo o sistema aos Restaurantes (B2B) para chegar a nós (B2C).', NULL, NULL),
        (994, N'bonus4', N'Bônus 04: O que é a métrica CAC (Custo de Aquisição de Clientes)?', N'O investimento médio exigido em marketing e vendas para conseguir convencer um novo cliente a comprar o seu produto.', N'Quanto custa cada cliente novo.', NULL, NULL),
        (995, N'bonus4', N'Bônus 04: O que é a métrica LTV (Lifetime Value)?', N'A estimativa da receita líquida total que um cliente gerará para a empresa durante todo o seu tempo de retenção/assinatura.', N'O LTV tem de ser pelo menos 3x maior que o CAC.', NULL, NULL),
        (996, N'bonus4', N'Bônus 04: O que é o Churn Rate?', N'A taxa que mede a percentagem de clientes ou assinantes que cancelaram o serviço ou deixaram de comprar num determinado período.', N'O ''buraco'' no balde da empresa.', NULL, NULL),
        (997, N'bonus4', N'Bônus 04: O que é ''Pivotar'' (Pivot)?', N'Mudar drasticamente a direção do modelo de negócio, do produto ou do público-alvo quando se percebe que a estratégia atual falhou no mercado.', N'Correção de rota sem fechar a empresa.', NULL, NULL),
        (998, N'bonus4', N'Bônus 04: O que é o Break-even Point (Ponto de Equilíbrio)?', N'O momento exato em que os custos de operação da empresa se igualam às receitas de vendas (Lucro Zero). Tudo o que entrar acima disso é lucro real.', N'Sair do vermelho e empatar o jogo.', NULL, NULL),
        (999, N'bonus4', N'Bônus 04: O que é um modelo Freemium?', N'Um modelo de negócio que oferece uma versão básica do produto de forma totalmente gratuita, cobrando uma assinatura (Premium) por recursos avançados.', N'Free + Premium. Ex: Spotify, LinkedIn.', NULL, NULL),
        (1000, N'bonus4', N'Bônus 04: O que é Crowdfunding?', N'Um financiamento coletivo em que várias pessoas (''a multidão'') investem pequenas quantias de dinheiro pela internet para ajudar a viabilizar um projeto.', N'A famosa ''vaquinha online'' empresarial.', NULL, NULL);
    INSERT INTO flashcards (id, codigo_fase, frente, verso, dica, opcoes, correta) VALUES
        (1001, N'bonus4', N'Bônus 04: O que é o Valuation de uma empresa?', N'A avaliação financeira estimativa do valor total de mercado de uma startup. Usado para definir quanta % da empresa os investidores recebem pelo dinheiro aportado.', N'Quanto vale a sua empresa hoje?', NULL, NULL),
        (1002, N'bonus4', N'Bônus 04: O que é o ''Exit'' (Saída) de uma startup?', N'O evento final em que os fundadores e primeiros investidores vendem as suas participações e têm o retorno lucrativo (Ex: Sendo comprados por uma gigante como a Google).', N'O dia do grande pagamento.', NULL, NULL),
        (1003, N'bonus4', N'Bônus 04: O que significa IPO (Initial Public Offering)?', N'A Oferta Pública Inicial, momento em que uma empresa privada cresce tanto que abre o seu capital para vender ações na Bolsa de Valores pública.', N'Quando a startup vira uma ''Megacorporação''.', NULL, NULL),
        (1004, N'bonus4', N'Bônus 04: O que significa atingir o ''Product-Market Fit''?', N'É o momento mágico em que uma startup construiu um produto que resolve tão bem a dor do cliente, que este mercado começa a comprar e recomendar avidamente.', N'O produto casa perfeitamente com a procura.', NULL, NULL),
        (1005, N'bonus4', N'Bônus 04: Quem são os ''Early Adopters'' (Adotantes Iniciais)?', N'O pequeno grupo de clientes visionários que estão dispostos a comprar e testar a primeira versão (MVP) de um produto antes de ele se tornar famoso.', N'Os clientes que validam o seu negócio.', NULL, NULL),
        (1006, N'bonus4', N'Bônus 04: O que é Growth Hacking?', N'O uso de estratégias criativas de marketing com baixo custo, análise de dados rigorosa e engenharia de software para gerar um crescimento (growth) rápido de usuários.', N'Hackear o crescimento através da tecnologia.', NULL, NULL),
        (1007, N'bonus4', N'Bônus 04: O que é um MVP (Minimum Viable Product)?', N'O Produto Mínimo Viável. A versão mais básica da sua solução que possui as funcionalidades mínimas para atrair os Early Adopters e testar o mercado.', N'Se não tem vergonha da primeira versão do seu produto, lançou-o tarde demais.', NULL, NULL),
        (1008, N'bonus4', N'Bônus 04: O que são OKRs (Objectives and Key Results)?', N'Metodologia de gestão usada pelo Google e Netflix para alinhar a empresa, definindo Objetivos qualitativos inspiradores e Resultados Chave quantitativos e mensuráveis.', N'Para onde vamos (O) e como mediremos se chegámos (KR).', NULL, NULL),
        (1009, N'bonus4', N'Bônus 04: O que são KPIs (Key Performance Indicators)?', N'Indicadores chave de desempenho. Métricas numéricas que os gestores analisam diariamente para medir a saúde técnica e comercial da empresa.', N'O painel do carro do gestor.', NULL, NULL),
        (1010, N'bonus4', N'Bônus 04: O que é uma Cap Table (Capitalization Table)?', N'Uma tabela jurídica que detalha quem são os donos da startup e qual a percentagem exata (quotas ou ações) que pertence aos fundadores, funcionários e investidores.', N'A divisão oficial do bolo da empresa.', NULL, NULL),
        (1011, N'bonus4', N'Bônus 04: O que é o ''Vale da Morte'' das Startups?', N'A fase crítica inicial em que a startup já começou a operar e gastar capital (Burn Rate alto), mas ainda não atingiu receitas suficientes (Break-even).', N'Onde 90% das empresas morrem de falta de caixa.', NULL, NULL),
        (1012, N'bonus4', N'Bônus 04: O que é o Contrato de ''Vesting'' para fundadores?', N'Uma cláusula que exige que os sócios permaneçam a trabalhar na empresa por um tempo mínimo (ex: 4 anos) para receberem progressivamente o total das suas ações.', N'Evita que um sócio abandone o barco com metade da empresa.', NULL, NULL),
        (1013, N'bonus4', N'Bônus 04: O que é um ''Term Sheet''?', N'O documento preliminar que resume os termos e condições básicos de um investimento proposto por um Venture Capital antes do contrato jurídico final.', N'A proposta de noivado antes do casamento.', NULL, NULL),
        (1014, N'bonus4', N'Bônus 04: O que é Inovação Disruptiva?', N'Uma tecnologia ou modelo de negócio que é criado na base do mercado, mais acessível e barato, e que eventualmente desaloja os gigantes e domina o mundo.', N'Ex: Câmeras digitais aniquilaram as de filme (Kodak).', NULL, NULL),
        (1015, N'bonus4', N'Bônus 04: O que é um Acordo de Confidencialidade (NDA) para startups?', N'Um contrato que protege o sigilo da ideia, código ou plano de negócio. NOTA: Investidores não assinam NDAs para escutar a sua ideia inicial.', N'As ideias não valem nada, a execução vale tudo.', NULL, NULL),
        (1016, N'bonus4', N'Bônus 04: O que significa ''Escalabilidade'' num modelo de negócio?', N'A capacidade da empresa de multiplicar as suas receitas de forma exponencial, enquanto os seus custos operacionais crescem de forma muito lenta ou quase zero.', N'O Santo Graal de qualquer software.', NULL, NULL),
        (1017, N'fase21', N'(ENADE - Gestão) Uma empresa adotou metodologias ágeis. Durante uma iteração, a equipe percebeu que um dos requisitos estava mal detalhado, gerando atraso.' + NCHAR(10) + N'' + NCHAR(10) + N'Qual cerimônia do Scrum é o momento IDEAL para a equipe inspecionar esse problema de processo e sugerir melhorias para o próximo ciclo?', N'Alternativa D: Sprint Retrospective.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: A Retrospectiva serve exatamente para avaliar o processo, as falhas de comunicação e ferramentas, buscando melhoria contínua para a próxima Sprint.', N'Foco no processo e na equipe, não no produto.', N'["A) Sprint Planning","B) Daily Scrum","C) Sprint Review","D) Sprint Retrospective"]', 3),
        (1018, N'fase21', N'(ENADE - LGPD) Uma clínica médica recolhe dados biométricos e histórico de doenças de seus pacientes. Segundo a Lei Geral de Proteção de Dados (LGPD), estes dados são classificados como:', N'Alternativa B: Dados Sensíveis.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Dados sobre saúde, biometria, origem racial, religião e orientação sexual são sensíveis pois podem gerar discriminação, exigindo maior rigor de proteção.', N'A saúde é um tema que exige proteção redobrada.', N'["A) Dados P\u00FAblicos","B) Dados Sens\u00EDveis","C) Dados Anonimizados","D) Dados Tempor\u00E1rios"]', 1),
        (1019, N'fase21', N'(ENADE - UX/UI) Uma equipe está refatorando a interface de um sistema. O sistema atual possui textos com baixo contraste e depende apenas da cor vermelha para indicar erros.' + NCHAR(10) + N'' + NCHAR(10) + N'Qual das ações abaixo NÃO corresponde a uma boa prática de Acessibilidade (WCAG)?', N'Alternativa B: Depender exclusivamente da cor para mensagens de erro.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Pessoas daltônicas não conseguirão identificar o erro. O correto é usar Cor + Ícone + Texto descritivo.', N'Pense na experiência de um usuário daltônico.', N'["A) Adicionar atributos \u0027alt\u0027 em imagens.","B) Depender exclusivamente da cor para mensagens de erro.","C) Garantir navega\u00E7\u00E3o completa via teclado (Tab).","D) Manter alto contraste entre fundo e texto."]', 1),
        (1020, N'fase21', N'(ENADE - Eng. de Software) No contexto de levantamento de requisitos, um analista documentou: ''O sistema deve ser capaz de processar 10.000 transações por segundo''.' + NCHAR(10) + N'' + NCHAR(10) + N'Este é um exemplo clássico de:', N'Alternativa C: Requisito Não Funcional.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Requisitos Não Funcionais descrevem *como* o sistema deve operar (desempenho, segurança, usabilidade), enquanto os Funcionais descrevem *o que* ele faz.', N'Refere-se à performance (o ''como''), não a uma funcionalidade.', N'["A) Requisito Funcional","B) Regra de Neg\u00F3cio","C) Requisito N\u00E3o Funcional","D) Caso de Uso"]', 2),
        (1021, N'fase21', N'(ENADE - Scrum) Durante o desenvolvimento de um produto, o cliente solicita constantemente mudanças. No framework Scrum, quem é o papel responsável por maximizar o valor do produto e gerenciar o Backlog, aceitando ou recusando essas mudanças?', N'Alternativa B: Product Owner (PO).' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: O PO é a voz do cliente dentro da equipe. Ele é o único responsável por priorizar, adicionar ou remover itens do Product Backlog.', N'É o ''dono'' do produto e do backlog.', N'["A) Scrum Master","B) Product Owner (PO)","C) Tech Lead","D) Desenvolvedor Full-Stack"]', 1),
        (1022, N'fase21', N'(ENADE - Ética) Um desenvolvedor descobre uma falha crítica de segurança no sistema da empresa e decide vendê-la na Dark Web em vez de reportá-la. ' + NCHAR(10) + N'' + NCHAR(10) + N'Na segurança da informação, essa atitude enquadra-se no perfil de um hacker do tipo:', N'Alternativa C: Black Hat.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Hackers Black Hat exploram vulnerabilidades para ganho financeiro ou fins maliciosos, agindo de forma ilegal e antiética.', N'Chapéu preto = intenções maliciosas.', N'["A) White Hat","B) Gray Hat","C) Black Hat","D) Red Hat"]', 2),
        (1023, N'fase21', N'(ENADE - UML) Em um Diagrama de Casos de Uso, quando um Caso de Uso ''A'' obrigatoriamente executa o Caso de Uso ''B'' para completar sua função, qual é o tipo de relacionamento entre eles?', N'Alternativa B: <<include>>.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: O relacionamento <<include>> (inclusão) indica que o caso de uso base sempre, obrigatoriamente, incorpora o comportamento do caso de uso incluído.', N'É uma dependência obrigatória.', N'["A) \u003C\u003Cextend\u003E\u003E","B) \u003C\u003Cinclude\u003E\u003E","C) Generaliza\u00E7\u00E3o","D) Associa\u00E7\u00E3o Simples"]', 1),
        (1024, N'fase21', N'(ENADE - Governança) A biblioteca ITIL tem como foco principal o alinhamento da TI com os negócios da empresa. Qual é a principal diferença entre a ITIL e o COBIT?', N'Alternativa A: A ITIL foca em serviços; o COBIT foca em auditoria e governança.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: A ITIL foca nas boas práticas de Gestão de Serviços de TI (ITSM), enquanto o COBIT fornece um modelo abrangente de Governança corporativa e auditoria de TI.', N'ITIL = Serviços. COBIT = Controle/Auditoria.', N'["A) A ITIL foca em servi\u00E7os de TI; o COBIT foca em auditoria e governan\u00E7a.","B) O COBIT \u00E9 para desenvolvimento \u00E1gil; a ITIL \u00E9 para gest\u00E3o financeira.","C) Ambos s\u00E3o frameworks exclusivos para seguran\u00E7a da informa\u00E7\u00E3o.","D) A ITIL substitui a LGPD; o COBIT substitui o Scrum."]', 0),
        (1025, N'fase21', N'(ENADE - Qualidade) Em um processo de testes de software, os testes unitários são fundamentais. Quem é o principal responsável pela criação e execução dos testes unitários?', N'Alternativa C: O Desenvolvedor do código.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Os testes unitários validam os menores blocos de código (funções/métodos) e devem ser escritos pelo próprio programador que desenvolveu a lógica.', N'Quem escreve a função, testa a função.', N'["A) O Analista de Requisitos","B) O Usu\u00E1rio Final","C) O Desenvolvedor do c\u00F3digo","D) O Gerente de Projetos"]', 2),
        (1026, N'fase21', N'(ENADE - Inovação) No contexto de startups, o conceito de MVP (Minimum Viable Product) refere-se a:', N'Alternativa C: A versão mais simples de um produto para validação.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: O MVP serve para testar a viabilidade do negócio no mercado rapidamente, recolhendo feedback antes de investir pesadamente no desenvolvimento.', N'Mínimo + Viável = Rápido e Funcional.', N'["A) Um produto finalizado e sem bugs.","B) A vers\u00E3o mais complexa de um sistema para testes de estresse.","C) A vers\u00E3o mais simples de um produto que permite validar uma hip\u00F3tese com o menor esfor\u00E7o.","D) Um prot\u00F3tipo visual feito apenas no papel."]', 2),
        (1027, N'fase21', N'(ENADE - Negócios) Um modelo de negócio onde uma empresa fornece software através da internet mediante uma assinatura mensal (como a Netflix ou Spotify) é classificado como:', N'Alternativa C: SaaS (Software as a Service).' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: No modelo SaaS, o usuário final acessa uma aplicação pronta e hospedada na nuvem, pagando pelo uso ou assinatura, sem se preocupar com a infraestrutura.', N'O S significa Software.', N'["A) IaaS (Infrastructure as a Service)","B) PaaS (Platform as a Service)","C) SaaS (Software as a Service)","D) DaaS (Data as a Service)"]', 2),
        (1028, N'fase21', N'(ENADE - Métricas) O que mede o KPI conhecido como ''Churn Rate'' em uma empresa de tecnologia SaaS?', N'Alternativa B: A taxa de cancelamento de clientes.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: O Churn mede a porcentagem de clientes que pararam de usar o serviço. É uma métrica crítica para avaliar a retenção e a satisfação do cliente.', N'Churn significa perda ou cancelamento.', N'["A) O n\u00FAmero de novos usu\u00E1rios por m\u00EAs.","B) A taxa de cancelamento ou evas\u00E3o de clientes em um determinado per\u00EDodo.","C) A velocidade de carregamento da p\u00E1gina.","D) O custo para adquirir um novo cliente (CAC)."]', 1),
        (1029, N'fase21', N'(ENADE - Negócios) Em finanças e gestão de TI, o que significa a métrica ROI?', N'Alternativa B: Return on Investment (Retorno sobre Investimento).' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: O ROI mede a rentabilidade de um investimento, calculando quanto dinheiro a empresa ganhou ou perdeu em relação ao valor que foi investido no projeto.', N'Mede se o projeto deu lucro ou prejuízo.', N'["A) Return on Incident (Retorno sobre Incidente).","B) Return on Investment (Retorno sobre Investimento).","C) Rate of Integration (Taxa de Integra\u00E7\u00E3o).","D) Resource Optimization Index (\u00CDndice de Otimiza\u00E7\u00E3o de Recursos)."]', 1),
        (1030, N'fase21', N'(ENADE - Kanban) O que significa a prática de ''Limitar o WIP'' (Work in Progress) na metodologia Kanban?', N'Alternativa B: Restringir a quantidade de tarefas em andamento.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Limitar o WIP evita a sobrecarga da equipe, foca na finalização das tarefas (terminar o que começou) e identifica gargalos no fluxo de trabalho.', N'Pare de começar e comece a terminar.', N'["A) Limitar o n\u00FAmero de horas que a equipe pode trabalhar por dia.","B) Restringir a quantidade m\u00E1xima de tarefas que podem estar em andamento simultaneamente em uma coluna do quadro.","C) Limitar o acesso do cliente ao c\u00F3digo-fonte.","D) Reduzir o escopo do projeto pela metade."]', 1),
        (1031, N'fase21', N'(ENADE - LGPD) De acordo com a LGPD, quem é a figura do ''Titular'' dos dados?', N'Alternativa C: A pessoa natural (física) a quem se referem os dados pessoais.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Na LGPD, o titular é o dono dos dados (o cidadão, cliente ou funcionário), e a ele são garantidos os direitos de acesso, alteração e eliminação.', N'É o verdadeiro dono da informação.', N'["A) A empresa que armazena os dados no banco de dados.","B) O administrador do sistema (DBA).","C) A pessoa natural (f\u00EDsica) a quem se referem os dados pessoais.","D) O governo federal."]', 2),
        (1032, N'fase21', N'(ENADE - LGPD) De acordo com a LGPD, quem é o ''DPO'' (Data Protection Officer) ou Encarregado de Dados?', N'Alternativa C: O canal de comunicação sobre proteção de dados.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: O DPO (Encarregado) é o profissional responsável por garantir que a empresa está em conformidade com a LGPD e atuar como ponte de comunicação oficial.', N'É o ''porta-voz'' da privacidade na empresa.', N'["A) O hacker contratado para testar o sistema.","B) O gerente de banco de dados (DBA).","C) A pessoa indicada pela empresa para atuar como canal de comunica\u00E7\u00E3o entre a empresa, os titulares dos dados e a Autoridade Nacional (ANPD).","D) O desenvolvedor back-end s\u00EAnior."]', 2),
        (1033, N'fase21', N'(ENADE - Cloud) Uma empresa quer focar apenas em escrever o código do seu sistema web, sem precisar gerenciar o sistema operacional do servidor, atualizações de segurança ou redes. Qual modelo de Cloud deve ser contratado?', N'Alternativa B: PaaS (Platform as a Service).' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: O modelo PaaS fornece o ambiente e as ferramentas para o desenvolvedor executar a aplicação, abstraindo toda a gestão da infraestrutura por trás.', N'Plataforma focada no desenvolvedor (Platform).', N'["A) IaaS","B) PaaS","C) SaaS","D) On-Premises"]', 1),
        (1034, N'fase21', N'(ENADE - Projetos) Em uma matriz SWOT (FOFA), quais os fatores representam o ambiente EXTERNO da organização, sobre os quais a empresa não tem controle direto?', N'Alternativa D: Oportunidades e Ameaças.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Forças e Fraquezas são aspectos internos (equipe, tecnologia). Oportunidades e Ameaças vêm de fora (mercado, concorrência, novas leis).', N'O que vem de fora (mercado/leis).', N'["A) For\u00E7as e Fraquezas","B) Fraquezas e Oportunidades","C) For\u00E7as e Amea\u00E7as","D) Oportunidades e Amea\u00E7as"]', 3),
        (1035, N'fase21', N'(ENADE - Qualidade de Software) O que é o processo de Refatoração (Refactoring)?', N'Alternativa B: Melhorar a estrutura interna sem alterar o comportamento externo.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Refatorar é limpar o código (deixá-lo mais legível, otimizado e modular) sem mudar as regras de negócio ou a interface do usuário.', N'Melhorar por dentro, manter igual por fora.', N'["A) Reescrever o c\u00F3digo para alterar suas funcionalidades externas e adicionar bot\u00F5es.","B) Melhorar a estrutura interna do c\u00F3digo sem alterar seu comportamento externo (o que o usu\u00E1rio v\u00EA).","C) Apagar o sistema e come\u00E7ar tudo do zero.","D) Adicionar novas features durante a fase de testes."]', 1),
        (1036, N'fase21', N'(ENADE - Gestão) O Ciclo PDCA é uma ferramenta de gestão interativa amplamente utilizada para o controle e melhoria contínua. O que significam as siglas PDCA?', N'Alternativa B: Plan (Planejar), Do (Fazer), Check (Checar), Act (Agir).' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: O PDCA é um método de 4 passos para garantir a melhoria contínua de processos e produtos em qualquer área da empresa.', N'Planejar, Fazer, Verificar e Agir.', N'["A) Program, Develop, Code, Analyze.","B) Plan, Do, Check, Act.","C) Process, Data, Control, Audit.","D) Plan, Deploy, Compile, Act."]', 1),
        (1037, N'fase21', N'(ENADE - Eng. Requisitos) Uma técnica ágil eficaz para capturar requisitos sob a perspectiva do usuário segue o formato: ''Como [perfil], eu quero [ação], para [benefício]''. Como se chama essa técnica?', N'Alternativa B: História de Usuário (User Story).' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: A User Story é uma técnica ágil focada em descrever uma funcionalidade sob a perspectiva do usuário final e do valor que ela gera para o negócio.', N'Foca no ''quem'', ''o quê'' e ''porquê''.', N'["A) Diagrama de Classes","B) Hist\u00F3ria de Usu\u00E1rio (User Story)","C) Mapa Mental","D) Documento de Vis\u00E3o"]', 1),
        (1038, N'fase21', N'(ENADE - Eng. Requisitos) Na metodologia Ágil, quando uma História de Usuário (User Story) é muito grande ou complexa para ser entregue em uma única Sprint, como ela é chamada?', N'Alternativa B: Épico (Epic).' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Um Épico é uma grande iniciativa ou requisito que não cabe em uma Sprint e precisa ser quebrado (fatiado) em várias User Stories menores.', N'Uma história grande e épica.', N'["A) Bug","B) \u00C9pico (Epic)","C) Tarefa (Task)","D) Spike"]', 1),
        (1039, N'fase21', N'(ENADE - Design Thinking) O Design Thinking é uma abordagem de inovação centrada no ser humano. Qual é a primeira etapa fundamental desse processo?', N'Alternativa D: Empatia (Imersão).' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Antes de criar soluções, a equipe precisa se colocar no lugar do usuário (empatia) para entender profundamente suas dores, necessidades e o contexto do problema.', N'Se colocar no lugar do cliente primeiro.', N'["A) Prototipa\u00E7\u00E3o","B) Idea\u00E7\u00E3o","C) Teste","D) Empatia (Imers\u00E3o)"]', 3),
        (1040, N'fase21', N'(ENADE - Projetos) No PMBOK, o que é o ''Caminho Crítico'' em um cronograma de projeto?', N'Alternativa B: A sequência que determina a duração total mais longa.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: As tarefas no caminho crítico têm zero ''folga''. Se uma delas atrasar um dia, todo o projeto atrasará um dia no cronograma.', N'São as tarefas sem folga de tempo.', N'["A) A sequ\u00EAncia de atividades com o menor risco de falha.","B) A sequ\u00EAncia de atividades que determina a dura\u00E7\u00E3o total do projeto, onde qualquer atraso afeta a data de entrega final.","C) O conjunto de tarefas que custam mais dinheiro.","D) O caminho percorrido pelo cliente."]', 1),
        (1041, N'fase21', N'(ENADE - Projetos) O ''Triângulo de Ferro'' da gestão de projetos clássica define três restrições principais que devem ser equilibradas para garantir a qualidade do projeto. Quais são elas?', N'Alternativa B: Escopo, Tempo e Custo.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Alterar um lado do triângulo invariavelmente afeta os outros. Se o cliente aumentar o Escopo, o Tempo e/ou o Custo precisarão ser aumentados para manter a qualidade.', N'Restrições triplas clássicas.', N'["A) C\u00F3digo, Testes e Deploy.","B) Escopo, Tempo e Custo.","C) Risco, Qualidade e Comunica\u00E7\u00E3o.","D) Design, Front-end e Back-end."]', 1),
        (1042, N'fase21', N'(ENADE - Empreendedorismo) O que significa a sigla B2B em modelos de negócios?', N'Alternativa A: Business to Business.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: B2B ocorre quando uma empresa cria soluções (como um ERP de RH ou maquinário pesado) e vende para outras empresas, e não para pessoas físicas.', N'Empresa para Empresa.', N'["A) Business to Business (Empresa vendendo para Empresa).","B) Business to Consumer (Empresa vendendo para Consumidor final).","C) Back to Basics (De volta ao b\u00E1sico).","D) Banco para Banco."]', 0),
        (1043, N'fase21', N'(ENADE - Inovação) A Uber mudou completamente a indústria de transportes sem possuir um único carro de frota. O Netflix fez o mesmo com as locadoras de vídeo. Esse fenômeno é conhecido como:', N'Alternativa C: Inovação Disruptiva.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Inovações disruptivas criam um novo mercado ou rede de valor, desestabilizando líderes de mercado existentes e mudando as regras do jogo.', N'Destrói o modelo antigo e cria um novo.', N'["A) Inova\u00E7\u00E3o Incremental","B) Inova\u00E7\u00E3o de Sustenta\u00E7\u00E3o","C) Inova\u00E7\u00E3o Disruptiva","D) Reengenharia Reversa"]', 2),
        (1044, N'fase21', N'(ENADE - Scrum) O que é o objetivo da cerimônia ''Daily Scrum''?', N'Alternativa B: Reunião diária de sincronização (Timebox de 15 min).' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: A Daily serve para a equipe de desenvolvimento inspecionar o progresso em direção ao objetivo da Sprint e identificar impedimentos rapidamente.', N'Reunião em pé (Stand-up), rápida e diária.', N'["A) Discutir a arquitetura t\u00E9cnica do banco de dados por 2 horas.","B) Reuni\u00E3o di\u00E1ria de no m\u00E1ximo 15 minutos para sincronizar as atividades da equipe e planejar as pr\u00F3ximas 24 horas.","C) Apresentar o software finalizado para o cliente.","D) Revisar as falhas do membro mais lento da equipe."]', 1),
        (1045, N'fase21', N'(ENADE - Scrum) Quem é o ''Scrum Master'' na metodologia ágil?', N'Alternativa B: O líder servidor e facilitador.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: O Scrum Master não é um gerente que dita tarefas. Ele facilita cerimônias, protege a equipe de distrações externas e remove gargalos (impedimentos).', N'Líder servidor e facilitador.', N'["A) O chefe ou gerente tradicional que manda na equipe.","B) O l\u00EDder servidor que garante que o Scrum seja compreendido e aplicado, removendo impedimentos t\u00E9cnicos e organizacionais da equipe.","C) O desenvolvedor que escreve o c\u00F3digo mais r\u00E1pido.","D) O representante legal do cliente (Product Owner)."]', 1),
        (1046, N'fase21', N'(ENADE - Negócios) O que é o CAC (Custo de Aquisição de Clientes)?', N'Alternativa B: O custo para atrair um novo cliente.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: O CAC mostra quanto dinheiro a empresa precisou gastar em campanhas publicitárias e vendedores para convencer uma pessoa a comprar o produto.', N'Quanto custa ''comprar'' um cliente novo.', N'["A) O valor que o cliente paga mensalmente pelo software.","B) O custo total com marketing e vendas dividido pelo n\u00FAmero de novos clientes conquistados.","C) A taxa de cancelamento de assinaturas.","D) O custo dos servidores na nuvem AWS."]', 1),
        (1047, N'fase21', N'(ENADE - Sustentabilidade) O conceito de ''Green IT'' (TI Verde) busca reduzir o impacto ambiental da tecnologia. Qual das práticas abaixo NÃO é uma prática de TI Verde?', N'Alternativa B: Descarte de lixo eletrônico em aterros comuns.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Lixo eletrônico contém metais pesados (chumbo, mercúrio) tóxicos. A TI Verde exige a reciclagem e o descarte correto especializado desses componentes.', N'Lixo eletrônico é altamente tóxico.', N'["A) Virtualiza\u00E7\u00E3o de servidores para economizar energia f\u00EDsica.","B) Descarte de lixo eletr\u00F4nico em aterros sanit\u00E1rios comuns.","C) Uso de data centers alimentados por energia e\u00F3lica/solar.","D) Pol\u00EDticas de impress\u00E3o reduzida e digitaliza\u00E7\u00E3o de documentos."]', 1),
        (1048, N'fase21', N'(ENADE - Qualidade) O que é o Teste UAT (User Acceptance Testing) no ciclo de vida de um software?', N'Alternativa C: Teste de Aceitação do Usuário.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: O UAT é o momento onde os stakeholders finais (quem pediu o software) validam se o sistema construído realmente atende às necessidades de negócio acordadas.', N'É a validação final do cliente.', N'["A) Teste focado em verificar vulnerabilidades de banco de dados.","B) Teste executado por um rob\u00F4 para checar a API.","C) Teste de Aceita\u00E7\u00E3o do Usu\u00E1rio, a fase final onde o cliente testa o sistema no mundo real antes de o aprovar para produ\u00E7\u00E3o.","D) Teste de mesa para revisar diagramas UML."]', 2),
        (1049, N'fase21', N'(ENADE - Governança) O que é um SLA (Service Level Agreement - Acordo de Nível de Serviço)?', N'Alternativa B: Um contrato de garantia de serviço.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: O SLA estabelece métricas claras (tempo de resposta do suporte, uptime do site, penalidades financeiras se o serviço cair) que o fornecedor deve cumprir.', N'É o contrato de garantias técnicas.', N'["A) Um protocolo de internet para enviar e-mails.","B) Um contrato que define as expectativas de n\u00EDvel de servi\u00E7o entre o provedor e o cliente (ex: garantir 99,9% de disponibilidade do servidor).","C) Uma lei brasileira de prote\u00E7\u00E3o de dados.","D) Uma certifica\u00E7\u00E3o de qualidade de c\u00F3digo C#."]', 1),
        (1050, N'fase21', N'(ENADE - DevOps) A cultura DevOps visa a integração contínua (CI) e entrega contínua (CD). O que é o processo de ''Integração Contínua'' (CI)?', N'Alternativa B: Fazer merge frequente de código com testes automatizados.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: A CI (Continuous Integration) garante que as alterações de código feitas pela equipe sejam validadas constantemente, evitando o ''integration hell'' no final do projeto.', N'Evita conflitos gigantes de código no GitHub.', N'["A) Juntar as equipes de RH e TI na mesma sala.","B) Fazer o merge frequente do c\u00F3digo de v\u00E1rios desenvolvedores em um reposit\u00F3rio central, executando testes automatizados a cada envio.","C) Ligar o banco de dados SQL a um banco NoSQL.","D) Lan\u00E7ar o sistema diretamente em produ\u00E7\u00E3o sem testes."]', 1),
        (1051, N'fase21', N'(ENADE - Inovação) No mundo das Startups, o que significa a expressão ''Pivotar'' (Pivot)?', N'Alternativa C: Alterar a direção e o modelo de negócio.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Pivotar significa manter um pé na visão da empresa, mas girar em outra direção para encontrar um mercado mais lucrativo (Ex: A Netflix começou entregando DVDs pelo correio).', N'Mudar a rota do barco antes de afundar.', N'["A) Vender a empresa para o Google.","B) Mudar o c\u00F3digo de Python para Java.","C) Alterar drasticamente a estrat\u00E9gia ou o modelo de neg\u00F3cio da startup ap\u00F3s perceber que a ideia original n\u00E3o est\u00E1 dando certo no mercado.","D) Demitir toda a equipe executiva."]', 2),
        (1052, N'fase21', N'(ENADE - Gestão) Na gestão de projetos e Governança de TI, quem são os ''Stakeholders''?', N'Alternativa C: Todas as partes interessadas.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Stakeholder é qualquer pessoa ou grupo que tem interesse no sucesso (ou fracasso) do projeto, indo desde o CEO até o usuário final do aplicativo.', N'Partes interessadas (todos os envolvidos).', N'["A) Apenas os acionistas que colocaram dinheiro na empresa.","B) Os rob\u00F4s que testam o software.","C) Todas as partes interessadas que podem afetar ou ser afetadas pelo projeto (clientes, equipe, usu\u00E1rios, governo, diretores).","D) Apenas os programadores do sistema."]', 2),
        (1053, N'fase21', N'(ENADE - Ágil) No Scrum, qual é a principal função do gráfico ''Burndown Chart''?', N'Alternativa B: Visualizar o trabalho restante na Sprint.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: A linha do Burndown cai (queima) a cada dia conforme as tarefas são concluídas, permitindo que a equipe saiba rapidamente se conseguirá entregar tudo até o fim da Sprint.', N'O gráfico ''queima'' para baixo até chegar a zero.', N'["A) Mostrar o lucro financeiro da empresa ao longo do m\u00EAs.","B) Visualizar graficamente a quantidade de trabalho restante versus o tempo restante na Sprint.","C) Rastrear quais desenvolvedores cometeram mais bugs.","D) Mapear a arquitetura de rede em nuvem."]', 1),
        (1054, N'fase21', N'(ENADE - Governança) O que significa atuar em ''Compliance'' na área de Tecnologia da Informação?', N'Alternativa B: Estar em conformidade legal e normativa.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Compliance vem do verbo *to comply* (cumprir, estar de acordo). Significa seguir rigidamente as leis trabalhistas, de segurança de dados, ambientais e normas da indústria.', N'Andar na linha com as leis e regras.', N'["A) Programar em linguagens modernas de alto n\u00EDvel.","B) Garantir que os processos de TI estejam em total conformidade e obede\u00E7am a leis, regulamentos, pol\u00EDticas internas e normas externas (ex: LGPD).","C) Usar computadores da Apple.","D) Contratar seguro contra inc\u00EAndios no servidor."]', 1),
        (1055, N'fase21', N'(ENADE - Ética) Uma empresa copia integralmente o código-fonte e o layout de um aplicativo concorrente sem permissão, lançando-o como se fosse seu. Isso fere qual princípio ético/legal?', N'Alternativa B: Propriedade Intelectual e Direitos Autorais.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: O código-fonte original é protegido por leis de direitos autorais como propriedade intelectual do seu criador. Copiá-lo para fins comerciais caracteriza pirataria/plágio.', N'O código tem um ''dono'' por direito autoral.', N'["A) LGPD (Prote\u00E7\u00E3o de Dados).","B) Propriedade Intelectual e Direitos Autorais de Software.","C) C\u00F3digo de Defesa do Consumidor.","D) Marco Civil da Internet."]', 1),
        (1056, N'fase21', N'(ENADE - Negócios) Em métricas financeiras de startups, o que é o Break-even Point (Ponto de Equilíbrio)?', N'Alternativa B: Receitas igualam os custos totais.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: O Break-even é a linha mágica. A partir do momento em que a empresa ultrapassa esse ponto, cada nova venda começa finalmente a gerar Lucro real.', N'O zero a zero financeiro (empatou).', N'["A) O momento em que a empresa decreta fal\u00EAncia.","B) O momento em que a receita total da empresa iguala exatamente seus custos totais (n\u00E3o h\u00E1 lucro, nem preju\u00EDzo).","C) O pico m\u00E1ximo de vendas no final do ano.","D) O desconto dado aos primeiros clientes."]', 1),
        (1057, N'fase21', N'(ENADE - Negócios) O que é a métrica LTV (Lifetime Value) em produtos SaaS?', N'Alternativa B: Valor gerado pelo cliente durante seu tempo de retenção.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Se um cliente paga R$ 50/mês na Netflix e assina por 20 meses, o LTV dele é de R$ 1.000. Uma empresa saudável deve ter o LTV muito maior que o CAC (Custo de Aquisição).', N'Valor de vida do cliente.', N'["A) O tempo que o servidor fica ligado sem reiniciar.","B) O valor total de receita que um cliente gera para a empresa durante todo o tempo em que ele permanece como assinante.","C) O tempo de vida \u00FAtil da bateria do notebook.","D) A multa rescis\u00F3ria do contrato."]', 1),
        (1058, N'fase21', N'(ENADE - Projetos) Qual ferramenta visual, muito comum na gestão clássica de projetos (PMBOK), é formada por barras horizontais e ilustra o cronograma de atividades ao longo dos dias e meses?', N'Alternativa B: Gráfico de Gantt.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: O Gráfico de Gantt é a representação visual de um cronograma, mostrando quando uma tarefa começa, quando termina e se ela depende do fim de outra tarefa anterior.', N'Gráfico de barras temporais em cascata.', N'["A) Diagrama de Entidade-Relacionamento (DER).","B) Gr\u00E1fico de Gantt.","C) Quadro Kanban.","D) Diagrama de Dispers\u00E3o."]', 1),
        (1059, N'fase21', N'(ENADE - Qualidade) Uma equipe implementou uma nova tela no sistema. Qual teste deve ser rodado para garantir que o código novo não quebrou ou gerou bugs em funcionalidades antigas que já estavam funcionando?', N'Alternativa C: Teste de Regressão.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Como o nome sugere, serve para verificar se o software ''regrediu'' em qualidade. É essencial rodá-lo (geralmente de forma automatizada) a cada nova atualização do sistema.', N'Garante que o passado não quebrou.', N'["A) Teste de Usabilidade.","B) Teste de Carga/Estresse.","C) Teste de Regress\u00E3o.","D) Teste de Invas\u00E3o (PenTest)."]', 2),
        (1060, N'fase21', N'(ENADE - Scrum) No final de uma Sprint, a equipe realiza a ''Sprint Review'' (Revisão da Sprint). Qual é o propósito desta reunião?', N'Alternativa B: Inspecionar o produto pronto e colher feedback do cliente.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Enquanto a Retrospectiva foca no Processo da equipe, a Review foca no Produto. É a hora do ''Show and Tell'', mostrando o software rodando na prática.', N'Demonstração prática para o cliente.', N'["A) Discutir os sentimentos da equipe e as falhas de comunica\u00E7\u00E3o.","B) Apresentar o incremento do software pronto para os Stakeholders/Cliente e adaptar o Backlog do Produto conforme o feedback.","C) Estimar o esfor\u00E7o das tarefas da pr\u00F3xima semana (Planning Poker).","D) Escrever a documenta\u00E7\u00E3o t\u00E9cnica da API."]', 1),
        (1061, N'fase21', N'(ENADE - Inovação) O que é um ''Design Sprint'' (criado pelo Google Ventures)?', N'Alternativa B: Processo de 5 dias para prototipar e validar ideias.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: O Design Sprint condensa meses de debates em uma única semana focada, saindo do problema para uma ideia desenhada, prototipada e testada com usuários reais na sexta-feira.', N'Validação de ideia em 5 dias.', N'["A) Uma corrida de programa\u00E7\u00E3o onde ganha quem digitar mais r\u00E1pido.","B) Um processo de 5 dias usado para responder quest\u00F5es cr\u00EDticas de neg\u00F3cios atrav\u00E9s do design, prototipa\u00E7\u00E3o e teste de ideias com clientes.","C) Um framework para otimizar o banco de dados do Google.","D) Apenas o desenho do logotipo da empresa."]', 1),
        (1062, N'fase21', N'(ENADE - Governança) O que é o COBIT na área de TI?', N'Alternativa B: Framework de Governança de TI.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: O COBIT ajuda diretores e executivos a gerenciarem os riscos de TI, garantirem a segurança da informação e auditarem se os investimentos tecnológicos geram valor ao negócio.', N'Focado em Diretoria, Governança e Auditoria.', N'["A) Uma linguagem de programa\u00E7\u00E3o orientada a objetos baseada em COBOL.","B) Um framework global para a Governan\u00E7a e Gest\u00E3o corporativa de Tecnologia da Informa\u00E7\u00E3o.","C) Um software antiv\u00EDrus empresarial.","D) Uma lei americana de prote\u00E7\u00E3o de patentes."]', 1),
        (1063, N'fase21', N'(ENADE - Negócios) O que é o modelo de negócio ''Marketplace''?', N'Alternativa B: Uma plataforma que conecta múltiplos vendedores a compradores.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: A plataforma de Marketplace não possui necessariamente o estoque dos produtos; ela intermedeia a transação financeira, garantindo segurança e tráfego para os parceiros.', N'É um shopping center virtual.', N'["A) Uma empresa que fabrica os pr\u00F3prios sapatos e os vende em loja f\u00EDsica.","B) Uma plataforma online que conecta vendedores independentes a compradores, recebendo comiss\u00F5es pelas vendas (Ex: Mercado Livre, Amazon, Uber).","C) Uma ONG focada na doa\u00E7\u00E3o de hardware antigo.","D) Um modelo onde o software \u00E9 gr\u00E1tis mas o suporte \u00E9 pago."]', 1),
        (1064, N'fase21', N'(ENADE - Ética e IA) Em relação ao desenvolvimento de algoritmos de Inteligência Artificial, o que é o ''Viés Algorítmico'' (Algorithmic Bias)?', N'Alternativa C: Decisões discriminatórias baseadas em dados viciados.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Se uma IA de recrutamento for treinada com currículos de uma empresa que historicamente contratava mais homens brancos, a IA aprenderá que esse perfil é o ''ideal'' e passará a descartar minorias, herdando o preconceito humano.', N'A IA reproduzindo o preconceito humano.', N'["A) Quando o c\u00F3digo Python \u00E9 substitu\u00EDdo por R.","B) A capacidade da IA de ter sentimentos humanos.","C) Quando a IA toma decis\u00F5es preconceituosas, injustas ou discriminat\u00F3rias devido a falhas nos dados hist\u00F3ricos usados em seu treinamento.","D) O atraso na resposta de um servidor de IA na nuvem."]', 2),
        (1065, N'fase21', N'(ENADE - Ágil) No Scrum, O que representa o ''Product Backlog''?', N'Alternativa C: Lista viva e priorizada de requisitos.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: O Product Backlog nunca está ''pronto''. Enquanto o produto existir, o backlog existirá, sendo constantemente refinado e priorizado pelo Product Owner com base no valor de negócio.', N'Lista de desejos do produto.', N'["A) Uma lista est\u00E1tica de requisitos que nunca pode ser alterada ap\u00F3s o in\u00EDcio do projeto.","B) O log de erros do servidor em produ\u00E7\u00E3o.","C) Uma lista viva, ordenada e priorizada de tudo que \u00E9 conhecido e necess\u00E1rio para criar e melhorar o Produto.","D) O painel visual onde as tarefas est\u00E3o na coluna \u0027Em Andamento\u0027."]', 2),
        (1066, N'fase21', N'(ENADE - Projetos) Durante o levantamento de Requisitos Funcionais, um usuário relata: ''A tela de login travou e apareceu erro 404''. Como a equipe de TI classifica essa informação?', N'Alternativa C: É um Bug (Defeito/Incidente).' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: O erro 404 indica que algo no código ou servidor que já deveria estar operando falhou. Bugs devem ser priorizados na fila de resolução, separados de novas features.', N'O sistema não operou conforme projetado.', N'["A) \u00C9 um requisito funcional novo.","B) \u00C9 uma melhoria (Feature).","C) \u00C9 um Bug (Defeito/Incidente) que afeta a disponibilidade e funcionalidade do sistema.","D) \u00C9 um requisito de neg\u00F3cio estrutural."]', 2),
        (1067, N'fase22', N'(ENADE - Algoritmos) Considere a estrutura de dados ''Fila'' (Queue) a ser usada para gerenciar requisições de impressão num escritório. Foram inseridos, nesta ordem, os arquivos: A, B e C.' + NCHAR(10) + N'' + NCHAR(10) + N'Se o comando ''dequeue()'' for executado duas vezes, qual arquivo restará na fila?', N'Alternativa C: Arquivo C.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: A Fila segue o princípio FIFO (First In, First Out). O primeiro a entrar é o primeiro a sair. Sairão o A e o B, restando apenas o C.', N'FIFO = First In, First Out.', N'["A) Arquivo A","B) Arquivo B","C) Arquivo C","D) A fila ficar\u00E1 vazia"]', 2),
        (1068, N'fase22', N'(ENADE - POO) Na Programação Orientada a Objetos, qual é o pilar que permite ocultar os detalhes internos de implementação de uma classe (colocando variáveis como private) e expor apenas os métodos públicos necessários (getters/setters)?', N'Alternativa C: Encapsulamento.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: O encapsulamento protege os dados do objeto contra alterações diretas indevidas por parte de outras classes, garantindo a integridade do estado interno.', N'Funciona como uma cápsula de proteção.', N'["A) Heran\u00E7a","B) Polimorfismo","C) Encapsulamento","D) Abstra\u00E7\u00E3o"]', 2),
        (1069, N'fase22', N'(ENADE - Bancos de Dados) Num modelo relacional, o que caracteriza uma restrição de integridade referencial implementada através de uma Chave Estrangeira (Foreign Key)?', N'Alternativa B: Garante que os valores correspondam a uma Chave Primária noutra tabela.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: A Chave Estrangeira impede que se registre um ''Pedido'' para um ''Cliente'' que não existe no banco de dados, mantendo a integridade dos dados.', N'Evita registros órfãos.', N'["A) Garante que uma coluna n\u00E3o tenha valores nulos (NOT NULL).","B) Garante que os valores de uma coluna de uma tabela existam como valores de uma chave prim\u00E1ria (PK) noutra tabela relacionada.","C) Garante a ordena\u00E7\u00E3o alfab\u00E9tica das colunas.","D) Impede atualiza\u00E7\u00F5es no banco de dados."]', 1),
        (1070, N'fase22', N'(ENADE - SQL) Qual comando DML (Data Manipulation Language) do SQL é utilizado para atualizar registros já existentes numa tabela?', N'Alternativa D: UPDATE.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: O comando UPDATE altera os dados de uma ou mais linhas existentes. (O ALTER TABLE é um comando DDL usado para alterar a estrutura da tabela, não os dados).', N'Lembre-se da estrutura UPDATE ... SET ... WHERE.', N'["A) ALTER TABLE","B) MODIFY","C) INSERT","D) UPDATE"]', 3),
        (1071, N'fase22', N'(ENADE - UML) Qual é a finalidade principal do Diagrama de Sequência na linguagem UML?', N'Alternativa C: Modelar a interação e a troca de mensagens ao longo do tempo.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: O diagrama de sequência evidencia a ordem temporal cronológica das interações entre componentes ou atores num determinado cenário.', N'Foco na linha do tempo e nas mensagens (setas).', N'["A) Mostrar a hierarquia de heran\u00E7a entre as classes.","B) Descrever os estados pelos quais um objeto passa durante a sua vida.","C) Modelar a intera\u00E7\u00E3o e a troca de mensagens entre os objetos ao longo do tempo.","D) Estruturar o banco de dados do sistema."]', 2),
        (1072, N'fase22', N'(ENADE - Estruturas de Dados) Se necessitar de um algoritmo que faça pesquisas extremamente rápidas em grandes conjuntos de dados ordenados, qual estrutura e respetivo algoritmo oferecem complexidade O(log n)?', N'Alternativa C: Árvore Binária de Busca (Busca Binária).' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Na busca binária, a cada passo dividimos o conjunto de dados pela metade, o que resulta na eficiência logarítmica O(log n).', N'A cada passo corta o problema pela metade.', N'["A) Fila (Pesquisa Linear)","B) Array n\u00E3o ordenado (Busca Cega)","C) \u00C1rvore Bin\u00E1ria de Busca (Busca Bin\u00E1ria)","D) Pilha (LIFO)"]', 2),
        (1073, N'fase22', N'(ENADE - Redes) Numa aplicação cliente-servidor (ex: Streaming de vídeo), onde a velocidade e o envio contínuo são mais importantes que a garantia de entrega de cada pacote, qual protocolo da camada de transporte é preferível utilizar?', N'Alternativa B: UDP.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: O UDP não verifica se os pacotes chegaram ao destino (não tem confirmação de entrega - ACK), sendo muito mais rápido e ideal para transmissões em tempo real.', N'Rápido, mas sem confirmação.', N'["A) TCP","B) UDP","C) HTTP","D) FTP"]', 1),
        (1074, N'fase22', N'(ENADE - Arquitetura) Qual é a principal característica da arquitetura de Microserviços em comparação com uma arquitetura Monolítica?', N'Alternativa B: Dividir a aplicação em pequenos serviços independentes.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Nos microserviços, cada serviço foca-se numa regra de negócio específica, podendo ser implementado e escalado de forma totalmente isolada.', N'Serviços pequenos e isolados.', N'["A) Compartilhar o mesmo banco de dados para todo o sistema de forma r\u00EDgida.","B) Dividir a aplica\u00E7\u00E3o em pequenos servi\u00E7os independentes que comunicam via APIs.","C) O c\u00F3digo-fonte reside inteiramente num \u00FAnico arquivo execut\u00E1vel.","D) N\u00E3o \u00E9 compat\u00EDvel com computa\u00E7\u00E3o na nuvem."]', 1),
        (1075, N'fase22', N'(ENADE - SO) O que é o processo de ''Swapping'' (troca) gerenciado pelo Sistema Operacional?', N'Alternativa C: Transferir processos da RAM para o Disco (memória virtual).' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Quando a memória RAM fica cheia, o SO move dados inativos para uma área de troca (Swap) no disco rígido, libertando RAM para processos mais urgentes.', N'Cria a ''memória virtual'' no disco.', N'["A) Trocar o processador principal em tempo de execu\u00E7\u00E3o.","B) Substituir o sistema Linux pelo Windows.","C) Transferir processos temporariamente da mem\u00F3ria RAM para o Disco/SSD (mem\u00F3ria virtual) para libertar espa\u00E7o.","D) Efetuar a troca de pacotes de rede pelo router."]', 2),
        (1076, N'fase22', N'(ENADE - Criptografia) Numa comunicação com criptografia Assimétrica (Chave Pública/Privada), como a Alice garante que uma mensagem que ela envia para o Bob só poderá ser lida por ele?', N'Alternativa B: Encriptando com a Chave Pública do Bob.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Se a Alice usar a Chave Pública do Bob (que todos conhecem) para encriptar, apenas a Chave Privada do Bob (que só ele possui) conseguirá desencriptar e ler a mensagem.', N'A fechadura é pública, mas a chave é privada.', N'["A) Encriptando com a Chave Privada da Alice.","B) Encriptando com a Chave P\u00FAblica do Bob.","C) Encriptando com a Chave P\u00FAblica da Alice.","D) Encriptando com a Chave Privada do Bob."]', 1),
        (1077, N'fase22', N'(ENADE - Web) O que é o modelo DOM (Document Object Model) no desenvolvimento Front-end?', N'Alternativa C: Representação estrutural do documento HTML como árvore de objetos.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: O DOM permite que o JavaScript modifique elementos, estilos e eventos da página em tempo real, alterando a estrutura de árvore.', N'A ''árvore'' estrutural do HTML vista pelo JS.', N'["A) Um banco de dados nativo do navegador.","B) Uma linguagem que substitui o HTML.","C) Uma interface de programa\u00E7\u00E3o (API) que representa o documento HTML como uma \u00E1rvore de objetos.","D) Um protocolo de rede."]', 2),
        (1078, N'fase22', N'(ENADE - Lógica) O que é a Recursividade na construção de um algoritmo?', N'Alternativa B: Quando uma função chama-se a si mesma.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Algoritmos recursivos resolvem problemas complexos quebrando-os em instâncias menores do próprio problema (ex: cálculo de Fatorial).', N'Uma função que se invoca a si própria.', N'["A) Um loop while infinito.","B) Quando uma fun\u00E7\u00E3o chama-se a si mesma at\u00E9 atingir uma condi\u00E7\u00E3o de paragem.","C) Quando o c\u00F3digo compartilha vari\u00E1veis globais.","D) Quando o c\u00F3digo \u00E9 executado num servidor remoto."]', 1),
        (1079, N'fase22', N'(ENADE - POO) Qual é a utilidade prática de uma Classe Abstrata na POO?', N'Alternativa A: Servir apenas como modelo para herança.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Uma classe abstrata (ex: ''Animal'') representa um conceito genérico. Não se cria um ''Animal'' direto, mas sim instâncias concretas das filhas (''Cão'', ''Gato'').', N'Não permite usar o operador ''new'' diretamente nela.', N'["A) Evitar que a classe seja instanciada diretamente, servindo apenas como modelo (superclasse) para as suas classes filhas.","B) For\u00E7ar que todos os seus m\u00E9todos estejam vazios (como numa Interface).","C) Esconder o c\u00F3digo-fonte num arquivo DLL fechado.","D) Substituir o uso de vari\u00E1veis locais no escopo."]', 0),
        (1080, N'fase22', N'(ENADE - Segurança) Um atacante envia um link manipulado para a vítima. Quando a vítima clica no link, estando autenticada no site do banco, o código faz uma transferência indesejada. Este ataque é o:', N'Alternativa C: CSRF (Falsificação de Pedido Entre Sites).' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: No CSRF, o atacante usa a sessão válida (os cookies de login) do usuário para executar ações indesejadas no servidor de destino.', N'Falsifica uma ação do próprio usuário autenticado.', N'["A) SQL Injection","B) Cross-Site Scripting (XSS)","C) Cross-Site Request Forgery (CSRF)","D) Buffer Overflow"]', 2),
        (1081, N'fase22', N'(ENADE - Redes) O que diferencia o protocolo HTTPS do protocolo HTTP padrão?', N'Alternativa B: O HTTPS utiliza encriptação SSL/TLS.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: O ''S'' (Secure) garante que toda a comunicação entre o cliente e o servidor esteja encriptada, impedindo a interceção de dados em texto claro.', N'O cadeado no navegador.', N'["A) O HTTPS \u00E9 mais r\u00E1pido para v\u00EDdeo.","B) O HTTPS utiliza uma camada adicional de seguran\u00E7a (SSL/TLS) para encriptar os dados.","C) O HTTPS n\u00E3o exige servidor web.","D) O HTTPS usa o UDP em vez do TCP."]', 1),
        (1082, N'fase22', N'(ENADE - ACID) A respeito das transações em Bancos de Dados Relacionais, o que garante a propriedade da ''Atomicidade''?', N'Alternativa A: Tudo ou nada na transação.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Se no meio de uma transferência o sistema for abaixo, a atomicidade garante o ROLLBACK, revertendo toda a operação para que os dados não fiquem inconsistentes.', N'Ação indestrutível, executa tudo ou não executa nada.', N'["A) A transa\u00E7\u00E3o ser\u00E1 executada inteiramente com sucesso, ou falhar\u00E1 totalmente (tudo ou nada).","B) O sistema volta sempre \u00E0 vers\u00E3o original do dia anterior.","C) Duas transa\u00E7\u00F5es n\u00E3o afetam a mesma tabela.","D) Os dados s\u00E3o salvos em m\u00FAltiplos discos simultaneamente."]', 0),
        (1083, N'fase22', N'(ENADE - API REST) Qual o método HTTP utilizado especificamente para solicitar a *atualização completa* de um recurso no servidor?', N'Alternativa A: PUT.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: O PUT é usado para substituir completamente um recurso existente. O PATCH é usado quando se deseja atualizar apenas uma parte (atualização parcial) do recurso.', N'Substitui todo o objeto.', N'["A) PUT","B) GET","C) PATCH","D) DELETE"]', 0),
        (1084, N'fase22', N'(ENADE - Design Patterns) O Padrão de Projeto ''Singleton'' é categorizado como um padrão de Criação. Qual é a sua finalidade no código?', N'Alternativa B: Garantir uma única instância global da classe.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Singleton é muito usado para gerenciar conexões com o banco de dados, onde ter várias instâncias ativas gastaria memória desnecessária.', N'Single (Uma única instância).', N'["A) Criar m\u00FAltiplas inst\u00E2ncias din\u00E2micas de uma classe.","B) Garantir que uma classe tenha uma \u00FAnica inst\u00E2ncia em todo o sistema e fornecer um ponto global de acesso a ela.","C) Ocultar a complexidade de cria\u00E7\u00E3o sob uma Interface.","D) Criar fam\u00EDlias de objetos inter-relacionados."]', 1),
        (1085, N'fase22', N'(ENADE - Git) Num fluxo de trabalho usando Git, o que o comando ''git commit'' executa?', N'Alternativa C: Guarda o estado atual no repositório LOCAL.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: O comando commit registra as alterações no histórico da máquina do usuário. Para enviar para a nuvem, usa-se o git push.', N'Grava a versão localmente.', N'["A) Envia o c\u00F3digo para a nuvem no GitHub.","B) Cria uma c\u00F3pia do projeto.","C) Guarda um snapshot do estado atual dos arquivos modificados no reposit\u00F3rio LOCAL do desenvolvedor.","D) Apaga o hist\u00F3rico."]', 2),
        (1086, N'fase22', N'(ENADE - Algoritmos) Qual é a finalidade principal do algoritmo de ordenação ''Bubble Sort''?', N'Alternativa B: Percorrer listas e trocar pares vizinhos até ordenar.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: O Bubble Sort é o algoritmo de ordenação mais simples e menos eficiente O(n²). O maior valor ''borbulha'' para a extremidade a cada ciclo.', N'Como bolhas a flutuar num copo.', N'["A) Compactar arquivos ZIP.","B) Percorrer uma lista, comparando pares vizinhos e trocando de posi\u00E7\u00E3o se estiverem fora de ordem, at\u00E9 que o maior flutue para o final.","C) Pesquisar a palavra mais longa num texto.","D) Criar matrizes multidimensionais vazias."]', 1),
        (1087, N'fase22', N'(ENADE - Bancos de Dados) O que significa a operação de ''Normalização'' aplicada a um esquema de banco de dados relacional?', N'Alternativa C: Eliminar anomalias e reduzir a redundância.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: A normalização (1FN, 2FN, 3FN) garante que não haverá inconsistências (ex: ter duas moradas diferentes para a mesma pessoa) isolando dados repetidos.', N'Regras para organizar tabelas sem repetições.', N'["A) Aumentar propositadamente a redund\u00E2ncia para tornar as pesquisas r\u00E1pidas.","B) Aumentar os tipos de dados permitidos.","C) Reestruturar as tabelas para eliminar anomalias de atualiza\u00E7\u00E3o, inser\u00E7\u00E3o e reduzir a redund\u00E2ncia de dados.","D) Traduzir o banco de dados para ORM."]', 2),
        (1088, N'fase22', N'(ENADE - Sistemas Distribuídos) O que dita o Teorema CAP focado em Bancos de Dados NoSQL e Sistemas Distribuídos?', N'Alternativa B: Impossível garantir as 3 propriedades simultaneamente (C, A e P).' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Num cluster, em caso de falha de rede (Partição), deve-se escolher se paralisa o sistema para manter a Consistência ou se permite gravações para manter a Disponibilidade.', N'Escolha apenas duas de três.', N'["A) Que n\u00E3o se pode ter uma rede sem routers.","B) Que \u00E9 imposs\u00EDvel fornecer simultaneamente as tr\u00EAs garantias: Consist\u00EAncia (C), Disponibilidade (A) e Toler\u00E2ncia a Parti\u00E7\u00E3o (P). S\u00F3 se escolhe duas.","C) Que toda a base distribu\u00EDda deve usar SQL.","D) Que backups evitam qualquer falha de hardware."]', 1),
        (1089, N'fase22', N'(ENADE - Cloud) O que caracteriza a ''Escalabilidade Horizontal'' numa infraestrutura Web em comparação com a Vertical?', N'Alternativa B: Adicionar mais servidores e dividir o tráfego com Load Balancer.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: A escalabilidade vertical (Scale-up) aumenta o poder da própria máquina. A horizontal (Scale-out) resolve a alta procura colocando mais máquinas a trabalhar em equipe.', N'Mais máquinas lado a lado = Horizontal.', N'["A) Aumentar a CPU e a RAM do mesmo servidor existente.","B) Adicionar mais servidores \u00E0 arquitetura e dividir o tr\u00E1fego (Load Balancer) entre eles.","C) Aumento da largura de banda do provedor.","D) Mover o sistema on-premises para a nuvem."]', 1),
        (1090, N'fase22', N'(ENADE - C) Na linguagem C, qual o grande problema causado quando o programador aloca memória dinamicamente usando malloc() e esquece de a libertar com free()?', N'Alternativa B: Memory Leak (Fuga de Memória).' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: O sistema operacional perde a referência dessa alocação, mas não a liberta. Se ocorrer repetidamente, o computador fica sem memória RAM disponível e crasha.', N'Fuga contínua de memória RAM.', N'["A) Stack Overflow (Estouro da Pilha).","B) Memory Leak (Fuga de Mem\u00F3ria).","C) Null Pointer Exception.","D) Loop Infinito."]', 1),
        (1091, N'fase22', N'(ENADE - Engenharia de Software) Qual é o objetivo do padrão arquitetural MVC (Model-View-Controller)?', N'Alternativa B: Separar dados, interface e controle lógico.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: O MVC promove a separação de preocupações (Separation of Concerns), tornando o código mais modular, fácil de testar e de manter.', N'Separa a tela da lógica.', N'["A) Aumentar o acoplamento do sistema.","B) Separar a representa\u00E7\u00E3o da informa\u00E7\u00E3o (dados), a intera\u00E7\u00E3o do usuário (interface) e o controle l\u00F3gico em tr\u00EAs componentes interligados.","C) Juntar todo o c\u00F3digo num \u00FAnico arquivo JavaScript.","D) Substituir a necessidade de um banco de dados."]', 1),
        (1092, N'fase22', N'(ENADE - POO) A técnica em que duas ou mais funções da mesma classe têm o mesmo nome, mas diferem no número ou tipo dos seus parâmetros, chama-se:', N'Alternativa B: Sobrecarga (Overloading).' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: A sobrecarga de métodos ocorre em tempo de compilação. Permite criar métodos com o mesmo nome (ex: calcularArea(int lado) e calcularArea(int base, int altura)) na mesma classe.', N'Mesmo nome, assinaturas diferentes.', N'["A) Sobrescrita (Overriding)","B) Sobrecarga (Overloading)","C) Abstra\u00E7\u00E3o","D) Interface"]', 1),
        (1093, N'fase22', N'(ENADE - Bancos de Dados) Numa tabela de banco de dados relacional, uma chave primária (Primary Key) composta é formada por:', N'Alternativa B: Dois ou mais atributos combinados.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Quando uma única coluna não é suficiente para garantir a exclusividade do registro (ex: ID_Aluno e ID_Disciplina numa tabela de matrículas), utiliza-se a junção das colunas como Chave Primária Composta.', N'Combinação de duas ou mais colunas.', N'["A) Apenas um atributo num\u00E9rico e autoincremental.","B) Dois ou mais atributos que, combinados, identificam unicamente uma linha na tabela.","C) Uma chave que faz refer\u00EAncia a outra tabela externa.","D) Uma chave que permite valores nulos."]', 1),
        (1094, N'fase22', N'(ENADE - Estruturas de Dados) Numa estrutura do tipo Pilha (Stack), as operações clássicas de inserção e remoção são conhecidas, respetivamente, como:', N'Alternativa C: Push e Pop.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Numa Pilha (LIFO - Last In, First Out), a operação de empilhar um item no topo chama-se ''Push'', e a operação de retirar o item do topo chama-se ''Pop''.', N'Empurrar e Estourar.', N'["A) Enqueue e Dequeue","B) Insert e Delete","C) Push e Pop","D) Add e Remove"]', 2),
        (1095, N'fase22', N'(ENADE - Lógica) Numa expressão condicional, o operador lógico ''XOR'' (OU Exclusivo) retorna VERDADEIRO apenas quando:', N'Alternativa C: Apenas uma das proposições é verdadeira, e a outra é falsa.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: O XOR (Exclusive OR) exige que as entradas sejam diferentes para ser verdadeiro. Se ambas forem iguais (True/True ou False/False), o resultado é falso.', N'Um ou outro, mas não os dois.', N'["A) Ambas as proposi\u00E7\u00F5es s\u00E3o verdadeiras.","B) Ambas as proposi\u00E7\u00F5es s\u00E3o falsas.","C) Apenas uma das proposi\u00E7\u00F5es \u00E9 verdadeira, e a outra \u00E9 falsa.","D) O valor \u00E9 nulo."]', 2),
        (1096, N'fase22', N'(ENADE - SQL) A cláusula GROUP BY no SQL é geralmente utilizada em conjunto com:', N'Alternativa B: Funções de agregação.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: O GROUP BY serve para agrupar linhas que têm os mesmos valores em colunas de resumo, permitindo calcular médias, somas ou totais por grupo (ex: COUNT(*) de usuários agrupados por País).', N'Agrupa para somar ou contar.', N'["A) Comandos INSERT e UPDATE.","B) Fun\u00E7\u00F5es de agrega\u00E7\u00E3o (como SUM, AVG, COUNT, MAX, MIN).","C) Comandos de cria\u00E7\u00E3o de tabelas (CREATE TABLE).","D) Cl\u00E1usulas LIMIT e OFFSET exclusivamente."]', 1),
        (1097, N'fase22', N'(ENADE - Engenharia de Software) Qual é o modelo de ciclo de vida de software que se caracteriza por uma progressão estrita e linear através de fases (Requisitos, Design, Implementação, Testes, Manutenção) sem possibilidade de retorno natural à fase anterior?', N'Alternativa C: Modelo Cascata (Waterfall).' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: O modelo em cascata é sequencial e rígido. Uma nova fase só começa quando a anterior termina totalmente, sendo difícil e dispendioso acomodar mudanças de requisitos no meio do projeto.', N'A água só cai, não sobe.', N'["A) Modelo \u00C1gil (Scrum)","B) Modelo em Espiral","C) Modelo Cascata (Waterfall)","D) Modelo Prototipagem"]', 2),
        (1098, N'fase22', N'(ENADE - DevOps) Na terminologia de contentorização (ex: Docker), o que é uma ''Imagem'' (Image)?', N'Alternativa B: Um template read-only contendo as dependências para rodar a app.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: A Imagem é o ''molde'' estático. Quando executamos uma Imagem no Docker, ela torna-se um Contentor (Container) vivo e em execução.', N'É a ''receita de bolo'' do contentor.', N'["A) Uma fotografia JPEG do layout do site.","B) Um template apenas de leitura (read-only) que cont\u00E9m o SO, bibliotecas e o c\u00F3digo-fonte necess\u00E1rio para executar a aplica\u00E7\u00E3o num contentor.","C) O disco r\u00EDgido f\u00EDsico onde os dados s\u00E3o salvos permanentemente.","D) Um servi\u00E7o de hospedagem na AWS."]', 1),
        (1099, N'fase22', N'(ENADE - Sistemas Operacionais) O conceito de ''Multithreading'' refere-se à:', N'Alternativa B: Múltiplas linhas de execução paralelas.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: O Multithreading permite que a aplicação faça várias tarefas ao mesmo tempo (ex: um jogo carrega o som numa thread enquanto processa a física noutra), otimizando o uso do processador.', N'Processamento simultâneo.', N'["A) Capacidade de ligar v\u00E1rios monitores ao computador.","B) Capacidade de um programa se dividir em m\u00FAltiplas threads (linhas de execu\u00E7\u00E3o) que podem ser processadas em paralelo pelo CPU.","C) Transfer\u00EAncia de arquivos pesados via FTP.","D) Instala\u00E7\u00E3o de m\u00FAltiplos sistemas operacionais no mesmo disco."]', 1),
        (1100, N'fase22', N'(ENADE - Web) No desenvolvimento web, o que são as sessões armazenadas nos Cookies ou no Local Storage do navegador?', N'Alternativa B: Dados armazenados no cliente para manter o estado.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Como o HTTP é ''sem estado'' (não lembra da última requisição), os cookies e o Local Storage guardam os tokens de autenticação (ex: JWT) para manter o usuário ''logado''.', N'Memória do navegador.', N'["A) Arquivos de v\u00EDdeo em cache.","B) Pequenos fragmentos de dados armazenados no cliente (navegador) para manter o estado da aplica\u00E7\u00E3o e identificar o usuário entre as requisi\u00E7\u00F5es HTTP (que s\u00E3o stateless).","C) Componentes do servidor de banco de dados MySQL.","D) Um protocolo de encripta\u00E7\u00E3o de senhas."]', 1);
    INSERT INTO flashcards (id, codigo_fase, frente, verso, dica, opcoes, correta) VALUES
        (1101, N'fase22', N'(ENADE - Segurança) O que caracteriza um ataque do tipo ''SQL Injection'' (Injeção de SQL)?', N'Alternativa B: Inserir instruções SQL maliciosas em campos de input.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Ocorre quando a aplicação não filtra/higieniza os dados do usuário. O atacante pode enviar algo como `'' OR 1=1 --` num campo de login para acessar o sistema sem senha.', N'Input malicioso que engana o banco de dados.', N'["A) Inserir um cabo de rede n\u00E3o autorizado no servidor.","B) Explorar vulnerabilidades numa aplica\u00E7\u00E3o inserindo instru\u00E7\u00F5es SQL maliciosas nos campos de input (formul\u00E1rios) para manipular ou destruir o banco de dados.","C) Quando o banco de dados desliga por sobrecarga de mem\u00F3ria.","D) Interce\u00E7\u00E3o de pacotes na rede Wi-Fi aberta."]', 1),
        (1102, N'fase22', N'(ENADE - Redes) O Modelo OSI é um padrão de referência para interligação de sistemas abertos. É composto por quantas camadas lógicas?', N'Alternativa C: 7 camadas.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: O Modelo OSI tem 7 camadas: Física, Enlace (Dados), Rede, Transporte, Sessão, Apresentação e Aplicação. O modelo TCP/IP, mais prático, é que condensa estas em apenas 4 camadas.', N'F-E-R-T-S-A-A.', N'["A) 4 camadas","B) 5 camadas","C) 7 camadas","D) 9 camadas"]', 2),
        (1103, N'fase22', N'(ENADE - POO) A que conceito de POO se refere a afirmação: ''As subclasses podem fornecer a sua própria implementação específica para um método que já foi definido na superclasse''?', N'Alternativa B: Sobrescrita (Overriding).' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: A sobrescrita ocorre em tempo de execução quando uma classe herda de outra e redefine (altera o bloco de código) de um método existente no pai (ex: @Override no Java/C#).', N'A mesma assinatura, comportamento redefinido.', N'["A) Construtor","B) Sobrescrita (Overriding)","C) Sobrecarga (Overloading)","D) Interface"]', 1),
        (1104, N'fase22', N'(ENADE - Arquitetura REST) Uma API RESTful deve ser ''Stateless'' (Sem Estado). O que isto significa obrigatoriamente?', N'Alternativa B: Cada requisição contém toda a informação necessária.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: O servidor não guarda quem está ''logado''. O cliente envia um token (como o JWT) no cabeçalho (Header) de TODAS as requisições para provar quem é.', N'O servidor não tem memória da requisição passada.', N'["A) Que n\u00E3o pode usar banco de dados.","B) Que cada requisi\u00E7\u00E3o do cliente para o servidor deve conter todas as informa\u00E7\u00F5es necess\u00E1rias para ser compreendida e processada, sem depender de contextos salvos no servidor.","C) Que o servidor deve gravar a sess\u00E3o do cliente na mem\u00F3ria RAM.","D) Que o formato de resposta tem de ser em XML."]', 1),
        (1105, N'fase22', N'(ENADE - Lógica) Numa tabela de verdade para o operador lógico ''AND'' (E), se tivermos as variáveis A (Verdadeiro), B (Falso) e C (Verdadeiro), qual será o resultado da expressão A AND B AND C?', N'Alternativa B: Falso.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: O operador AND lógico só retorna Verdadeiro se TODAS as condições fornecidas forem Verdadeiras. Como a variável B é Falsa, toda a expressão se torna Falsa.', N'AND exige perfeição (todos verdadeiros).', N'["A) Verdadeiro","B) Falso","C) Null","D) Ocorre um erro de compila\u00E7\u00E3o."]', 1),
        (1106, N'fase22', N'(ENADE - Algoritmos) Qual é a técnica de otimização de algoritmos (frequentemente usada junto com recursividade) que consiste em guardar os resultados de cálculos pesados já processados num cache/tabela para evitar reprocessamento futuro?', N'Alternativa B: Memoization (Programação Dinâmica).' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Memoization é o ato de memorizar a saída de uma função cara. Na sequência de Fibonacci recursiva, sem Memoization a árvore de chamadas cresce exponencialmente (repetindo cálculos iguais).', N'Memorizar o que já foi calculado.', N'["A) Backtracking","B) Memoization (Programa\u00E7\u00E3o Din\u00E2mica)","C) Algoritmo Guloso (Greedy)","D) Ordena\u00E7\u00E3o por inser\u00E7\u00E3o"]', 1),
        (1107, N'fase22', N'(ENADE - Criptografia) O algoritmo de Hash (como SHA-256 ou MD5) possui uma característica fundamental que o difere da Criptografia padrão (como AES ou RSA). Qual é essa característica?', N'Alternativa B: É de mão única (One-way), não tem reversão.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Criptografia serve para encriptar e depois desencriptar. O Hash destrói a string original e cria uma ''impressão digital''. É assim que as senhas são guardadas com segurança no banco de dados.', N'Pode transformar a carne na salsicha, mas não a salsicha na carne.', N'["A) O Hash \u00E9 utilizado para encriptar arquivos grandes em formato zip.","B) O Hash \u00E9 uma via de m\u00E3o \u00FAnica (One-way): \u00E9 imposs\u00EDvel (ou invi\u00E1vel computacionalmente) reverter o c\u00F3digo gerado de volta para a palavra original.","C) O Hash necessita sempre de uma chave p\u00FAblica para ser lido.","D) O Hash s\u00F3 aceita n\u00FAmeros inteiros como entrada."]', 1),
        (1108, N'fase22', N'(ENADE - Cloud) Em provedores de nuvem (AWS, Azure, GCP), o conceito de ''Elasticidade'' refere-se à capacidade do sistema de:', N'Alternativa B: Aumentar e diminuir recursos automaticamente com a procura.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: A elasticidade é o que permite a um e-commerce manter-se online na Black Friday (alugando mais servidores por algumas horas) e reduzir os custos na semana seguinte.', N'Estica e encolhe como um elástico.', N'["A) Alterar a cor da interface dependendo do fuso hor\u00E1rio do usuário.","B) Aumentar (Scale-out) ou diminuir (Scale-in) automaticamente e de forma din\u00E2mica os recursos de infraestrutura com base na procura em tempo real.","C) Compactar o tamanho do banco de dados relacional.","D) Impedir ataques DDoS bloqueando IPs asi\u00E1ticos."]', 1),
        (1109, N'fase22', N'(ENADE - Mobile) Qual é a principal diferença entre criar uma aplicação Mobile Nativa e uma aplicação Cross-Platform (Híbrida)?', N'Alternativa C: A Cross-Platform usa uma base de código única para ambos os sistemas operacionais.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Aplicações nativas têm o melhor desempenho e integração, mas exigem duas equipes (Android e iOS). Frameworks híbridos ganham em produtividade e tempo de lançamento.', N'Nativa = Código diferente. Híbrida = Código único.', N'["A) A Nativa s\u00F3 funciona offline. A H\u00EDbrida precisa de internet.","B) A Nativa utiliza o GPS. A H\u00EDbrida n\u00E3o tem acesso ao hardware.","C) A Nativa exige c\u00F3digos separados para Android (Kotlin/Java) e iOS (Swift/Objective-C). A Cross-Platform (ex: React Native, Flutter) gera ambos a partir de uma base de c\u00F3digo \u00FAnica.","D) N\u00E3o existem diferen\u00E7as estruturais."]', 2),
        (1110, N'fase22', N'(ENADE - Banco de Dados) O que faz o comando JOIN da cláusula LEFT OUTER JOIN (ou LEFT JOIN) no SQL?', N'Alternativa B: Retorna todos da esquerda, independentemente da correspondência na direita.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: O LEFT JOIN é essencial quando queremos listar, por exemplo, todos os ''Clientes'' e os seus ''Pedidos'', incluindo na lista os clientes que ainda não fizeram nenhum pedido (NULL).', N'Prioriza a tabela da Esquerda.', N'["A) Retorna apenas os registros que t\u00EAm correspond\u00EAncia nas duas tabelas.","B) Retorna todos os registros da tabela da ESQUERDA, e apenas as correspond\u00EAncias da tabela da direita. Se n\u00E3o houver correspond\u00EAncia, preenche com NULL.","C) Apaga as linhas duplicadas do lado esquerdo.","D) Multiplica todos os registros (Produto Cartesiano)."]', 1),
        (1111, N'fase22', N'(ENADE - Segurança) O que significa aplicar o princípio do ''Menor Privilégio'' (Least Privilege) num sistema operacional ou banco de dados?', N'Alternativa B: Fornecer apenas as permissões estritamente necessárias.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: É uma regra de ouro em segurança cibernética. Se a conta de um funcionário comum for pirateada, o atacante não conseguirá eliminar o banco de dados central, pois a conta não tem esse privilégio.', N'Só dê a chave da porta que a pessoa precisa de abrir.', N'["A) Dar acesso total de Admin a todos para evitar bloqueios de trabalho.","B) Fornecer a cada usuário ou programa apenas as permiss\u00F5es e acessos estritamente necess\u00E1rios para realizar as suas tarefas, e nada mais.","C) Remover as permiss\u00F5es de quem ganha o menor sal\u00E1rio.","D) Cobrar menos por assinaturas de software b\u00E1sicas."]', 1),
        (1112, N'fase22', N'(ENADE - Eng. de Requisitos) No desenvolvimento de software, os ''Diagramas de Casos de Uso'' são utilizados primariamente durante qual fase do ciclo de vida?', N'Alternativa C: Levantamento e Análise de Requisitos.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Os Casos de Uso (da UML) são ferramentas visuais para traduzir as necessidades do negócio e as interações entre os atores (usuários) e o sistema, antes de a equipe começar a programar.', N'É o planejamento antes do código.', N'["A) Manuten\u00E7\u00E3o e Evolu\u00E7\u00E3o","B) Testes de Integra\u00E7\u00E3o e Deployment","C) Levantamento e An\u00E1lise de Requisitos","D) Refatora\u00E7\u00E3o de C\u00F3digo"]', 2),
        (1113, N'fase22', N'(ENADE - Versionamento) No Git, se um desenvolvedor quiser criar um caminho isolado para desenvolver uma nova funcionalidade sem interferir com o código principal, qual comando deverá usar?', N'Alternativa B: git branch.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: O comando branch cria uma ''ramificação''. Isto permite que o programador crie código isoladamente numa ramificação de testes, e só faça a junção (merge) com a ramificação principal (main) após ter a certeza que o código funciona.', N'Cria um ramo (branch) isolado.', N'["A) git clone","B) git branch","C) git log","D) git rm"]', 1),
        (1114, N'fase22', N'(ENADE - Design de Interface) No CSS, utilizando o modelo Flexbox (display: flex), qual propriedade é utilizada para alinhar os itens horizontalmente ao longo do eixo principal?', N'Alternativa C: justify-content.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: A propriedade `justify-content` lida com o alinhamento no eixo principal (que por padrão é o horizontal, da esquerda para a direita). O `align-items` faz o alinhamento no eixo transversal (vertical).', N'Justifica o conteúdo na linha.', N'["A) align-items","B) flex-direction","C) justify-content","D) float: left"]', 2),
        (1115, N'fase22', N'(ENADE - Web) Numa API REST desenvolvida em NodeJS ou C#, se o cliente envia dados sigilosos, como uma senha, no corpo (body) de um formulário. Qual método HTTP está sendo utilizado?', N'Alternativa C: POST.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: O verbo POST é usado para enviar dados sensíveis ou longos contidos no corpo (body) da requisição. O método GET anexa os dados no URL (na barra de endereço), o que expõe a senha publicamente.', N'O GET mostra no URL, o POST oculta no Corpo.', N'["A) GET","B) OPTIONS","C) POST","D) HEAD"]', 2),
        (1116, N'fase22', N'(ENADE - Eng. de Software) O padrão de arquitetura SOLID traz princípios para a programação orientada a objetos. O ''S'' (Single Responsibility Principle) diz que:', N'Alternativa B: Uma classe deve ter apenas uma responsabilidade.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: O Princípio da Responsabilidade Única evita a criação de ''Classes Deus'' (classes gigantes que fazem de tudo: enviam email, guardam no banco, desenham a interface). Classes pequenas e focadas evitam bugs.', N'Princípio da Responsabilidade Única.', N'["A) O sistema deve rodar num servidor \u00FAnico.","B) Uma classe deve ter uma, e apenas uma, raz\u00E3o para mudar (uma \u00FAnica responsabilidade).","C) S\u00F3 pode existir uma heran\u00E7a por classe.","D) O c\u00F3digo deve ser escrito por um \u00FAnico programador."]', 1),
        (1117, N'fase23', N'O que é o ENADE?', N'O Exame Nacional de Desempenho dos Estudantes, aplicado pelo INEP. Ele avalia os cursos de graduação e, para o estudante convocado, é obrigatório: quem não faz fica com pendência para receber o diploma.', N'Quem aplica é o INEP.', NULL, NULL),
        (1118, N'fase23', N'Como a prova do ENADE é dividida?', N'40 questões em 4 horas:' + NCHAR(10) + N'• Formação Geral: 2 discursivas + 8 objetivas.' + NCHAR(10) + N'• Componente Específico (ADS): 3 discursivas + 27 objetivas.' + NCHAR(10) + N'No fim há ainda um questionário de percepção da prova, que não vale nota.', N'10 de Formação Geral + 30 específicas.', NULL, NULL),
        (1119, N'fase23', N'Quanto vale cada parte do ENADE?', N'Formação Geral vale 25% da nota e Componente Específico, 75%.' + NCHAR(10) + N'Dentro da Formação Geral: discursivas 40% e objetivas 60%.' + NCHAR(10) + N'Dentro do Específico: discursivas 15% e objetivas 85%.', N'As objetivas específicas são a maior parte da nota.', NULL, NULL),
        (1120, N'fase23', N'Como são as questões discursivas do ENADE?', N'Cada resposta tem no máximo 15 linhas. Na Formação Geral, pedem um texto argumentativo com proposta (2021: arte, cultura e censura; cidades inteligentes). No Específico de ADS caíram código em pseudocódigo (fila, lista encadeada, média de valores) e diagrama de classes.', N'15 linhas, sem passar do espaço.', NULL, NULL),
        (1121, N'fase23', N'Como resolver uma questão do tipo "avalie as afirmações"?', N'Julgue cada afirmação sozinha (V ou F) e anote. Depois procure a alternativa com exatamente as verdadeiras. Achou uma falsa com certeza? Elimine todas as alternativas que a incluem.', N'Eliminar alternativas economiza tempo.', NULL, NULL),
        (1122, N'fase23', N'Como resolver uma questão de asserção-razão ("I PORQUE II")?', N'1º veja se I é verdadeira. 2º veja se II é verdadeira. 3º só se as duas forem, pergunte se II explica I. Se uma for falsa, a relação nem importa.', N'Julgue as duas antes da relação.', NULL, NULL),
        (1123, N'fase23', N'Qual a diferença entre requisito funcional e não funcional?', N'Funcional diz O QUE o sistema faz ("emitir relatório de compras"). Não funcional diz COMO ou com que restrição ("responder em até 2 segundos", "rodar no Linux", "ficar pronto em 6 meses").', N'Caiu em 2017 (Q12) e 2021 (Q09).', NULL, NULL),
        (1124, N'fase23', N'Quais são os tipos de requisito não funcional?', N'Desempenho (tempo de resposta), usabilidade (facilidade de aprender e usar, acessibilidade), portabilidade (trocar de sistema operacional), segurança (controle de acesso) e confiabilidade (funcionar sem falhas).', N'Confiabilidade não é tempo de resposta.', NULL, NULL),
        (1125, N'fase23', N'Quais são os subprocessos da engenharia de requisitos?', N'Estudo de viabilidade, elicitação (ex.: entrevista com usuários), especificação (ex.: casos de uso dos requisitos funcionais) e validação (ex.: protótipo de telas).', N'Caso de uso modela requisito funcional.', NULL, NULL),
        (1126, N'fase23', N'O que é o caminho crítico de um projeto?', N'A sequência de atividades com a maior duração total. Se qualquer atividade dele atrasar, o projeto inteiro atrasa. Para achar: some as durações de cada caminho e pegue o maior.', N'Some todos os caminhos.', NULL, NULL),
        (1127, N'fase23', N'Quais são os tipos de manutenção de software?', N'Corretiva: conserta defeito.' + NCHAR(10) + N'Adaptativa: ajusta a um ambiente novo (outro SO, nova lei).' + NCHAR(10) + N'Evolutiva/perfectiva: acrescenta ou melhora funções (ex.: um relatório novo).' + NCHAR(10) + N'Preventiva: evita problemas futuros.', N'Relatório novo = evolutiva.', NULL, NULL),
        (1128, N'fase23', N'Quando usar cascata, incremental, espiral e RAD?', N'Cascata: requisitos estáveis, fases em sequência (lida mal com mudanças).' + NCHAR(10) + N'Incremental: entrega o sistema em partes.' + NCHAR(10) + N'Espiral: projetos grandes e arriscados, com análise de risco no planejamento.' + NCHAR(10) + N'RAD: prazo muito curto.', N'Urgência pede incremental ou RAD.', NULL, NULL),
        (1129, N'fase23', N'No Scrum, quem gerencia o Product Backlog?', N'O Product Owner. O Scrum Master cuida do processo e remove impedimentos; os desenvolvedores constroem o incremento.', N'Pegadinha clássica: não é o Scrum Master.', NULL, NULL),
        (1130, N'fase23', N'O que caracteriza a XP (eXtreme Programming)?', N'Foco na qualidade do código: testes automatizados escritos antes do código (TDD), programação em par, integração contínua e entregas pequenas e frequentes.', N'Teste antes do código = TDD.', NULL, NULL),
        (1131, N'fase23', N'Quais são as tarefas da gerência de configuração de software?', N'Identificação dos itens de configuração, controle de versão, controle de alterações, auditoria de configuração e relatório de status. Ela começa junto com o projeto, não depois da entrega.', N'São cinco tarefas.', NULL, NULL),
        (1132, N'fase23', N'No controle de versão, para que servem checkout, branch, merge e tag?', N'Checkout: baixa os arquivos do repositório.' + NCHAR(10) + N'Branch: ramo separado para uma mudança grande.' + NCHAR(10) + N'Merge: junta versões e resolve conflitos.' + NCHAR(10) + N'Tag: marca uma versão (release); não resolve conflito.', N'Conflito se resolve com merge.', NULL, NULL),
        (1133, N'fase23', N'Qual a diferença entre teste caixa-branca e caixa-preta?', N'Caixa-branca olha a estrutura interna do código (caminhos, condições). Caixa-preta olha só entradas e saídas, sem ver o código (ex.: testar em vários navegadores).', N'Branca = vê o código.', NULL, NULL),
        (1134, N'fase23', N'O que são teste unitário, de carga, alfa e de aceitação?', N'Unitário: testa um método ou classe isolado.' + NCHAR(10) + N'Carga: vê se aguenta o volume (ex.: 100 pedidos simultâneos).' + NCHAR(10) + N'Alfa: o usuário testa no ambiente do desenvolvedor, supervisionado (o beta é no ambiente do usuário).' + NCHAR(10) + N'Aceitação: o cliente confirma que é o que pediu.', N'Alfa = com os desenvolvedores por perto.', NULL, NULL),
        (1135, N'fase23', N'O que é o CMMI?', N'Um modelo de maturidade de processos: a empresa sobe de nível cumprindo metas de processo, até chegar à melhoria contínua. É pesado e voltado a organizações maiores; no Brasil, o MPS.BR foi pensado para pequenas e médias.', N'Maturidade = processo estável e institucionalizado.', NULL, NULL),
        (1136, N'fase23', N'Em casos de uso, qual a diferença entre <<include>> e <<extend>>?', N'<<include>>: o comportamento incluído SEMPRE acontece (obrigatório).' + NCHAR(10) + N'<<extend>>: acontece só em certa condição (opcional), como "matrícula fora do prazo".' + NCHAR(10) + N'Generalização: formas diferentes de fazer a mesma coisa (validar por retina ou por digital).', N'Include obrigatório, extend opcional.', NULL, NULL),
        (1137, N'fase23', N'Como ler as multiplicidades 1, 0..1, 0..* e 1..* na UML?', N'1: exatamente um. 0..1: no máximo um, pode não ter. 0..*: zero ou muitos. 1..*: pelo menos um, sem limite. Um lado 1..* pede uma coleção (lista) no código, não um atributo simples.', N'1..* não tem limite superior.', NULL, NULL),
        (1138, N'fase23', N'O que indica o losango cheio num diagrama de classes?', N'Composição: a parte depende do todo e não existe sem ele. O losango vazio é agregação, um vínculo mais fraco.', N'Cheio = composição.', NULL, NULL),
        (1139, N'fase23', N'O que é o padrão de projeto Strategy?', N'Uma família de algoritmos com a mesma interface, que podem ser trocados em tempo de execução trocando o objeto usado (ex.: modo comum e modo probabilista de uma calculadora). Princípio: programar para uma interface.', N'Não confunda com Adapter, que converte interfaces.', NULL, NULL),
        (1140, N'fase23', N'Pode criar um vetor de uma classe abstrata em Java?', N'Pode: Impressora imp[] = new Impressora[3] cria só o vetor. O que não pode é new Impressora(). Cada posição recebe um objeto concreto, e imp[i].imprimir() chama a versão de cada classe: polimorfismo.', N'Vetor do tipo abstrato compila.', NULL, NULL),
        (1141, N'fase23', N'Como funcionam a pilha e a fila?', N'Pilha é LIFO: push empilha, pop tira o topo, top só lê.' + NCHAR(10) + N'Fila é FIFO: enqueue entra no fim, dequeue sai do início.' + NCHAR(10) + N'No push de uma pilha encadeada: novo.prox = topo; topo = novo.', N'top() não remove nada.', NULL, NULL),
        (1142, N'fase23', N'Quais são os percursos de uma árvore binária?', N'Pré-ordem: raiz, esquerda, direita.' + NCHAR(10) + N'Em-ordem: esquerda, raiz, direita (numa árvore de busca, sai ordenado).' + NCHAR(10) + N'Pós-ordem: esquerda, direita, raiz.', N'O nome diz quando a raiz é visitada.', NULL, NULL),
        (1143, N'fase23', N'Como funciona a ordenação por inserção?', N'Pega cada elemento e o encaixa na parte já ordenada, empurrando os maiores uma casa para a direita (vetor[j + 1] <- vetor[j]) até achar a posição.', N'Como ordenar cartas na mão.', NULL, NULL),
        (1144, N'fase23', N'Quando usar GROUP BY numa consulta SQL?', N'Sempre que usar função de agregação (SUM, AVG, COUNT, MAX, MIN) junto de outras colunas: agrupe por essas colunas. SUM soma valores, COUNT conta linhas, AVG tira média. Para mostrar do maior para o menor: ORDER BY ... DESC.', N'Total de votos é SUM, não COUNT.', NULL, NULL),
        (1145, N'fase23', N'Como ler a cardinalidade (mínimo, máximo) no modelo entidade-relacionamento?', N'O par (mín, máx) junto de uma entidade diz quantas vezes ela participa. Ex.: pessoa (1,1) — possui — (0,1) cavalo: cada cavalo tem exatamente um dono, e cada pessoa tem no máximo um cavalo (pode não ter).', N'Mínimo 0 = participação opcional.', NULL, NULL),
        (1146, N'fase23', N'Como converter números de outras bases para decimal?', N'Multiplique cada dígito pela potência da base. (1001)₂ = 8 + 1 = 9; (15)₈ = 1×8 + 5 = 13; (FF)₁₆ = 15×16 + 15 = 255.', N'Em hexadecimal, A = 10 ... F = 15.', NULL, NULL),
        (1147, N'fase23', N'Para que serve a máscara de sub-rede?', N'Ela diz que parte do IP é a rede. Máquinas só se falam direto se estiverem na mesma rede: 175.16.10.200 com máscara 255.255.255.0 fica na rede 175.16.10.0 e não alcança 175.16.30.200 sem roteador. Com 255.255.0.0, as duas ficam na 175.16.0.0.', N'Mesma rede = comunicação direta.', NULL, NULL),
        (1148, N'fase23', N'O que é multiprogramação, e quem protege a memória dos processos?', N'Multiprogramação: a CPU alterna rapidamente entre processos, dando a impressão de paralelismo. A gerência de memória do sistema operacional dá a cada processo o seu espaço e impede que um escreva na área do outro.', N'Proteção de memória = gerência de memória.', NULL, NULL),
        (1149, N'fase23', N'Quais são os fundamentos da LGPD (art. 2º)?', N'Respeito à privacidade; autodeterminação informativa; liberdade de expressão, informação, comunicação e opinião; inviolabilidade da intimidade, da honra e da imagem; desenvolvimento econômico e tecnológico e inovação; livre iniciativa, livre concorrência e defesa do consumidor; direitos humanos, dignidade e cidadania.', N'Lei 13.709/2018.', NULL, NULL),
        (1150, N'fase23', N'Qual recurso do HTML atende a acessibilidade em imagens?', N'O atributo alt: os leitores de tela leem esse texto para pessoas com deficiência visual. Outras boas práticas (WCAG): bom contraste, navegação pelo teclado e não depender só da cor.', N'Acessibilidade = igualdade de acesso.', NULL, NULL),
        (1151, N'fase23', N'Quais são os 9 blocos do Business Model Canvas?', N'Segmentos de clientes, proposta de valor, canais, relacionamento com clientes, fontes de receita, recursos principais, atividades-chave, parcerias principais e estrutura de custo. Serve para modelar e validar a ideia de negócio.', N'Nenhum bloco pode ser ignorado.', NULL, NULL),
        (1152, N'fase23', N'Como funciona um sistema especialista com regras de produção?', N'Usa regras "se condição então conclusão" sobre os fatos da memória de trabalho. Uma regra como "se febre e dores, então dengue com 70% de chance" dá uma probabilidade para cada caso, não uma contagem exata de pessoas.', N'Probabilidade não é garantia.', NULL, NULL),
        (1153, N'fase24', N'(ENADE 2017 · Questão 10 · Matemática e Lógica) A álgebra booleana possui o operador unário ~ (NÃO) e os operadores binários * (E) e + (OU). A tabela verdade da fórmula G, para as proposições p, q e r, é:' + NCHAR(10) + N'' + NCHAR(10) + N'p q r | G' + NCHAR(10) + N'V V V | V' + NCHAR(10) + N'V V F | F' + NCHAR(10) + N'V F V | F' + NCHAR(10) + N'V F F | F' + NCHAR(10) + N'F V V | V' + NCHAR(10) + N'F V F | V' + NCHAR(10) + N'F F V | V' + NCHAR(10) + N'F F F | V' + NCHAR(10) + N'' + NCHAR(10) + N'Considerando a ordem de precedência dos operadores booleanos, a fórmula G possui a mesma tabela verdade da proposição', N'Alternativa C.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Quando p é falso, ~p já torna G verdadeira (as quatro últimas linhas). Quando p é verdadeiro, G só vale V se q e r forem verdadeiros, ou seja, q * r.' + NCHAR(10) + N'' + NCHAR(10) + N'Fonte: INEP, ENADE 2017, Tecnologia em Análise e Desenvolvimento de Sistemas, questão 10 (gabarito definitivo).', N'Questão oficial do ENADE 2017: Matemática e Lógica.', N'["A) p \u002B ~q * r.","B) p \u002B q * ~r.","C) ~p \u002B q * r.","D) ~p \u002B ~q * r.","E) ~p \u002B q * ~r."]', 2),
        (1154, N'fase24', N'(ENADE 2017 · Questão 11 · Banco de Dados) Num sistema para um clube recreativo, o diagrama de classes tem: Tipo_Associado (codigo, descricao, valorMensalidade) ligado a Associado com multiplicidade 1 para 0..*; e Associado (codigo, nome, endereco, telefone) ligado a Mensalidade (codigo, anomesreferencia, valormensalidade, datavencimento, valorpago, datapagamento) com multiplicidade 1 para 1..*.' + NCHAR(10) + N'' + NCHAR(10) + N'Avalie as afirmações:' + NCHAR(10) + N'I. Haverá somente 12 mensalidades para cada associado, ou seja, elas não poderão ultrapassar os 12 meses do ano.' + NCHAR(10) + N'II. Não existem associados sem mensalidades, nem mensalidades sem associado a elas relacionado.' + NCHAR(10) + N'III. Alterando-se o valor da mensalidade definido para cada tipo de associado, o sistema automaticamente altera os valores das mensalidades geradas anteriormente.' + NCHAR(10) + N'IV. Poderão existir tipos de associados que não terão nenhum associado relacionado a eles.' + NCHAR(10) + N'' + NCHAR(10) + N'É correto apenas o que se afirma em', N'Alternativa C.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: II: 1..* obriga cada associado a ter ao menos uma mensalidade, e cada mensalidade tem exatamente um associado. IV: 0..* permite tipo sem associados. I é falsa (1..* não tem limite) e III também (cada mensalidade guarda o próprio valor).' + NCHAR(10) + N'' + NCHAR(10) + N'Fonte: INEP, ENADE 2017, Tecnologia em Análise e Desenvolvimento de Sistemas, questão 11 (gabarito definitivo).', N'Questão oficial do ENADE 2017: Banco de Dados.', N'["A) I e II.","B) I e III.","C) II e IV.","D) I, III e IV.","E) II, III e IV."]', 2),
        (1155, N'fase24', N'(ENADE 2017 · Questão 12 · Engenharia de Software) Considere os requisitos de um sistema acadêmico de uma universidade:' + NCHAR(10) + N'R1: o sistema deve permitir que cada professor realize o lançamento de notas das turmas nas quais lecionou;' + NCHAR(10) + N'R2: o sistema deverá ser desenvolvido de forma a possibilitar seu transporte para outro sistema operacional em, no máximo, sessenta dias;' + NCHAR(10) + N'R3: o sistema deve permitir que um estudante realize a sua matrícula nas disciplinas oferecidas em um semestre letivo;' + NCHAR(10) + N'R4: o sistema atualiza a nota do estudante, permitindo sua visualização, em até dois segundos depois do momento que o professor a registra;' + NCHAR(10) + N'R5: o sistema deve permitir que o auxiliar de serviços acadêmicos realize o cadastro de um estudante em não mais do que dez minutos de orientação.' + NCHAR(10) + N'' + NCHAR(10) + N'Representam requisitos não funcionais apenas os requisitos', N'Alternativa D.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: R2 é portabilidade, R4 é desempenho e R5 é usabilidade (facilidade de aprendizado). R1 e R3 descrevem funções do sistema.' + NCHAR(10) + N'' + NCHAR(10) + N'Fonte: INEP, ENADE 2017, Tecnologia em Análise e Desenvolvimento de Sistemas, questão 12 (gabarito definitivo).', N'Questão oficial do ENADE 2017: Engenharia de Software.', N'["A) R1, R2 e R3.","B) R1, R2 e R5.","C) R1, R3 e R4.","D) R2, R4 e R5.","E) R3, R4 e R5."]', 3),
        (1156, N'fase24', N'(ENADE 2017 · Questão 13 · Engenharia de Software) Sobre o modelo CMMI, avalie as asserções e a relação proposta entre elas.' + NCHAR(10) + N'' + NCHAR(10) + N'I. O CMMI fornece diretrizes para a melhoria dos processos e habilidades organizacionais, incluindo o ciclo de vida de produtos e serviços, que abrange as fases de concepção, desenvolvimento, aquisição, entrega e manutenção.' + NCHAR(10) + N'' + NCHAR(10) + N'PORQUE' + NCHAR(10) + N'' + NCHAR(10) + N'II. As empresas brasileiras estão aderindo a programas de fomento à melhoria da qualidade de software, por meio da aplicação do modelo de maturidade CMMI, que é mais direcionado às pequenas e médias empresas, apesar de também ser aplicável em grandes organizações.', N'Alternativa C.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: I descreve o CMMI corretamente. II é falsa: o CMMI não é voltado principalmente a pequenas e médias empresas (no Brasil, quem tem esse foco é o MPS.BR).' + NCHAR(10) + N'' + NCHAR(10) + N'Fonte: INEP, ENADE 2017, Tecnologia em Análise e Desenvolvimento de Sistemas, questão 13 (gabarito definitivo).', N'Questão oficial do ENADE 2017: Engenharia de Software.', N'["A) As asser\u00E7\u00F5es I e II s\u00E3o verdadeiras, e a II \u00E9 uma justificativa correta da I.","B) As asser\u00E7\u00F5es I e II s\u00E3o verdadeiras, mas a II n\u00E3o \u00E9 uma justificativa correta da I.","C) A asser\u00E7\u00E3o I \u00E9 verdadeira, e a II \u00E9 falsa.","D) A asser\u00E7\u00E3o I \u00E9 falsa, e a II \u00E9 verdadeira.","E) As asser\u00E7\u00F5es I e II s\u00E3o falsas."]', 2),
        (1157, N'fase24', N'(ENADE 2017 · Questão 14 · Gestão de Projetos) A tabela apresenta as atividades de um projeto (predecessora; duração em dias):' + NCHAR(10) + N'A (--; 3), B (A; 5), C (--; 12), D (--; 4), E (D; 2), F (D; 5), G (F; 7), H (E e G; 8), I (B; 11), J (C, H e I; 3).' + NCHAR(10) + N'' + NCHAR(10) + N'Avalie as afirmações:' + NCHAR(10) + N'I. O caminho crítico é composto pelas atividades A, B, I e J.' + NCHAR(10) + N'II. O caminho crítico tem 27 dias.' + NCHAR(10) + N'III. A atividade H faz parte do caminho crítico.' + NCHAR(10) + N'IV. O projeto em pauta possui dois caminhos críticos.' + NCHAR(10) + N'' + NCHAR(10) + N'É correto apenas o que se afirma em', N'Alternativa C.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: D-F-G-H-J soma 4+5+7+8+3 = 27 dias, o maior caminho. A-B-I-J soma 22 e C-J soma 15, então só há um caminho crítico, e ele passa por H.' + NCHAR(10) + N'' + NCHAR(10) + N'Fonte: INEP, ENADE 2017, Tecnologia em Análise e Desenvolvimento de Sistemas, questão 14 (gabarito definitivo).', N'Questão oficial do ENADE 2017: Gestão de Projetos.', N'["A) I e II.","B) I e IV.","C) II e III.","D) I, III e IV.","E) II, III e IV."]', 2),
        (1158, N'fase24', N'(ENADE 2017 · Questão 16 · Programação Orientada a Objetos) Um diagrama de classes modela a transferência de materiais entre funcionários. RequisicaoTransferencia (dataRequisicao: date) tem duas associações navegáveis para Funcionario (nome: string), com os papéis "origem" e "destino" e multiplicidade 1. RequisicaoTransferencia também tem uma composição (losango cheio do seu lado) com Material (descricao: string, preco: double), navegável para Material, com papel "material" e multiplicidade 0..1 do lado da requisição e 1..* do lado de Material.' + NCHAR(10) + N'' + NCHAR(10) + N'Avalie as afirmações:' + NCHAR(10) + N'I. A classe Funcionario é abstrata.' + NCHAR(10) + N'II. Uma RequisicaoTransferencia só existe se estiver vinculada a um Material.' + NCHAR(10) + N'III. A classe Funcionario, em razão de sua associação, possui um atributo do tipo RequisicaoTransferencia.' + NCHAR(10) + N'IV. Em uma implementação da classe RequisicaoTransferencia, é necessário adicionar um atributo simples do tipo Material.' + NCHAR(10) + N'' + NCHAR(10) + N'É correto o que se afirma em', N'Alternativa A.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: A multiplicidade 1..* obriga a requisição a ter ao menos um material. Funcionario não é abstrata, a navegação vai da requisição para o funcionário (não o contrário) e 1..* pede uma coleção de materiais, não um atributo simples.' + NCHAR(10) + N'' + NCHAR(10) + N'Fonte: INEP, ENADE 2017, Tecnologia em Análise e Desenvolvimento de Sistemas, questão 16 (gabarito definitivo).', N'Questão oficial do ENADE 2017: Programação Orientada a Objetos.', N'["A) II, apenas.","B) I e II, apenas.","C) III e IV, apenas.","D) I, III e IV, apenas.","E) I, II, III e IV."]', 0),
        (1159, N'fase24', N'(ENADE 2017 · Questão 17 · Engenharia de Software) Considerando a etapa de manutenção no processo de desenvolvimento de software, avalie as afirmações:' + NCHAR(10) + N'I. A fase de manutenção é uma parte explícita do modelo em cascata do processo de desenvolvimento de software.' + NCHAR(10) + N'II. A atualização do sistema para inserir customizações é considerada um tipo de manutenção.' + NCHAR(10) + N'III. A depuração do programa é um processo específico da fase de desenvolvimento e um tipo de manutenção.' + NCHAR(10) + N'IV. O acréscimo de novas funções a um sistema existente, sem perturbar sua operação, é considerado um tipo de manutenção.' + NCHAR(10) + N'V. A manutenção do sistema está relacionada ao aumento do ciclo de vida do software.' + NCHAR(10) + N'' + NCHAR(10) + N'É correto apenas o que se afirma em', N'Alternativa D.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: A cascata termina em operação e manutenção, e customizar ou acrescentar funções são manutenções que prolongam a vida do software. A depuração faz parte do desenvolvimento, não é um tipo de manutenção.' + NCHAR(10) + N'' + NCHAR(10) + N'Fonte: INEP, ENADE 2017, Tecnologia em Análise e Desenvolvimento de Sistemas, questão 17 (gabarito definitivo).', N'Questão oficial do ENADE 2017: Engenharia de Software.', N'["A) I e III.","B) IV e V.","C) I, II e III.","D) I, II, IV e V.","E) II, III, IV e V."]', 3),
        (1160, N'fase24', N'(ENADE 2017 · Questão 18 · Redes e Sistemas Distribuídos) As redes de computadores estão por toda parte e compartilham recursos por meio de sistemas distribuídos, que comunicam e coordenam vários dispositivos.' + NCHAR(10) + N'' + NCHAR(10) + N'Assinale a opção que apresenta exemplos atuais de sistemas distribuídos.', N'Alternativa A.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Todos os itens da alternativa A rodam em várias máquinas que se comunicam pela rede. Pesquisa no Windows e jogos em mídia física rodam numa máquina só.' + NCHAR(10) + N'' + NCHAR(10) + N'Fonte: INEP, ENADE 2017, Tecnologia em Análise e Desenvolvimento de Sistemas, questão 18 (gabarito definitivo).', N'Questão oficial do ENADE 2017: Redes e Sistemas Distribuídos.', N'["A) Pesquisa na web, jogos on-line, e-commerce e o banco de dados das ag\u00EAncias banc\u00E1rias.","B) Jogos on-line, e-commerce, pesquisa no Windows e e-mails.","C) E-commerce, jogos em m\u00EDdia f\u00EDsica, pesquisa no Windows e redes sociais.","D) Pesquisa na web, jogos em m\u00EDdia f\u00EDsica, e-commerce e e-mails.","E) Pesquisa no Windows, pesquisa na web, jogos on-line e o banco de dados das ag\u00EAncias banc\u00E1rias."]', 0),
        (1161, N'fase24', N'(ENADE 2017 · Questão 19 · Sistemas Operacionais) Conceitualmente, cada processo tem sua própria CPU virtual. Na realidade, a CPU troca a execução, a todo momento, de um processo para outro, mas é muito mais fácil pensar em um conjunto de processos sendo executados (pseudo) paralelamente do que tentar controlar o modo como a CPU faz esses chaveamentos. (Tanenbaum, adaptado)' + NCHAR(10) + N'' + NCHAR(10) + N'De acordo com o exposto, o conceito descrito denomina-se', N'Alternativa C.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Multiprogramação é a CPU alternando rapidamente entre vários processos, o que dá a impressão de execução paralela mesmo com um só processador.' + NCHAR(10) + N'' + NCHAR(10) + N'Fonte: INEP, ENADE 2017, Tecnologia em Análise e Desenvolvimento de Sistemas, questão 19 (gabarito definitivo).', N'Questão oficial do ENADE 2017: Sistemas Operacionais.', N'["A) thread.","B) multiprocessador.","C) multiprograma\u00E7\u00E3o.","D) processo monothread.","E) m\u00E1quina de estados finitos."]', 2),
        (1162, N'fase24', N'(ENADE 2017 · Questão 21 · Engenharia de Software) A respeito dos modelos de processo de software, avalie as afirmações:' + NCHAR(10) + N'I. São atividades do modelo incremental: especificação, desenvolvimento e validação.' + NCHAR(10) + N'II. No modelo espiral, a fase de modelagem é responsável, entre outras atividades, pela estimativa, cronograma e análise de risco.' + NCHAR(10) + N'III. O modelo cascata sugere uma abordagem sequencial e sistemática para o desenvolvimento de software, iniciando na especificação de requisitos e finalizando com a entrega do software concluído.' + NCHAR(10) + N'' + NCHAR(10) + N'É correto o que se afirma em', N'Alternativa D.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: No espiral, estimativa, cronograma e análise de risco ficam na fase de planejamento, não na de modelagem. I e III descrevem corretamente o incremental e o cascata.' + NCHAR(10) + N'' + NCHAR(10) + N'Fonte: INEP, ENADE 2017, Tecnologia em Análise e Desenvolvimento de Sistemas, questão 21 (gabarito definitivo).', N'Questão oficial do ENADE 2017: Engenharia de Software.', N'["A) II, apenas.","B) III, apenas.","C) I e II, apenas.","D) I e III, apenas.","E) I, II e III."]', 3),
        (1163, N'fase24', N'(ENADE 2017 · Questão 22 · Engenharia de Software) Um desenvolvedor recém-formado recebeu explicações sobre como a gerência de configuração funcionava. Avalie as afirmações:' + NCHAR(10) + N'I. Inicialmente, para ter acesso à base de desenvolvimento, o profissional deve realizar uma operação de checkout para baixar os arquivos do projeto que estão armazenados no servidor.' + NCHAR(10) + N'II. Quando mais de um desenvolvedor estiver modificando um mesmo documento, ao se tentar realizar um commit, pode ser necessário realizar uma operação de tag (release) para resolução do conflito entre a versão local e a versão mais recente no repositório.' + NCHAR(10) + N'III. No desenvolvimento de um novo caso de uso, em que diversos arquivos sejam modificados, é recomendada a criação de uma ramificação (branch).' + NCHAR(10) + N'IV. A versão estável é o ramo principal de desenvolvimento, que segue do começo do desenvolvimento até o momento presente.' + NCHAR(10) + N'' + NCHAR(10) + N'É correto apenas o que se afirma em', N'Alternativa B.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Conflito se resolve com merge, não com tag (tag só marca uma versão). O ramo principal de desenvolvimento é o trunk/main, que não é necessariamente a versão estável.' + NCHAR(10) + N'' + NCHAR(10) + N'Fonte: INEP, ENADE 2017, Tecnologia em Análise e Desenvolvimento de Sistemas, questão 22 (gabarito definitivo).', N'Questão oficial do ENADE 2017: Engenharia de Software.', N'["A) I e II.","B) I e III.","C) II e IV.","D) I, III e IV.","E) II, III e IV."]', 1),
        (1164, N'fase24', N'(ENADE 2017 · Questão 23 · Engenharia de Software) Verificações, validações e testes são fundamentais para certificar a qualidade do software. Avalie as afirmações:' + NCHAR(10) + N'I. O teste funcional certifica se o software desempenha as funções especificadas nos requisitos.' + NCHAR(10) + N'II. O teste de desempenho valida a conformidade da especificação do processo de desenvolvimento de software.' + NCHAR(10) + N'III. O teste de aceitação é realizado pelo cliente a fim de validar se aquilo que foi implementado é o que foi solicitado.' + NCHAR(10) + N'IV. O teste de instalação, invariavelmente, é executado no local determinado pelo cliente para instalação do software.' + NCHAR(10) + N'V. As técnicas de verificação e validação de software asseguram que o sistema que está sendo desenvolvido seja adequado ao seu propósito.' + NCHAR(10) + N'' + NCHAR(10) + N'É correto apenas o que se afirma em', N'Alternativa B.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: O teste de desempenho mede tempo de resposta e carga, não a conformidade do processo. E o teste de instalação nem sempre é feito no local do cliente.' + NCHAR(10) + N'' + NCHAR(10) + N'Fonte: INEP, ENADE 2017, Tecnologia em Análise e Desenvolvimento de Sistemas, questão 23 (gabarito definitivo).', N'Questão oficial do ENADE 2017: Engenharia de Software.', N'["A) I e IV.","B) I, III e V.","C) II, III e IV.","D) II, IV e V.","E) I, II, III e V."]', 1),
        (1165, N'fase24', N'(ENADE 2017 · Questão 24 · Engenharia de Software) Muitos sistemas corporativos das décadas de 1970 e 1980 foram feitos em Cobol, com ADABAS e arquivos ISAM e VSAM, produtos que estão sendo descontinuados. A reengenharia desses sistemas com linguagens e bancos mais modernos é uma oportunidade de negócio. Avalie as afirmações:' + NCHAR(10) + N'I. A dificuldade de reengenharia de sistemas antigos deve-se ao fato de que, na maioria das vezes, o desenvolvedor definia o sistema e esse já era o próprio processo da organização.' + NCHAR(10) + N'II. O custo de alteração para modernização de uma linha de código em Cobol é alto; por isso, fazer a manutenção desses sistemas é menos dispendioso.' + NCHAR(10) + N'III. Uma estratégia de conversão dos referidos sistemas para uma linguagem orientada a objetos é definir uma estrutura de classes e métodos e realizar o refatoramento do código.' + NCHAR(10) + N'' + NCHAR(10) + N'É correto o que se afirma em', N'Alternativa E.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: As três descrevem a realidade dos sistemas legados: a regra de negócio ficou presa no código, reescrever é caro e a migração para OO passa por definir classes e refatorar.' + NCHAR(10) + N'' + NCHAR(10) + N'Fonte: INEP, ENADE 2017, Tecnologia em Análise e Desenvolvimento de Sistemas, questão 24 (gabarito definitivo).', N'Questão oficial do ENADE 2017: Engenharia de Software.', N'["A) I, apenas.","B) III, apenas.","C) I e II, apenas.","D) II e III, apenas.","E) I, II e III."]', 4),
        (1166, N'fase24', N'(ENADE 2017 · Questão 25 · Algoritmos e Estruturas de Dados) O fragmento C++ a seguir insere um nó em uma árvore binária.' + NCHAR(10) + N'' + NCHAR(10) + N'struct noArvore {' + NCHAR(10) + N'    int dado;' + NCHAR(10) + N'    noArvore *esquerda;' + NCHAR(10) + N'    noArvore *direita;' + NCHAR(10) + N'};' + NCHAR(10) + N'' + NCHAR(10) + N'noArvore *insere(noArvore *arvore, int valor) {' + NCHAR(10) + N'    if (arvore == NULL) {' + NCHAR(10) + N'        arvore = new noArvore;' + NCHAR(10) + N'        arvore->esquerda = NULL;' + NCHAR(10) + N'        arvore->direita = NULL;' + NCHAR(10) + N'        arvore->dado = valor;' + NCHAR(10) + N'    } else if (valor < arvore->dado) {' + NCHAR(10) + N'        arvore->esquerda = insere(arvore->esquerda, valor);' + NCHAR(10) + N'    } else {' + NCHAR(10) + N'        arvore->direita = insere(arvore->direita, valor);' + NCHAR(10) + N'    }' + NCHAR(10) + N'    return arvore;' + NCHAR(10) + N'}' + NCHAR(10) + N'' + NCHAR(10) + N'Assinale a opção que imprime os valores dos nós percorrendo a árvore em pré-ordem.', N'Alternativa A.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Pré-ordem visita primeiro a raiz, depois a subárvore esquerda e por fim a direita. A opção C é em-ordem e a D é pós-ordem.' + NCHAR(10) + N'' + NCHAR(10) + N'Fonte: INEP, ENADE 2017, Tecnologia em Análise e Desenvolvimento de Sistemas, questão 25 (gabarito definitivo).', N'Questão oficial do ENADE 2017: Algoritmos e Estruturas de Dados.', N'["A) if (raiz != NULL) {\n    cout \u003C\u003C raiz-\u003Edado \u003C\u003C \u0022 \u0022;\n    preorder(raiz-\u003Eesquerda);\n    preorder(raiz-\u003Edireita);\n}","B) if (raiz != NULL) {\n    preorder(raiz-\u003Edireita);\n    preorder(raiz-\u003Eesquerda);\n    cout \u003C\u003C raiz-\u003Edado \u003C\u003C \u0022 \u0022;\n}","C) if (raiz != NULL) {\n    preorder(raiz-\u003Eesquerda);\n    cout \u003C\u003C raiz-\u003Edado \u003C\u003C \u0022 \u0022;\n    preorder(raiz-\u003Edireita);\n}","D) if (raiz != NULL) {\n    preorder(raiz-\u003Eesquerda);\n    preorder(raiz-\u003Edireita);\n    cout \u003C\u003C raiz-\u003Edado \u003C\u003C \u0022 \u0022;\n}","E) if (raiz != NULL) {\n    preorder(raiz-\u003Edireita);\n    cout \u003C\u003C raiz-\u003Edado \u003C\u003C \u0022 \u0022;\n    preorder(raiz-\u003Eesquerda);\n}"]', 0),
        (1167, N'fase24', N'(ENADE 2017 · Questão 26 · Programação Orientada a Objetos) Uma calculadora feita com MVC tem dois modos: comum e probabilista. A classe Calculadora guarda uma variável c do tipo CalculadoraController; o método multiplica(valores) apenas retorna c.multiplica(valores), e alteraModo() faz c = new ProbabilistaController() se modo == 1, senão c = new OrdinarioController(). ProbabilistaController e OrdinarioController herdam de CalculadoraController e implementam multiplica(valores: double[]): double, formando uma família de algoritmos intercambiáveis.' + NCHAR(10) + N'' + NCHAR(10) + N'Avalie as afirmações:' + NCHAR(10) + N'I. A hierarquia exibida ilustra o uso do padrão de projetos Strategy.' + NCHAR(10) + N'II. O padrão composto MVC define a existência de um único controller e, portanto, a solução proposta não caracteriza o uso desse padrão.' + NCHAR(10) + N'III. O método multiplica da classe Calculadora chama o método multiplica de CalculadoraController, o que caracteriza uma conversão de interfaces e, portanto, o uso do padrão de projetos Adapter.' + NCHAR(10) + N'' + NCHAR(10) + N'É correto o que se afirma em', N'Alternativa A.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Trocar o algoritmo trocando o objeto referenciado é o Strategy. O MVC não exige um controller único, e repassar a chamada com a mesma assinatura é delegação, não Adapter.' + NCHAR(10) + N'' + NCHAR(10) + N'Fonte: INEP, ENADE 2017, Tecnologia em Análise e Desenvolvimento de Sistemas, questão 26 (gabarito definitivo).', N'Questão oficial do ENADE 2017: Programação Orientada a Objetos.', N'["A) I, apenas.","B) II, apenas.","C) I e III, apenas.","D) II e III, apenas.","E) I, II e III."]', 0),
        (1168, N'fase24', N'(ENADE 2017 · Questão 28 · Engenharia de Software) O processo de descobrir, analisar, documentar e verificar os serviços e restrições de um sistema é denominado engenharia de requisitos (Sommerville). Avalie as atribuições listadas, no que se refere à etapa de especificação de requisitos:' + NCHAR(10) + N'I. Identificar as expectativas e necessidades dos stakeholders com relação ao software a ser desenvolvido.' + NCHAR(10) + N'II. Distribuir os requisitos em categorias, explorar as relações entre eles e classificar sua importância para os stakeholders.' + NCHAR(10) + N'III. Produzir um documento de especificação de requisitos, de forma que todos os stakeholders possam entendê-lo.' + NCHAR(10) + N'IV. Examinar a especificação do software para assegurar que todos os requisitos foram definidos sem inconsistências.' + NCHAR(10) + N'' + NCHAR(10) + N'São atribuições na etapa de especificação de requisitos os itens', N'Alternativa E.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Segundo o gabarito oficial, as quatro atribuições fazem parte da especificação: entender os stakeholders, organizar e priorizar, documentar e checar a consistência.' + NCHAR(10) + N'' + NCHAR(10) + N'Fonte: INEP, ENADE 2017, Tecnologia em Análise e Desenvolvimento de Sistemas, questão 28 (gabarito definitivo).', N'Questão oficial do ENADE 2017: Engenharia de Software.', N'["A) I e III, apenas.","B) I e IV, apenas.","C) II e III, apenas.","D) II e IV, apenas.","E) I, II, III e IV."]', 4),
        (1169, N'fase24', N'(ENADE 2017 · Questão 29 · Matemática e Lógica) Uma pesquisa usa os conjuntos A ("possui ensino superior"), B ("possui pós-graduação") e C ("possui pelo menos 5 anos de experiência"). As expressões são:' + NCHAR(10) + N'Expressão 1: x ∈ A ∧ x ∉ (B ∪ C)' + NCHAR(10) + N'Expressão 2: x ∈ A − (B ∪ C)' + NCHAR(10) + N'Expressão 3: x ∈ A ∧ x ∈ B ∧ x ∈ C' + NCHAR(10) + N'' + NCHAR(10) + N'Um programa em C usa a função contem(conjunto, p):' + NCHAR(10) + N'/* condição 1 */' + NCHAR(10) + N'if (contem(A, p) && !contem(B, p) && !contem(C, p)) { ... }' + NCHAR(10) + N'/* condição 2 */' + NCHAR(10) + N'else if (contem(A, p) || contem(B, p) || contem(C, p)) { ... }' + NCHAR(10) + N'' + NCHAR(10) + N'Assinale a opção correta.', N'Alternativa D.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: As três descrevem "está em A e não está em B nem em C". A condição 2 usa OU (é uma união), por isso não equivale à expressão 3, que usa E.' + NCHAR(10) + N'' + NCHAR(10) + N'Fonte: INEP, ENADE 2017, Tecnologia em Análise e Desenvolvimento de Sistemas, questão 29 (gabarito definitivo).', N'Questão oficial do ENADE 2017: Matemática e Lógica.', N'["A) A condi\u00E7\u00E3o 2 do programa \u00E9 equivalente \u00E0 express\u00E3o 3.","B) Pessoas com p\u00F3s-gradua\u00E7\u00E3o pertencem ao conjunto definido pela express\u00E3o 2.","C) A condi\u00E7\u00E3o 1 do programa \u00E9 verdadeira para todas as pessoas com ensino superior.","D) A condi\u00E7\u00E3o 1 do programa e as express\u00F5es 1 e 2, que representam o mesmo subconjunto, s\u00E3o equivalentes.","E) A condi\u00E7\u00E3o 2 do programa define o conjunto de pessoas que tem ensino superior, p\u00F3s-gradua\u00E7\u00E3o e pelo menos cinco anos de experi\u00EAncia em sua \u00E1rea de atua\u00E7\u00E3o."]', 3),
        (1170, N'fase24', N'(ENADE 2017 · Questão 30 · Programação Orientada a Objetos) Considere o código Java:' + NCHAR(10) + N'' + NCHAR(10) + N'public abstract class Impressora {' + NCHAR(10) + N'    String nome;' + NCHAR(10) + N'    public void imprimir() {}' + NCHAR(10) + N'}' + NCHAR(10) + N'public class Laser extends Impressora {' + NCHAR(10) + N'    public void imprimir() { System.out.println("Imprimindo na Laser"); }' + NCHAR(10) + N'}' + NCHAR(10) + N'class Matricial extends Impressora {' + NCHAR(10) + N'    public void imprimir() { System.out.println("Imprimindo na Matricial"); }' + NCHAR(10) + N'}' + NCHAR(10) + N'public class JatoDeTinta extends Impressora {' + NCHAR(10) + N'    public void imprimir() { System.out.println("Imprimindo na Jato de tinta"); }' + NCHAR(10) + N'}' + NCHAR(10) + N'public class Main {' + NCHAR(10) + N'    public static void main(String args[]) {' + NCHAR(10) + N'        Impressora imp[] = new Impressora[3];' + NCHAR(10) + N'        imp[0] = new Laser();' + NCHAR(10) + N'        imp[1] = new JatoDeTinta();' + NCHAR(10) + N'        imp[2] = new Matricial();' + NCHAR(10) + N'        for (int i = imp.length - 1; i >= 0; i--) {' + NCHAR(10) + N'            imp[i].imprimir();' + NCHAR(10) + N'        }' + NCHAR(10) + N'    }' + NCHAR(10) + N'}' + NCHAR(10) + N'' + NCHAR(10) + N'Avalie as afirmações:' + NCHAR(10) + N'I. A execução resulta em: Imprimindo na Laser / Imprimindo na Matricial / Imprimindo na Jato de tinta.' + NCHAR(10) + N'II. O código faz uso da técnica denominada polimorfismo.' + NCHAR(10) + N'III. O código não será compilado, pois o vetor imp foi instanciado por meio da classe abstrata Impressora.' + NCHAR(10) + N'' + NCHAR(10) + N'É correto o que se afirma em', N'Alternativa A.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: O laço vai do fim para o começo: imprime Matricial, Jato de tinta e Laser. Criar um vetor do tipo abstrato é permitido (só não dá para instanciar a classe). Cada objeto executa o seu imprimir(): polimorfismo.' + NCHAR(10) + N'' + NCHAR(10) + N'Fonte: INEP, ENADE 2017, Tecnologia em Análise e Desenvolvimento de Sistemas, questão 30 (gabarito definitivo).', N'Questão oficial do ENADE 2017: Programação Orientada a Objetos.', N'["A) II, apenas.","B) III, apenas.","C) I e II, apenas.","D) I e III, apenas.","E) I, II e III."]', 0),
        (1171, N'fase24', N'(ENADE 2017 · Questão 31 · UX/UI e Requisitos) À medida que o projeto de uma interface evolui, quatro questões quase sempre aparecem: tempo de resposta, recursos de ajuda, tratamento de erros e nomes de comandos (Pressman). Avalie as afirmações:' + NCHAR(10) + N'I. A análise de interfaces tem por objetivo identificar o perfil dos usuários e auxiliar na especificação do requisito não funcional de segurança pertinente ao perfil de acesso dos usuários.' + NCHAR(10) + N'II. O requisito não funcional de segurança descreve as características relacionadas a inteligibilidade, modo de usar ou operar o sistema.' + NCHAR(10) + N'III. O requisito não funcional de confiabilidade descreve as características relacionadas ao tempo de resposta para processamento de dados ou informações.' + NCHAR(10) + N'IV. O requisito não funcional de usabilidade descreve diretrizes de acessibilidade para pessoas com deficiência.' + NCHAR(10) + N'' + NCHAR(10) + N'É correto apenas o que se afirma em', N'Alternativa B.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: II descreve usabilidade, não segurança. III descreve desempenho (eficiência), não confiabilidade.' + NCHAR(10) + N'' + NCHAR(10) + N'Fonte: INEP, ENADE 2017, Tecnologia em Análise e Desenvolvimento de Sistemas, questão 31 (gabarito definitivo).', N'Questão oficial do ENADE 2017: UX/UI e Requisitos.', N'["A) I e III.","B) I e IV.","C) II e IV.","D) I, II e III.","E) II, III e IV."]', 1),
        (1172, N'fase24', N'(ENADE 2017 · Questão 32 · Banco de Dados) Um banco guarda o resultado de uma eleição nas tabelas Partido (numero, nome, sigla), Candidato (numero, nome), em que o número do candidato é o número do seu partido, e Votacao (partido, votos, estado), com os votos de cada partido em cada estado.' + NCHAR(10) + N'' + NCHAR(10) + N'Qual comando SQL seleciona os nomes dos candidatos, seus partidos e o total de votos de cada partido?', N'Alternativa C.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Total de votos é SUM (COUNT só contaria as linhas), e uma função de agregação junto de outras colunas exige GROUP BY por essas colunas.' + NCHAR(10) + N'' + NCHAR(10) + N'Fonte: INEP, ENADE 2017, Tecnologia em Análise e Desenvolvimento de Sistemas, questão 32 (gabarito definitivo).', N'Questão oficial do ENADE 2017: Banco de Dados.', N'["A) SELECT c.nome, p.nome, SUM(v.votos) FROM Partido p, Candidato c, Votacao v WHERE c.numero = p.numero and v.partido = c.numero;","B) SELECT c.nome, p.nome, COUNT(v.votos) FROM Partido p, Candidato c, Votacao v WHERE c.numero = p.numero and v.partido = c.numero GROUP BY c.nome, p.nome;","C) SELECT c.nome, p.nome, SUM(v.votos) FROM Partido p, Candidato c, Votacao v WHERE c.numero = p.numero and v.partido = c.numero GROUP BY c.nome, p.nome;","D) SELECT c.nome, p.nome, v.votos FROM Partido p, Candidato c, Votacao v WHERE c.numero = p.numero and v.partido = c.numero GROUP BY c.nome, p.nome, SUM(v.votos);","E) SELECT c.nome, p.nome, COUNT(v.votos) FROM Partido p, Candidato c, Votacao v WHERE c.numero = p.numero and v.partido = c.numero GROUP BY c.nome, p.nome, v.votos;"]', 2),
        (1173, N'fase24', N'(ENADE 2017 · Questão 33 · Algoritmos e Estruturas de Dados) Um programador implementou a ordenação por inserção para vetor[1..9], mas o algoritmo não funciona:' + NCHAR(10) + N'' + NCHAR(10) + N'01 para i <- 2 até 9 faça' + NCHAR(10) + N'02    valor <- vetor[i]' + NCHAR(10) + N'03    j <- i - 1' + NCHAR(10) + N'04    enquanto ((j >= 1) e (valor < vetor[j])) faça' + NCHAR(10) + N'05       vetor[i] <- vetor[j]' + NCHAR(10) + N'06       j <- j - 1' + NCHAR(10) + N'07       se (j = 0) então' + NCHAR(10) + N'08          interrompa' + NCHAR(10) + N'09       fim se' + NCHAR(10) + N'10    fim enquanto' + NCHAR(10) + N'11    vetor[j + 1] <- valor' + NCHAR(10) + N'12 fim para' + NCHAR(10) + N'' + NCHAR(10) + N'Qual linha e comando devem ser substituídos para que o algoritmo ordene o vetor de forma crescente?', N'Alternativa D.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Na inserção, cada elemento maior é empurrado uma posição para a direita: vetor[j + 1] <- vetor[j]. Escrever sempre em vetor[i] perde os valores.' + NCHAR(10) + N'' + NCHAR(10) + N'Fonte: INEP, ENADE 2017, Tecnologia em Análise e Desenvolvimento de Sistemas, questão 33 (gabarito definitivo).', N'Questão oficial do ENADE 2017: Algoritmos e Estruturas de Dados.', N'["A) Linha 01; para i \u003C- 1 at\u00E9 9 fa\u00E7a","B) Linha 03; j \u003C- i","C) Linha 04; enquanto ((j \u003E= 1) ou (valor \u003C vetor[j])) fa\u00E7a","D) Linha 05; vetor[j \u002B 1] \u003C- vetor[j]","E) Linha 11; vetor[j] \u003C- valor"]', 3),
        (1174, N'fase24', N'(ENADE 2017 · Questão 34 · Banco de Dados) Inspirado no diálogo entre Chicó e João Grilo (Auto da Compadecida), um modelo de dados tem a entidade pessoa (codigo, que é o identificador; rg; cpf; nome) ligada pelo relacionamento possui à entidade cavalo (codigo, que é o identificador; raca; eBento?). A cardinalidade (1,1) aparece junto de pessoa e (0,1) junto de cavalo.' + NCHAR(10) + N'' + NCHAR(10) + N'Avalie as afirmações:' + NCHAR(10) + N'I. O Chicó e a velha poderão ser cadastrados na entidade pessoa.' + NCHAR(10) + N'II. O Chicó e a velha poderão ter mais que um cavalo cadastrados.' + NCHAR(10) + N'III. O atributo rg da entidade pessoa pode ter a função de chave primária nessa entidade.' + NCHAR(10) + N'IV. O cavalo deverá ter no mínimo uma pessoa e uma pessoa poderá ser cadastrada sem a necessidade de ter um cavalo.' + NCHAR(10) + N'' + NCHAR(10) + N'É correto apenas o que se afirma em', N'Alternativa B.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: (1,1) do lado de pessoa: todo cavalo tem exatamente um dono. (0,1) do lado de cavalo: a pessoa tem no máximo um cavalo, e pode não ter nenhum. O identificador escolhido é codigo, não rg.' + NCHAR(10) + N'' + NCHAR(10) + N'Fonte: INEP, ENADE 2017, Tecnologia em Análise e Desenvolvimento de Sistemas, questão 34 (gabarito definitivo).', N'Questão oficial do ENADE 2017: Banco de Dados.', N'["A) I e III.","B) I e IV.","C) II e III.","D) I, II e IV.","E) II, III e IV."]', 1),
        (1175, N'fase24', N'(ENADE 2017 · Questão 35 · UX/UI e Requisitos) Num site de venda de ingressos, os links para cada show são imagens. O web designer implementou cada link assim, para que usuários de leitores de tela recebam um texto informativo:' + NCHAR(10) + N'' + NCHAR(10) + N'<a href="link-area-venda-ingresso">' + NCHAR(10) + N'    <img src="imagem-show.jpg" alt="identificação do show" />' + NCHAR(10) + N'</a>' + NCHAR(10) + N'' + NCHAR(10) + N'Considerando o uso do atributo alt e a interação humano-computador, o web designer atendeu o requisito de', N'Alternativa C.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: O alt é lido pelos leitores de tela: é o recurso básico de acessibilidade para pessoas com deficiência visual.' + NCHAR(10) + N'' + NCHAR(10) + N'Fonte: INEP, ENADE 2017, Tecnologia em Análise e Desenvolvimento de Sistemas, questão 35 (gabarito definitivo).', N'Questão oficial do ENADE 2017: UX/UI e Requisitos.', N'["A) seguran\u00E7a no uso, pois se uma imagem tiver baixa resolu\u00E7\u00E3o, o texto associado possibilita identificar o conte\u00FAdo do link.","B) facilidade de aprendizado, pois imagens aliadas a textos informativos ajudam o usu\u00E1rio a aprender os caminhos de navega\u00E7\u00E3o.","C) acessibilidade, pois a possibilidade de acesso \u00E0 p\u00E1gina por pessoas com defici\u00EAncia visual oferece condi\u00E7\u00F5es de igualdade na intera\u00E7\u00E3o com o sistema web.","D) ergonomia, pois imagens em links causam cansa\u00E7o visual em smartphones e o atributo alt substitui a imagem por texto.","E) comunicabilidade, pois se uma imagem n\u00E3o comunica adequadamente a informa\u00E7\u00E3o, o texto alternativo deve complement\u00E1-la."]', 2),
        (1176, N'fase25', N'(ENADE 2021 · Questão 9 · Engenharia de Software) A etapa de definição de requisitos estabelece quais funções são requeridas pelo sistema e as restrições sobre a operação e o desenvolvimento do software. Os requisitos podem ser funcionais ou não funcionais (Sommerville).' + NCHAR(10) + N'' + NCHAR(10) + N'Assinale a alternativa em que o item é um requisito funcional.', N'Alternativa C.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Emitir relatórios é uma função do sistema. As demais são restrições: plataforma, prazo, desempenho e segurança.' + NCHAR(10) + N'' + NCHAR(10) + N'Fonte: INEP, ENADE 2021, Tecnologia em Análise e Desenvolvimento de Sistemas, questão 9 (gabarito definitivo).', N'Questão oficial do ENADE 2021: Engenharia de Software.', N'["A) O software deve ser operacionalizado no sistema Linux.","B) O tempo de desenvolvimento n\u00E3o deve ultrapassar seis meses.","C) O software deve emitir relat\u00F3rios de compras a cada quinze dias.","D) O tempo de resposta do sistema n\u00E3o deve ultrapassar 30 segundos.","E) A base de dados deve ser protegida para acesso apenas de usu\u00E1rios autorizados."]', 2),
        (1177, N'fase25', N'(ENADE 2021 · Questão 11 · Algoritmos e Estruturas de Dados) O código Java a seguir implementa uma Pilha encadeada.' + NCHAR(10) + N'' + NCHAR(10) + N'public class No {' + NCHAR(10) + N'    public int dado;' + NCHAR(10) + N'    public No prox;' + NCHAR(10) + N'    public No(int dado) { this.dado = dado; }' + NCHAR(10) + N'}' + NCHAR(10) + N'public class PilhaEncadeada {' + NCHAR(10) + N'    private No topo;' + NCHAR(10) + N'    public int pop() {' + NCHAR(10) + N'        if (topo == null) return -1;' + NCHAR(10) + N'        No lixo = topo;' + NCHAR(10) + N'        topo = topo.prox;' + NCHAR(10) + N'        lixo.prox = null;' + NCHAR(10) + N'        return lixo.dado;' + NCHAR(10) + N'    }' + NCHAR(10) + N'    public int top() {' + NCHAR(10) + N'        if (topo == null) return -1;' + NCHAR(10) + N'        return topo.dado;' + NCHAR(10) + N'    }' + NCHAR(10) + N'}' + NCHAR(10) + N'' + NCHAR(10) + N'Assinale a opção com a implementação correta do método push.', N'Alternativa E.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: O novo nó aponta para o topo atual e passa a ser o topo. Assim o pop(), que lê topo.prox, encontra o elemento de baixo.' + NCHAR(10) + N'' + NCHAR(10) + N'Fonte: INEP, ENADE 2021, Tecnologia em Análise e Desenvolvimento de Sistemas, questão 11 (gabarito definitivo).', N'Questão oficial do ENADE 2021: Algoritmos e Estruturas de Dados.', N'["A) No novo = new No(elemento);\nif (topo == null) topo = novo;\nelse topo.prox = novo;","B) No novo = new No(elemento);\ntopo = novo;","C) topo.dado = elemento;","D) No novo = new No(elemento);\nwhile (topo != null) topo = topo.prox;\ntopo.prox = novo;","E) No novo = new No(elemento);\nnovo.prox = topo;\ntopo = novo;"]', 4),
        (1178, N'fase25', N'(ENADE 2021 · Questão 12 · Engenharia de Software) Uma fábrica de software usa Scrum, eXtreme Programming (XP) e quadro Kanban. Avalie as afirmações:' + NCHAR(10) + N'I. Métodos ágeis são baseados em ciclos iterativos e incrementais que se concentram no desenvolvimento rápido e na flexibilidade às mudanças, com a participação do cliente no processo de software.' + NCHAR(10) + N'II. Uma forte característica da XP é a garantia da qualidade do código produzido e, para isso, os desenvolvedores produzem testes automatizados antes mesmo de codificar uma funcionalidade.' + NCHAR(10) + N'III. O planejamento no Scrum é baseado na elaboração dos itens do product backlog, que é uma lista de funcionalidades desejadas pelo cliente, sendo o Scrum Master o responsável por gerenciá-lo.' + NCHAR(10) + N'IV. O quadro Kanban permite monitorar a evolução das tarefas necessárias durante o processo ágil, possibilitando um acompanhamento visual das atividades em construção.' + NCHAR(10) + N'' + NCHAR(10) + N'É correto apenas o que se afirma em', N'Alternativa C.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Quem gerencia o product backlog é o Product Owner, não o Scrum Master. As outras afirmações estão certas (o teste antes do código da II é o TDD).' + NCHAR(10) + N'' + NCHAR(10) + N'Fonte: INEP, ENADE 2021, Tecnologia em Análise e Desenvolvimento de Sistemas, questão 12 (gabarito definitivo).', N'Questão oficial do ENADE 2021: Engenharia de Software.', N'["A) II.","B) I e III.","C) I, II e IV.","D) I, III e IV.","E) II, III e IV."]', 2),
        (1179, N'fase25', N'(ENADE 2021 · Questão 13 · Algoritmos e Estruturas de Dados) As variáveis pilha e fila são uma Pilha e uma Fila. Um programador executou:' + NCHAR(10) + N'' + NCHAR(10) + N'pilha.push(''A''); pilha.push(''B''); pilha.push(''C'');' + NCHAR(10) + N'fila.enqueue(pilha.top());' + NCHAR(10) + N'fila.enqueue(pilha.top());' + NCHAR(10) + N'fila.enqueue(''D'');' + NCHAR(10) + N'pilha.push(fila.dequeue());' + NCHAR(10) + N'fila.enqueue(fila.dequeue());' + NCHAR(10) + N'fila.enqueue(pilha.pop());' + NCHAR(10) + N'pilha.push(''E'');' + NCHAR(10) + N'fila.enqueue(''E'');' + NCHAR(10) + N'pilha.pop();' + NCHAR(10) + N'' + NCHAR(10) + N'Ao imprimir o conteúdo de pilha e fila, respectivamente, seria exibido:', N'Alternativa C.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: top() só lê, então a fila recebe C, C e D. O primeiro C volta para a pilha, o segundo vai para o fim da fila, e o pop() devolve esse C para a fila. O E entra e sai da pilha: pilha C, B, A e fila D, C, C, E.' + NCHAR(10) + N'' + NCHAR(10) + N'Fonte: INEP, ENADE 2021, Tecnologia em Análise e Desenvolvimento de Sistemas, questão 13 (gabarito definitivo).', N'Questão oficial do ENADE 2021: Algoritmos e Estruturas de Dados.', N'["A) pilha: topo \u2192 C \u2192 A \u2192 E; fila: in\u00EDcio \u2192 D \u2192 A \u2192 A \u2192 E","B) pilha: topo \u2192 A; fila: in\u00EDcio \u2192 D \u2192 B \u2192 C \u2192 E","C) pilha: topo \u2192 C \u2192 B \u2192 A; fila: in\u00EDcio \u2192 D \u2192 C \u2192 C \u2192 E","D) pilha: topo \u2192 B \u2192 A; fila: in\u00EDcio \u2192 D \u2192 B \u2192 C \u2192 E","E) pilha: topo \u2192 C \u2192 B \u2192 A; fila: in\u00EDcio \u2192 D \u2192 B \u2192 C \u2192 E"]', 2),
        (1180, N'fase25', N'(ENADE 2021 · Questão 14 · Gestão de Projetos) Um projeto de integração de um ERP com um CRM não implementou todos os serviços esperados e há falhas nos já implementados. Uma auditoria identificou desentendimentos entre os membros da equipe; os membros da qualidade não compreendem o que deve ser avaliado; demandas de novos solicitantes aparecem constantemente; e o patrocinador demora muito a responder às solicitações. Tudo isso atrasou o projeto e estourou o orçamento.' + NCHAR(10) + N'' + NCHAR(10) + N'O gerente de projeto deve priorizar o gerenciamento de', N'Alternativa E.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Todos os problemas citados vêm das pessoas envolvidas: equipe, qualidade, solicitantes e patrocinador. Atraso e custo são consequências.' + NCHAR(10) + N'' + NCHAR(10) + N'Fonte: INEP, ENADE 2021, Tecnologia em Análise e Desenvolvimento de Sistemas, questão 14 (gabarito definitivo).', N'Questão oficial do ENADE 2021: Gestão de Projetos.', N'["A) custo.","B) tempo.","C) escopo.","D) qualidade.","E) partes interessadas."]', 4),
        (1181, N'fase25', N'(ENADE 2021 · Questão 17 · Banco de Dados) Um banco de dados bancário tem, entre outras, as tabelas CLIENTE (COD_CLIENTE, NOM_CLIENTE, ...), CONTA (NUM_CONTA, COD_CLIENTE, ...) e HISTORICO_MOVIMENTACAO (COD_HISTORICO_MOVIMENTACAO, NUM_CONTA, VAL_MOVIMENTACAO, DTA_MOVIMENTACAO, ...).' + NCHAR(10) + N'' + NCHAR(10) + N'Indique a consulta SQL que recupera o nome dos clientes e o valor médio movimentado por eles em sua conta até o momento, exibindo primeiro os clientes com maior média.', N'Alternativa C.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Média por cliente pede AVG com GROUP BY pelo cliente (o código evita juntar homônimos) e ORDER BY ... DESC. A opção D liga as chaves erradas e a E agrupa só pelo nome.' + NCHAR(10) + N'' + NCHAR(10) + N'Fonte: INEP, ENADE 2021, Tecnologia em Análise e Desenvolvimento de Sistemas, questão 17 (gabarito definitivo).', N'Questão oficial do ENADE 2021: Banco de Dados.', N'["A) SELECT CL.NOME, HM.VAL_MOVIMENTADO FROM CLIENTE CL INNER JOIN CONTA CO ON CL.COD_CLIENTE = CO.COD_CLIENTE INNER JOIN HISTORICO_MOVIMENTACAO HM ON CO.NUM_CONTA = HM.NUM_CONTA ORDER BY HM.VAL_MOVIMENTADO","B) SELECT CL.NOME, AVG(HM.VAL_MOVIMENTADO) FROM CLIENTE CL INNER JOIN CONTA CO ON CL.COD_CLIENTE = CO.COD_CLIENTE INNER JOIN HISTORICO_MOVIMENTACAO HM ON CO.NUM_CONTA = HM.NUM_CONTA ORDER BY HM.VAL_MOVIMENTADO DESC","C) SELECT CL.NOME, AVG(HM.VAL_MOVIMENTADO) FROM CLIENTE CL INNER JOIN CONTA CO ON CL.COD_CLIENTE = CO.COD_CLIENTE INNER JOIN HISTORICO_MOVIMENTACAO HM ON CO.NUM_CONTA = HM.NUM_CONTA GROUP BY CL.COD_CLIENTE, CL.NOME ORDER BY AVG(HM.VAL_MOVIMENTADO) DESC","D) SELECT CL.NOME, AVG(HM.VAL_MOVIMENTADO) FROM CLIENTE CL LEFT OUTER JOIN CONTA CO ON CL.COD_CLIENTE = CO.NUM_CONTA LEFT OUTER JOIN HISTORICO_MOVIMENTACAO HM ON CO.NUM_CONTA = HM.COD_HISTORICO_MOVIMENTACAO GROUP BY CL.NOME ORDER BY AVG(HM.VAL_MOVIMENTADO) DESC","E) SELECT CL.NOME, AVG(HM.VAL_MOVIMENTADO) FROM CLIENTE CL LEFT OUTER JOIN CONTA CO ON CL.COD_CLIENTE = CO.COD_CLIENTE LEFT OUTER JOIN HISTORICO_MOVIMENTACAO HM ON CO.NUM_CONTA = HM.NUM_CONTA GROUP BY CL.NOME ORDER BY AVG(HM.VAL_MOVIMENTADO) DESC"]', 2),
        (1182, N'fase25', N'(ENADE 2021 · Questão 18 · Engenharia de Software) A engenharia de requisitos tem quatro subprocessos: estudo de viabilidade, elicitação, especificação e validação (Sommerville). Uma equipe vai desenvolver um software de Suporte Técnico; o estudo de viabilidade já foi aprovado e ela seguirá os outros três subprocessos.' + NCHAR(10) + N'' + NCHAR(10) + N'Quais artefatos podem ser usados nesses três subprocessos?', N'Alternativa A.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Entrevista serve à elicitação, caso de uso à especificação dos requisitos funcionais e protótipo à validação. Viabilidade já foi feita, e caso de uso não modela requisito não funcional.' + NCHAR(10) + N'' + NCHAR(10) + N'Fonte: INEP, ENADE 2021, Tecnologia em Análise e Desenvolvimento de Sistemas, questão 18 (gabarito definitivo).', N'Questão oficial do ENADE 2021: Engenharia de Software.', N'["A) Documento de entrevista com usu\u00E1rios; modelo de caso de uso para os requisitos funcionais; prototipa\u00E7\u00E3o de telas.","B) Documento de estudo de viabilidade; modelo de caso de uso para os requisitos funcionais; prototipa\u00E7\u00E3o de telas.","C) Matriz de rastreabilidade; modelo de caso de uso para os requisitos n\u00E3o-funcionais; prototipa\u00E7\u00E3o de telas.","D) Documento de entrevista com usu\u00E1rios; modelo de caso de uso para os requisitos n\u00E3o-funcionais; matriz de rastreabilidade.","E) Documento de estudo de viabilidade; modelo de caso de uso para os requisitos funcionais; matriz de rastreabilidade."]', 0),
        (1183, N'fase25', N'(ENADE 2021 · Questão 19 · Engenharia de Software) A respeito dos estilos e padrões arquiteturais, avalie as afirmações:' + NCHAR(10) + N'I. Em arquiteturas orientadas a objetos, a comunicação entre os componentes do software é realizada por intermédio da troca de mensagens.' + NCHAR(10) + N'II. As arquiteturas monolíticas consistem de um sistema dividido em pequenas partes, possibilitando que estas tenham sua manutenção, execução e evolução individual.' + NCHAR(10) + N'III. No padrão MVC, a camada de Modelo armazena as interações realizadas no Controle, podendo ser apresentadas/manipuladas posteriormente na Visão.' + NCHAR(10) + N'IV. Nas arquiteturas de microsserviços, o software possui componentes altamente acoplados, dificultando a manutenção.' + NCHAR(10) + N'' + NCHAR(10) + N'É correto apenas o que se afirma em', N'Alternativa A.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: II descreve microsserviços, não monólito. E microsserviços buscam baixo acoplamento, o contrário do que diz a IV.' + NCHAR(10) + N'' + NCHAR(10) + N'Fonte: INEP, ENADE 2021, Tecnologia em Análise e Desenvolvimento de Sistemas, questão 19 (gabarito definitivo).', N'Questão oficial do ENADE 2021: Engenharia de Software.', N'["A) I e III.","B) II e III.","C) II e IV.","D) I, II e IV.","E) I, III e IV."]', 0),
        (1184, N'fase25', N'(ENADE 2021 · Questão 20 · UX/UI e Requisitos) Uma secretaria municipal vai criar um site para pessoas da terceira idade, com orientações de saúde, eventos esportivos e publicação de fotos que podem ser curtidas e comentadas. A maioria desse público acessa a internet pelo celular ou tablet, e uma parte prefere computadores.' + NCHAR(10) + N'' + NCHAR(10) + N'Avalie as afirmações:' + NCHAR(10) + N'I. A segurança no uso é um fator crítico de usabilidade a ser considerado no projeto, tendo em vista que pessoas da terceira idade são temerosas quanto ao registro de dados pessoais e confidenciais em sites e aplicativos.' + NCHAR(10) + N'II. A responsividade, que pressupõe o uso de valores relativos para definir as dimensões de elementos na estilização de páginas HTML, deve ser considerada, tendo em vista o acesso por dispositivos com diferentes tamanhos de tela.' + NCHAR(10) + N'III. A construção de protótipos pode antecipar problemas de design de interação e minimizar custos, e é viável para uma comunicação mais objetiva com o público-alvo, possibilitando validar a usabilidade e a experiência do usuário.' + NCHAR(10) + N'IV. O design participativo é um processo de design de IHC viável para direcionar o projeto, pois o público-alvo tende a apresentar dificuldades no manuseio de tecnologias da informação e da comunicação.' + NCHAR(10) + N'' + NCHAR(10) + N'É correto apenas o que se afirma em', N'Alternativa E.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Responsividade, protótipos e design participativo se encaixam no cenário. A I parte de uma generalização sobre o público que o texto não sustenta.' + NCHAR(10) + N'' + NCHAR(10) + N'Fonte: INEP, ENADE 2021, Tecnologia em Análise e Desenvolvimento de Sistemas, questão 20 (gabarito definitivo).', N'Questão oficial do ENADE 2021: UX/UI e Requisitos.', N'["A) I e II.","B) I e III.","C) II e IV.","D) I, III e IV.","E) II, III e IV."]', 4),
        (1185, N'fase25', N'(ENADE 2021 · Questão 21 · Engenharia de Software) A Gestão de Configuração de Software estabelece um conjunto de atividades para gerenciar alterações durante todo o ciclo de vida de um software (Pressman).' + NCHAR(10) + N'' + NCHAR(10) + N'Assinale a opção correta acerca das atividades de gestão de configuração de software.', N'Alternativa B.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: São as cinco tarefas clássicas da gestão de configuração em Pressman: identificação, controle de versão, controle de alterações, auditoria e relatório de status.' + NCHAR(10) + N'' + NCHAR(10) + N'Fonte: INEP, ENADE 2021, Tecnologia em Análise e Desenvolvimento de Sistemas, questão 21 (gabarito definitivo).', N'Questão oficial do ENADE 2021: Engenharia de Software.', N'["A) Identifica\u00E7\u00E3o de itens na configura\u00E7\u00E3o de software, gerenciamento de altera\u00E7\u00F5es, valida\u00E7\u00E3o de vers\u00F5es e controle de qualidade.","B) Identifica\u00E7\u00E3o de objetos na configura\u00E7\u00E3o de software, controle de vers\u00E3o, controle de altera\u00E7\u00F5es, auditoria de configura\u00E7\u00E3o e relat\u00F3rio de status.","C) Ger\u00EAncia de projeto, ger\u00EAncia de configura\u00E7\u00E3o de software, ciclo de vida do projeto, processo de software e evolu\u00E7\u00E3o das configura\u00E7\u00F5es.","D) Constru\u00E7\u00E3o de modelo de requisitos, m\u00E9tricas para modelo de projeto, m\u00E9tricas de controle de vers\u00E3o e relat\u00F3rio de manuten\u00E7\u00E3o.","E) Identifica\u00E7\u00E3o de altera\u00E7\u00F5es, controle de vers\u00E3o, mapeamento de altera\u00E7\u00E3o e notifica\u00E7\u00E3o da altera\u00E7\u00E3o aos envolvidos."]', 1),
        (1186, N'fase25', N'(ENADE 2021 · Questão 22 · Engenharia de Software) Sobre o processo de Gerência de Configuração de Software (GCS), avalie as afirmações:' + NCHAR(10) + N'I. O controle de versão possibilita o compartilhamento de dados e a edição colaborativa, permitindo a gestão de diferentes ramos de desenvolvimento e a existência de diferentes versões de forma simultânea.' + NCHAR(10) + N'II. A auditoria de configuração é uma atividade de garantia de qualidade que tem por objetivo assegurar que a qualidade do software seja mantida quando feitas alterações requisitadas.' + NCHAR(10) + N'III. O relatório de status de configuração tem por objetivo manter o cliente informado sobre as alterações, e deve ser gerado ao final do processo.' + NCHAR(10) + N'IV. A GCS proporciona atividades de acompanhamento e controle de mudanças que se iniciam logo depois que o software for fornecido ao cliente e colocado em operação.' + NCHAR(10) + N'' + NCHAR(10) + N'É correto apenas o que se afirma em', N'Alternativa A.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: O relatório de status informa a equipe ao longo de todo o processo, não só no final. E a GCS começa junto com o projeto, não depois da entrega.' + NCHAR(10) + N'' + NCHAR(10) + N'Fonte: INEP, ENADE 2021, Tecnologia em Análise e Desenvolvimento de Sistemas, questão 22 (gabarito definitivo).', N'Questão oficial do ENADE 2021: Engenharia de Software.', N'["A) I e II.","B) II e III.","C) III e IV.","D) I, II e IV.","E) I, III e IV."]', 0),
        (1187, N'fase25', N'(ENADE 2021 · Questão 23 · Engenharia de Software) A evolução de sistemas legados se divide em manutenção, modernização e substituição. Um ERP já implantado integra todos os departamentos de uma empresa, e surgiu a necessidade de criar um relatório gerencial de comissão da equipe de vendas.' + NCHAR(10) + N'' + NCHAR(10) + N'Nesse contexto, a manutenção a ser realizada é', N'Alternativa B.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Acrescentar uma funcionalidade nova (o relatório) é manutenção evolutiva. Corretiva conserta defeito e adaptativa ajusta o sistema a um ambiente novo.' + NCHAR(10) + N'' + NCHAR(10) + N'Fonte: INEP, ENADE 2021, Tecnologia em Análise e Desenvolvimento de Sistemas, questão 23 (gabarito definitivo).', N'Questão oficial do ENADE 2021: Engenharia de Software.', N'["A) corretiva.","B) evolutiva.","C) funcional.","D) preventiva.","E) adaptativa."]', 1),
        (1188, N'fase25', N'(ENADE 2021 · Questão 24 · Engenharia de Software) Num sistema web de delivery, o analista de teste descreveu:' + NCHAR(10) + N'01 – Verificar se o método "Finalizar Pedido" da classe "Pedido" está funcionando corretamente.' + NCHAR(10) + N'02 – Garantir que o sistema funcione corretamente em diferentes navegadores.' + NCHAR(10) + N'03 – O sistema deve passar por testes rigorosos na estrutura lógica interna do software.' + NCHAR(10) + N'04 – O sistema deve garantir, no mínimo, o registro de 100 pedidos simultâneos.' + NCHAR(10) + N'05 – O usuário deve testar o sistema em um ambiente controlado sob a supervisão dos desenvolvedores.' + NCHAR(10) + N'' + NCHAR(10) + N'Avalie as afirmações:' + NCHAR(10) + N'I. A descrição 01 deve ser verificada com teste unitário.' + NCHAR(10) + N'II. A descrição 02 deve ser executada com a abordagem caixa-branca.' + NCHAR(10) + N'III. A descrição 03 deve ser executada com a abordagem caixa-preta.' + NCHAR(10) + N'IV. A descrição 04 deve ser verificada com teste de carga.' + NCHAR(10) + N'V. A descrição 05 deve ser classificada como teste alfa.' + NCHAR(10) + N'' + NCHAR(10) + N'É correto apenas o que se afirma em', N'Alternativa D.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: II e III estão trocadas: testar navegadores é caixa-preta (olha só o comportamento) e testar a lógica interna é caixa-branca.' + NCHAR(10) + N'' + NCHAR(10) + N'Fonte: INEP, ENADE 2021, Tecnologia em Análise e Desenvolvimento de Sistemas, questão 24 (gabarito definitivo).', N'Questão oficial do ENADE 2021: Engenharia de Software.', N'["A) II e III.","B) I, II e IV.","C) I, III e V.","D) I, IV e V.","E) II, III, IV e V."]', 3),
        (1189, N'fase25', N'(ENADE 2021 · Questão 25 · Engenharia de Software) Uma empresa de piscicultura pediu com extrema urgência um sistema para gerenciar a criação dos peixes, das fases de alevino e engorda até a venda, registrando mortandade e rações.' + NCHAR(10) + N'' + NCHAR(10) + N'Avalie as afirmações sobre o processo de desenvolvimento a usar:' + NCHAR(10) + N'I. Deve ser adotado um processo baseado no modelo cascata, pois ele se adapta melhor a cenários com muitas mudanças.' + NCHAR(10) + N'II. Por se tratar de uma aplicação com escopo pequeno, o modelo espiral deverá ser utilizado, já que reduzirá riscos por meio da prototipação de cada fase dos peixes e diminuirá o tempo de entrega.' + NCHAR(10) + N'III. O modelo incremental deve ser utilizado, já que partes do sistema referentes à fase inicial dos peixes poderiam ser disponibilizadas, enquanto as demais estão nas etapas de concepção e desenvolvimento.' + NCHAR(10) + N'IV. Em razão da extrema urgência, a empresa deve elaborar seu processo utilizando o modelo RAD (Rapid Application Development).' + NCHAR(10) + N'' + NCHAR(10) + N'É correto apenas o que se afirma em', N'Alternativa E.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Entregar por partes (incremental) e com rapidez (RAD) atende a urgência. O cascata é o modelo que pior lida com mudanças, e o espiral é indicado para projetos grandes e arriscados.' + NCHAR(10) + N'' + NCHAR(10) + N'Fonte: INEP, ENADE 2021, Tecnologia em Análise e Desenvolvimento de Sistemas, questão 25 (gabarito definitivo).', N'Questão oficial do ENADE 2021: Engenharia de Software.', N'["A) I.","B) IV.","C) I e II.","D) II e III.","E) III e IV."]', 4),
        (1190, N'fase25', N'(ENADE 2021 · Questão 26 · Cibersegurança e LGPD) Empreender em computação exige observar a legislação, como a Lei Geral de Proteção de Dados Pessoais (LGPD, Lei n. 13.709/2018).' + NCHAR(10) + N'' + NCHAR(10) + N'Assinale os fundamentos da disciplina da proteção de dados pessoais, previstos no art. 2º da LGPD.', N'Alternativa E.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: A alternativa E reproduz os sete incisos do art. 2º. As outras misturam fundamentos com direitos do titular, bases legais e obrigações.' + NCHAR(10) + N'' + NCHAR(10) + N'Fonte: INEP, ENADE 2021, Tecnologia em Análise e Desenvolvimento de Sistemas, questão 26 (gabarito definitivo).', N'Questão oficial do ENADE 2021: Cibersegurança e LGPD.', N'["A) O direito ao usu\u00E1rio; as obriga\u00E7\u00F5es das organiza\u00E7\u00F5es nacionais ou estrangeiras; obrigatoriedade do consentimento; a livre iniciativa, a livre concorr\u00EAncia e a defesa do consumidor; os direitos humanos e a cidadania; e a regula\u00E7\u00E3o da ANPD.","B) O direito \u00E0 revoga\u00E7\u00E3o de um consentimento; a transfer\u00EAncia de dados para outro fornecedor; a solicita\u00E7\u00E3o de remo\u00E7\u00E3o de dados pessoais; a inviolabilidade da intimidade, da honra e da imagem; o desenvolvimento econ\u00F4mico e tecnol\u00F3gico e a inova\u00E7\u00E3o; a preserva\u00E7\u00E3o da vida e da integridade f\u00EDsica.","C) O respeito \u00E0 privacidade; obrigatoriedade do consentimento; os deveres dos usu\u00E1rios finais; os deveres das organiza\u00E7\u00F5es nacionais ou estrangeiras; o c\u00F3digo de defesa do consumidor; e a obrigatoriedade do respeito \u00E0 honra e \u00E0 imagem.","D) O direito ao anonimato; a liberdade de express\u00E3o; a inviolabilidade da intimidade; medidas preventivas de seguran\u00E7a; o direito ao recurso e revis\u00E3o; a administra\u00E7\u00E3o de riscos e falhas; os agentes de tratamento; e a regula\u00E7\u00E3o da ANPD.","E) O respeito \u00E0 privacidade; a autodetermina\u00E7\u00E3o informativa; a liberdade de express\u00E3o, de informa\u00E7\u00E3o, de comunica\u00E7\u00E3o e de opini\u00E3o; a inviolabilidade da intimidade, da honra e da imagem; o desenvolvimento econ\u00F4mico e tecnol\u00F3gico e a inova\u00E7\u00E3o; a livre iniciativa, a livre concorr\u00EAncia e a defesa do consumidor; e os direitos humanos, o livre desenvolvimento da personalidade, a dignidade e o exerc\u00EDcio da cidadania."]', 4),
        (1191, N'fase25', N'(ENADE 2021 · Questão 27 · Matemática e Lógica) Os profissionais de TI precisam converter números entre as bases binária (2), octal (8), decimal (10) e hexadecimal (16).' + NCHAR(10) + N'' + NCHAR(10) + N'Fazendo a conversão da soma (1001)₂ + (15)₈ + (FF)₁₆, qual é o número equivalente na base decimal?', N'Alternativa C.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: (1001)₂ = 9, (15)₈ = 1×8 + 5 = 13 e (FF)₁₆ = 15×16 + 15 = 255. Soma: 9 + 13 + 255 = 277.' + NCHAR(10) + N'' + NCHAR(10) + N'Fonte: INEP, ENADE 2021, Tecnologia em Análise e Desenvolvimento de Sistemas, questão 27 (gabarito definitivo).', N'Questão oficial do ENADE 2021: Matemática e Lógica.', N'["A) (188)\u2081\u2080","B) (215)\u2081\u2080","C) (277)\u2081\u2080","D) (316)\u2081\u2080","E) (345)\u2081\u2080"]', 2),
        (1192, N'fase25', N'(ENADE 2021 · Questão 28 · Sistemas Operacionais) O sistema operacional é um gerenciador de recursos. É uma péssima ideia permitir que os programas tenham acesso sem restrição à memória uns dos outros: um programa com defeito ou malicioso pode travar outro, produzir resultados incorretos ou afetar todo o sistema (Stuart, adaptado).' + NCHAR(10) + N'' + NCHAR(10) + N'A atividade com que o sistema operacional garante essa proteção é', N'Alternativa B.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: É o gerenciamento de memória que dá a cada processo o seu espaço de endereços e impede que um escreva na área do outro.' + NCHAR(10) + N'' + NCHAR(10) + N'Fonte: INEP, ENADE 2021, Tecnologia em Análise e Desenvolvimento de Sistemas, questão 28 (gabarito definitivo).', N'Questão oficial do ENADE 2021: Sistemas Operacionais.', N'["A) o programa antiv\u00EDrus.","B) o gerenciamento de mem\u00F3ria.","C) o gerenciamento de arquivos.","D) o gerenciamento de processos.","E) o gerenciamento de entrada e sa\u00EDda."]', 1),
        (1193, N'fase25', N'(ENADE 2021 · Questão 29 · Algoritmos e Estruturas de Dados) Considere o algoritmo:' + NCHAR(10) + N'' + NCHAR(10) + N'mat[1..3][1..5] = {{1, 2, -1, 2, 3}, {1, -3, 4, 2, 0}, {-3, 5, 2, 3, 4}}' + NCHAR(10) + N'sl[1..3] = {0, 0, 0}' + NCHAR(10) + N'x <- 0' + NCHAR(10) + N'para i <- 1 até 3 faça' + NCHAR(10) + N'    para j <- 1 até 5 faça' + NCHAR(10) + N'        sl[i] <- sl[i] + mat[i][j]' + NCHAR(10) + N'    fimpara' + NCHAR(10) + N'    x <- x + sl[i]' + NCHAR(10) + N'fimpara' + NCHAR(10) + N'imprima x' + NCHAR(10) + N'' + NCHAR(10) + N'No fim da execução, será exibido o valor', N'Alternativa D.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: As somas das linhas são 7, 4 e 11. x acumula essas somas: 7 + 4 + 11 = 22.' + NCHAR(10) + N'' + NCHAR(10) + N'Fonte: INEP, ENADE 2021, Tecnologia em Análise e Desenvolvimento de Sistemas, questão 29 (gabarito definitivo).', N'Questão oficial do ENADE 2021: Algoritmos e Estruturas de Dados.', N'["A) 4.","B) 7.","C) 11.","D) 22.","E) 30."]', 3),
        (1194, N'fase25', N'(ENADE 2021 · Questão 30 · Redes e Sistemas Distribuídos) Na sala dos professores há 3 máquinas na rede:' + NCHAR(10) + N'PROFESSORES01: IP 175.16.10.200, máscara 255.255.255.0, gateway 175.16.1.1' + NCHAR(10) + N'PROFESSORES02: IP 175.16.20.200, máscara 255.255.0.0, gateway 175.16.1.1' + NCHAR(10) + N'PROFESSORES03: IP 175.16.30.200, máscara 255.255.0.0, gateway 175.16.1.1' + NCHAR(10) + N'' + NCHAR(10) + N'A estação PROFESSORES01 não consegue imprimir na impressora compartilhada pela PROFESSORES03. Que alteração resolve o problema?', N'Alternativa C.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Com máscara 255.255.255.0, a PROFESSORES01 se vê na rede 175.16.10.0 e acha que a 03 está em outra rede. Com 255.255.0.0, todas ficam na 175.16.0.0.' + NCHAR(10) + N'' + NCHAR(10) + N'Fonte: INEP, ENADE 2021, Tecnologia em Análise e Desenvolvimento de Sistemas, questão 30 (gabarito definitivo).', N'Questão oficial do ENADE 2021: Redes e Sistemas Distribuídos.', N'["A) Alterar o gateway da esta\u00E7\u00E3o PROFESSORES03 para 175.16.10.200.","B) Alterar o endere\u00E7o de IP da esta\u00E7\u00E3o PROFESSORES01 para 175.16.30.200.","C) Alterar a m\u00E1scara de sub-rede da esta\u00E7\u00E3o PROFESSORES01 para 255.255.0.0.","D) Alterar a m\u00E1scara de sub-rede da esta\u00E7\u00E3o PROFESSORES03 para 255.255.255.0.","E) Alterar o gateway da esta\u00E7\u00E3o PROFESSORES01 para o endere\u00E7o de IP 175.16.30.200."]', 2),
        (1195, N'fase25', N'(ENADE 2021 · Questão 31 · Engenharia de Software) Um software de matrículas tem este diagrama de casos de uso: o ator Aluno se liga a "Realizar Matrícula"; "Realizar Matrícula Fora do Prazo" estende (<<extend>>) "Realizar Matrícula"; "Realizar Matrícula Fora do Prazo" inclui (<<include>>) "Validar Aluno"; e "Validar via Retina" e "Validar via Digital" são especializações de "Validar Aluno".' + NCHAR(10) + N'' + NCHAR(10) + N'Avalie as afirmações:' + NCHAR(10) + N'I. O aluno poderá realizar a matrícula fora do prazo e as tratativas são as mesmas da matrícula feita dentro do prazo.' + NCHAR(10) + N'II. O aluno poderá, opcionalmente, realizar a matrícula fora do prazo.' + NCHAR(10) + N'III. O sistema, obrigatoriamente, deverá validar o aluno que realizar a matrícula fora do prazo.' + NCHAR(10) + N'IV. A validação do aluno deverá ser feita a partir da sua matrícula informada no sistema.' + NCHAR(10) + N'V. A validação do aluno, a ser feita por retina, é diferente da validação feita pela digital.' + NCHAR(10) + N'' + NCHAR(10) + N'É correto apenas o que se afirma em', N'Alternativa D.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: <<extend>> é opcional (II), <<include>> é obrigatório (III) e as especializações são formas diferentes de validar (V). A validação é por retina ou digital, não pela matrícula.' + NCHAR(10) + N'' + NCHAR(10) + N'Fonte: INEP, ENADE 2021, Tecnologia em Análise e Desenvolvimento de Sistemas, questão 31 (gabarito definitivo).', N'Questão oficial do ENADE 2021: Engenharia de Software.', N'["A) I e IV.","B) I, II e IV.","C) I, III e V.","D) II, III e V.","E) II, III, IV e V."]', 3),
        (1196, N'fase25', N'(ENADE 2021 · Questão 32 · Gestão e Empreendedorismo) O Canvas de Osterwalder divide o modelo de negócio em nove componentes: segmentos de clientes, proposta de valor, canais, relacionamento com cliente, fontes de receita, recursos principais, atividades-chave, parcerias principais e estrutura de custo. É muito usado por startups.' + NCHAR(10) + N'' + NCHAR(10) + N'Diante deste contexto, conclui-se que as startups', N'Alternativa B.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: O Canvas serve justamente para modelar e validar a ideia antes de investir, em qualquer segmento. Nenhum tipo de startup nasce validado ou pode ignorar um componente.' + NCHAR(10) + N'' + NCHAR(10) + N'Fonte: INEP, ENADE 2021, Tecnologia em Análise e Desenvolvimento de Sistemas, questão 32 (gabarito definitivo).', N'Questão oficial do ENADE 2021: Gestão e Empreendedorismo.', N'["A) financeiras desenvolvem primeiro o plano de neg\u00F3cios, para em seguida partir para o Canvas.","B) de big data utilizam o Canvas para a modelagem da valida\u00E7\u00E3o da ideia de neg\u00F3cio, ou seja, do problema a ser resolvido.","C) de educa\u00E7\u00E3o dispensam a utiliza\u00E7\u00E3o do Canvas, ou seja, os modelos de neg\u00F3cios deste segmento j\u00E1 nascem validados.","D) de log\u00EDstica utilizam o plano de neg\u00F3cios ao inv\u00E9s do Canvas, ou seja, elas nascem a partir de um produto m\u00EDnimo vi\u00E1vel (MVP).","E) de impacto social podem desconsiderar o componente 1 (segmentos de clientes), pois possuem somente um segmento."]', 1),
        (1197, N'fase25', N'(ENADE 2021 · Questão 33 · Engenharia de Software) O CMMI descreve práticas, processos e atividades de gestão que guiam a melhoria do processo de software até o nível mais alto de maturidade. Avalie as afirmações:' + NCHAR(10) + N'I. A maturidade implica no crescimento da capacidade e indica tanto a efetividade do processo de software quanto o grau de consistência com que este é aplicado nos diferentes projetos da organização.' + NCHAR(10) + N'II. A maturidade do processo de software implica melhorias contínuas com base em etapas evolutivas que se caracterizam pela capacidade de inovação e absorção de novas tecnologias.' + NCHAR(10) + N'III. A maturidade do processo de software implica na sua institucionalização por meio de políticas e padrões organizacionais, levando a uma cultura corporativa de métodos, práticas e procedimentos com efetividade plenamente reconhecida.' + NCHAR(10) + N'IV. Cada nível do CMMI implica na satisfação de um conjunto de metas de processo que estabilizam um componente importante do processo de software e representa o seu estágio de maturidade.' + NCHAR(10) + N'' + NCHAR(10) + N'É correto apenas o que se afirma em', N'Alternativa D.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: Pelo gabarito, a II é a falsa: as etapas evolutivas do CMMI são níveis de controle do processo, não de capacidade de inovação ou absorção de tecnologias.' + NCHAR(10) + N'' + NCHAR(10) + N'Fonte: INEP, ENADE 2021, Tecnologia em Análise e Desenvolvimento de Sistemas, questão 33 (gabarito definitivo).', N'Questão oficial do ENADE 2021: Engenharia de Software.', N'["A) III.","B) I e II.","C) II e IV.","D) I, III e IV.","E) I, II, III e IV."]', 3),
        (1198, N'fase25', N'(ENADE 2021 · Questão 34 · Inteligência Artificial) Um sistema especialista para diagnóstico de dengue usa a regra de produção:' + NCHAR(10) + N'' + NCHAR(10) + N'Se ((temperatura > 38º) e (dores musculares intensas))' + NCHAR(10) + N'então (quadro de dengue, com 70% de chance);' + NCHAR(10) + N'senão (quadro de resfriado comum com 30% de chance);' + NCHAR(10) + N'' + NCHAR(10) + N'Levando em conta essa regra, é correto afirmar que', N'Alternativa A.' + NCHAR(10) + N'' + NCHAR(10) + N'Justificativa: A regra dá uma probabilidade para cada pessoa com os dois sintomas: 0,7. Ela não garante uma contagem exata (C) nem diz nada certo sobre quem tem só um sintoma.' + NCHAR(10) + N'' + NCHAR(10) + N'Fonte: INEP, ENADE 2021, Tecnologia em Análise e Desenvolvimento de Sistemas, questão 34 (gabarito definitivo).', N'Questão oficial do ENADE 2021: Inteligência Artificial.', N'["A) cada pessoa que procura atendimento apresentando ambos os sintomas possui a probabilidade 0,7 de estar contaminada pela dengue.","B) se 50 pessoas procurarem o atendimento apresentando um dos dois sintomas, provavelmente 15 pessoas estar\u00E3o com resfriado comum.","C) se 100 pessoas procurarem o atendimento apresentando ambos os sintomas, a quantidade de pessoas com dengue ser\u00E1 igual a 70.","D) cada pessoa que chega apresentando um dos dois sintomas estar\u00E1 com resfriado comum.","E) a cada 100 pessoas que procuram atendimento, no m\u00E1ximo 30 estar\u00E3o doentes."]', 0);
