    INSERT INTO tb_provas (id_prova, ano, tipo) VALUES
        (1, 2017, N'ENADE'),
        (2, 2021, N'ENADE');
    INSERT INTO tb_questoes (id_questao, id_area, enunciado, origem) VALUES
        (1, 1, N'A álgebra booleana possui o operador unário ~ (NÃO) e os operadores binários * (E) e + (OU). A tabela verdade da fórmula G, para as proposições p, q e r, é:' + NCHAR(10) + N'' + NCHAR(10) + N'p q r | G' + NCHAR(10) + N'V V V | V' + NCHAR(10) + N'V V F | F' + NCHAR(10) + N'V F V | F' + NCHAR(10) + N'V F F | F' + NCHAR(10) + N'F V V | V' + NCHAR(10) + N'F V F | V' + NCHAR(10) + N'F F V | V' + NCHAR(10) + N'F F F | V' + NCHAR(10) + N'' + NCHAR(10) + N'Considerando a ordem de precedência dos operadores booleanos, a fórmula G possui a mesma tabela verdade da proposição', N'ENADE 2017 - questão 10'),
        (2, 2, N'Num sistema para um clube recreativo, o diagrama de classes tem: Tipo_Associado (codigo, descricao, valorMensalidade) ligado a Associado com multiplicidade 1 para 0..*; e Associado (codigo, nome, endereco, telefone) ligado a Mensalidade (codigo, anomesreferencia, valormensalidade, datavencimento, valorpago, datapagamento) com multiplicidade 1 para 1..*.' + NCHAR(10) + N'' + NCHAR(10) + N'Avalie as afirmações:' + NCHAR(10) + N'I. Haverá somente 12 mensalidades para cada associado, ou seja, elas não poderão ultrapassar os 12 meses do ano.' + NCHAR(10) + N'II. Não existem associados sem mensalidades, nem mensalidades sem associado a elas relacionado.' + NCHAR(10) + N'III. Alterando-se o valor da mensalidade definido para cada tipo de associado, o sistema automaticamente altera os valores das mensalidades geradas anteriormente.' + NCHAR(10) + N'IV. Poderão existir tipos de associados que não terão nenhum associado relacionado a eles.' + NCHAR(10) + N'' + NCHAR(10) + N'É correto apenas o que se afirma em', N'ENADE 2017 - questão 11'),
        (3, 3, N'Considere os requisitos de um sistema acadêmico de uma universidade:' + NCHAR(10) + N'R1: o sistema deve permitir que cada professor realize o lançamento de notas das turmas nas quais lecionou;' + NCHAR(10) + N'R2: o sistema deverá ser desenvolvido de forma a possibilitar seu transporte para outro sistema operacional em, no máximo, sessenta dias;' + NCHAR(10) + N'R3: o sistema deve permitir que um estudante realize a sua matrícula nas disciplinas oferecidas em um semestre letivo;' + NCHAR(10) + N'R4: o sistema atualiza a nota do estudante, permitindo sua visualização, em até dois segundos depois do momento que o professor a registra;' + NCHAR(10) + N'R5: o sistema deve permitir que o auxiliar de serviços acadêmicos realize o cadastro de um estudante em não mais do que dez minutos de orientação.' + NCHAR(10) + N'' + NCHAR(10) + N'Representam requisitos não funcionais apenas os requisitos', N'ENADE 2017 - questão 12'),
        (4, 3, N'Sobre o modelo CMMI, avalie as asserções e a relação proposta entre elas.' + NCHAR(10) + N'' + NCHAR(10) + N'I. O CMMI fornece diretrizes para a melhoria dos processos e habilidades organizacionais, incluindo o ciclo de vida de produtos e serviços, que abrange as fases de concepção, desenvolvimento, aquisição, entrega e manutenção.' + NCHAR(10) + N'' + NCHAR(10) + N'PORQUE' + NCHAR(10) + N'' + NCHAR(10) + N'II. As empresas brasileiras estão aderindo a programas de fomento à melhoria da qualidade de software, por meio da aplicação do modelo de maturidade CMMI, que é mais direcionado às pequenas e médias empresas, apesar de também ser aplicável em grandes organizações.', N'ENADE 2017 - questão 13'),
        (5, 4, N'A tabela apresenta as atividades de um projeto (predecessora; duração em dias):' + NCHAR(10) + N'A (--; 3), B (A; 5), C (--; 12), D (--; 4), E (D; 2), F (D; 5), G (F; 7), H (E e G; 8), I (B; 11), J (C, H e I; 3).' + NCHAR(10) + N'' + NCHAR(10) + N'Avalie as afirmações:' + NCHAR(10) + N'I. O caminho crítico é composto pelas atividades A, B, I e J.' + NCHAR(10) + N'II. O caminho crítico tem 27 dias.' + NCHAR(10) + N'III. A atividade H faz parte do caminho crítico.' + NCHAR(10) + N'IV. O projeto em pauta possui dois caminhos críticos.' + NCHAR(10) + N'' + NCHAR(10) + N'É correto apenas o que se afirma em', N'ENADE 2017 - questão 14'),
        (6, 5, N'Um diagrama de classes modela a transferência de materiais entre funcionários. RequisicaoTransferencia (dataRequisicao: date) tem duas associações navegáveis para Funcionario (nome: string), com os papéis "origem" e "destino" e multiplicidade 1. RequisicaoTransferencia também tem uma composição (losango cheio do seu lado) com Material (descricao: string, preco: double), navegável para Material, com papel "material" e multiplicidade 0..1 do lado da requisição e 1..* do lado de Material.' + NCHAR(10) + N'' + NCHAR(10) + N'Avalie as afirmações:' + NCHAR(10) + N'I. A classe Funcionario é abstrata.' + NCHAR(10) + N'II. Uma RequisicaoTransferencia só existe se estiver vinculada a um Material.' + NCHAR(10) + N'III. A classe Funcionario, em razão de sua associação, possui um atributo do tipo RequisicaoTransferencia.' + NCHAR(10) + N'IV. Em uma implementação da classe RequisicaoTransferencia, é necessário adicionar um atributo simples do tipo Material.' + NCHAR(10) + N'' + NCHAR(10) + N'É correto o que se afirma em', N'ENADE 2017 - questão 16'),
        (7, 3, N'Considerando a etapa de manutenção no processo de desenvolvimento de software, avalie as afirmações:' + NCHAR(10) + N'I. A fase de manutenção é uma parte explícita do modelo em cascata do processo de desenvolvimento de software.' + NCHAR(10) + N'II. A atualização do sistema para inserir customizações é considerada um tipo de manutenção.' + NCHAR(10) + N'III. A depuração do programa é um processo específico da fase de desenvolvimento e um tipo de manutenção.' + NCHAR(10) + N'IV. O acréscimo de novas funções a um sistema existente, sem perturbar sua operação, é considerado um tipo de manutenção.' + NCHAR(10) + N'V. A manutenção do sistema está relacionada ao aumento do ciclo de vida do software.' + NCHAR(10) + N'' + NCHAR(10) + N'É correto apenas o que se afirma em', N'ENADE 2017 - questão 17'),
        (8, 6, N'As redes de computadores estão por toda parte e compartilham recursos por meio de sistemas distribuídos, que comunicam e coordenam vários dispositivos.' + NCHAR(10) + N'' + NCHAR(10) + N'Assinale a opção que apresenta exemplos atuais de sistemas distribuídos.', N'ENADE 2017 - questão 18'),
        (9, 7, N'Conceitualmente, cada processo tem sua própria CPU virtual. Na realidade, a CPU troca a execução, a todo momento, de um processo para outro, mas é muito mais fácil pensar em um conjunto de processos sendo executados (pseudo) paralelamente do que tentar controlar o modo como a CPU faz esses chaveamentos. (Tanenbaum, adaptado)' + NCHAR(10) + N'' + NCHAR(10) + N'De acordo com o exposto, o conceito descrito denomina-se', N'ENADE 2017 - questão 19'),
        (10, 3, N'A respeito dos modelos de processo de software, avalie as afirmações:' + NCHAR(10) + N'I. São atividades do modelo incremental: especificação, desenvolvimento e validação.' + NCHAR(10) + N'II. No modelo espiral, a fase de modelagem é responsável, entre outras atividades, pela estimativa, cronograma e análise de risco.' + NCHAR(10) + N'III. O modelo cascata sugere uma abordagem sequencial e sistemática para o desenvolvimento de software, iniciando na especificação de requisitos e finalizando com a entrega do software concluído.' + NCHAR(10) + N'' + NCHAR(10) + N'É correto o que se afirma em', N'ENADE 2017 - questão 21'),
        (11, 3, N'Um desenvolvedor recém-formado recebeu explicações sobre como a gerência de configuração funcionava. Avalie as afirmações:' + NCHAR(10) + N'I. Inicialmente, para ter acesso à base de desenvolvimento, o profissional deve realizar uma operação de checkout para baixar os arquivos do projeto que estão armazenados no servidor.' + NCHAR(10) + N'II. Quando mais de um desenvolvedor estiver modificando um mesmo documento, ao se tentar realizar um commit, pode ser necessário realizar uma operação de tag (release) para resolução do conflito entre a versão local e a versão mais recente no repositório.' + NCHAR(10) + N'III. No desenvolvimento de um novo caso de uso, em que diversos arquivos sejam modificados, é recomendada a criação de uma ramificação (branch).' + NCHAR(10) + N'IV. A versão estável é o ramo principal de desenvolvimento, que segue do começo do desenvolvimento até o momento presente.' + NCHAR(10) + N'' + NCHAR(10) + N'É correto apenas o que se afirma em', N'ENADE 2017 - questão 22'),
        (12, 3, N'Verificações, validações e testes são fundamentais para certificar a qualidade do software. Avalie as afirmações:' + NCHAR(10) + N'I. O teste funcional certifica se o software desempenha as funções especificadas nos requisitos.' + NCHAR(10) + N'II. O teste de desempenho valida a conformidade da especificação do processo de desenvolvimento de software.' + NCHAR(10) + N'III. O teste de aceitação é realizado pelo cliente a fim de validar se aquilo que foi implementado é o que foi solicitado.' + NCHAR(10) + N'IV. O teste de instalação, invariavelmente, é executado no local determinado pelo cliente para instalação do software.' + NCHAR(10) + N'V. As técnicas de verificação e validação de software asseguram que o sistema que está sendo desenvolvido seja adequado ao seu propósito.' + NCHAR(10) + N'' + NCHAR(10) + N'É correto apenas o que se afirma em', N'ENADE 2017 - questão 23'),
        (13, 3, N'Muitos sistemas corporativos das décadas de 1970 e 1980 foram feitos em Cobol, com ADABAS e arquivos ISAM e VSAM, produtos que estão sendo descontinuados. A reengenharia desses sistemas com linguagens e bancos mais modernos é uma oportunidade de negócio. Avalie as afirmações:' + NCHAR(10) + N'I. A dificuldade de reengenharia de sistemas antigos deve-se ao fato de que, na maioria das vezes, o desenvolvedor definia o sistema e esse já era o próprio processo da organização.' + NCHAR(10) + N'II. O custo de alteração para modernização de uma linha de código em Cobol é alto; por isso, fazer a manutenção desses sistemas é menos dispendioso.' + NCHAR(10) + N'III. Uma estratégia de conversão dos referidos sistemas para uma linguagem orientada a objetos é definir uma estrutura de classes e métodos e realizar o refatoramento do código.' + NCHAR(10) + N'' + NCHAR(10) + N'É correto o que se afirma em', N'ENADE 2017 - questão 24'),
        (14, 8, N'O fragmento C++ a seguir insere um nó em uma árvore binária.' + NCHAR(10) + N'' + NCHAR(10) + N'struct noArvore {' + NCHAR(10) + N'    int dado;' + NCHAR(10) + N'    noArvore *esquerda;' + NCHAR(10) + N'    noArvore *direita;' + NCHAR(10) + N'};' + NCHAR(10) + N'' + NCHAR(10) + N'noArvore *insere(noArvore *arvore, int valor) {' + NCHAR(10) + N'    if (arvore == NULL) {' + NCHAR(10) + N'        arvore = new noArvore;' + NCHAR(10) + N'        arvore->esquerda = NULL;' + NCHAR(10) + N'        arvore->direita = NULL;' + NCHAR(10) + N'        arvore->dado = valor;' + NCHAR(10) + N'    } else if (valor < arvore->dado) {' + NCHAR(10) + N'        arvore->esquerda = insere(arvore->esquerda, valor);' + NCHAR(10) + N'    } else {' + NCHAR(10) + N'        arvore->direita = insere(arvore->direita, valor);' + NCHAR(10) + N'    }' + NCHAR(10) + N'    return arvore;' + NCHAR(10) + N'}' + NCHAR(10) + N'' + NCHAR(10) + N'Assinale a opção que imprime os valores dos nós percorrendo a árvore em pré-ordem.', N'ENADE 2017 - questão 25'),
        (15, 5, N'Uma calculadora feita com MVC tem dois modos: comum e probabilista. A classe Calculadora guarda uma variável c do tipo CalculadoraController; o método multiplica(valores) apenas retorna c.multiplica(valores), e alteraModo() faz c = new ProbabilistaController() se modo == 1, senão c = new OrdinarioController(). ProbabilistaController e OrdinarioController herdam de CalculadoraController e implementam multiplica(valores: double[]): double, formando uma família de algoritmos intercambiáveis.' + NCHAR(10) + N'' + NCHAR(10) + N'Avalie as afirmações:' + NCHAR(10) + N'I. A hierarquia exibida ilustra o uso do padrão de projetos Strategy.' + NCHAR(10) + N'II. O padrão composto MVC define a existência de um único controller e, portanto, a solução proposta não caracteriza o uso desse padrão.' + NCHAR(10) + N'III. O método multiplica da classe Calculadora chama o método multiplica de CalculadoraController, o que caracteriza uma conversão de interfaces e, portanto, o uso do padrão de projetos Adapter.' + NCHAR(10) + N'' + NCHAR(10) + N'É correto o que se afirma em', N'ENADE 2017 - questão 26'),
        (16, 3, N'O processo de descobrir, analisar, documentar e verificar os serviços e restrições de um sistema é denominado engenharia de requisitos (Sommerville). Avalie as atribuições listadas, no que se refere à etapa de especificação de requisitos:' + NCHAR(10) + N'I. Identificar as expectativas e necessidades dos stakeholders com relação ao software a ser desenvolvido.' + NCHAR(10) + N'II. Distribuir os requisitos em categorias, explorar as relações entre eles e classificar sua importância para os stakeholders.' + NCHAR(10) + N'III. Produzir um documento de especificação de requisitos, de forma que todos os stakeholders possam entendê-lo.' + NCHAR(10) + N'IV. Examinar a especificação do software para assegurar que todos os requisitos foram definidos sem inconsistências.' + NCHAR(10) + N'' + NCHAR(10) + N'São atribuições na etapa de especificação de requisitos os itens', N'ENADE 2017 - questão 28'),
        (17, 1, N'Uma pesquisa usa os conjuntos A ("possui ensino superior"), B ("possui pós-graduação") e C ("possui pelo menos 5 anos de experiência"). As expressões são:' + NCHAR(10) + N'Expressão 1: x ∈ A ∧ x ∉ (B ∪ C)' + NCHAR(10) + N'Expressão 2: x ∈ A − (B ∪ C)' + NCHAR(10) + N'Expressão 3: x ∈ A ∧ x ∈ B ∧ x ∈ C' + NCHAR(10) + N'' + NCHAR(10) + N'Um programa em C usa a função contem(conjunto, p):' + NCHAR(10) + N'/* condição 1 */' + NCHAR(10) + N'if (contem(A, p) && !contem(B, p) && !contem(C, p)) { ... }' + NCHAR(10) + N'/* condição 2 */' + NCHAR(10) + N'else if (contem(A, p) || contem(B, p) || contem(C, p)) { ... }' + NCHAR(10) + N'' + NCHAR(10) + N'Assinale a opção correta.', N'ENADE 2017 - questão 29'),
        (18, 5, N'Considere o código Java:' + NCHAR(10) + N'' + NCHAR(10) + N'public abstract class Impressora {' + NCHAR(10) + N'    String nome;' + NCHAR(10) + N'    public void imprimir() {}' + NCHAR(10) + N'}' + NCHAR(10) + N'public class Laser extends Impressora {' + NCHAR(10) + N'    public void imprimir() { System.out.println("Imprimindo na Laser"); }' + NCHAR(10) + N'}' + NCHAR(10) + N'class Matricial extends Impressora {' + NCHAR(10) + N'    public void imprimir() { System.out.println("Imprimindo na Matricial"); }' + NCHAR(10) + N'}' + NCHAR(10) + N'public class JatoDeTinta extends Impressora {' + NCHAR(10) + N'    public void imprimir() { System.out.println("Imprimindo na Jato de tinta"); }' + NCHAR(10) + N'}' + NCHAR(10) + N'public class Main {' + NCHAR(10) + N'    public static void main(String args[]) {' + NCHAR(10) + N'        Impressora imp[] = new Impressora[3];' + NCHAR(10) + N'        imp[0] = new Laser();' + NCHAR(10) + N'        imp[1] = new JatoDeTinta();' + NCHAR(10) + N'        imp[2] = new Matricial();' + NCHAR(10) + N'        for (int i = imp.length - 1; i >= 0; i--) {' + NCHAR(10) + N'            imp[i].imprimir();' + NCHAR(10) + N'        }' + NCHAR(10) + N'    }' + NCHAR(10) + N'}' + NCHAR(10) + N'' + NCHAR(10) + N'Avalie as afirmações:' + NCHAR(10) + N'I. A execução resulta em: Imprimindo na Laser / Imprimindo na Matricial / Imprimindo na Jato de tinta.' + NCHAR(10) + N'II. O código faz uso da técnica denominada polimorfismo.' + NCHAR(10) + N'III. O código não será compilado, pois o vetor imp foi instanciado por meio da classe abstrata Impressora.' + NCHAR(10) + N'' + NCHAR(10) + N'É correto o que se afirma em', N'ENADE 2017 - questão 30'),
        (19, 9, N'À medida que o projeto de uma interface evolui, quatro questões quase sempre aparecem: tempo de resposta, recursos de ajuda, tratamento de erros e nomes de comandos (Pressman). Avalie as afirmações:' + NCHAR(10) + N'I. A análise de interfaces tem por objetivo identificar o perfil dos usuários e auxiliar na especificação do requisito não funcional de segurança pertinente ao perfil de acesso dos usuários.' + NCHAR(10) + N'II. O requisito não funcional de segurança descreve as características relacionadas a inteligibilidade, modo de usar ou operar o sistema.' + NCHAR(10) + N'III. O requisito não funcional de confiabilidade descreve as características relacionadas ao tempo de resposta para processamento de dados ou informações.' + NCHAR(10) + N'IV. O requisito não funcional de usabilidade descreve diretrizes de acessibilidade para pessoas com deficiência.' + NCHAR(10) + N'' + NCHAR(10) + N'É correto apenas o que se afirma em', N'ENADE 2017 - questão 31'),
        (20, 2, N'Um banco guarda o resultado de uma eleição nas tabelas Partido (numero, nome, sigla), Candidato (numero, nome), em que o número do candidato é o número do seu partido, e Votacao (partido, votos, estado), com os votos de cada partido em cada estado.' + NCHAR(10) + N'' + NCHAR(10) + N'Qual comando SQL seleciona os nomes dos candidatos, seus partidos e o total de votos de cada partido?', N'ENADE 2017 - questão 32'),
        (21, 8, N'Um programador implementou a ordenação por inserção para vetor[1..9], mas o algoritmo não funciona:' + NCHAR(10) + N'' + NCHAR(10) + N'01 para i <- 2 até 9 faça' + NCHAR(10) + N'02    valor <- vetor[i]' + NCHAR(10) + N'03    j <- i - 1' + NCHAR(10) + N'04    enquanto ((j >= 1) e (valor < vetor[j])) faça' + NCHAR(10) + N'05       vetor[i] <- vetor[j]' + NCHAR(10) + N'06       j <- j - 1' + NCHAR(10) + N'07       se (j = 0) então' + NCHAR(10) + N'08          interrompa' + NCHAR(10) + N'09       fim se' + NCHAR(10) + N'10    fim enquanto' + NCHAR(10) + N'11    vetor[j + 1] <- valor' + NCHAR(10) + N'12 fim para' + NCHAR(10) + N'' + NCHAR(10) + N'Qual linha e comando devem ser substituídos para que o algoritmo ordene o vetor de forma crescente?', N'ENADE 2017 - questão 33'),
        (22, 2, N'Inspirado no diálogo entre Chicó e João Grilo (Auto da Compadecida), um modelo de dados tem a entidade pessoa (codigo, que é o identificador; rg; cpf; nome) ligada pelo relacionamento possui à entidade cavalo (codigo, que é o identificador; raca; eBento?). A cardinalidade (1,1) aparece junto de pessoa e (0,1) junto de cavalo.' + NCHAR(10) + N'' + NCHAR(10) + N'Avalie as afirmações:' + NCHAR(10) + N'I. O Chicó e a velha poderão ser cadastrados na entidade pessoa.' + NCHAR(10) + N'II. O Chicó e a velha poderão ter mais que um cavalo cadastrados.' + NCHAR(10) + N'III. O atributo rg da entidade pessoa pode ter a função de chave primária nessa entidade.' + NCHAR(10) + N'IV. O cavalo deverá ter no mínimo uma pessoa e uma pessoa poderá ser cadastrada sem a necessidade de ter um cavalo.' + NCHAR(10) + N'' + NCHAR(10) + N'É correto apenas o que se afirma em', N'ENADE 2017 - questão 34'),
        (23, 9, N'Num site de venda de ingressos, os links para cada show são imagens. O web designer implementou cada link assim, para que usuários de leitores de tela recebam um texto informativo:' + NCHAR(10) + N'' + NCHAR(10) + N'<a href="link-area-venda-ingresso">' + NCHAR(10) + N'    <img src="imagem-show.jpg" alt="identificação do show" />' + NCHAR(10) + N'</a>' + NCHAR(10) + N'' + NCHAR(10) + N'Considerando o uso do atributo alt e a interação humano-computador, o web designer atendeu o requisito de', N'ENADE 2017 - questão 35'),
        (24, 3, N'A etapa de definição de requisitos estabelece quais funções são requeridas pelo sistema e as restrições sobre a operação e o desenvolvimento do software. Os requisitos podem ser funcionais ou não funcionais (Sommerville).' + NCHAR(10) + N'' + NCHAR(10) + N'Assinale a alternativa em que o item é um requisito funcional.', N'ENADE 2021 - questão 9'),
        (25, 8, N'O código Java a seguir implementa uma Pilha encadeada.' + NCHAR(10) + N'' + NCHAR(10) + N'public class No {' + NCHAR(10) + N'    public int dado;' + NCHAR(10) + N'    public No prox;' + NCHAR(10) + N'    public No(int dado) { this.dado = dado; }' + NCHAR(10) + N'}' + NCHAR(10) + N'public class PilhaEncadeada {' + NCHAR(10) + N'    private No topo;' + NCHAR(10) + N'    public int pop() {' + NCHAR(10) + N'        if (topo == null) return -1;' + NCHAR(10) + N'        No lixo = topo;' + NCHAR(10) + N'        topo = topo.prox;' + NCHAR(10) + N'        lixo.prox = null;' + NCHAR(10) + N'        return lixo.dado;' + NCHAR(10) + N'    }' + NCHAR(10) + N'    public int top() {' + NCHAR(10) + N'        if (topo == null) return -1;' + NCHAR(10) + N'        return topo.dado;' + NCHAR(10) + N'    }' + NCHAR(10) + N'}' + NCHAR(10) + N'' + NCHAR(10) + N'Assinale a opção com a implementação correta do método push.', N'ENADE 2021 - questão 11'),
        (26, 3, N'Uma fábrica de software usa Scrum, eXtreme Programming (XP) e quadro Kanban. Avalie as afirmações:' + NCHAR(10) + N'I. Métodos ágeis são baseados em ciclos iterativos e incrementais que se concentram no desenvolvimento rápido e na flexibilidade às mudanças, com a participação do cliente no processo de software.' + NCHAR(10) + N'II. Uma forte característica da XP é a garantia da qualidade do código produzido e, para isso, os desenvolvedores produzem testes automatizados antes mesmo de codificar uma funcionalidade.' + NCHAR(10) + N'III. O planejamento no Scrum é baseado na elaboração dos itens do product backlog, que é uma lista de funcionalidades desejadas pelo cliente, sendo o Scrum Master o responsável por gerenciá-lo.' + NCHAR(10) + N'IV. O quadro Kanban permite monitorar a evolução das tarefas necessárias durante o processo ágil, possibilitando um acompanhamento visual das atividades em construção.' + NCHAR(10) + N'' + NCHAR(10) + N'É correto apenas o que se afirma em', N'ENADE 2021 - questão 12'),
        (27, 8, N'As variáveis pilha e fila são uma Pilha e uma Fila. Um programador executou:' + NCHAR(10) + N'' + NCHAR(10) + N'pilha.push(''A''); pilha.push(''B''); pilha.push(''C'');' + NCHAR(10) + N'fila.enqueue(pilha.top());' + NCHAR(10) + N'fila.enqueue(pilha.top());' + NCHAR(10) + N'fila.enqueue(''D'');' + NCHAR(10) + N'pilha.push(fila.dequeue());' + NCHAR(10) + N'fila.enqueue(fila.dequeue());' + NCHAR(10) + N'fila.enqueue(pilha.pop());' + NCHAR(10) + N'pilha.push(''E'');' + NCHAR(10) + N'fila.enqueue(''E'');' + NCHAR(10) + N'pilha.pop();' + NCHAR(10) + N'' + NCHAR(10) + N'Ao imprimir o conteúdo de pilha e fila, respectivamente, seria exibido:', N'ENADE 2021 - questão 13'),
        (28, 4, N'Um projeto de integração de um ERP com um CRM não implementou todos os serviços esperados e há falhas nos já implementados. Uma auditoria identificou desentendimentos entre os membros da equipe; os membros da qualidade não compreendem o que deve ser avaliado; demandas de novos solicitantes aparecem constantemente; e o patrocinador demora muito a responder às solicitações. Tudo isso atrasou o projeto e estourou o orçamento.' + NCHAR(10) + N'' + NCHAR(10) + N'O gerente de projeto deve priorizar o gerenciamento de', N'ENADE 2021 - questão 14'),
        (29, 2, N'Um banco de dados bancário tem, entre outras, as tabelas CLIENTE (COD_CLIENTE, NOM_CLIENTE, ...), CONTA (NUM_CONTA, COD_CLIENTE, ...) e HISTORICO_MOVIMENTACAO (COD_HISTORICO_MOVIMENTACAO, NUM_CONTA, VAL_MOVIMENTACAO, DTA_MOVIMENTACAO, ...).' + NCHAR(10) + N'' + NCHAR(10) + N'Indique a consulta SQL que recupera o nome dos clientes e o valor médio movimentado por eles em sua conta até o momento, exibindo primeiro os clientes com maior média.', N'ENADE 2021 - questão 17'),
        (30, 3, N'A engenharia de requisitos tem quatro subprocessos: estudo de viabilidade, elicitação, especificação e validação (Sommerville). Uma equipe vai desenvolver um software de Suporte Técnico; o estudo de viabilidade já foi aprovado e ela seguirá os outros três subprocessos.' + NCHAR(10) + N'' + NCHAR(10) + N'Quais artefatos podem ser usados nesses três subprocessos?', N'ENADE 2021 - questão 18'),
        (31, 3, N'A respeito dos estilos e padrões arquiteturais, avalie as afirmações:' + NCHAR(10) + N'I. Em arquiteturas orientadas a objetos, a comunicação entre os componentes do software é realizada por intermédio da troca de mensagens.' + NCHAR(10) + N'II. As arquiteturas monolíticas consistem de um sistema dividido em pequenas partes, possibilitando que estas tenham sua manutenção, execução e evolução individual.' + NCHAR(10) + N'III. No padrão MVC, a camada de Modelo armazena as interações realizadas no Controle, podendo ser apresentadas/manipuladas posteriormente na Visão.' + NCHAR(10) + N'IV. Nas arquiteturas de microsserviços, o software possui componentes altamente acoplados, dificultando a manutenção.' + NCHAR(10) + N'' + NCHAR(10) + N'É correto apenas o que se afirma em', N'ENADE 2021 - questão 19'),
        (32, 9, N'Uma secretaria municipal vai criar um site para pessoas da terceira idade, com orientações de saúde, eventos esportivos e publicação de fotos que podem ser curtidas e comentadas. A maioria desse público acessa a internet pelo celular ou tablet, e uma parte prefere computadores.' + NCHAR(10) + N'' + NCHAR(10) + N'Avalie as afirmações:' + NCHAR(10) + N'I. A segurança no uso é um fator crítico de usabilidade a ser considerado no projeto, tendo em vista que pessoas da terceira idade são temerosas quanto ao registro de dados pessoais e confidenciais em sites e aplicativos.' + NCHAR(10) + N'II. A responsividade, que pressupõe o uso de valores relativos para definir as dimensões de elementos na estilização de páginas HTML, deve ser considerada, tendo em vista o acesso por dispositivos com diferentes tamanhos de tela.' + NCHAR(10) + N'III. A construção de protótipos pode antecipar problemas de design de interação e minimizar custos, e é viável para uma comunicação mais objetiva com o público-alvo, possibilitando validar a usabilidade e a experiência do usuário.' + NCHAR(10) + N'IV. O design participativo é um processo de design de IHC viável para direcionar o projeto, pois o público-alvo tende a apresentar dificuldades no manuseio de tecnologias da informação e da comunicação.' + NCHAR(10) + N'' + NCHAR(10) + N'É correto apenas o que se afirma em', N'ENADE 2021 - questão 20'),
        (33, 3, N'A Gestão de Configuração de Software estabelece um conjunto de atividades para gerenciar alterações durante todo o ciclo de vida de um software (Pressman).' + NCHAR(10) + N'' + NCHAR(10) + N'Assinale a opção correta acerca das atividades de gestão de configuração de software.', N'ENADE 2021 - questão 21'),
        (34, 3, N'Sobre o processo de Gerência de Configuração de Software (GCS), avalie as afirmações:' + NCHAR(10) + N'I. O controle de versão possibilita o compartilhamento de dados e a edição colaborativa, permitindo a gestão de diferentes ramos de desenvolvimento e a existência de diferentes versões de forma simultânea.' + NCHAR(10) + N'II. A auditoria de configuração é uma atividade de garantia de qualidade que tem por objetivo assegurar que a qualidade do software seja mantida quando feitas alterações requisitadas.' + NCHAR(10) + N'III. O relatório de status de configuração tem por objetivo manter o cliente informado sobre as alterações, e deve ser gerado ao final do processo.' + NCHAR(10) + N'IV. A GCS proporciona atividades de acompanhamento e controle de mudanças que se iniciam logo depois que o software for fornecido ao cliente e colocado em operação.' + NCHAR(10) + N'' + NCHAR(10) + N'É correto apenas o que se afirma em', N'ENADE 2021 - questão 22'),
        (35, 3, N'A evolução de sistemas legados se divide em manutenção, modernização e substituição. Um ERP já implantado integra todos os departamentos de uma empresa, e surgiu a necessidade de criar um relatório gerencial de comissão da equipe de vendas.' + NCHAR(10) + N'' + NCHAR(10) + N'Nesse contexto, a manutenção a ser realizada é', N'ENADE 2021 - questão 23'),
        (36, 3, N'Num sistema web de delivery, o analista de teste descreveu:' + NCHAR(10) + N'01 – Verificar se o método "Finalizar Pedido" da classe "Pedido" está funcionando corretamente.' + NCHAR(10) + N'02 – Garantir que o sistema funcione corretamente em diferentes navegadores.' + NCHAR(10) + N'03 – O sistema deve passar por testes rigorosos na estrutura lógica interna do software.' + NCHAR(10) + N'04 – O sistema deve garantir, no mínimo, o registro de 100 pedidos simultâneos.' + NCHAR(10) + N'05 – O usuário deve testar o sistema em um ambiente controlado sob a supervisão dos desenvolvedores.' + NCHAR(10) + N'' + NCHAR(10) + N'Avalie as afirmações:' + NCHAR(10) + N'I. A descrição 01 deve ser verificada com teste unitário.' + NCHAR(10) + N'II. A descrição 02 deve ser executada com a abordagem caixa-branca.' + NCHAR(10) + N'III. A descrição 03 deve ser executada com a abordagem caixa-preta.' + NCHAR(10) + N'IV. A descrição 04 deve ser verificada com teste de carga.' + NCHAR(10) + N'V. A descrição 05 deve ser classificada como teste alfa.' + NCHAR(10) + N'' + NCHAR(10) + N'É correto apenas o que se afirma em', N'ENADE 2021 - questão 24'),
        (37, 3, N'Uma empresa de piscicultura pediu com extrema urgência um sistema para gerenciar a criação dos peixes, das fases de alevino e engorda até a venda, registrando mortandade e rações.' + NCHAR(10) + N'' + NCHAR(10) + N'Avalie as afirmações sobre o processo de desenvolvimento a usar:' + NCHAR(10) + N'I. Deve ser adotado um processo baseado no modelo cascata, pois ele se adapta melhor a cenários com muitas mudanças.' + NCHAR(10) + N'II. Por se tratar de uma aplicação com escopo pequeno, o modelo espiral deverá ser utilizado, já que reduzirá riscos por meio da prototipação de cada fase dos peixes e diminuirá o tempo de entrega.' + NCHAR(10) + N'III. O modelo incremental deve ser utilizado, já que partes do sistema referentes à fase inicial dos peixes poderiam ser disponibilizadas, enquanto as demais estão nas etapas de concepção e desenvolvimento.' + NCHAR(10) + N'IV. Em razão da extrema urgência, a empresa deve elaborar seu processo utilizando o modelo RAD (Rapid Application Development).' + NCHAR(10) + N'' + NCHAR(10) + N'É correto apenas o que se afirma em', N'ENADE 2021 - questão 25'),
        (38, 10, N'Empreender em computação exige observar a legislação, como a Lei Geral de Proteção de Dados Pessoais (LGPD, Lei n. 13.709/2018).' + NCHAR(10) + N'' + NCHAR(10) + N'Assinale os fundamentos da disciplina da proteção de dados pessoais, previstos no art. 2º da LGPD.', N'ENADE 2021 - questão 26'),
        (39, 1, N'Os profissionais de TI precisam converter números entre as bases binária (2), octal (8), decimal (10) e hexadecimal (16).' + NCHAR(10) + N'' + NCHAR(10) + N'Fazendo a conversão da soma (1001)₂ + (15)₈ + (FF)₁₆, qual é o número equivalente na base decimal?', N'ENADE 2021 - questão 27'),
        (40, 7, N'O sistema operacional é um gerenciador de recursos. É uma péssima ideia permitir que os programas tenham acesso sem restrição à memória uns dos outros: um programa com defeito ou malicioso pode travar outro, produzir resultados incorretos ou afetar todo o sistema (Stuart, adaptado).' + NCHAR(10) + N'' + NCHAR(10) + N'A atividade com que o sistema operacional garante essa proteção é', N'ENADE 2021 - questão 28'),
        (41, 8, N'Considere o algoritmo:' + NCHAR(10) + N'' + NCHAR(10) + N'mat[1..3][1..5] = {{1, 2, -1, 2, 3}, {1, -3, 4, 2, 0}, {-3, 5, 2, 3, 4}}' + NCHAR(10) + N'sl[1..3] = {0, 0, 0}' + NCHAR(10) + N'x <- 0' + NCHAR(10) + N'para i <- 1 até 3 faça' + NCHAR(10) + N'    para j <- 1 até 5 faça' + NCHAR(10) + N'        sl[i] <- sl[i] + mat[i][j]' + NCHAR(10) + N'    fimpara' + NCHAR(10) + N'    x <- x + sl[i]' + NCHAR(10) + N'fimpara' + NCHAR(10) + N'imprima x' + NCHAR(10) + N'' + NCHAR(10) + N'No fim da execução, será exibido o valor', N'ENADE 2021 - questão 29'),
        (42, 6, N'Na sala dos professores há 3 máquinas na rede:' + NCHAR(10) + N'PROFESSORES01: IP 175.16.10.200, máscara 255.255.255.0, gateway 175.16.1.1' + NCHAR(10) + N'PROFESSORES02: IP 175.16.20.200, máscara 255.255.0.0, gateway 175.16.1.1' + NCHAR(10) + N'PROFESSORES03: IP 175.16.30.200, máscara 255.255.0.0, gateway 175.16.1.1' + NCHAR(10) + N'' + NCHAR(10) + N'A estação PROFESSORES01 não consegue imprimir na impressora compartilhada pela PROFESSORES03. Que alteração resolve o problema?', N'ENADE 2021 - questão 30'),
        (43, 3, N'Um software de matrículas tem este diagrama de casos de uso: o ator Aluno se liga a "Realizar Matrícula"; "Realizar Matrícula Fora do Prazo" estende (<<extend>>) "Realizar Matrícula"; "Realizar Matrícula Fora do Prazo" inclui (<<include>>) "Validar Aluno"; e "Validar via Retina" e "Validar via Digital" são especializações de "Validar Aluno".' + NCHAR(10) + N'' + NCHAR(10) + N'Avalie as afirmações:' + NCHAR(10) + N'I. O aluno poderá realizar a matrícula fora do prazo e as tratativas são as mesmas da matrícula feita dentro do prazo.' + NCHAR(10) + N'II. O aluno poderá, opcionalmente, realizar a matrícula fora do prazo.' + NCHAR(10) + N'III. O sistema, obrigatoriamente, deverá validar o aluno que realizar a matrícula fora do prazo.' + NCHAR(10) + N'IV. A validação do aluno deverá ser feita a partir da sua matrícula informada no sistema.' + NCHAR(10) + N'V. A validação do aluno, a ser feita por retina, é diferente da validação feita pela digital.' + NCHAR(10) + N'' + NCHAR(10) + N'É correto apenas o que se afirma em', N'ENADE 2021 - questão 31'),
        (44, 11, N'O Canvas de Osterwalder divide o modelo de negócio em nove componentes: segmentos de clientes, proposta de valor, canais, relacionamento com cliente, fontes de receita, recursos principais, atividades-chave, parcerias principais e estrutura de custo. É muito usado por startups.' + NCHAR(10) + N'' + NCHAR(10) + N'Diante deste contexto, conclui-se que as startups', N'ENADE 2021 - questão 32'),
        (45, 3, N'O CMMI descreve práticas, processos e atividades de gestão que guiam a melhoria do processo de software até o nível mais alto de maturidade. Avalie as afirmações:' + NCHAR(10) + N'I. A maturidade implica no crescimento da capacidade e indica tanto a efetividade do processo de software quanto o grau de consistência com que este é aplicado nos diferentes projetos da organização.' + NCHAR(10) + N'II. A maturidade do processo de software implica melhorias contínuas com base em etapas evolutivas que se caracterizam pela capacidade de inovação e absorção de novas tecnologias.' + NCHAR(10) + N'III. A maturidade do processo de software implica na sua institucionalização por meio de políticas e padrões organizacionais, levando a uma cultura corporativa de métodos, práticas e procedimentos com efetividade plenamente reconhecida.' + NCHAR(10) + N'IV. Cada nível do CMMI implica na satisfação de um conjunto de metas de processo que estabilizam um componente importante do processo de software e representa o seu estágio de maturidade.' + NCHAR(10) + N'' + NCHAR(10) + N'É correto apenas o que se afirma em', N'ENADE 2021 - questão 33'),
        (46, 12, N'Um sistema especialista para diagnóstico de dengue usa a regra de produção:' + NCHAR(10) + N'' + NCHAR(10) + N'Se ((temperatura > 38º) e (dores musculares intensas))' + NCHAR(10) + N'então (quadro de dengue, com 70% de chance);' + NCHAR(10) + N'senão (quadro de resfriado comum com 30% de chance);' + NCHAR(10) + N'' + NCHAR(10) + N'Levando em conta essa regra, é correto afirmar que', N'ENADE 2021 - questão 34');
